-- Tour & Package Database Schema and Initial Data
CREATE DATABASE IF NOT EXISTS `u570061185_jobiho_db`;
USE `u570061185_jobiho_db`;

DROP TABLE IF EXISTS `tour_package_images`;
DROP TABLE IF EXISTS `tour_package_travel_tips`;
DROP TABLE IF EXISTS `tour_package_things_to_do`;
DROP TABLE IF EXISTS `tour_package_itinerary`;
DROP TABLE IF EXISTS `tour_packages`;

CREATE TABLE `tour_packages` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `slug` VARCHAR(255) UNIQUE NOT NULL,
  `name` VARCHAR(255) NOT NULL,
  `country` VARCHAR(255) NOT NULL,
  `region` VARCHAR(255) NOT NULL,
  `tagline` VARCHAR(255),
  `hero_image` VARCHAR(255),
  `overview` TEXT,
  `coords_lon` DOUBLE,
  `coords_lat` DOUBLE,
  `tag` VARCHAR(100),
  `tag_color` VARCHAR(100),
  `short_description` TEXT,
  `thumbnail_image` VARCHAR(255),
  `status` VARCHAR(20) DEFAULT 'published',
  `price` VARCHAR(255),
  `duration` VARCHAR(100),
  `quick_fact_capital` VARCHAR(255),
  `quick_fact_currency` VARCHAR(255),
  `quick_fact_climate` VARCHAR(255),
  `quick_fact_best_season` VARCHAR(255),
  `quick_fact_languages` VARCHAR(255),
  `quick_fact_time_zone` VARCHAR(255),
  `quick_fact_driving_side` VARCHAR(255),
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `tour_package_itinerary` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `tour_package_id` INT NOT NULL,
  `day_number` INT NOT NULL,
  `title` VARCHAR(255) NOT NULL,
  `location` VARCHAR(255) NOT NULL,
  `description` TEXT,
  `highlights` JSON,
  `image_url` VARCHAR(255),
  `sort_order` INT DEFAULT 0,
  FOREIGN KEY (`tour_package_id`) REFERENCES `tour_packages` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `tour_package_things_to_do` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `tour_package_id` INT NOT NULL,
  `title` VARCHAR(255) NOT NULL,
  `description` TEXT,
  `icon_name` VARCHAR(255),
  `sort_order` INT DEFAULT 0,
  FOREIGN KEY (`tour_package_id`) REFERENCES `tour_packages` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `tour_package_travel_tips` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `tour_package_id` INT NOT NULL,
  `tip` TEXT NOT NULL,
  `sort_order` INT DEFAULT 0,
  FOREIGN KEY (`tour_package_id`) REFERENCES `tour_packages` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `tour_package_images` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `tour_package_id` INT NOT NULL,
  `image_url` VARCHAR(255) NOT NULL,
  `sort_order` INT DEFAULT 0,
  FOREIGN KEY (`tour_package_id`) REFERENCES `tour_packages` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'tokyo', 'Tokyo', 'Japan', 'East Asia', 
  'Where ancient traditions pulse beneath neon-lit skyscrapers', 'https://images.pexels.com/photos/34142/pexels-photo.jpg?auto=compress&cs=tinysrgb&h=650&w=940', 'Tokyo is a city of mesmerizing contrasts — a place where centuries-old Shinto shrines stand in the shadow of glass towers, where Michelin-starred sushi bars sit beside smoky yakitori alleys, and where rush-hour silence on packed trains gives way to the electric roar of Shibuya Crossing. It is at once the world''s most orderly metropolis and its most eclectic, a living proof that tradition and hyper-modernity can not only coexist, but thrive together.

From the serene gravel gardens of Meiji Jingu to the sensory overload of Akihabara''s electronics district, every neighborhood tells a different story. Wake early for the tuna auctions at Toyosu Market, spend an afternoon lost in the vintage boutiques of Shimokitazawa, then watch the sun set from the observation deck of Tokyo Skytree before descending into the golden-lit izakaya of Yurakucho.

Beyond the city limits, snow-capped Mount Fuji beckons for a day of awe-inspiring natural beauty. Whether you are chasing cherry blossoms in spring, hunting street fashion in Harajuku, or simply savoring a perfect bowl of ramen at 2 a.m., Tokyo rewards curiosity at every turn.', 
  139.69, 35.69, 'Corporate', 'bg-slate-600', 
  'Executive retreats, tech-industry immersion tours, and conference facilities in Asia''s premier business capital.', '/images/city-2.jpg', 
  'published', '', '5 Days', 
  'Tokyo (national capital)', 'Japanese Yen (¥)', 'Humid subtropical with warm summers and mild winters', 'March–May (cherry blossom) & October–November (autumn foliage)', 
  'Japanese', 'JST (UTC+9)', 'Left'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  1, 1, 'Shibuya, Harajuku & Shinjuku', 'Shibuya & Shinjuku, Tokyo', 
  'Dive straight into Tokyo''s beating heart. Start with the iconic Shibuya Crossing — the world''s busiest pedestrian scramble — then wander through Harajuku''s Takeshita Street for avant-garde street fashion and crepe stalls. Walk the forested path to Meiji Jingu Shrine for a moment of stillness, before ending the evening amid the electric glow of Shinjuku''s Golden Gai, where over 200 tiny bars line six narrow alleys.', '["Cross Shibuya Scramble and photograph it from the Magnet rooftop","Explore Harajuku''s Takeshita Street and Cat Street boutiques","Write a wish on an ema board at Meiji Jingu Shrine","Bar-hop through Golden Gai''s themed micro-bars"]', 'https://images.pexels.com/photos/34142/pexels-photo.jpg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  1, 2, 'Temples, Gardens & Traditional Tokyo', 'Asakusa & Ueno, Tokyo', 
  'Step back in time in Asakusa, where the thunderous Kaminarimon gate leads you through Nakamise-dori''s souvenir stalls to the incense-filled Sensō-ji, Tokyo''s oldest Buddhist temple. Continue to Ueno Park to visit the Tokyo National Museum''s samurai armor collection, then stroll through the immaculate Rikugien Garden as afternoon light filters through centuries-old maple trees.', '["Pass through Kaminarimon and draw fortune slips at Sensō-ji","View Edo-period woodblock prints at Tokyo National Museum","Tea ceremony experience in Rikugien Garden''s lakeside teahouse","Evening rickshaw ride through Asakusa''s lantern-lit backstreets"]', 'https://images.pexels.com/photos/5362196/pexels-photo-5362196.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  1, 3, 'Toyosu Market & Tsukiji Outer Market', 'Toyosu & Tsukiji, Tokyo', 
  'Rise before dawn for the tuna auction at Toyosu Market, where bluefin worth tens of thousands of dollars change hands in minutes. Afterward, head to the Tsukiji Outer Market for a walking breakfast of tamagoyaki, fresh uni, and mochi. Spend the afternoon in the upscale Ginza district, exploring department store food halls — a culinary art form in themselves.', '["Witness the 5:30 a.m. bluefin tuna auction at Toyosu","Taste ultra-fresh sashimi at a Tsukiji Outer Market stall","Sample wagyu beef skewers and matcha soft-serve in Ginza","Browse the spectacular basement food hall at Mitsukoshi department store"]', 'https://images.pexels.com/photos/2982653/pexels-photo-2982653.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  1, 4, 'Mount Fuji & Hakone Day Trip', 'Hakone & Mount Fuji, Kanagawa', 
  'Board the Romance Car express to Hakone for a day framed by Japan''s most iconic peak. Cruise across Lake Ashi with Fuji''s snow-dusted cone reflected in the water, ride the Hakone Ropeway over the volcanic vents of Ōwakudani, and soak in a traditional onsen with mountain views. The black eggs boiled in Ōwakudani''s sulfuric springs are said to add seven years to your life.', '["Panoramic Lake Ashi pirate-ship cruise with Fuji views","Ride the Hakone Ropeway over Ōwakudani''s volcanic valley","Eat a life-extending black egg at Ōwakudani","Soak in a natural hot-spring onsen overlooking the mountains"]', 'https://images.pexels.com/photos/36476004/pexels-photo-36476004.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  1, 5, 'Akihabara, Odaiba & Farewell Tokyo', 'Akihabara & Odaiba, Tokyo', 
  'Explore the neon wonderland of Akihabara — Tokyo''s otaku (geek-culture) epicenter — where multi-story arcades, manga shops, and maid cafés compete for attention. Cross Rainbow Bridge to Odaiba''s futuristic waterfront, home to teamLab Borderless, an immersive digital-art museum where rooms of light and color dissolve the boundaries between art and viewer. End the trip with a sunset view of the Tokyo skyline from Odaiba''s seaside deck.', '["Play retro games in Akihabara''s multi-floor arcades","Walk through the infinite mirror rooms at teamLab Borderless","Photograph the 1:1 scale Unicorn Gundam statue at DiverCity","Sunset cocktails overlooking Rainbow Bridge and Tokyo Tower"]', 'https://images.pexels.com/photos/5905578/pexels-photo-5905578.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  1, 'Sushi Omakase Experience', 'Sit at a hinoki-wood counter as a master itamae selects and prepares 15–20 courses of the day''s finest catch, each piece placed directly before you with precise choreography.', 'Utensils', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  1, 'Cherry Blossom Hanami', 'Join locals beneath canopies of pale-pink sakura in Ueno Park or along the Meguro River for a traditional hanami picnic of bento boxes, sake, and springtime joy.', 'Flower2', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  1, 'Sumo Tournament', 'Witness the thunderous clash of sumo wrestlers at Ryōgoku Kokugikan during one of three annual Tokyo basho tournaments — a ritual sport stretching back centuries.', 'Trophy', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  1, 'Robot Restaurant Show', 'Experience Shinjuku''s wildest spectacle: neon-lit robots, laser beams, taiko drums, and dancers in a sensory extravaganza that defies all description.', 'Bot', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  1, 'Shibuya Night Photography', 'Capture the city''s kinetic energy after dark — from the scramble crossing''s human river to the moody backstreets of Nonbei Yokocho, Tokyo is a photographer''s playground.', 'Camera', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  1, 'Traditional Tea Ceremony', 'Learn the meditative art of chanoyu in a tatami-mat room, where every gesture — from folding the fukusa cloth to whisking the matcha — carries centuries of meaning.', 'Coffee', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  1, 'Get a 7-day Japan Rail Pass before arrival — it pays for itself with the Hakone day trip alone.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  1, 'IC cards (Suica or Pasmo) work on all trains, buses, and even vending machines — load one at any station.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  1, 'Tipping is not practiced in Japan and can cause confusion; excellent service is the cultural standard.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  1, 'Convenience stores (konbini) like 7-Eleven and Lawson sell surprisingly high-quality meals around the clock.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  1, 'Download the Navitime or Japan Transit app for real-time train routing — Google Maps also works well.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  1, 'Carry cash for smaller shops and street stalls; many traditional establishments don''t accept cards.', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  1, 'Bow slightly when greeting and thanking — it''s deeply appreciated even from foreign visitors.', 6
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  1, 'Shoes off before entering temples, traditional restaurants, and ryokan inns.', 7
);
