INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'rajasthan', 'Rajasthan', 'India', 'South Asia', 
  'A land of maharajas, desert fortresses, and living color', 'https://images.pexels.com/photos/12931430/pexels-photo-12931430.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 'Rajasthan is India distilled to its most vivid essence — a desert state where every surface seems to blaze with color, from the pink sandstone of Jaipur to the blue-washed houses of Jodhpur, the white marble palaces of Udaipur, and the golden bastions of Jaisalmer rising like a mirage from the Thar Desert. This is the land of Rajput warrior kings, whose legacy lives on in some of the most magnificent forts and palaces on earth.

Beyond the architecture, Rajasthan pulses with life. Camel caravans trace ancient trade routes through rolling dunes, turbaned elders play folk music on haunting sarangi strings, and women in embroidered ghagras carry brass pots past crumbling havelis painted with elaborate frescoes. Markets overflow with block-printed textiles, silver jewelry, and the intoxicating scent of cardamom chai.

A journey through Rajasthan is as much an encounter with living traditions as with historical grandeur. From the fierce elegance of Mehrangarh Fort to the serene sunset over Lake Pichola, every moment confirms why this remains one of the world''s most unforgettable travel destinations.', 
  73.8, 26.9, 'Historical', 'bg-amber-600', 
  'Royal forts, grand palaces, desert safaris, and living heritage of warrior kings.', '/images/dest-16.jpg', 
  'published', '', '6 Days', 
  'Jaipur', 'Indian Rupee (₹)', 'Hot semi-arid; scorching summers, cool and pleasant winters', 'October–March (cool, dry winter season)', 
  'Hindi, Rajasthani, English widely understood in tourist areas', 'IST (UTC+5:30)', 'Left'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  2, 1, 'The Pink City — Jaipur', 'Jaipur, Rajasthan', 
  'Arrive in Jaipur, Rajasthan''s flamboyant capital, where the entire old city was painted terracotta-pink in 1876 to welcome Prince Albert. Begin at the Hawa Mahal, its 953 latticed windows designed so royal women could observe street life unseen. Continue to the City Palace, still home to the Jaipur royal family, then lose yourself in the Johari Bazaar''s lanes of gem traders and lac bangle makers.', '["Photograph the iconic honeycomb façade of Hawa Mahal at sunrise","Explore the City Palace''s Peacock Courtyard and textile gallery","Haggle for uncut emeralds and block-printed fabrics in Johari Bazaar","Dine on laal maas (fiery red mutton curry) at a heritage haveli restaurant"]', 'https://images.pexels.com/photos/12931430/pexels-photo-12931430.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  2, 2, 'Amber Fort & Jaipur Craft Traditions', 'Amber & Jaipur, Rajasthan', 
  'Ascend to Amber Fort by jeep along its fortified ramp, entering a palace complex where mirrored Sheesh Mahal chambers glitter like constellations. Spend the afternoon at a traditional block-printing workshop in Sanganer, where artisans hand-carve teak stamps and press intricate patterns onto cotton using natural dyes. As dusk falls, witness the Aarti ceremony at Birla Mandir, its white marble glowing against the twilight sky.', '["Walk through Amber Fort''s Sheesh Mahal (Hall of Mirrors)","Try your hand at Sanganeri block-printing with master artisans","Watch the sunset from Nahargarh Fort overlooking the entire city","Evening aarti ceremony at the luminous Birla Mandir temple"]', 'https://images.pexels.com/photos/36470562/pexels-photo-36470562.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  2, 3, 'The Blue City — Jodhpur', 'Jodhpur, Rajasthan', 
  'Drive west to Jodhpur, where the colossal Mehrangarh Fort crowns a sheer cliff 400 feet above a sea of indigo-blue houses. Inside, galleries showcase palanquins, armories, and the finest collection of Rajput miniature paintings in India. Descend into the old city''s labyrinthine lanes to discover stepwells, spice markets, and tiny lassi shops serving creamy saffron-and-cardamom yogurt drinks.', '["Explore Mehrangarh Fort''s ramparts and cannon-studded battlements","Photograph the blue-painted Brahmin houses from the fort''s walls","Taste makhaniya lassi — Jodhpur''s legendary saffron yogurt drink","Browse the Sardar Market''s clock-tower spice stalls at sunset"]', 'https://images.pexels.com/photos/36470621/pexels-photo-36470621.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  2, 4, 'The White City — Udaipur', 'Udaipur, Rajasthan', 
  'Continue south to Udaipur, the ''Venice of the East,'' where white marble palaces float on Lake Pichola like a dream. Take a boat to the Lake Palace — now a luxury hotel seeming to hover on the water — and visit the sprawling City Palace complex, a fusion of Rajput and Mughal architecture spanning 400 years of construction. As evening falls, dine on a rooftop overlooking the lake as the palaces glow amber in the fading light.', '["Sunset boat cruise on Lake Pichola past Jag Mandir island","Tour the City Palace''s balconies, courtyards, and peacock mosaics","Watch a traditional Rajasthani puppet show at Bagore Ki Haveli","Rooftop dinner overlooking the illuminated Lake Palace"]', 'https://images.pexels.com/photos/35394354/pexels-photo-35394354.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  2, 5, 'The Ranakpur Jain Temples', 'Ranakpur, Rajasthan', 
  'En route to Jaisalmer, detour to the Ranakpur Jain Temples, hidden in a wooded valley of the Aravalli Hills. The main Chaumukha Temple contains 1,444 individually carved marble pillars — no two alike — supporting a labyrinth of domes, corridors, and intricately filigreed ceilings that rank among India''s supreme architectural achievements. The silence here is profound, broken only by birdsong and the murmur of prayers.', '["Marvel at 1,444 uniquely carved marble pillars in Chaumukha Temple","Photograph the impossibly detailed marble lattice ceilings","Spot langur monkeys and peacocks in the surrounding forest","Continue westward through the Aravalli hills toward the Thar Desert"]', 'https://images.pexels.com/photos/29449927/pexels-photo-29449927.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 4
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  2, 6, 'The Golden City & Desert Camp — Jaisalmer', 'Jaisalmer & Sam Sand Dunes, Rajasthan', 
  'Arrive at Jaisalmer, a living citadel of golden sandstone rising from the Thar Desert. Walk the fort''s narrow lanes where families still reside, visit the ornate Patwon Ki Haveli with its carved balconies, then head into the Sam Sand Dunes for a camel safari as the desert turns from gold to crimson at sunset. Spend the night at a luxury desert camp under a canopy of stars, serenaded by Manganiar folk musicians playing the kamaycha.', '["Wander the living fort of Jaisalmer — one of the last inhabited forts in the world","Camel safari through Sam Sand Dunes at sunset","Overnight stay in a luxury desert camp with traditional Rajasthani feast","Stargazing in the Thar Desert and Manganiar folk music performance"]', 'https://images.pexels.com/photos/4314300/pexels-photo-4314300.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 5
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  2, 'Heritage Palace Stay', 'Sleep in a converted royal palace or fort — Rajasthan has more heritage hotels than anywhere on earth, from intimate havelis to former maharaja residences with gilded suites.', 'Castle', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  2, 'Camel Safari at Sunset', 'Ride through the undulating dunes of the Thar as the sun melts into the horizon, then dine under the stars at a desert camp while folk musicians play haunting melodies.', 'Sun', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  2, 'Block Printing Workshop', 'Learn the centuries-old craft of Sanganeri and Bagru block printing — carving teak stamps and pressing natural-dye patterns onto cotton with master artisans.', 'Paintbrush', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  2, 'Rajasthani Cooking Class', 'Master the art of dal baati churma, laal maas, and ker sangri in a home kitchen, grinding spices on a stone sil-batta and cooking over a traditional chulha fire.', 'ChefHat', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  2, 'Hot Air Balloon Over Jaipur', 'Float above the Pink City at dawn, drifting over Amber Fort, the Aravalli Hills, and the patchwork farmlands of rural Rajasthan as the first light turns everything gold.', 'Wind', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  2, 'Village Safari & Folk Music', 'Visit Bishnoi tribal villages near Jodhpur to witness a community that has practiced environmental conservation for five centuries, accompanied by live folk performances.', 'Music', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  2, 'Visit between October and March to avoid the extreme summer heat that can exceed 45°C (113°F).', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  2, 'Dress modestly when visiting temples and religious sites — shoulders and knees should be covered.', 1
);
INSERT INTO `tour_package_travel_tips` (
