INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'varanasi', 'Varanasi', 'India', 'South Asia', 
  'The eternal city where life, death, and the divine flow as one', 'https://images.pexels.com/photos/36565405/pexels-photo-36565405.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 'Varanasi is the oldest continuously inhabited city in the world — a place where the sacred and the everyday are woven so tightly together that it''s impossible to separate them. Along the western bank of the Ganges, 88 stone ghats descend into the river like a grand amphitheater, hosting an unbroken cycle of bathing, prayer, cremation, and celebration that has continued for over 3,000 years.

At dawn, the ghats come alive with pilgrims performing ritual ablutions in the honey-gold light, sadhus meditating beneath tattered umbrellas, and boatmen gliding silently past. By evening, the river''s edge transforms into a stage for the Ganga Aarti — a breathtaking fire ceremony where priests wave towering brass lamps in synchronized arcs, filling the air with the scent of camphor and marigold while thousands of clay diyas float downstream like earthbound stars.

Beyond the ghats, Varanasi''s labyrinthine alleys conceal silk-weaving workshops producing some of India''s finest Banarasi brocade, ancient Shiva temples echoing with the ring of brass bells, and tiny sweet shops where families have made the same milk-based delicacies for generations. A journey here is not a sightseeing trip — it is an encounter with the raw essence of existence.', 
  83, 25.32, 'Spiritual', 'bg-violet-500', 
  'The holiest city — Ganga Aarti, ancient ghats, and sacred rituals dating back millennia.', '/images/dest-22.jpg', 
  'published', '', '4 Days', 
  NULL, 'Indian Rupee (₹)', 'Humid subtropical with hot summers and cool, foggy winters', 'October–March (cooler temperatures, festival season)', 
  'Hindi, Bhojpuri, English in tourist areas', 'IST (UTC+5:30)', 'Left'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  3, 1, 'Dawn on the Ganges & the Ghats', 'Dashashwamedh Ghat, Varanasi', 
  'Rise before the sun and board a wooden rowboat for a dawn cruise along the ghats. Watch as the city awakens — priests chanting mantras, yogis holding impossible postures on stone platforms, children flying kites from rooftops, and funeral pyres smoldering at Manikarnika Ghat in a ritual unchanged for millennia. Disembark at Assi Ghat for a chai with the boatman, then walk the entire ghat stretch as the morning light paints the sandstone amber.', '["Sunrise boat ride past all 88 ghats with a knowledgeable boatman","Witness morning rituals and ablutions at Dashashwamedh Ghat","Observe the eternal cremation fires at Manikarnika Ghat from the river","Morning chai and paratha breakfast at a riverside stall near Assi Ghat"]', 'https://images.pexels.com/photos/36565405/pexels-photo-36565405.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  3, 2, 'Temples, Alleys & Ganga Aarti', 'Old City & Dashashwamedh Ghat, Varanasi', 
  'Plunge into Varanasi''s legendary old city — a maze of lanes barely wide enough for two people, where every turn reveals a shrine, a sweet shop, or a family of langur monkeys. Visit the Kashi Vishwanath Temple, one of Hinduism''s holiest sites, then seek out the Nepali Temple with its erotic wood carvings. As dusk falls, secure a prime spot on the steps of Dashashwamedh Ghat for the Ganga Aarti — a 45-minute fire ceremony of hypnotic devotion.', '["Navigate the ancient labyrinthine lanes of the old city on foot","Pay respects at the Kashi Vishwanath Temple (Golden Temple)","Taste the legendary Varanasi sweets — malaiyo, rabri, and thandai","Front-row experience of the Ganga Aarti fire ceremony at sunset"]', 'https://images.pexels.com/photos/36565405/pexels-photo-36565405.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  3, 3, 'Sarnath — Where Buddhism Began', 'Sarnath, near Varanasi', 
  'Drive 10 kilometers northeast to Sarnath, where Siddhartha Gautama delivered his first sermon after achieving enlightenment, setting the Wheel of Dharma in motion. Explore the Dhamek Stupa — a massive 5th-century brick monument — the Archaeological Museum housing the iconic four-lion Ashoka capital (now India''s national emblem), and the serene Mulagandha Kuti Vihar with its stunning Japanese murals depicting the Buddha''s life.', '["Circumambulate the 1,500-year-old Dhamek Stupa at Sarnath","View the original Ashoka Lion Capital in the Archaeological Museum","Meditate in the Mulagandha Kuti Vihar''s painted interior","Visit the Tibetan and Thai monasteries in Sarnath''s pilgrimage quarter"]', 'https://images.pexels.com/photos/5592369/pexels-photo-5592369.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  3, 4, 'Silk Weaving & Farewell to the Ganges', 'Weaver''s Quarter & Ramnagar, Varanasi', 
  'Spend the morning in the Muslim weaver''s quarter, where families have produced Banarasi silk brocade for over 500 years. Watch as weavers work handlooms with extraordinary precision, creating saris that take three to six months to complete and are passed down as heirlooms. Cross the Ganges by boat to explore the crumbling Ramnagar Fort and its eclectic museum, then return for a final sunset on the river — floating diyas in your wake as a blessing.', '["Watch master weavers create Banarasi silk brocade on handlooms","Learn about the zari (gold thread) techniques that date back to Mughal courts","Explore Ramnagar Fort''s collection of vintage cars, ivory, and astronomical clocks","Float clay diyas on the Ganges as a farewell offering at sunset"]', 'https://images.pexels.com/photos/5439052/pexels-photo-5439052.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  3, 'Ganga Aarti Ceremony', 'Witness the evening fire ceremony at Dashashwamedh Ghat — priests wave massive brass lamps in synchronized patterns while chanting ancient Vedic hymns to the river goddess.', 'Flame', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  3, 'Silk Weaving Workshop', 'Visit family workshops in the weaver''s quarter to see Banarasi silk being created on handlooms — an art form recognized by UNESCO and practiced for over five centuries.', 'Scissors', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  3, 'Dawn Boat Ride', 'Glide along the Ganges at first light as the city stirs to life — arguably the single most profound travel experience in all of India.', 'Sailboat', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  3, 'Classical Music Concert', 'Varanasi is the cradle of Hindustani classical music. Attend an intimate sitar or tabla recital in a riverside haveli — the city that produced Ravi Shankar still nurtures prodigies.', 'Music', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  3, 'Street Food Trail', 'Follow a local guide through the old city''s food lanes for kachori sabzi, tamatar chaat, creamy lassi, and the winter-only specialty malaiyo — a saffron milk foam.', 'Utensils', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  3, 'Hire a local guide for the old city lanes — GPS is unreliable in the narrow alleys.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  3, 'Remove shoes before entering any temple or stepping onto the lower ghat steps.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  3, 'Photography is prohibited at Manikarnika Ghat cremation area — respect the mourners.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  3, 'Visit Sarnath early in the morning to avoid crowds and heat.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  3, 'The Ganga Aarti starts at sunset (around 6:45 PM in winter, 7:15 PM in summer) — arrive 30 minutes early.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  3, 'Carry small denominations for donations at temples and for boat rides.', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  3, 'Beware of self-appointed ''guides'' at the ghats — arrange a reputable one through your hotel.', 6
);
