INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'bali', 'Bali', 'Indonesia', 'Southeast Asia', 
  'Island of the gods — where emerald rice terraces meet sacred temples', 'https://images.pexels.com/photos/2412711/pexels-photo-2412711.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 'Bali casts a spell that has drawn travelers for centuries. This small island — barely 150 kilometers across — contains an almost impossible diversity of landscapes and experiences: mist-shrouded volcanic peaks, sculpted rice terraces that cascade down hillsides like giant green staircases, ancient Hindu temples perched on sea cliffs, and beaches ranging from powdery white to dramatic volcanic black.

At Bali''s spiritual heart lies Ubud, a town of artists, healers, and ceremony. Every morning, Balinese women place tiny palm-leaf offerings (canang sari) on doorsteps, dashboards, and temple altars — a reminder that the sacred infuses every aspect of daily life here. The island''s unique form of Hinduism, blended with animist and Buddhist elements, produces a calendar overflowing with processions, dance performances, and temple festivals.

Beyond the spiritual, Bali rewards the senses: world-class surf breaks crash against coral reefs, spas set in jungle ravines offer flower-petal baths, and farm-to-table restaurants serve dishes made with ingredients harvested that morning from volcanic soil. Whether you seek transformation or relaxation, Bali delivers both in abundance.', 
  115.2, -8.3, 'Spiritual', 'bg-violet-500', 
  'Hindu temples, rice terrace meditation, sacred monkey forests, and healing retreats.', '/images/dest-10.jpg', 
  'published', '', '5 Days', 
  'Denpasar', 'Indonesian Rupiah (Rp)', 'Tropical with dry season (April–October) and wet season (November–March)', 'April–October (dry season, ideal for beaches and trekking)', 
  'Balinese, Indonesian (Bahasa), English widely spoken in tourist areas', 'WITA (UTC+8)', 'Left'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  4, 1, 'Ubud — Art, Jungle & Ceremony', 'Ubud, Bali', 
  'Begin in Ubud, Bali''s cultural capital. Walk through the Sacred Monkey Forest Sanctuary, where long-tailed macaques leap between moss-covered stone temples. Explore the Ubud Royal Palace, then wander the town''s galleries showcasing everything from traditional Balinese painting to contemporary installation art. End the day with a Kecak fire dance performance at sunset — 100 bare-chested men chanting in concentric circles as the Ramayana epic unfolds.', '["Walk among 700 macaques in the Sacred Monkey Forest Sanctuary","Browse world-class Balinese art galleries along Jalan Raya Ubud","Witness the hypnotic Kecak fire dance at Ubud Palace at dusk","Dinner at a cliffside restaurant overlooking the Ayung River gorge"]', 'https://images.pexels.com/photos/2412711/pexels-photo-2412711.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  4, 2, 'Tegallalang Rice Terraces & Water Temples', 'Tegallalang & Tirta Empul, Bali', 
  'Drive north to the Tegallalang Rice Terraces — a cascade of luminous green paddies sculpted into a steep valley using the ancient subak irrigation system, a UNESCO-recognized cooperative water-management tradition. Continue to Tirta Empul, a 1,000-year-old water temple where Balinese Hindus purify themselves under 30 sacred spring fountains. With permission, join the purification ritual as crystal-clear water pours over your shoulders.', '["Walk along the sculpted ridges of Tegallalang Rice Terraces","Participate in a purification ritual at Tirta Empul''s sacred springs","Lunch at a restaurant with infinity-pool views over the rice paddies","Visit a traditional Balinese coffee plantation and taste luwak coffee"]', 'https://images.pexels.com/photos/2088019/pexels-photo-2088019.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  4, 3, 'Tanah Lot & Jatiluwih', 'Tanah Lot & Jatiluwih, Bali', 
  'Journey west to the Jatiluwih Rice Terraces, a vast UNESCO World Heritage landscape far less visited than Tegallalang, where paddies stretch to the horizon beneath the volcanic cone of Mount Batukaru. Trek through the terraces with a local farmer, learning how the subak system distributes water equally across hundreds of fields. In the late afternoon, reach Tanah Lot — a sea temple perched on a rocky islet, silhouetted against one of Bali''s most photographed sunsets.', '["Trek through the expansive UNESCO-listed Jatiluwih Rice Terraces","Learn the subak irrigation system from a local rice farmer","Watch the sunset behind Tanah Lot''s silhouetted sea temple","Explore the holy caves and freshwater spring beneath the temple rock"]', 'https://images.pexels.com/photos/7612816/pexels-photo-7612816.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  4, 4, 'Uluwatu Cliff Temple & Southern Beaches', 'Uluwatu & Bukit Peninsula, Bali', 
  'Head south to the dramatic Bukit Peninsula, where limestone cliffs plunge into turquoise surf. Visit Uluwatu Temple, a 10th-century clifftop shrine 70 meters above the Indian Ocean, where cheeky monkeys guard the entrance. Descend to Padang Padang Beach — a hidden cove accessed through a narrow rock crevice — for a swim in gin-clear water. Return to Uluwatu for the cliff-edge Kecak dance as the sun drops into the sea behind the performers.', '["Explore Uluwatu Temple perched 70 meters above crashing waves","Swim at the secret Padang Padang Beach through a rock crevice","Watch surfers tackle Uluwatu''s legendary left-hand break","Sunset Kecak fire dance on the Uluwatu clifftop amphitheater"]', 'https://images.pexels.com/photos/6015320/pexels-photo-6015320.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  4, 5, 'Seminyak Beach & Farewell Bali', 'Seminyak, Bali', 
  'End the journey in Seminyak, Bali''s most stylish coastal district. Spend the morning at a luxurious Balinese spa — a two-hour Boreh body scrub using volcanic spices, followed by a flower-petal bath in a stone tub overlooking tropical gardens. Stroll Seminyak''s boutique-lined streets for handmade jewelry and resort wear, then settle into a beanbag on the beach with a fresh coconut as the final Bali sunset streaks the sky in shades of tangerine and violet.', '["Indulge in a traditional Boreh spice scrub and flower-petal bath","Shop for artisan jewelry and textiles along Jalan Laksmana","Beachfront farewell dinner at a top Seminyak seafood restaurant","Sunset cocktails on the sand with live acoustic music"]', 'https://images.pexels.com/photos/36184005/pexels-photo-36184005.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  4, 'Mount Batur Sunrise Trek', 'Hike an active volcano in the pre-dawn darkness, reaching the crater rim as the sun erupts over the horizon, illuminating Lake Batur and Mount Agung in spectral light.', 'Mountain', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  4, 'Balinese Cooking Class', 'Start with a market tour to source fresh galangal, lemongrass, and palm sugar, then cook a full Balinese feast — sate lilit, lawar, and bebek betutu — in an open-air kitchen surrounded by rice fields.', 'ChefHat', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  4, 'Snorkeling at Nusa Penida', 'Speed-boat to the neighboring island of Nusa Penida and snorkel alongside manta rays at Manta Point and over pristine coral gardens at Crystal Bay.', 'Waves', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  4, 'Traditional Balinese Massage', 'Experience a two-hour treatment blending long acupressure strokes with aromatic frangipani oil in a spa pavilion overlooking a river gorge or tropical garden.', 'Heart', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  4, 'Waterfall Chasing', 'Discover hidden cascades in Bali''s lush interior — Tegenungan, Sekumpul, and Tukad Cepung, where sunlight pierces a cave to illuminate a curtain of falling water.', 'Droplets', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  4, 'Rent a scooter only if you''re an experienced rider — Bali''s traffic is chaotic and travel insurance often excludes motorbike injuries.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  4, 'Always carry a sarong and sash for temple visits — they''re required at every Balinese Hindu temple.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  4, 'Tap water is not drinkable; most hotels and restaurants provide refillable filtered water.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  4, 'The dry season (April–October) is ideal; the wet season brings afternoon downpours but also lush green landscapes and fewer crowds.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  4, 'Negotiate taxi fares in advance or use ride-hailing apps like Grab and Gojek for transparent pricing.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  4, 'Respect the canang sari offerings placed on the ground — step around them, never on them.', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  4, 'Learn basic Indonesian: ''Terima kasih'' (thank you) and ''Permisi'' (excuse me) go a long way.', 6
);
