INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'paris', 'Paris', 'France', 'Europe', 
  'The luminous city of art, haute cuisine, and timeless romance', 'https://images.pexels.com/photos/6059888/pexels-photo-6059888.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 'Paris needs no introduction, yet it forever surprises. The City of Light is a living museum where every boulevard, bridge, and boulangerie tells a story — from the Gothic majesty of Notre-Dame to the iron lattice of the Eiffel Tower, from the Impressionist canvases of Musée d''Orsay to the cutting-edge installations of the Palais de Tokyo. It is a city designed for lingering: over a café crème at a zinc-topped bar, along the Seine''s bouquiniste bookstalls, through the manicured allées of the Tuileries.

But Paris is far more than its monuments. It is the crunch of a perfect baguette at 7 a.m., the hush of a candlelit wine bar in the Marais, the exhilaration of stumbling upon a jazz trio playing in a Metro tunnel. Each arrondissement has its own personality — the bohemian energy of Belleville, the aristocratic calm of Saint-Germain, the multicultural bustle of the Goutte d''Or.

Whether you are returning for the tenth time or seeing the Eiffel Tower sparkle for the first, Paris delivers a singular magic: the conviction that beauty, pleasure, and intellectual life are not luxuries but necessities.', 
  2.35, 48.86, 'Historical', 'bg-amber-600', 
  'Louvre, Versailles, Notre-Dame — centuries of art, revolution, and romance.', '/images/tour-5.jpg', 
  'published', '', '4 Days', 
  'Paris (national capital)', 'Euro (€)', 'Oceanic; mild summers, cool winters, rain throughout the year', 'April–June & September–October (mild weather, fewer crowds than July–August)', 
  'French; English widely understood in tourist areas', 'CET (UTC+1) / CEST (UTC+2) in summer', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  6, 1, 'Eiffel Tower, Seine & Left Bank', '7th Arrondissement, Paris', 
  'Begin with the icon. Ascend the Eiffel Tower to the summit for a bird''s-eye panorama of the city''s zinc rooftops and grand avenues, then descend for a picnic of cheese, charcuterie, and rosé on the Champ de Mars. In the afternoon, stroll along the Left Bank of the Seine, browsing the bouquinistes'' vintage book stalls, before settling into a café terrace in Saint-Germain-des-Prés — the literary quarter once haunted by Hemingway and Sartre.', '["Sunrise ascent to the Eiffel Tower summit for city-wide views","Gourmet picnic on the Champ de Mars with local cheeses and wine","Browse vintage books and prints at Seine-side bouquiniste stalls","Evening café crème at Café de Flore in Saint-Germain-des-Prés"]', 'https://images.pexels.com/photos/6059888/pexels-photo-6059888.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  6, 2, 'The Louvre, Tuileries & Marais', '1st & 4th Arrondissements, Paris', 
  'Devote the morning to the Louvre — not trying to see everything, but savoring key works: the Winged Victory of Samothrace, Vermeer''s The Lacemaker, and of course the Mona Lisa. Emerge into the Tuileries Garden for a moment of green calm, then walk to the Marais — Paris''s most charismatic quarter, a tapestry of medieval hôtels particuliers, Jewish bakeries, LGBTQ+ nightlife, and concept stores in 17th-century courtyards.', '["Guided highlights tour of the Louvre''s masterpieces in 3 hours","Stroll through the Tuileries Garden to Place de la Concorde","Explore the Marais — vintage shops, falafel on Rue des Rosiers","Evening at Place des Vosges, Paris''s oldest and most beautiful square"]', 'https://images.pexels.com/photos/36040350/pexels-photo-36040350.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  6, 3, 'Montmartre, Sacré-Cœur & Hidden Paris', '18th Arrondissement, Paris', 
  'Climb the cobbled lanes of Montmartre to the gleaming white basilica of Sacré-Cœur, whose steps offer a sweeping view across the entire city. Wander through the Place du Tertre, still alive with portrait artists, then descend to explore the lesser-known passages couverts — glass-roofed shopping arcades from the 19th century, filled with antique dealers, rare-book sellers, and old-world tea rooms.', '["Sunrise at Sacré-Cœur for panoramic views before the crowds arrive","Explore Montmartre''s artists'' quarter and Place du Tertre","Discover the covered passages — Galerie Vivienne and Passage des Panoramas","Wine tasting at a cave à vin in the 9th arrondissement"]', 'https://images.pexels.com/photos/5005317/pexels-photo-5005317.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  6, 4, 'Versailles — Palace of the Sun King', 'Versailles, Île-de-France', 
  'Take the RER train to Versailles, the palace Louis XIV built to awe the world — and it still does. Wander the Hall of Mirrors, where 357 mirrors reflect the light of 20,000 candles, then escape to the formal gardens with their geometric parterres, fountains, and the intimate Petit Trianon where Marie Antoinette played at country life. Return to Paris for a final dinner at a bistro serving classic onion soup, duck confit, and crème brûlée.', '["Walk the Hall of Mirrors in the Palace of Versailles","Explore the formal gardens during the Grande Eaux fountain show","Visit Marie Antoinette''s Petit Trianon and hamlet","Farewell dinner at a classic Parisian bistro with onion soup and duck confit"]', 'https://images.pexels.com/photos/5972294/pexels-photo-5972294.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  6, 'Pastry & Chocolate Tour', 'Follow a food historian through Saint-Germain tasting croissants, éclairs, macarons, and artisan chocolates at the ateliers that define French pâtisserie.', 'Cake', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  6, 'Seine River Cruise', 'Glide past Notre-Dame, the Louvre, and the Musée d''Orsay on an evening dinner cruise, watching the Eiffel Tower sparkle on the hour as champagne flows.', 'Ship', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  6, 'Musée d''Orsay & Impressionism', 'Spend an afternoon with Monet''s water lilies, Renoir''s dancers, and Van Gogh''s Starry Night Over the Rhône in the former Beaux-Arts railway station.', 'Palette', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  6, 'Cooking Class in Le Marais', 'Learn to prepare a three-course French meal — mastering sauces, soufflés, and the art of the perfect tarte tatin — in a professional kitchen with a Cordon Bleu chef.', 'ChefHat', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  6, 'Jazz in a Cave Club', 'Descend into a stone-vaulted cellar in the Latin Quarter for live jazz — Paris''s underground clubs have nurtured the genre since the days of Django Reinhardt.', 'Music', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  6, 'Buy a Paris Museum Pass (2 or 4 days) for skip-the-line access to the Louvre, Orsay, Versailles, and 50+ museums.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  6, 'The Métro is fast and cheap — buy a carnet of 10 tickets or use the Navigo Découverte weekly pass.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  6, 'Restaurants serve lunch from 12–2 PM and dinner from 7:30–10 PM; arriving outside these hours may mean closed kitchens.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  6, 'A simple ''Bonjour'' when entering any shop or café is considered essential politeness.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  6, 'Pickpockets operate around tourist hotspots — use a cross-body bag and stay aware on the Métro.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  6, 'Tap water is free and excellent; ask for ''une carafe d''eau'' at restaurants instead of bottled.', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  6, 'Most shops close on Sundays except in the Marais and along the Champs-Élysées.', 6
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  6, 'https://images.pexels.com/photos/6059888/pexels-photo-6059888.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  6, 'https://images.pexels.com/photos/36040350/pexels-photo-36040350.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  6, 'https://images.pexels.com/photos/5005317/pexels-photo-5005317.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_images` (
