INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'machu-picchu', 'Machu Picchu', 'Peru', 'Americas', 
  'The lost citadel of the Incas, veiled in cloud and mystery', '/images/dest-17.jpg', 'Perched at 2,430 meters on a razor-thin ridge between two Andean peaks, Machu Picchu is one of the most extraordinary achievements of any civilization. Built in the 15th century as a royal estate for the Inca emperor Pachacuti, then abandoned during the Spanish conquest and swallowed by cloud forest for nearly 400 years, the citadel was only revealed to the outside world in 1911 — and it has not stopped astonishing visitors since.

The ruins are a masterclass in Inca engineering: massive granite blocks fitted without mortar so precisely that a knife blade cannot slip between them, terraces that prevented erosion on near-vertical slopes, and an astronomical observatory — the Intihuatana stone — aligned to mark the solstices with shadow. The setting amplifies the wonder: swirling mists part to reveal Huayna Picchu''s green spire, condors ride thermals above the Urubamba gorge, and the silence is broken only by wind and birdsong.

The journey to Machu Picchu is as remarkable as the destination. Whether you hike the classic Inca Trail through mountain passes and subtropical forest, take the scenic train along the Urubamba River, or explore the Sacred Valley''s markets and ruins en route, the experience builds to a crescendo that no photograph can fully convey.', 
  -72.55, -13.16, 'Historical', 'bg-amber-600', 
  'Lost city of the Incas — stone citadel above the clouds and a global wonder.', '/images/about-8.jpg', 
  'published', '', '5 Days', 
  'Lima (national capital)', 'Peruvian Sol (S/.)', 'Cool and humid subtropical at altitude; dry season May–September', 'May–September (dry season with clearer skies; June–August busiest)', 
  'Spanish, Quechua', 'PET (UTC-5)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  7, 1, 'Arrival in Cusco — Imperial City of the Incas', 'Cusco, Peru', 
  'Arrive in Cusco, the ancient Inca capital at 3,400 meters, and spend the day acclimatizing to the altitude. Walk the cobblestone streets where Inca stonework forms the foundations of Spanish colonial buildings. Visit the Qorikancha — once the richest temple in the Inca world, its walls sheathed in gold — now topped by the Santo Domingo convent. End the evening in the lively San Pedro Market, sipping coca tea to ward off altitude sickness.', '["Explore Cusco''s Plaza de Armas surrounded by Inca and colonial architecture","Visit Qorikancha, the Inca Temple of the Sun, with its precision stonework","Taste Peruvian street food at San Pedro Market — empanadas, juices, ceviche","Sip coca tea and acclimatize in a courtyard café"]', '/images/tour-8.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  7, 2, 'The Sacred Valley — Pisac & Ollantaytambo', 'Sacred Valley, Peru', 
  'Descend into the Sacred Valley of the Urubamba River, the agricultural heartland of the Inca Empire. At Pisac, explore the ruins of a hilltop fortress and browse the vibrant artisan market for hand-woven textiles and painted ceramics. Continue to Ollantaytambo, a living Inca town where water still flows through original stone channels and the massive temple-fortress looms above narrow streets unchanged in 600 years.', '["Hike the Pisac archaeological site overlooking the Sacred Valley","Shop for hand-woven alpaca textiles at Pisac''s artisan market","Climb the monumental stone terraces of Ollantaytambo''s temple-fortress","Walk the living Inca streets of Ollantaytambo — still inhabited after 600 years"]', '/images/dest-18.jpg', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  7, 3, 'Inca Trail Trek — Cloud Forest & Mountain Passes', 'Inca Trail, Cusco Region', 
  'Begin the final stretch of the classic Inca Trail, hiking through ecosystems that shift from high-altitude grassland to dripping cloud forest. Pass through Wiñay Wayna — an exquisitely preserved set of agricultural terraces and fountains cascading down a steep slope — as orchids, hummingbirds, and bromeliads line the stone-paved path. Camp within earshot of the ruins, anticipating tomorrow''s dawn arrival at the Sun Gate.', '["Hike ancient Inca stone pathways through cloud forest and alpine meadows","Discover the cascading terraces and fountains of Wiñay Wayna","Spot Andean orchids, hummingbirds, and spectacled bear habitat","Camp in the mountains with views of the Urubamba gorge below"]', '/images/explor-4.jpg', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  7, 4, 'Machu Picchu — The Citadel Revealed', 'Machu Picchu, Peru', 
  'Rise in the dark and hike the final steps to Inti Punku, the Sun Gate. As the first rays of light pierce the mist, Machu Picchu materializes below — a breathtaking panorama of temples, plazas, and terraces framed by the green spire of Huayna Picchu. Descend into the citadel with a specialist guide, exploring the Temple of the Sun, the Room of Three Windows, and the Intihuatana stone, Inca astronomy carved in granite.', '["Sunrise arrival through Inti Punku (the Sun Gate) with mist parting over the ruins","Guided tour of the Temple of the Sun and astronomical Intihuatana stone","Photograph the classic postcard view from the Caretaker''s Hut","Optional climb of Huayna Picchu for a vertigo-inducing aerial perspective"]', '/images/hero-destinations.jpg', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  7, 5, 'Aguas Calientes & Return to Cusco', 'Aguas Calientes & Cusco, Peru', 
  'Spend the morning revisiting Machu Picchu''s quieter corners as the early crowds thin, or soak sore muscles in the thermal hot springs that give Aguas Calientes its name. Board the Vistadome train back through the Urubamba gorge — panoramic glass ceilings framing the snow-capped Andes — and return to Cusco for a celebratory dinner of Peruvian-fusion cuisine: ceviche, alpaca steak, and a pisco sour crafted tableside.', '["Second morning entry to Machu Picchu for crowd-free exploration","Soak in the natural thermal springs of Aguas Calientes","Scenic Vistadome train ride through the Urubamba gorge","Celebratory pisco sour and Peruvian-fusion dinner in Cusco"]', '/images/tour-9.jpg', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  7, 'Classic Inca Trail Hike', 'Trek 43 kilometers over four days through mountain passes, cloud forests, and ancient Inca ruins, culminating in the dramatic sunrise arrival at the Sun Gate above Machu Picchu.', 'Footprints', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  7, 'Peruvian Cooking Class', 'Learn to prepare ceviche, lomo saltado, and causa in a Cusco kitchen, using Andean superfoods like quinoa, maca, and purple corn that the Incas cultivated centuries ago.', 'ChefHat', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  7, 'Textile Weaving Demonstration', 'Visit a women''s weaving cooperative in the Sacred Valley to learn how Quechua artisans spin alpaca wool and create intricate patterns encoding Andean cosmology.', 'Scissors', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  7, 'Mountain Biking Maras to Moray', 'Ride downhill through the Sacred Valley from the Maras salt terraces to the concentric Moray amphitheater — an Inca agricultural laboratory testing crop varieties at different altitudes.', 'Bike', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  7, 'Pisco Sour Masterclass', 'Join a mixologist in Cusco''s San Blas neighborhood to learn the art of Peru''s national cocktail — pisco, lime, egg white, and Angostura bitters shaken to frothy perfection.', 'GlassWater', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  7, 'Spend at least two days in Cusco before hiking to acclimatize to the 3,400 m altitude — rushing causes altitude sickness.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  7, 'Inca Trail permits are limited to 500 per day (including porters) and sell out months in advance — book 6+ months ahead.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  7, 'Coca tea (mate de coca) is a traditional and effective remedy for altitude headaches; it''s legal and sold everywhere.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  7, 'Bring layers — temperatures can swing from 25°C in the sun to near freezing at night in the mountains.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  7, 'Book Machu Picchu entry tickets in advance; timed-entry slots and daily visitor caps are strictly enforced.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  7, 'Rain gear is essential even in the dry season — Machu Picchu''s cloud-forest location means mist and showers can arrive at any time.', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  7, 'Hire a licensed guide at Machu Picchu — the ruins are far more meaningful with expert interpretation.', 6
);
