INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'istanbul', 'Istanbul', 'Turkey', 'Middle East', 
  'Where continents collide and empires echo through every stone', 'https://images.pexels.com/photos/7539810/pexels-photo-7539810.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 'Istanbul is the only city in the world that straddles two continents, and this geographic drama shapes everything about it. For over 1,600 years, it served as the capital of two of history''s greatest empires — the Byzantine and the Ottoman — and their layered legacy is visible everywhere: in the soaring dome of Hagia Sophia, the cascading courtyards of Topkapi Palace, the 4,000 shops of the Grand Bazaar, and the six slender minarets of the Blue Mosque.

But Istanbul is no museum city. It pulses with a ferocious modern energy. Rooftop bars overlook the Bosphorus where container ships glide between Europe and Asia, hole-in-the-wall meyhanes serve raki and meze until 3 a.m., and contemporary art fills repurposed Ottoman warehouses. The food alone justifies the journey — from simit vendors on every corner to the smoky perfection of a kebab at a century-old lokanta.

Add a day trip to the surreal landscapes of Cappadocia — fairy chimneys, cave churches, and dawn balloon flights — and you have a journey that spans millennia of human ambition, artistry, and faith.', 
  29, 41, 'Historical', 'bg-amber-600', 
  'Hagia Sophia, Blue Mosque, Grand Bazaar — where empires left their mark.', '/images/city-5.jpg', 
  'published', '', '4 Days', 
  'Ankara (national capital); Istanbul is the cultural capital', 'Turkish Lira (₺)', 'Oceanic transitioning to Mediterranean; warm summers, cool winters', 'April–May & September–November (mild weather, thinner crowds)', 
  'Turkish; English spoken in tourist areas', 'TRT (UTC+3)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  8, 1, 'Sultanahmet — Hagia Sophia & Blue Mosque', 'Sultanahmet, Istanbul', 
  'Begin in Sultanahmet, Istanbul''s historic heart. Enter Hagia Sophia — for a thousand years the largest enclosed space on earth — and gaze up at the colossal dome that seems to float on a ring of light, its walls bearing both Byzantine mosaics and Ottoman calligraphy. Cross the garden to the Blue Mosque, named for the 20,000 Iznik tiles that create a shimmering azure interior, then explore the Hippodrome, the ancient chariot-racing arena now an elegant public square.', '["Stand beneath Hagia Sophia''s 56-meter dome and Byzantine gold mosaics","Admire the 20,000 hand-painted Iznik tiles inside the Blue Mosque","Walk the ancient Hippodrome past the Egyptian Obelisk and Serpentine Column","Turkish coffee and baklava at a café overlooking the minarets"]', 'https://images.pexels.com/photos/7539810/pexels-photo-7539810.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  8, 2, 'Topkapi Palace & Grand Bazaar', 'Sultanahmet & Beyazit, Istanbul', 
  'Spend the morning at Topkapi Palace, the opulent nerve-center of the Ottoman Empire for 400 years. Wander through the Harem''s tiled chambers, the Treasury''s emerald-encrusted daggers and 86-carat Spoonmaker''s Diamond, and the terrace overlooking the confluence of the Bosphorus and Golden Horn. In the afternoon, lose yourself in the Grand Bazaar — 61 covered streets, 4,000 shops, and five centuries of commerce under vaulted ceilings.', '["Tour Topkapi Palace''s Harem, Treasury, and Bosphorus terrace","See the 86-carat Spoonmaker''s Diamond and Topkapi Dagger","Haggle for hand-painted ceramics and kilim rugs in the Grand Bazaar","Evening fish sandwich from the boats at Eminönü dock by the Galata Bridge"]', 'https://images.pexels.com/photos/36229688/pexels-photo-36229688.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  8, 3, 'Bosphorus Cruise & Asian Istanbul', 'Bosphorus & Kadıköy, Istanbul', 
  'Board a ferry for a Bosphorus cruise, gliding between Europe and Asia past ornate Ottoman waterfront mansions (yalıs), the medieval Rumeli Fortress, and the gleaming new suspension bridges. Disembark on the Asian side at Kadıköy, a lively neighborhood of markets, vintage shops, and meyhane taverns. Wander through the fish market, taste the famous midye dolma (stuffed mussels), and return by ferry at sunset as the skyline of mosques and minarets is silhouetted in gold.', '["Bosphorus ferry cruise past Ottoman yalıs and Rumeli Fortress","Explore Kadıköy''s vibrant street art, markets, and food scene on the Asian side","Taste midye dolma (stuffed mussels) and fresh pomegranate juice","Sunset ferry return with the Sultanahmet skyline glowing amber"]', 'https://images.pexels.com/photos/36194906/pexels-photo-36194906.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  8, 4, 'Cappadocia — Fairy Chimneys & Balloon Flight', 'Cappadocia, Central Turkey', 
  'Fly to Cappadocia for the trip''s unforgettable finale. Rise before dawn to float in a hot-air balloon over a landscape that defies belief — thousands of fairy-chimney rock formations, cave churches carved by early Christians, and valleys striped in shades of rose, cream, and ochre. After landing, explore the underground city of Derinkuyu, a multi-level subterranean settlement that once sheltered 20,000 people, then watch the sunset paint the Göreme valley in impossible colors.', '["Hot-air balloon flight over Cappadocia''s fairy chimneys at sunrise","Explore the eight-level underground city of Derinkuyu","Visit the rock-hewn churches and Byzantine frescoes of the Göreme Open-Air Museum","Sunset over the Rose Valley from a panoramic viewpoint"]', 'https://images.pexels.com/photos/4973584/pexels-photo-4973584.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  8, 'Turkish Hammam Experience', 'Surrender to centuries of bathing tradition in a marble-domed hammam — hot steam, exfoliating kese scrub, and a foam massage beneath Ottoman-era architecture.', 'Droplets', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  8, 'Bosphorus Sunset Cruise', 'Charter a private gulet or join a public ferry for an evening cruise between continents, sipping Turkish tea as palaces and fortresses drift past on both shores.', 'Ship', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  8, 'Spice Bazaar & Food Tour', 'Navigate the aromatic Spice Bazaar and back-street eateries with a local guide, sampling Turkish delight, sujuk, kaymak with honey, and freshly ground Turkish coffee.', 'Utensils', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  8, 'Cappadocia Hot Air Balloon', 'Float silently above a landscape of fairy chimneys and cave dwellings at dawn — one of the world''s most iconic balloon flights, with hundreds of balloons filling the sky.', 'Wind', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  8, 'Whirling Dervish Ceremony', 'Witness the Mevlevi Sema ceremony — white-robed dervishes spinning in meditative trance, a 750-year-old Sufi ritual of spiritual union with the divine.', 'RotateCw', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  8, 'The Istanbulkart transit card works on ferries, trams, metro, and buses — essential for getting around cheaply.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  8, 'Remove shoes before entering mosques; women should cover their heads (scarves are available at mosque entrances).', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  8, 'Bargaining is expected in the Grand Bazaar and Spice Bazaar — start at about 50% of the asking price.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  8, 'Book Cappadocia balloon flights well in advance, especially for April–November season; flights cancel for weather.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  8, 'Istanbul''s traffic is legendary — use ferries and trams instead of taxis during rush hour.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  8, 'Try the street food: simit (sesame bread rings), balık ekmek (fish sandwiches), and kestane (roasted chestnuts).', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  8, 'Tipping 5–10% is customary at restaurants; round up for taxis.', 6
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  8, 'https://images.pexels.com/photos/7539810/pexels-photo-7539810.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  8, 'https://images.pexels.com/photos/36229688/pexels-photo-36229688.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  8, 'https://images.pexels.com/photos/36194906/pexels-photo-36194906.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_images` (
