INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'masai-mara', 'Masai Mara', 'Kenya', 'Africa', 
  'The great theatre of the wild, where the savannah teems with life', 'https://images.pexels.com/photos/226368/pexels-photo-226368.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 'The Masai Mara is the undisputed crown jewel of African safari. This 1,510-square-kilometer expanse of golden grassland, punctuated by acacia woodland and the winding Mara River, supports one of the densest concentrations of wildlife on the planet. Lions lounge in the shade of flat-topped trees, leopards drape themselves over branches, elephants move in silent herds, and — for a few breathtaking weeks each year — over two million wildebeest pour across the Mara River in the Great Migration, one of nature''s most awe-inspiring spectacles.

But the Mara is more than a wildlife reserve. It is the ancestral homeland of the Maasai people, semi-nomadic pastoralists whose red-robed warriors and beaded jewelry have become iconic images of East Africa. A visit to a Maasai village offers a window into a culture that has coexisted with lions and elephants for centuries — a relationship of mutual respect born of necessity.

Whether you''re witnessing a cheetah''s explosive sprint across the plains, sipping sundowners as hippos grunt in a nearby pool, or falling asleep in a luxury tented camp to the distant rumble of a lion''s roar, the Masai Mara delivers an experience that recalibrates your sense of wonder.', 
  35.3, -1.5, 'Safari', 'bg-green-600', 
  'Witness the Great Migration and Big Five encounters.', '/images/tour-1.jpg', 
  'published', '', '4 Days', 
  'Nairobi', 'Kenyan Shilling (KSh)', 'Tropical highland; warm days, cool nights, two rainy seasons', 'July–October (Great Migration river crossings; dry season)', 
  'Swahili, English', 'EAT (UTC+3)', 'Left'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  10, 1, 'Arrival & First Game Drive', 'Masai Mara National Reserve', 
  'Fly from Nairobi to the Mara in a light aircraft, landing on a red-earth airstrip surrounded by savannah. Transfer to your luxury tented camp, settle in, then head out for an afternoon game drive. Within the first hour, you are likely to spot several of the Big Five — lion, elephant, buffalo — along with giraffe, zebra, and a kaleidoscope of birdlife. Watch the sunset paint the Mara in shades of amber and rose while sipping a cold Tusker beer on the open-top vehicle.', '["Scenic bush-plane flight from Nairobi over the Great Rift Valley","Afternoon game drive with Big Five sightings","Sundowner cocktails on the savannah as the sun sets behind acacia trees","Return to camp for a bush dinner under the Southern Cross stars"]', 'https://images.pexels.com/photos/226368/pexels-photo-226368.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  10, 2, 'Great Migration & Mara River Crossing', 'Mara River, Masai Mara', 
  'Rise before dawn for the day''s main event — a drive to the Mara River crossing points. If timing and nature cooperate, you will witness one of Earth''s greatest wildlife spectacles: vast columns of wildebeest gathering on the riverbank, then plunging into the crocodile-infested waters in a desperate surge to reach fresh grazing on the other side. Even outside migration season, the Mara River teems with hippo pods and monster Nile crocodiles.', '["Position at a Mara River crossing point at dawn for wildebeest migration","Witness the dramatic river crossing — predator-prey drama in real time","Spot Nile crocodiles and hippo pods along the riverbanks","Picnic lunch under an acacia tree on the open savannah"]', 'https://images.pexels.com/photos/12748795/pexels-photo-12748795.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  10, 3, 'Maasai Village & Predator Tracking', 'Maasai Community & Masai Mara', 
  'Visit a traditional Maasai village (manyatta) to meet the community, watch warriors perform the adumu jumping dance, learn how enkang homes are built from cow dung and clay, and hear elders share stories of coexisting with wildlife. In the afternoon, join a specialist guide to track predators — lion prides, solitary leopards in riverine forest, and cheetah mothers teaching cubs to hunt on the open plains.', '["Cultural immersion in a Maasai manyatta village with warrior dance","Track a lion pride on an afternoon predator-focused game drive","Search for elusive leopards in the riverine forest along the Mara","Photograph cheetahs hunting on the open Mara plains at golden hour"]', 'https://images.pexels.com/photos/6299632/pexels-photo-6299632.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  10, 4, 'Hot Air Balloon Safari & Farewell', 'Masai Mara National Reserve', 
  'Cap the safari with its most magical experience: a dawn hot-air balloon flight over the Mara. Float silently above herds of zebra and wildebeest, spot elephants and giraffe from above, and watch the shadow of your balloon ripple across the golden grass. Land for a champagne bush breakfast laid out on white linen in the middle of the savannah, with hippos grunting nearby in the river. Transfer to the airstrip for the flight back to Nairobi.', '["Sunrise hot-air balloon flight over the Masai Mara savannah","Aerial views of herds, river crossings, and predator tracks below","Champagne bush breakfast on white linen in the open savannah","Final game drive en route to the airstrip for departure"]', 'https://images.pexels.com/photos/7780132/pexels-photo-7780132.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  10, 'Big Five Game Drive', 'Track lion, leopard, elephant, buffalo, and rhino across the Mara''s grasslands and riverine forests with an expert Maasai guide reading the landscape like a book.', 'Binoculars', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  10, 'Hot Air Balloon Safari', 'Float above the savannah at sunrise, watching wildlife from a silent aerial perspective, followed by a champagne breakfast served in the bush.', 'Wind', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  10, 'Maasai Cultural Visit', 'Enter a traditional manyatta, learn warrior dances and fire-making, and purchase beaded jewelry directly from the artisans — all proceeds support the community.', 'Users', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  10, 'Night Game Drive', 'After dark, the Mara reveals its nocturnal residents — aardvarks, bush babies, serval cats, and hunting hyenas — spotted by the red-filtered beam of a tracker''s spotlight.', 'Moon', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  10, 'Bush Walking Safari', 'Step out of the vehicle for a guided walking safari with a Maasai warrior, learning to read animal tracks, identify medicinal plants, and experience the bush at ground level.', 'Footprints', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  10, 'The Great Migration river crossings typically occur July–October, but wildlife is abundant year-round.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  10, 'Pack neutral-colored clothing (khaki, olive, tan) — bright colors can disturb wildlife.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  10, 'Binoculars are essential; a 10x42 pair is ideal for game viewing.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  10, 'Antimalarial medication is strongly recommended; the Mara is in a malaria zone.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  10, 'Bring a quality zoom lens (200–400 mm) for wildlife photography; dust-proof camera bags are wise.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  10, 'Respect the wildlife — never stand up in the vehicle, make sudden movements, or use flash photography.', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  10, 'Bush camp accommodations book out 6–12 months ahead during migration season — plan early.', 6
);
