INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'new-york-city', 'New York City', 'USA', 'Americas', 
  'The city that never sleeps — eight million stories in the naked city', '/images/banner-3.jpg', 'New York City is the ultimate urban experience — a place where ambition, creativity, and sheer human density have produced something unlike anywhere else on earth. From the Art Deco spire of the Chrysler Building catching the morning sun to the neon canyon of Times Square at midnight, from the hushed galleries of the Met to the raucous energy of a Harlem gospel brunch, NYC operates on a frequency that simultaneously exhausts and exhilarates.

Each borough is a world unto itself. Manhattan packs iconic landmarks into a narrow island: Central Park''s 843 acres of green calm, the Statue of Liberty rising from the harbor, the High Line''s elevated garden threading through Chelsea. Brooklyn offers artisan everything — coffee, chocolate, pickles — along with jaw-dropping Manhattan views from DUMBO''s waterfront. Queens serves the world''s cuisines along a single subway line, and the Bronx gave birth to hip-hop.

New York rewards spontaneity. The best moments are often unplanned: a jazz trio in a Washington Square Park, a perfect bagel discovered on a random corner, or the sudden revelation of the Manhattan skyline as you cross the Brooklyn Bridge at golden hour. It is a city that asks only one thing of its visitors — keep up.', 
  -74, 40.71, 'Corporate', 'bg-slate-600', 
  'Wall Street immersion, Fortune-500 office tours, MICE conventions, and executive team-building experiences.', '/images/about-1.jpg', 
  'published', '', '5 Days', 
  'Washington D.C. (national capital)', 'US Dollar ($)', 'Humid subtropical; hot summers, cold winters, all four seasons', 'September–November (crisp fall, foliage) & April–June (spring bloom)', 
  'English; over 800 languages spoken citywide', 'EST (UTC-5) / EDT (UTC-4) in summer', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  11, 1, 'Times Square, Broadway & Midtown Icons', 'Midtown Manhattan', 
  'Plunge into the sensory overload of Times Square — a canyon of LED billboards and human energy that somehow never gets old. Walk south to the Empire State Building for its 86th-floor observation deck, then stroll through Bryant Park and Grand Central Terminal''s celestial ceiling. As evening falls, take your seat for a Broadway show — the pinnacle of live theater, with productions ranging from sweeping musicals to intimate dramas.', '["Experience the neon spectacle of Times Square on foot","Sunset from the Empire State Building''s 86th-floor open-air deck","Admire the astronomical ceiling mural of Grand Central Terminal","Evening Broadway show in the Theater District"]', '/images/city-5.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  11, 2, 'Central Park, the Met & Upper West Side', 'Upper Manhattan', 
  'Spend the morning in Central Park — row a boat on the Lake, wander through the Ramble''s forested paths, and find Strawberry Fields'' mosaic tribute to John Lennon. Cross to the Metropolitan Museum of Art, where you could spend a lifetime among Egyptian temples, Impressionist masterpieces, and medieval armor. End the day at a rooftop bar overlooking the park''s green rectangle set against the skyline.', '["Row a boat on Central Park''s Lake with the skyline as backdrop","Explore the Met''s Temple of Dendur and Impressionist galleries","Visit Strawberry Fields and the Bethesda Fountain","Rooftop cocktails with Central Park and skyline views at sunset"]', '/images/offer-2.jpg', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  11, 3, 'Statue of Liberty & Lower Manhattan', 'Lower Manhattan & Liberty Island', 
  'Ferry to Liberty Island for a pedestal-access visit to the Statue of Liberty, climbing inside the monument for harbor views and a close-up of Lady Liberty''s copper robes. Return to explore the 9/11 Memorial — the twin reflecting pools set in the original tower footprints — and the adjacent museum. Walk through the Financial District''s narrow colonial streets to the new Oculus transit hub, a soaring white-ribbed cathedral of glass designed by Santiago Calatrava.', '["Pedestal-access visit to the Statue of Liberty on Liberty Island","Pay respects at the 9/11 Memorial''s twin reflecting pools","Walk through the Oculus — Calatrava''s stunning transit cathedral","Dinner at a historic tavern in the cobblestoned Stone Street district"]', '/images/offer-3.jpg', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  11, 4, 'Brooklyn Bridge, DUMBO & Williamsburg', 'Brooklyn', 
  'Walk across the Brooklyn Bridge at sunrise — the Gothic stone towers and web of steel cables framing a postcard view of the Manhattan skyline. Descend into DUMBO (Down Under the Manhattan Bridge Overpass), where cobblestone streets, converted warehouses, and the iconic bridge-framed view of the Empire State Building have made this one of NYC''s most photographed neighborhoods. Continue to Williamsburg for vintage shopping, street art, and some of the city''s best food.', '["Sunrise walk across the Brooklyn Bridge with Manhattan panorama","Photograph the iconic Manhattan Bridge view from Washington Street, DUMBO","Explore Brooklyn Bridge Park''s waterfront with skyline backdrop","Street food and vintage shopping in Williamsburg"]', '/images/offer-4.jpg', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  11, 5, 'Chelsea, High Line & Greenwich Village', 'Downtown Manhattan', 
  'Walk the High Line — an elevated rail line transformed into a 2.3-kilometer aerial garden threading through Chelsea''s gallery district, with views of the Hudson River and the city''s evolving architecture. Descend to Chelsea Market for artisan food vendors, then wander to Greenwich Village, where tree-lined streets, jazz clubs, and Washington Square Park''s marble arch evoke the bohemian spirit of Dylan, Ginsberg, and Hendrix.', '["Stroll the High Line''s elevated gardens with Hudson River views","Taste artisan lobster rolls and tacos at Chelsea Market","Explore Greenwich Village''s jazz clubs and tree-lined streets","Farewell sunset from the Edge observation deck at Hudson Yards"]', '/images/city-6.jpg', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  11, 'Broadway Show', 'Experience the magic of a Tony Award–winning musical or play in one of Broadway''s 41 historic theaters — the gold standard of live performance anywhere in the world.', 'Theater', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  11, 'Food Tour of Queens', 'Ride the 7 train through the world''s most diverse borough, tasting Tibetan momos, Colombian arepas, Sichuan hand-pulled noodles, and Greek pastries — all within a few stops.', 'Utensils', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  11, 'Harlem Gospel Brunch', 'Join a Sunday service at a Harlem Baptist church for soaring gospel harmonies that will move you regardless of faith — a profound and uplifting NYC experience.', 'Music', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  11, 'Helicopter Tour', 'Lift off from the Downtown Manhattan Heliport for a 15-minute flight over the Statue of Liberty, Central Park, and the full skyline — the ultimate bird''s-eye view.', 'Plane', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  11, 'Late-Night Jazz Club', 'Catch a midnight set at the Blue Note, Village Vanguard, or Smalls — New York''s jazz heritage is alive and burning in intimate basement clubs across the Village.', 'Music', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  11, 'Buy an unlimited MetroCard for 7 days — it pays for itself quickly and works on subways and buses.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  11, 'Walk whenever possible — many of NYC''s best moments happen between destinations.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  11, 'Reserve Statue of Liberty pedestal/crown tickets well in advance; they sell out weeks ahead.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  11, 'Broadway TKTS booths in Times Square sell same-day discounted tickets — arrive early for best selection.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  11, 'Tipping 18–20% is standard at sit-down restaurants; $1–2 per drink at bars.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  11, 'Avoid eating in Times Square — walk a few blocks in any direction for better and cheaper food.', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  11, 'The subway runs 24/7, but late-night waits can be long — ride-hailing apps are a good backup.', 6
);
