INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'santorini', 'Santorini', 'Greece', 'Europe', 
  'A volcanic jewel of white and blue, suspended between sea and sky', 'https://images.pexels.com/photos/6604243/pexels-photo-6604243.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 'Santorini is the kind of place that feels too beautiful to be real. Born from one of the most cataclysmic volcanic eruptions in recorded history — an explosion so powerful it may have destroyed the Minoan civilization and inspired the legend of Atlantis — the island is essentially the rim of a submerged caldera, its sheer inner cliffs dropping 300 meters into a deep-blue lagoon still warmed by volcanic activity below.

Along this crescent-shaped cliff edge, the villages of Oia, Fira, and Imerovigli cascade in a tumble of whitewashed cubes and blue-domed churches that have become one of the world''s most recognizable landscapes. The light here is extraordinary — intense Aegean sun reflecting off white walls, refracting through wine glasses, and finally surrendering in sunsets so vivid they draw nightly applause from crowds gathered at Oia''s castle.

Beneath the postcard beauty, Santorini rewards deeper exploration: volcanic wine tastings of the rare Assyrtiko grape, black and red beaches formed from lava and pumice, ancient Minoan ruins at Akrotiri often called the ''Pompeii of the Aegean,'' and seafood tavernas where the day''s catch is grilled over charcoal with nothing more than lemon, olive oil, and a view.', 
  25.43, 36.39, 'Island', 'bg-cyan-500', 
  'White-washed villages, breathtaking sunsets, and Aegean charm.', '/images/explor-3.jpg', 
  'published', '', '3 Days', 
  'Athens (national capital); Fira is Santorini''s capital', 'Euro (€)', 'Mediterranean; hot dry summers, mild winters', 'May–June & September–October (warm but less crowded; lower prices)', 
  'Greek; English widely spoken', 'EET (UTC+2) / EEST (UTC+3) in summer', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  12, 1, 'Oia — Blue Domes & the World''s Best Sunset', 'Oia, Santorini', 
  'Begin in Oia, the crown jewel of Santorini, where narrow marble lanes wind between whitewashed cave houses, art galleries, and boutique hotels clinging to the caldera''s edge. Descend the 300 steps to Ammoudi Bay for a seafood lunch of grilled octopus and saganaki at a waterside taverna, then climb back up in time for the sunset. As the sun touches the Aegean, it detonates in shades of crimson and gold while the blue domes glow — a spectacle that draws spontaneous applause every single evening.', '["Wander Oia''s cliffside lanes and photograph the iconic blue-domed churches","Descent to Ammoudi Bay for grilled octopus at a waterside taverna","Watch the legendary Oia sunset from the castle ruins","Post-sunset stroll through Oia''s galleries and candlelit restaurants"]', 'https://images.pexels.com/photos/6604243/pexels-photo-6604243.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  12, 2, 'Caldera Cruise, Volcano & Wine Tasting', 'Nea Kameni Volcano & Santorini Wineries', 
  'Board a catamaran for a caldera cruise to Nea Kameni, the volcanic island still steaming at the center of the lagoon. Hike to the active crater, feel the heat rising through your shoes, then swim in the warm sulfur springs of Palea Kameni. Return to the main island for an afternoon of volcanic wine tasting — Santorini''s Assyrtiko grape, grown in basket-shaped vines on volcanic soil, produces one of the Mediterranean''s most distinctive white wines.', '["Catamaran cruise across the flooded caldera to Nea Kameni volcano","Hike to the active volcanic crater and feel the geothermal heat","Swim in the warm thermal springs of Palea Kameni","Sunset wine tasting of volcanic Assyrtiko at a caldera-view winery"]', 'https://images.pexels.com/photos/161342/greece-santorini-architecture-island-161342.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  12, 3, 'Akrotiri Ruins, Red Beach & Farewell', 'Akrotiri & Southern Santorini', 
  'Explore the Minoan ruins of Akrotiri — a Bronze Age city preserved under volcanic ash for 3,600 years, with multi-story buildings, frescoes, and drainage systems that reveal an astonishingly advanced civilization. Walk to the nearby Red Beach, a dramatic cove of crimson volcanic cliffs tumbling into turquoise water. End the trip with a farewell lunch at a cliffside restaurant in Imerovigli — the ''balcony of the Aegean'' — where the caldera view stretches from Oia to the volcano and beyond.', '["Tour the 3,600-year-old Minoan ruins of Akrotiri — the ''Greek Pompeii''","Swim at the dramatic Red Beach beneath crimson volcanic cliffs","Farewell lunch at a cliffside restaurant in Imerovigli","Final panoramic view of the caldera from the Skaros Rock trail"]', 'https://images.pexels.com/photos/2912449/pexels-photo-2912449.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  12, 'Oia Sunset Watch', 'Claim a spot at the ruined castle of Oia as the sun performs its nightly vanishing act — a ritual that has become one of the most celebrated sunset experiences on Earth.', 'Sun', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  12, 'Volcanic Wine Tasting', 'Sample the unique Assyrtiko, Nykteri, and Vinsanto wines produced from grapes grown in volcanic soil — a terroir found nowhere else, yielding crisp minerality and honeyed depth.', 'Wine', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  12, 'Caldera Catamaran Cruise', 'Sail the flooded caldera on a luxury catamaran, swimming in hot springs, snorkeling over volcanic formations, and dining on fresh seafood as the cliffs glow at sunset.', 'Sailboat', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  12, 'Akrotiri Archaeological Site', 'Walk through a Minoan city frozen in time by volcanic ash — multi-story buildings, painted pottery, and the earliest known flush toilets, dating to 1,600 BCE.', 'Landmark', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  12, 'Black Beach Horseback Ride', 'Ride along the volcanic black-sand beach of Perissa at sunset, the dark sand contrasting dramatically with the white surf and the orange sky above.', 'Heart', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  12, 'Visit in May–June or September–October to avoid the peak-season crowds and cruise-ship surges of July–August.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  12, 'Book caldera-view accommodations in Oia, Fira, or Imerovigli well in advance — the best spots sell out months ahead.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  12, 'Rent an ATV or car rather than relying on buses — Santorini''s roads are manageable and freedom to explore is invaluable.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  12, 'Wear sturdy shoes for the volcanic hikes — sandals won''t cut it on Nea Kameni''s jagged lava rocks.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  12, 'Carry sunscreen and water everywhere — there''s very little shade on the island and the sun is intense.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  12, 'Santorini''s tap water is desalinated and safe but not great-tasting; bottled water is inexpensive.', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  12, 'For the best sunset photos, arrive at Oia Castle at least 45 minutes before sunset to secure a spot.', 6
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  12, 'https://images.pexels.com/photos/6604243/pexels-photo-6604243.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  12, 'https://images.pexels.com/photos/161342/greece-santorini-architecture-island-161342.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  12, 'https://images.pexels.com/photos/2912449/pexels-photo-2912449.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);

INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'kerala', 'Kerala', 'India', 'South Asia', 
  'Where emerald backwaters cradle ancient healing wisdom', 'https://images.pexels.com/photos/35977920/pexels-photo-35977920.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 'Kerala unfurls along India''s southwestern Malabar Coast like a green silk sari draped over the Arabian Sea. This is the birthplace of Ayurveda — a 5,000-year-old science of life still practiced in thatched-roof clinics where physicians prescribe oil baths, herbal elixirs, and Shirodhara treatments beneath slow-turning ceiling fans. From the labyrinthine backwaters of Alleppey, where kettuvallam houseboats glide past rice paddies and coir-rope villages, to the mist-wrapped tea estates of Munnar at 1,600 meters, every turn reveals a landscape of almost absurd fertility.

Spice gardens in Thekkady perfume the air with cardamom, black pepper, and vanilla. Kathakali dancers paint their faces into living mythology each evening in Kochi''s Fort Quarter, where 500-year-old Chinese fishing nets still dip into the harbor at sunset. The cuisine is a revelation — appam with stew, meen pollichathu wrapped in banana leaf, and fiery Malabar prawn curry scooped with flaky parotta.

Beyond wellness and gastronomy, Kerala offers wild encounters: Periyar Tiger Reserve''s bamboo-raft safaris, Wayanad''s prehistoric Edakkal Caves, and Varkala''s dramatic red laterite cliffs plunging into turquoise surf. This is slow travel at its most nourishing — a place that heals you before you even realize you needed healing.', 
  76.3, 10, 'Medical', 'bg-teal-500', 
  'Authentic Ayurveda retreats, backwater wellness cruises, and holistic healing traditions.', '/images/dest-19.jpg', 
  'published', '', '5 Days', 
  'Thiruvananthapuram', 'Indian Rupee (₹)', 'Tropical monsoon with two rainy seasons', 'September–March (post-monsoon clarity and cool weather)', 
  'Malayalam, English', 'IST (UTC+5:30)', 'Left'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  13, 1, 'Fort Kochi & Chinese Fishing Nets', 'Kochi, Kerala', 
  'Arrive in Kochi and wander the cobbled lanes of Fort Kochi, where Portuguese churches, Dutch cemeteries, and Jewish synagogues coexist within a few blocks. Watch the cantilevered Chinese fishing nets — introduced by traders from the court of Kublai Khan — haul their evening catch as the sun sinks into the Arabian Sea.', '["Photograph the iconic Chinese fishing nets at sunset","Visit the 16th-century Mattancherry Palace and its Kerala murals","Explore the Paradesi Synagogue in Jew Town","Attend an evening Kathakali performance at Kerala Kathakali Centre"]', 'https://images.pexels.com/photos/35977920/pexels-photo-35977920.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  13, 2, 'Alleppey Backwater Cruise', 'Alleppey (Alappuzha), Kerala', 
  'Board a traditional kettuvallam houseboat and drift through Alleppey''s network of canals, lagoons, and palm-fringed waterways. Pass villages where women wash clothes on stone steps and toddy tappers scale coconut palms with astonishing speed. Fall asleep on the water to the symphony of crickets and lapping waves.', '["Cruise the Vembanad Lake on a thatched-roof houseboat","Taste fresh karimeen (pearl spot fish) grilled onboard","Watch coir-rope making in waterside villages","Witness a spectacular backwater sunset from the upper deck"]', 'https://images.pexels.com/photos/36718000/pexels-photo-36718000.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  13, 3, 'Periyar Wildlife & Spice Plantations', 'Thekkady, Kerala', 
  'Drive into the Western Ghats to Periyar Tiger Reserve, where elephants wade in the lake''s shallows and Nilgiri langurs swing through the canopy. After a bamboo-raft safari, visit a spice plantation where cardamom pods, pepper vines, cinnamon bark, and vanilla orchids grow in fragrant profusion.', '["Spot wild elephants on a Periyar Lake bamboo-raft safari","Tour a working cardamom and pepper plantation","Try freshly brewed spice tea with jaggery","Hike the Periyar Tiger Trail with a tribal guide"]', 'https://images.pexels.com/photos/36717711/pexels-photo-36717711.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  13, 4, 'Munnar Tea Highlands', 'Munnar, Kerala', 
  'Ascend to Munnar, where emerald tea carpets roll across every hillside like a painter''s hallucination. Visit the Kolukkumalai estate — the world''s highest orthodox tea plantation at 2,400 meters — and learn the delicate art of hand-rolling leaves. The evening air at this altitude is cool enough for a sweater, a rarity in tropical India.', '["Jeep ride to Kolukkumalai, the world''s highest tea estate","Walk through the Eravikulam National Park to spot Nilgiri tahr","Photograph the Mattupetty Dam and surrounding shola forests","Sample fresh single-estate teas at the KDHP Tea Museum"]', 'https://images.pexels.com/photos/35994958/pexels-photo-35994958.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  13, 5, 'Ayurveda & Varkala Cliffs', 'Varkala, Kerala', 
  'Descend to the coast and check into an Ayurvedic retreat perched above Varkala''s red laterite cliffs. Spend the morning receiving an Abhyanga oil massage and Shirodhara therapy, then walk the cliff path to Papanasam Beach — a sacred strand where Hindus believe a dip absolves all sins.', '["Experience a traditional Abhyanga full-body oil massage","Swim at Papanasam Beach beneath dramatic cliff faces","Dine on fresh seafood at a cliff-edge restaurant at sunset","Visit the 2,000-year-old Janardanaswamy Temple"]', 'https://images.pexels.com/photos/6652178/pexels-photo-6652178.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  13, 'Ayurvedic Wellness Retreats', 'Undergo authentic Panchakarma detox programs at heritage retreats in Kovalam and Varkala, guided by hereditary Ayurvedic physicians.', 'Heart', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  13, 'Backwater Houseboat Cruises', 'Glide through 900 kilometers of interconnected canals on a kettuvallam, sleeping under the stars as the boat drifts past paddy fields.', 'Waves', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  13, 'Kathakali & Kalaripayattu', 'Watch Kathakali dancers transform into demons and gods with elaborate makeup, then see Kalaripayattu — India''s oldest martial art — performed live.', 'Landmark', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  13, 'Spice Plantation Tours', 'Walk through fragrant estates in Wayanad and Thekkady, tasting raw pepper, fresh vanilla, and hand-ground cardamom straight from the vine.', 'Utensils', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  13, 'Tea Estate Trekking', 'Hike through Munnar''s rolling tea hills and visit working factories where leaves are withered, rolled, and fired into world-class black tea.', 'Mountain', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  13, 'Wildlife Safaris', 'Track Bengal tigers, Asian elephants, and great hornbills in Periyar and Wayanad''s dense tropical forests on guided bamboo-raft expeditions.', 'Globe', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  13, 'Monsoon season (June–August) brings heavy rains but also Ayurveda''s most effective treatment period — many clinics offer monsoon-special Panchakarma packages.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  13, 'Carry mosquito repellent with DEET, especially during backwater cruises; dengue risk increases post-monsoon.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  13, 'Learn a few Malayalam phrases — ''nanni'' (thank you) and ''sugamaano?'' (are you well?) earn genuine warmth from locals.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  13, 'Book houseboat trips midweek to avoid weekend crowds and negotiate better rates with operators in Alleppey.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  13, 'Dress modestly when visiting temples — shoulders and knees must be covered, and shoes are removed at the entrance.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  13, 'Kerala''s road network is narrow and winding in the Ghats — allocate extra travel time between hill stations and always hire a local driver.', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  13, 'Try the local toddy (fermented coconut sap) at a toddy shop — pair it with spicy tapioca and fish curry for the authentic Kerala lunch experience.', 6
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  13, 'https://images.pexels.com/photos/35977920/pexels-photo-35977920.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  13, 'https://images.pexels.com/photos/36718000/pexels-photo-36718000.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  13, 'https://images.pexels.com/photos/36717711/pexels-photo-36717711.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  13, 'https://images.pexels.com/photos/35994958/pexels-photo-35994958.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_images` (
