INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'goa', 'Goa', 'India', 'South Asia', 
  'Golden sands, barefoot nights, and the spirit of Susegad', 'https://images.pexels.com/photos/36664613/pexels-photo-36664613.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 'Goa is India''s smallest state but its largest mood — a 100-kilometer ribbon of golden coastline where Portuguese cathedrals stand beside Hindu temples, shack bars serve kingfish recheado with cold Kingfisher beers, and the philosophy of susegad (a Konkani term for contented laziness) permeates every sunset hour. The north beaches — Anjuna, Vagator, Calangute — throb with electronic music, flea markets, and backpacker energy, while the south — Palolem, Agonda, Cola — offers crescent coves lapped by gentle waves and framed by coconut palms.

Beyond the beach, Old Goa is a UNESCO World Heritage site where the Basilica of Bom Jesus houses the 450-year-old remains of St. Francis Xavier in a silver casket. The Latin Quarter of Fontainhas in Panjim is a pastel maze of Indo-Portuguese mansions, azulejo-tiled walls, and family-run tavernas serving prawn balchão and bebinca — a layered coconut cake that takes hours to bake. Dudhsagar Falls, a four-tiered cascade plunging 310 meters through the Western Ghats, is Goa''s best-kept inland secret.

Whether you come for the legendary New Year''s Eve parties at Curlies or the meditative quiet of a yoga shala in Assagao, Goa meets you exactly where you are — with a cold feni in hand and sand between your toes.', 
  74, 15.3, 'Beach', 'bg-blue-500', 
  'Golden beaches, vibrant nightlife, and unforgettable coastal energy.', '/images/dest-15.jpg', 
  'published', '', '5 Days', 
  'Panaji (Panjim)', 'Indian Rupee (₹)', 'Tropical monsoon with a long dry season', 'November–February (dry, warm, peak festival season)', 
  'Konkani, Marathi, English, Portuguese (heritage)', 'IST (UTC+5:30)', 'Left'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  15, 1, 'Old Goa & Fontainhas Heritage Walk', 'Panjim & Old Goa', 
  'Start at the Basilica of Bom Jesus, where St. Francis Xavier''s relics have drawn pilgrims since 1605. Cross to the Se Cathedral — Asia''s largest church — then drive to Panjim''s Fontainhas quarter for a walking tour past azulejo-tiled mansions, ending with a cold feni cocktail at a rooftop bar overlooking the Mandovi River.', '["Visit the Basilica of Bom Jesus and its gilded baroque altar","Explore Se Cathedral, the largest church in Asia","Wander Fontainhas'' pastel-painted Portuguese-era lanes","Sip cashew feni at a Mandovi River sunset bar"]', 'https://images.pexels.com/photos/36664613/pexels-photo-36664613.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  15, 2, 'North Goa Beach Crawl', 'Anjuna, Vagator & Baga, Goa', 
  'Rent a scooter and cruise through North Goa''s iconic beach strip. Browse the Wednesday Anjuna Flea Market for silver jewelry and tie-dye, climb to the Chapora Fort for a panoramic view over Vagator''s red cliffs, and end the day at Baga''s Tito''s Lane — Goa''s most famous nightlife strip.', '["Haggle at the Anjuna Wednesday Flea Market","Watch sunset from Chapora Fort (the ''Dil Chahta Hai'' fort)","Swim in Vagator''s cove beneath dramatic red laterite cliffs","Dance at Tito''s or Club Cubana in Baga"]', 'https://images.pexels.com/photos/35916755/pexels-photo-35916755.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  15, 3, 'South Goa''s Serene Crescents', 'Palolem & Agonda, Goa', 
  'Escape to Palolem''s perfect crescent bay, where colorful wooden huts line the shore and silent kayakers paddle to Butterfly Island. Walk south to Cola Beach — accessible only by a steep jungle path — and float in its freshwater lagoon just meters from the sea.', '["Kayak from Palolem to Butterfly Island at dawn","Discover the hidden Cola Beach freshwater lagoon","Try Goan fish thali at a Palolem beach shack","Join a silent noise headphone party on Palolem sands"]', 'https://images.pexels.com/photos/35916755/pexels-photo-35916755.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  15, 4, 'Dudhsagar Falls & Spice Farm', 'Mollem, Goa', 
  'Jeep through the Bhagwan Mahaveer Sanctuary to Dudhsagar Falls — the ''Sea of Milk'' — a 310-meter cascade that thunders through jungle mist during and after monsoon. On the return, stop at Sahakari Spice Farm for a traditional Goan lunch served on banana leaves, surrounded by nutmeg, cinnamon, and vanilla vines.', '["Wade in the natural pool beneath Dudhsagar''s four tiers","Spot Malabar giant squirrels in the sanctuary forest","Feast on a 12-dish Goan banana-leaf lunch at a spice farm","Learn about cashew, betel nut, and vanilla cultivation"]', 'https://images.pexels.com/photos/1299355/pexels-photo-1299355.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  15, 5, 'Assagao Yoga & Farewell Feast', 'Assagao & Candolim, Goa', 
  'Begin with a sunrise yoga session in Assagao, Goa''s wellness village, where century-old Portuguese villas have become boutique retreats. Brunch at Gunpowder — famous for its Kerala-Goan fusion — then spend the afternoon at Sinquerim Fort before a farewell seafood feast at Fisherman''s Wharf as the Arabian Sea turns gold.', '["Practice sunrise yoga in a heritage Assagao villa","Brunch on Malabar prawn curry at Gunpowder","Explore the 17th-century Aguada Fort and lighthouse","Feast on tiger prawns and Goan sausage at Fisherman''s Wharf"]', 'https://images.pexels.com/photos/14512449/pexels-photo-14512449.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  15, 'Beach Hopping by Scooter', 'Rent a scooter for ₹300/day and cruise from Arambol''s drum circles to Palolem''s crescent — Goa''s coastline rewards spontaneous detours.', 'Car', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  15, 'Portuguese Heritage Trail', 'Walk through 450 years of colonial history at Old Goa''s basilicas, Fontainhas'' pastel mansions, and Chandor''s Braganza House.', 'Landmark', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  15, 'Nightlife & Music Scene', 'From Anjuna''s psytrance to Panjim''s jazz bars and Baga''s club strip, Goa''s after-dark scene is India''s most diverse and legendary.', 'Lightbulb', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  15, 'Goan Culinary Trail', 'Taste vindaloo at its birthplace, crack into crab xec xec, and sample bebinca — Goa''s iconic 16-layer coconut dessert — at family tavernas.', 'Utensils', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  15, 'Water Sports & Diving', 'Dive at Grande Island to see shipwrecks and coral, or try jet-skiing, parasailing, and wakeboarding off Calangute and Baga beaches.', 'Waves', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  15, 'Wellness & Yoga Retreats', 'Join multi-day yoga teacher trainings in Assagao or drop into oceanfront meditation sessions at Arambol and Morjim.', 'Heart', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  15, 'Rent a scooter (₹300–500/day) — it''s the most practical way to navigate Goa''s narrow laterite lanes and beach-hop freely.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  15, 'Carry an international driving permit if you''re a foreign national; Goa police conduct checks on tourists during peak season.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  15, 'Monsoon (June–September) shuts most beach shacks but opens Dudhsagar Falls at full power — it''s the best time for inland Goa.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  15, 'Negotiate taxi fares before getting in — Goa taxis don''t use meters, and rates are roughly ₹20/km.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  15, 'Sundays are sacred — many local restaurants and shops close, so stock up on Saturday or eat at beach shacks.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  15, 'Beware of riptides at Morjim and Arambol; swim where local lifeguards are posted and heed red flag warnings.', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  15, 'Try local cashew feni responsibly — it''s stronger than it tastes, and authentic single-distilled feni is smoother than the commercial variety.', 6
);
