INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'rishikesh', 'Rishikesh', 'India', 'South Asia', 
  'The yoga capital of the world, where the Ganges flows and the soul breathes', 'https://images.pexels.com/photos/36123985/pexels-photo-36123985.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 'Rishikesh sits at the point where the Ganges tumbles out of the Himalayas and enters the plains — a geographic and spiritual threshold that has drawn seekers for millennia. The Beatles came here in 1968 to study Transcendental Meditation with Maharishi Mahesh Yogi, and the now-restored Beatles Ashram (Chaurasi Kutia) still echoes with psychedelic graffiti and creative energy. Today, the town is a global magnet for yoga practitioners, with hundreds of ashrams offering everything from dawn pranayama on the riverbank to month-long Ashtanga immersions.

But Rishikesh is far more than meditation cushions and mantra chanting. The Ganges here runs fast and cold — perfect for Grade III–IV white-water rafting through rapids named ''The Wall,'' ''Golf Course,'' and ''Roller Coaster.'' Bungee jumps from a 83-meter cliff platform, the highest in India, draw adrenaline junkies between yoga sessions. The Ram Jhula and Lakshman Jhula suspension bridges connect temples, cafés, and ashrams on both banks, swaying gently as sadhus and backpackers cross in equal measure.

Each evening, the Triveni Ghat Ganga Aarti transforms the riverfront into a spectacle of fire, chanting, and floating marigold diyas. The vegetarian food scene is exceptional — organic cafés serve wood-fired pizza alongside thali plates, and the German Bakery has been fueling travelers with banana pancakes since the 1970s.', 
  78.27, 30.09, 'Wellness', 'bg-emerald-500', 
  'Yoga capital of the world — ashrams, meditation, and spiritual immersion.', '/images/dest-23.jpg', 
  'published', '', '4 Days', 
  NULL, 'Indian Rupee (₹)', 'Subtropical with cool winters and warm, humid summers', 'September–November & February–May (comfortable, clear skies)', 
  'Hindi, English', 'IST (UTC+5:30)', 'Left'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  16, 1, 'Ashrams & the Beatles Legacy', 'Rishikesh, Uttarakhand', 
  'Begin at the Beatles Ashram (Chaurasi Kutia), wandering through meditation cells adorned with psychedelic murals. Cross the Lakshman Jhula bridge to Swarg Ashram, browse spiritual bookshops, and attend your first yoga class at Parmarth Niketan — one of the largest ashrams on the Ganges.', '["Explore the restored Beatles Ashram and its graffiti-covered domes","Walk across the iconic Lakshman Jhula suspension bridge","Join an evening yoga session at Parmarth Niketan","Shop for rudraksha malas and Ayurvedic oils in Swarg Ashram"]', 'https://images.pexels.com/photos/36123985/pexels-photo-36123985.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  16, 2, 'White-Water Rafting the Ganges', 'Shivpuri to Rishikesh stretch', 
  'Launch from Shivpuri for a 16-kilometer white-water rafting run through rapids with names like ''Three Blind Mice'' and ''The Wall.'' Between rapids, cliff-jump into deep emerald pools and float on your back watching eagles circle above the forested gorge.', '["Raft Grade III–IV rapids on the sacred Ganges","Cliff-jump into deep river pools between rapids","Spot kingfishers and white-capped river chats along the banks","Enjoy a riverside maggi and chai at the take-out point"]', 'https://images.pexels.com/photos/7542627/pexels-photo-7542627.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  16, 3, 'Adrenaline Day — Bungee & Beyond', 'Mohan Chatti, near Rishikesh', 
  'Head to Jumpin Heights for India''s highest bungee jump — an 83-meter freefall over a rocky gorge. Follow it with the giant swing and flying fox across the valley. Return to town for a restorative deep-tissue Ayurvedic massage at an ashram spa.', '["Bungee jump from 83 meters at Jumpin Heights","Swing on India''s highest giant swing (83m arc)","Ride the 1-km flying fox zip-line across the gorge","Recover with an Ayurvedic Abhyanga massage at dusk"]', 'https://images.pexels.com/photos/1486036/pexels-photo-1486036.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  16, 4, 'Ganga Aarti & Spiritual Immersion', 'Triveni Ghat, Rishikesh', 
  'Spend the morning in a silent Vipassana meditation session, then visit the Neelkanth Mahadev Temple — a 1,330-meter hilltop shrine dedicated to Shiva. Return for the magnificent Triveni Ghat Ganga Aarti at sunset, where priests circle flaming brass lamps as thousands of marigold diyas float downstream.', '["Meditate in a guided Vipassana session at a riverside ashram","Trek to Neelkanth Mahadev Temple through forest trails","Witness the Triveni Ghat Ganga Aarti fire ceremony at sunset","Float a marigold diya on the Ganges and make a wish"]', 'https://images.pexels.com/photos/36675455/pexels-photo-36675455.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  16, 'Yoga & Meditation Retreats', 'Train at internationally certified ashrams offering 200-hour and 500-hour yoga teacher training, or drop into daily classes at Parmarth Niketan and Sivananda Ashram.', 'Heart', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  16, 'White-Water Rafting', 'Navigate 16–36 kilometers of Ganges rapids between Shivpuri and Rishikesh, suitable for beginners through experienced paddlers.', 'Waves', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  16, 'Bungee Jumping', 'Leap from India''s highest fixed-platform bungee at Jumpin Heights — 83 meters of pure freefall over a Himalayan gorge.', 'Dumbbell', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  16, 'Ganga Aarti Ceremony', 'Join thousands at Triveni Ghat each evening for the fire-and-chant ceremony, one of India''s most moving spiritual rituals.', 'Landmark', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  16, 'Café Culture & Organic Dining', 'Rishikesh is entirely vegetarian — explore cafés serving Israeli shakshuka, Italian wood-fired pizza, and traditional thali alongside the Ganges.', 'Utensils', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  16, 'Waterfall Treks', 'Hike to Neer Garh and Patna waterfalls through subtropical forest, swimming in natural rock pools surrounded by butterflies.', 'Mountain', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  16, 'Rishikesh is entirely vegetarian and alcohol-free by law — don''t expect meat or liquor anywhere in the town proper.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  16, 'Book yoga teacher training courses months in advance; reputable schools like Parmarth Niketan and Rishikul Yogshala fill up fast.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  16, 'The Ganges current is deceptively strong — never swim alone, and always check with locals about safe bathing spots.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  16, 'Rafting season runs September–June; operators shut down during monsoon (July–August) when water levels become dangerously high.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  16, 'Dress modestly in and around ashrams — sleeveless tops and shorts are frowned upon during ceremonies.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  16, 'Carry a headlamp — power cuts are common, especially during storms, and many ashram paths are unlit at night.', 5
);
