INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'andaman-islands', 'Andaman Islands', 'India', 'South Asia', 
  'Untouched emerald islands at the edge of the Bay of Bengal', 'https://images.pexels.com/photos/362690/pexels-photo-362690.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 'The Andaman Islands are India''s best-kept secret — a remote archipelago of 572 islands (only 37 inhabited) floating in the Bay of Bengal, closer to Myanmar than mainland India. Havelock Island (Swaraj Dweep) is home to Radhanagar Beach, repeatedly named Asia''s finest, where white sand curves beneath a canopy of Mahua trees and bioluminescence lights the shallows on moonless nights. Beneath the surface, coral gardens at sites like Nemo Reef and Dixon''s Pinnacle teem with manta rays, Napoleon wrasse, and schools of trevally.

Port Blair anchors the archipelago''s human history — the Cellular Jail here, where British colonialists imprisoned Indian freedom fighters in solitary cells, is now a national memorial whose nightly sound-and-light show is as haunting as it is essential. Ross Island''s atmospheric ruins, slowly consumed by strangler figs and feral deer, evoke a colonial past surrendered to nature. Baratang Island''s limestone caves, reached by boat through mangrove creeks, hide stalactite chambers that feel positively Jurassic.

For the intrepid, Neil Island (Shaheed Dweep) offers natural rock formations like the Howrah Bridge arch, empty beaches, and village cycling past papaya groves. The Andamans are not about luxury resorts — they''re about stripping back to essentials: warm water, clean sand, fish grilled on the beach, and a sky unpolluted by artificial light.', 
  92.7, 11.7, 'Island', 'bg-cyan-500', 
  'Untouched islands, scuba diving, and serene tropical escapes.', '/images/dest-17.jpg', 
  'published', '', '5 Days', 
  'Port Blair', 'Indian Rupee (₹)', 'Tropical maritime with year-round warmth', 'October–May (calm seas, clear visibility for diving)', 
  'Hindi, Bengali, Tamil, English', 'IST (UTC+5:30)', 'Left'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  17, 1, 'Port Blair & Cellular Jail', 'Port Blair, Andaman Islands', 
  'Arrive in Port Blair and visit the Cellular Jail, where each solitary cell tells the story of India''s independence struggle. Walk the seven wings radiating from the central tower, then stay for the evening sound-and-light show that illuminates the prison walls with projected history.', '["Tour the Cellular Jail''s seven wings and solitary cells","Watch the haunting evening sound-and-light show","Visit the Anthropological Museum to learn about the Jarawa and Sentinelese tribes","Stroll the Aberdeen Bazaar for fresh coconut water and local crafts"]', 'https://images.pexels.com/photos/362690/pexels-photo-362690.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  17, 2, 'Havelock Island & Radhanagar Beach', 'Havelock Island (Swaraj Dweep)', 
  'Ferry to Havelock Island and head straight for Radhanagar Beach — a 2-kilometer crescent of powdery white sand backed by primeval forest. The sunset here is legendary: the sky turns every shade of tangerine as the sea flattens into mercury. Snorkel at Elephant Beach to find Nemo among staghorn corals.', '["Swim at Radhanagar, Asia''s most beautiful beach","Snorkel with clownfish and parrotfish at Elephant Beach","Walk through littoral forest to a hidden mangrove creek","Dine on grilled lobster at a beachfront bamboo shack"]', 'https://images.pexels.com/photos/3155643/pexels-photo-3155643.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  17, 3, 'Scuba Diving at Nemo Reef', 'Havelock Island, Andaman Islands', 
  'Take a PADI-certified dive at Nemo Reef or Dixon''s Pinnacle, where visibility often exceeds 30 meters. Encounter manta rays, sea turtles, and clouds of fusiliers drifting along coral walls. Non-divers can try a Discover Scuba session in the shallows with an instructor.', '["Dive Dixon''s Pinnacle to spot reef sharks and giant groupers","Swim alongside green sea turtles at Turtle Point","Photograph vibrant soft corals and sea fans up close","Complete a PADI Open Water certification in tropical waters"]', 'https://images.pexels.com/photos/36389357/pexels-photo-36389357.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  17, 4, 'Neil Island & Natural Wonders', 'Neil Island (Shaheed Dweep)', 
  'Ferry to Neil Island for a slower pace — cycle past papaya and banana plantations to the Howrah Bridge, a natural rock arch sculpted by tidal erosion. Laze at Laxmanpur Beach through sunset, when the reef flats are exposed and tide pools reveal starfish, sea cucumbers, and tiny octopuses.', '["Cycle the island''s quiet lanes past tropical fruit farms","Photograph the Howrah Bridge natural rock formation","Explore tide pools teeming with marine life at Laxmanpur Beach","Watch the galaxy rise over unpolluted Neil Island skies"]', 'https://images.pexels.com/photos/3747567/pexels-photo-3747567.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  17, 5, 'Ross Island & North Bay Coral', 'Port Blair vicinity', 
  'Take a morning boat to Ross Island, where British-era ruins — a church, bakery, commissariat — are being swallowed by banyan roots and patrolled by spotted deer. Then snorkel at North Bay Island''s coral reef, one of the most accessible in the Andamans, before catching your return flight.', '["Wander Ross Island''s atmospheric, vine-covered colonial ruins","Spot deer and peacocks roaming freely among the ruins","Snorkel the vibrant coral garden at North Bay Island","Glass-bottom boat ride over coral for non-swimmers"]', 'https://images.pexels.com/photos/36505898/pexels-photo-36505898.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  17, 'Scuba Diving & Snorkeling', 'Dive world-class sites like Dixon''s Pinnacle, The Wall, and Nemo Reef with 30-meter visibility and encounters with manta rays and turtles.', 'Waves', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  17, 'Beach Exploration', 'Discover pristine, uncrowded beaches — from Radhanagar''s white sand to Kalapathar''s rocky shores and the hidden coves of Long Island.', 'Camera', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  17, 'Colonial History Trail', 'Walk through India''s freedom struggle at the Cellular Jail, Ross Island ruins, and Viper Island''s gallows.', 'Landmark', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  17, 'Kayaking Through Mangroves', 'Paddle through bioluminescent mangrove creeks at night, where every stroke lights up the water like liquid starlight.', 'Mountain', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  17, 'Island Cycling', 'Rent a bicycle on Neil Island and pedal through papaya groves, fishing villages, and empty beaches at your own pace.', 'Car', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  17, 'Seafood Feasting', 'Feast on fresh-caught lobster, crab, and red snapper grilled on the beach with lime, chili, and garlic — as fresh as seafood gets.', 'Utensils', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  17, 'Foreigners need a Restricted Area Permit (RAP) — it''s issued free on arrival at Port Blair airport, valid for 30 days.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  17, 'Book inter-island ferries (Makruzz or Nautika) online well in advance; they sell out during peak season (December–January).', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  17, 'There''s no ATM on Neil Island and limited ATMs on Havelock — carry enough cash from Port Blair.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  17, 'Carry reef-safe sunscreen — the coral here is pristine and highly sensitive to chemical sunscreens.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  17, 'Visiting Jarawa tribal reserves is illegal and exploitative; avoid ''human safari'' tours marketed in Port Blair.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  17, 'Mobile network coverage is patchy — BSNL has the best reach, but expect no signal on remote beaches.', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  17, 'Pack a dry bag for ferry crossings; spray and occasional waves can soak unprotected luggage on open-deck boats.', 6
);
