INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'male-atoll', 'Malé Atoll', 'Maldives', 'South Asia', 
  'Where turquoise infinity meets the sky', 'https://images.pexels.com/photos/1129343/pexels-photo-1129343.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 'The Malé Atoll — split into North and South — is the pulsing heart of the Maldives, an archipelago of 1,192 islands so flat that the highest natural point is barely 2 meters above sea level. This is the land of overwater villas with glass floors, house reefs where blacktip sharks patrol at arm''s length, and sunsets that turn the Indian Ocean into liquid gold. North Malé hosts some of the world''s most iconic resorts — Huvafen Fushi, One&Only Reethi Rah, Gili Lankanfushi — each on its own private island, accessible only by speedboat or seaplane.

Beneath the surface, the atoll is a diver''s paradise. Banana Reef, one of the first dive sites discovered in the Maldives, features overhangs dripping with soft coral and patrolled by Napoleon wrasse. Manta Point delivers reliable encounters with reef manta rays from May to November. The bioluminescent ''sea of stars'' phenomenon on some beaches — caused by dinoflagellate plankton — turns the shore into a mirror of the Milky Way.

Malé city itself is a fascinating counterpoint — one of the world''s most densely populated islands, where fish markets overflow at dawn, the 17th-century Hukuru Miskiy mosque gleams with coral-stone carvings, and locals play cricket in every available gap between buildings. It''s the gateway, the cultural anchor, and a reminder that the Maldives is a living nation, not just a resort catalog.', 
  73.5, 4.17, 'Luxury', 'bg-amber-500', 
  'Overwater villas, crystal lagoons, and world-class snorkeling.', '/images/dest-14.jpg', 
  'published', '', '4 Days', 
  'Malé', 'Maldivian Rufiyaa (MVR) — US dollars widely accepted', 'Tropical with two monsoon seasons', 'November–April (dry northeast monsoon, best visibility)', 
  'Dhivehi, English', 'MVT (UTC+5)', NULL
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  18, 1, 'Malé City & Transfer to Resort', 'Malé City & North Malé Atoll', 
  'Explore Malé''s compact intensity — the bustling fish market where yellowfin tuna are auctioned whole, the ornate Hukuru Miskiy (Old Friday Mosque) built from coral stone in 1658, and the colorful produce stalls of the local market. Then board a speedboat across turquoise shallows to your resort island.', '["Witness the dawn tuna auction at Malé Fish Market","Visit the 17th-century Hukuru Miskiy coral-stone mosque","Spot manta rays from the seaplane transfer window","Check into an overwater villa with a glass-floor panel"]', 'https://images.pexels.com/photos/1129343/pexels-photo-1129343.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  18, 2, 'House Reef Snorkeling & Spa', 'Resort Island, North Malé Atoll', 
  'Step off your overwater deck directly into the house reef — no boat required. Swim alongside blacktip reef sharks, hawksbill turtles, and kaleidoscopic parrotfish in water so clear the sandy bottom glows 15 meters below. Afternoon: indulge in an underwater spa treatment at a glass-walled pavilion beneath the lagoon.', '["Snorkel the house reef directly from your villa steps","Swim alongside blacktip reef sharks and eagle rays","Experience a couples massage in an underwater spa pavilion","Watch the sunset from an infinity pool that merges with the ocean"]', 'https://images.pexels.com/photos/4973961/pexels-photo-4973961.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  18, 3, 'Banana Reef & Manta Point Diving', 'North Malé Atoll dive sites', 
  'Dive Banana Reef — the Maldives'' most famous site — where a curved reef wall drops into a canyon of soft coral, barrel sponges, and shoals of oriental sweetlips. In the afternoon, head to Manta Point for a cleaning station dive, hovering motionless as 4-meter reef mantas glide overhead.', '["Dive the legendary Banana Reef canyon and overhangs","Encounter reef manta rays at a cleaning station","Photograph Napoleon wrasse and moray eels at close range","Night snorkel to witness bioluminescent plankton"]', 'https://images.pexels.com/photos/4809019/pexels-photo-4809019.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  18, 4, 'Sandbank Picnic & Dolphin Cruise', 'North Malé Atoll', 
  'Sail to a deserted sandbank — a pristine white tongue of sand surrounded by nothing but turquoise ocean — for a champagne picnic served by your resort chef. In the late afternoon, cruise the atoll''s outer channels for spinner dolphins, which leap in synchronized arcs as the sun dips below the horizon.', '["Picnic on a private sandbank visible only at low tide","Swim in impossibly clear water with no land in sight","Watch pods of spinner dolphins leap at sunset","Stargaze from the dhoni''s upper deck on the return sail"]', 'https://images.pexels.com/photos/5890131/pexels-photo-5890131.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  18, 'Overwater Villa Living', 'Wake above turquoise lagoons in a thatched-roof villa with a glass floor panel, private infinity pool, and direct reef access from your sundeck.', 'Heart', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  18, 'World-Class Diving', 'Dive 50+ sites including Banana Reef, HP Reef, and Manta Point — encountering whale sharks, mantas, and coral cathedrals.', 'Waves', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  18, 'Sandbank Excursions', 'Sail to vanishing sandbanks for private picnics, 360-degree ocean views, and snorkeling in gin-clear water.', 'MapPin', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  18, 'Dolphin & Whale Watching', 'Cruise at sunset to spot spinner dolphins, bottlenose dolphins, and — from January to April — migrating blue whales in deep channels.', 'Globe', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  18, 'Underwater Dining', 'Dine at an underwater restaurant surrounded by reef fish, or enjoy a private beach dinner with your feet in the sand and stars overhead.', 'Utensils', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  18, 'Bioluminescent Beach Walks', 'On moonless nights, walk beaches lit by glowing phytoplankton — each footstep sparking blue-white light in the wet sand.', 'Lightbulb', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  18, 'Resorts are on private islands — budget for speedboat or seaplane transfers (USD $300–600 round trip) on top of accommodation.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  18, 'The Maldives is a Muslim nation; alcohol is only available at resorts, not on inhabited local islands or in Malé.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  18, 'Bring reef-safe sunscreen — the Maldives'' coral reefs are critically threatened and chemical sunscreens accelerate bleaching.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  18, 'For budget travel, stay on local islands like Maafushi or Thulusdhoo where guesthouses cost USD $50–100/night with beach access.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  18, 'Tipping is not mandatory but appreciated — USD $5–10/day for housekeeping and dive guides is standard at resorts.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  18, 'Pack light, quick-dry clothing — you''ll live in swimwear and cover-ups, and laundry services at resorts are expensive.', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  18, 'Visit between August and November for the best manta ray encounters at cleaning stations across the atoll.', 6
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  18, 'https://images.pexels.com/photos/1129343/pexels-photo-1129343.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_images` (
