INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'colombo', 'Colombo', 'Sri Lanka', 'South Asia', 
  'A vibrant capital where colonial echoes meet curry-scented modernity', 'https://images.pexels.com/photos/36703578/pexels-photo-36703578.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 'Colombo is Sri Lanka''s beating, buzzing, horn-honking heart — a port city where Dutch-era warehouses now house craft cocktail bars, where Buddhist temples share blocks with Hindu kovils and colonial churches, and where the aroma of lamprais (rice baked in banana leaf with Dutch-Burgher spices) drifts through streets lined with Art Deco facades. The Pettah district is pure sensory overload — a labyrinth of wholesale markets selling everything from sari fabric to dried fish to mobile phone cases, all accompanied by a soundtrack of Bollywood hits and vendor calls.

The Galle Face Green promenade stretches along the Indian Ocean waterfront, where families fly kites at dusk and isso vadai (crispy prawn fritters) vendors work overtime. The Gangaramaya Temple — an eclectic fusion of Sri Lankan, Thai, Indian, and Chinese Buddhist architecture — houses a museum-like collection of gifts from devotees worldwide, from ivory tusks to vintage Rolls-Royces. Colombo''s dining scene has exploded in recent years, with Ministry of Crab (in a 400-year-old Dutch hospital) serving Sri Lanka''s legendary mud crabs, and rooftop bars in Fort district pouring arrack cocktails over sunset views.

Beyond the city center, the Beira Lake offers kayaking past colonial-era islands, the National Museum guards a throne carved from a single block of ivory, and the Kelaniya Raja Maha Viharaya — just outside town — contains murals dating to the 2nd century BCE. Colombo isn''t a city you fall in love with at first sight; it''s one that reveals its charm layer by layer, curry by curry.', 
  79.9, 6.9, 'Medical', 'bg-teal-500', 
  'Affordable cardiac, orthopaedic, and dental treatments in JCI-accredited hospitals with post-op recovery on tropical shores.', '/images/dest-6.jpg', 
  'published', '', '4 Days', 
  'Colombo (commercial) / Sri Jayawardenepura Kotte (legislative)', 'Sri Lankan Rupee (LKR)', 'Tropical with year-round warmth and two monsoon seasons', 'December–March (driest period on the west coast)', 
  'Sinhala, Tamil, English', 'SLST (UTC+5:30)', 'Left'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  19, 1, 'Fort District & Galle Face', 'Colombo Fort & Galle Face, Colombo', 
  'Start in the Fort district, where the Old Colombo Lighthouse, Dutch-period Wolvendaal Church, and the grand Cargills & Millers building coexist with gleaming office towers. Walk to Galle Face Green for isso vadai and kottu roti from street vendors as the sun sets over the Indian Ocean.', '["Explore the Fort district''s mix of colonial and modern architecture","Eat isso vadai and kottu roti at Galle Face Green vendors","Visit the Old Colombo Lighthouse and its ocean views","Sip an arrack sour at a rooftop bar overlooking the harbor"]', 'https://images.pexels.com/photos/36703578/pexels-photo-36703578.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  19, 2, 'Pettah Markets & Gangaramaya Temple', 'Pettah & Slave Island, Colombo', 
  'Plunge into Pettah''s chaotic energy — each street specializes in different goods, from electronics on Main Street to spices on 5th Cross Street. Emerge to the serenity of Gangaramaya Temple, whose Seema Malaka meditation platform floats on Beira Lake surrounded by lotus blooms and Buddha statues.', '["Navigate Pettah''s specialized market streets","Visit Gangaramaya Temple''s extraordinary eclectic museum","Meditate at the floating Seema Malaka on Beira Lake","Sample string hoppers and pol sambol at a traditional rice-and-curry lunch"]', 'https://images.pexels.com/photos/31194788/pexels-photo-31194788.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  19, 3, 'Colombo''s Culinary Trail', 'Various neighborhoods, Colombo', 
  'Embark on a food pilgrimage: hoppers and egg hoppers for breakfast at a Bambalapitiya café, lamprais from a Burgher family kitchen in Cinnamon Gardens, afternoon tea at the Mount Lavinia Hotel, and mud crab at the legendary Ministry of Crab inside a Dutch Hospital complex.', '["Crack into Sri Lanka''s famous mud crab at Ministry of Crab","Taste authentic lamprais wrapped in banana leaf","Learn to make hoppers at a Colombo cooking class","Enjoy high tea at the colonial Mount Lavinia Hotel"]', 'https://images.pexels.com/photos/5176006/pexels-photo-5176006.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  19, 4, 'Museums, Murals & Mount Lavinia', 'Colombo & Mount Lavinia', 
  'Visit the National Museum''s ivory throne and ancient crown jewels, then drive to Kelaniya Raja Maha Viharaya for its 2nd-century murals depicting the Buddha''s legendary visit to Sri Lanka. End the day at Mount Lavinia Beach, where the old governor''s mansion is now a hotel with a terrace bar overlooking the surf.', '["View the Colombo National Museum''s royal regalia and ivory throne","Admire Kelaniya Temple''s ancient murals and moonstone carvings","Relax at Mount Lavinia Beach as fishing boats return at sunset","Kayak across Beira Lake past the floating temple island"]', 'https://images.pexels.com/photos/36477911/pexels-photo-36477911.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  19, 'Street Food Safari', 'Devour kottu roti, isso vadai, hoppers, and short eats from Galle Face Green vendors to Pettah''s hole-in-the-wall eateries.', 'Utensils', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  19, 'Temple & Religious Trails', 'Visit Gangaramaya''s floating meditation platform, the Red Mosque, Wolvendaal Church, and the Sri Kailawasanathan Hindu Kovil — all within walking distance.', 'Landmark', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  19, 'Colonial Architecture Tour', 'Walk through layers of Portuguese, Dutch, and British architecture in Fort, Pettah, and Cinnamon Gardens neighborhoods.', 'Camera', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  19, 'Craft Cocktail & Arrack Bars', 'Colombo''s bar scene celebrates Ceylon arrack — try creative cocktails at Smoke & Mirrors, The Verandah, and rooftop spots in Fort.', 'Lightbulb', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  19, 'Pettah Market Immersion', 'Lose yourself in Colombo''s oldest bazaar — a grid of streets specializing in textiles, spices, electronics, and gold jewelry.', 'MapPin', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  19, 'Use the Colombo tuk-tuk app ''PickMe'' for metered rides — it prevents overcharging and works like Uber for three-wheelers.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  19, 'Full-moon Poya days are public holidays — alcohol sales are banned island-wide and many shops close, but temples are beautifully lit.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  19, 'Dress conservatively at temples — cover shoulders and knees, remove shoes, and don''t pose with your back to Buddha statues for photos.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  19, 'The Colombo Fort Railway Station connects to Kandy, Galle, and Ella — buy first-class observation car tickets in advance for scenic routes.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  19, 'Carry small denominations — street vendors and tuk-tuk drivers rarely have change for LKR 5,000 notes.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  19, 'Tap water is not safe to drink — stick to bottled or boiled water, and avoid ice at street stalls.', 5
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  19, 'https://images.pexels.com/photos/36703578/pexels-photo-36703578.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
