  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  31, 'https://images.pexels.com/photos/236519/pexels-photo-236519.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_images` (
