INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'shanghai', 'Shanghai', 'China', 'East Asia', 
  'The Bund, futuristic skyline, gateway to modern China', 'https://images.pexels.com/photos/4456054/pexels-photo-4456054.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 'Shanghai is China''s great paradox — a city where art deco mansions from the 1930s concession era line the same streets as the gravity-defying towers of Lujiazui, where grandmothers practice sword dancing in parks overlooked by the world''s second-tallest building. The Bund''s neoclassical façades gaze across the Huangpu River at a skyline that didn''t exist thirty years ago, a visual dialogue between colonial past and rocket-fueled future.

Beyond the postcard views, Shanghai rewards those who dig deeper. In the Former French Concession, plane-tree-canopied lanes hide speakeasy cocktail bars, vinyl record shops, and century-old shikumen lane houses where laundry still hangs between wrought-iron balconies. Tianzifang''s narrow alleys buzz with independent designers and ceramic studios, while M50 art district converts abandoned cotton mills into galleries showcasing China''s most provocative contemporary artists.

The city''s food scene is equally layered — from the scalding soup dumplings of Jia Jia Tang Bao to the molecular gastronomy of Ultraviolet, Shanghai''s dining landscape spans every price point and every province. Night falls, and the rooftop bars along the Bund come alive, their cocktail menus rivaling London and New York while their views surpass them both.', 
  121.47, 31.23, 'Education', 'bg-indigo-500', 
  'Factory-floor field trips, advanced manufacturing units, tech innovation parks, and urban planning study tours.', '/images/offer-3.jpg', 
  'published', '', '4 Days', 
  NULL, 'Chinese Yuan (¥ / CNY)', 'Humid subtropical with hot, muggy summers and chilly winters', 'March–May & September–November for pleasant temperatures', 
  'Mandarin Chinese, Shanghainese', 'CST (UTC+8)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  37, 1, 'The Bund & Pudong Skyline', 'The Bund & Lujiazui, Shanghai', 
  'Begin on the Bund''s granite promenade at sunrise, when the Pudong skyline glows amber across the river. Cross through the Bund Sightseeing Tunnel to Lujiazui, ascending the Shanghai Tower''s 118th-floor observation deck for 360-degree views of the Yangtze Delta.', '["Sunrise walk along the Bund''s mile-long waterfront promenade","Ascend the 632-meter Shanghai Tower observation deck","Photograph the Oriental Pearl Tower''s retro-futurist spheres","Evening cocktails at Bar Rouge overlooking the illuminated skyline"]', 'https://images.pexels.com/photos/4456054/pexels-photo-4456054.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  37, 2, 'French Concession & Tianzifang', 'Former French Concession, Shanghai', 
  'Lose yourself in the plane-tree-lined avenues of the Former French Concession, where art deco villas house boutique cafés and independent bookshops. Duck into Tianzifang''s maze of shikumen lane houses turned artisan workshops, then end the evening at a hidden speakeasy behind a Coca-Cola vending machine door.', '["Stroll Wukang Road''s canopy of London plane trees and art deco villas","Browse independent designer studios in Tianzifang''s alleys","Visit Sun Yat-sen''s former residence museum","Discover a secret speakeasy in the former concession quarter"]', 'https://images.pexels.com/photos/36064470/pexels-photo-36064470.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  37, 3, 'Yu Garden, Old City & Xiaolongbao Trail', 'Old City & Huangpu, Shanghai', 
  'Enter the ornate zigzag bridge to Yu Garden, a 16th-century classical garden of rockeries, dragon walls, and koi ponds hemmed in by the old city''s bustling bazaar. Spend the afternoon on a xiaolongbao pilgrimage — comparing the thin-skinned perfection of Din Tai Fung with the crab-roe laden parcels at Jia Jia Tang Bao.', '["Explore Yu Garden''s Ming-dynasty pavilions and rockeries","Cross the Nine-Turn Zigzag Bridge over the lotus pond","Taste-test xiaolongbao at three legendary dumpling houses","Shop for tea and silk in the Old City bazaar"]', 'https://images.pexels.com/photos/36487215/pexels-photo-36487215.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  37, 4, 'Art, Markets & River Cruise', 'M50, West Bund & Huangpu River', 
  'Start at M50 Art District, where converted cotton mills house galleries of Chinese contemporary painting and sculpture. Continue to the West Bund Museum, designed by David Chipperfield, for its rotating exhibitions. As evening falls, board a Huangpu River cruise to see both banks ablaze with light.', '["Wander gallery spaces in M50''s repurposed industrial buildings","Visit the West Bund Museum''s world-class contemporary exhibitions","Huangpu River night cruise between the Bund and Lujiazui","Late-night street food at Shouning Road''s crayfish stalls"]', 'https://images.pexels.com/photos/6902201/pexels-photo-6902201.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  37, 'Xiaolongbao Pilgrimage', 'Follow a soup-dumpling trail from the legendary Nanxiang Steamed Bun Restaurant to modern Din Tai Fung, comparing wrapper thickness, broth richness, and crab-roe fillings.', 'Utensils', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  37, 'Bund Architecture Walk', 'Trace the evolution of Shanghai''s colonial architecture from the Hongkong and Shanghai Bank''s domed ceiling to the art deco Sassoon House at Fairmont Peace Hotel.', 'Landmark', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  37, 'Rooftop Bar Hopping', 'Ascend the Bund''s rooftop bars — Flair, Vue, and Bar Rouge — for cocktails framed by the most electrifying urban skyline on Earth.', 'Globe', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  37, 'Shikumen Lane House Tour', 'Step inside restored shikumen — Shanghai''s iconic stone-gate lane houses — to understand the communal living that shaped generations of Shanghainese identity.', 'BookOpen', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  37, 'Zhujiajiao Water Town', 'Escape to this 1,700-year-old canal town just an hour from downtown, gliding under Ming-dynasty bridges in a wooden gondola and tasting sticky rice wrapped in lotus leaves.', 'Waves', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  37, 'Night Photography', 'Capture Pudong''s illuminated towers reflected in the Huangpu River from the Bund, one of the world''s great urban nightscapes.', 'Camera', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  37, 'Download WeChat and link a payment method — it''s essential for everything from buying subway tickets to ordering at restaurants.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  37, 'The metro is fast and cheap; Line 2 connects Pudong Airport to the city center in about an hour.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  37, 'Carry a portable fan in summer — July and August humidity regularly exceeds 85%.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  37, 'Avoid visiting Yu Garden on weekends or Chinese holidays when crowds are at their worst.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  37, 'Tipping is not customary and can sometimes cause confusion; prices are all-inclusive.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  37, 'A VPN is necessary for accessing Google, Instagram, and most Western social media platforms.', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  37, 'Learn the phrase ''bù yào là'' (no spice) if you''re sensitive to chili — Sichuan restaurants are everywhere.', 6
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  37, 'https://images.pexels.com/photos/4456054/pexels-photo-4456054.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  37, 'https://images.pexels.com/photos/36064470/pexels-photo-36064470.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_images` (
