INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'tibet', 'Tibet', 'China', 'East Asia', 
  'Potala Palace, Buddhist monasteries, traditions atop the world', 'https://images.pexels.com/photos/2149749/pexels-photo-2149749.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 'Tibet exists at the edge of imagination — a land where prayer flags snap in thin air at 4,500 meters, where monks debate philosophy with thunderclap hand-slaps in sunlit courtyards, and where the Potala Palace rises thirteen stories above Lhasa like a white-and-crimson fortress against an impossibly blue sky. This is the Roof of the World, a vast plateau of grasslands, turquoise lakes, and snow-capped peaks that has drawn pilgrims and seekers for over a thousand years.

Beyond Lhasa''s spiritual landmarks — Jokhang Temple, where a continuous stream of prostrating devotees circles the sacred kora path, and Sera Monastery, alive with the rapid-fire dialectics of debating monks — the Tibetan plateau unfolds into a wilderness of staggering scale. Yamdrok Lake shimmers in shades of sapphire and emerald depending on the light, nomadic yak herders traverse passes above 5,000 meters, and the north face of Everest looms at the end of a bone-rattling jeep track from Shigatse.

Travel here demands patience, flexibility, and respect. Altitude sickness is a real concern, permits are mandatory, and infrastructure outside Lhasa is basic. But for those willing to adapt, Tibet offers experiences found nowhere else on Earth: butter tea shared in a nomad''s tent, the deep horn blast of morning puja echoing across a silent valley, the overwhelming sight of Everest Base Camp at dawn.', 
  91.17, 29.65, 'Spiritual', 'bg-violet-500', 
  'Potala Palace, Buddhist monasteries, and profound traditions atop the world.', '/images/offer-4.jpg', 
  'published', '', '5 Days', 
  'Lhasa', 'Chinese Yuan (¥ / CNY)', 'High-altitude arid with intense sun, cold nights, and brief summer rains', 'May–June & September–October for clear skies and manageable temperatures', 
  'Tibetan, Mandarin Chinese', 'CST (UTC+8)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  38, 1, 'Arrival in Lhasa & Acclimatization', 'Lhasa, Tibet', 
  'Arrive at Lhasa Gonggar Airport and transfer to a hotel near the Barkhor. Spend the day acclimatizing at 3,650 meters — hydrate constantly, walk slowly, and take a gentle stroll around the Barkhor kora circuit as afternoon light gilds the Jokhang Temple''s golden roof.', '["First glimpse of the Potala Palace from the airport road","Gentle acclimatization walk around the Barkhor kora","Spin prayer wheels alongside Tibetan pilgrims","Evening yak-butter tea at a traditional Tibetan teahouse"]', 'https://images.pexels.com/photos/2149749/pexels-photo-2149749.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  38, 2, 'Potala Palace & Jokhang Temple', 'Lhasa, Tibet', 
  'Climb the 300-odd steps to the Potala Palace, winter residence of the Dalai Lamas since the 17th century, marveling at jewel-encrusted stupas and murals depicting Buddhist cosmology. Descend to the Jokhang Temple, Tibet''s holiest shrine, where the scent of juniper incense and melted yak butter permeates every room.', '["Explore the Potala''s 1,000 rooms of murals and golden stupas","Prostrate with pilgrims at the Jokhang''s ancient entrance","Browse thangka paintings and turquoise jewelry in Barkhor market","Watch sunset paint the Potala from the rooftop of a Barkhor café"]', 'https://images.pexels.com/photos/4088095/pexels-photo-4088095.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  38, 3, 'Sera Monastery & Drepung', 'Lhasa outskirts, Tibet', 
  'Witness the famed debating monks at Sera Monastery, where novices challenge each other with dramatic hand-claps in the afternoon sun. Continue to Drepung Monastery, once home to 10,000 monks and the seat of Tibet''s government before the Potala was built.', '["Watch monks'' spirited philosophical debates at Sera courtyard","Explore Drepung''s vast whitewashed monastic complex","Visit the giant thangka-unveiling wall on Drepung''s hillside","Sample momos and thukpa noodle soup at a monastery canteen"]', 'https://images.pexels.com/photos/35997831/pexels-photo-35997831.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  38, 4, 'Yamdrok Lake & Gyantse', 'Yamdrok Lake & Gyantse, Tibet', 
  'Drive over Kamba La Pass at 4,700 meters for your first staggering view of Yamdrok Lake, its turquoise surface ringed by snow-capped peaks and grazing yaks. Continue to Gyantse to explore the Kumbum stupa''s nine tiers of Buddhist murals at Pelkor Chöde Monastery.', '["Photograph Yamdrok Lake''s impossible turquoise from Kamba La Pass","Encounter yak herders on the high-altitude grasslands","Climb the tiered Kumbum stupa in Gyantse''s monastery complex","Overnight in Gyantse with views of the Dzong fortress"]', 'https://images.pexels.com/photos/6666087/pexels-photo-6666087.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  38, 5, 'Everest Base Camp & Return', 'Everest Base Camp, Tibet', 
  'Embark on the dramatic jeep journey to Everest Base Camp North, crossing the Friendship Highway past Shigatse and through barren, wind-scoured valleys. Arrive at the tent camp at 5,200 meters for an unforgettable sunset and sunrise over the world''s highest peak.', '["Drive the Friendship Highway through Tibet''s stark plateau","Stand at 5,200 meters facing Everest''s north face","Sunrise over Chomolungma from Everest Base Camp","Return via Rongbuk Monastery, the world''s highest monastery"]', 'https://images.pexels.com/photos/3747567/pexels-photo-3747567.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  38, 'Potala Palace Pilgrimage', 'Ascend the palace''s seemingly endless steps to rooms filled with golden Buddhas, jeweled stupas, and centuries of Tibetan religious art.', 'Landmark', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  38, 'Barkhor Kora Walking', 'Join the clockwise stream of pilgrims circling the Jokhang Temple, spinning brass prayer wheels and inhaling the smoke of juniper offerings.', 'Heart', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  38, 'Monk Debate Observation', 'Watch Sera Monastery''s monks engage in high-energy philosophical debates, a tradition of rapid questioning punctuated by dramatic hand-claps.', 'GraduationCap', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  38, 'High-Altitude Lake Trek', 'Hike along the shores of Yamdrok or Namtso Lake, where turquoise waters meet snowfields at altitudes above 4,500 meters.', 'Mountain', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  38, 'Tibetan Cuisine Tasting', 'Savor yak-butter tea, hand-pulled thukpa noodle soup, and steamed momos filled with yak meat at Lhasa''s traditional eateries.', 'Utensils', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  38, 'Everest Base Camp Visit', 'Stand at the foot of the world''s tallest mountain on the Tibetan north side, an experience of raw altitude and unparalleled grandeur.', 'Mountain', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  38, 'A Tibet Travel Permit is mandatory and must be arranged through a licensed tour agency at least 20 days before arrival.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  38, 'Spend at least two full days in Lhasa acclimatizing before heading to higher altitudes — altitude sickness is dangerous above 4,000 meters.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  38, 'Carry Diamox (acetazolamide) as a precaution and drink at least 3-4 liters of water daily.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  38, 'Pack extreme sun protection — UV radiation is intense at high altitude, even on overcast days.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  38, 'Respect local customs: always walk clockwise around monasteries and stupas, and ask before photographing monks or pilgrims.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  38, 'Bring cash in Chinese yuan; ATMs outside Lhasa are rare and unreliable.', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  38, 'Pack thermal layers, a down jacket, and a good sleeping bag — nights are cold year-round, even in summer.', 6
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  38, 'https://images.pexels.com/photos/2149749/pexels-photo-2149749.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  38, 'https://images.pexels.com/photos/4088095/pexels-photo-4088095.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
