INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'xian', 'Xi''an', 'China', 'East Asia', 
  'Terracotta Warriors, ancient city walls, Silk Road origins', '/images/dest-9.jpg', 'Xi''an is where China''s story begins. For over a millennium it served as the imperial capital under thirteen dynasties, and its DNA is woven from the threads of the Silk Road that once terminated at its western gates. The discovery of the Terracotta Army in 1974 — over 8,000 life-sized warriors buried for 2,200 years to guard Emperor Qin Shi Huang in the afterlife — transformed Xi''an from a provincial city into one of the world''s most compelling archaeological destinations.

But there is far more to Xi''an than its famous warriors. The intact Ming-dynasty city wall, a 14-kilometer circuit of rammed earth and grey brick, offers one of China''s great urban experiences when cycled at sunset. Inside the walls, the Muslim Quarter''s narrow alleys teem with sizzling lamb skewers, hand-pulled biangbiang noodles, and pomegranate juice vendors, a living legacy of the Hui Muslim community that has called this neighborhood home since the Tang dynasty.

Venture beyond the city to the Wild Goose Pagoda, built to house Buddhist scriptures brought from India, or to Huashan — one of China''s five sacred mountains — where chain-assisted trails cling to sheer granite cliffs above misty valleys. Xi''an is not just a museum piece; it is a vibrant, deeply layered city where the ancient Silk Road still flavors every meal and every street corner.', 
  108.94, 34.34, 'Heritage', 'bg-purple-500', 
  'Terracotta Warriors, ancient city walls, and Silk Road origins.', '/images/offer-5.jpg', 
  'published', '', '4 Days', 
  'Xi''an (capital of Shaanxi Province)', 'Chinese Yuan (¥ / CNY)', 'Semi-arid continental with hot summers and cold, dry winters', 'April–May & September–October for comfortable sightseeing weather', 
  'Mandarin Chinese', 'CST (UTC+8)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  39, 1, 'City Wall & Muslim Quarter', 'Xi''an City Center', 
  'Rent a bicycle atop Xi''an''s 600-year-old city wall and ride the full 14-kilometer circuit as the setting sun silhouettes the guard towers. Descend into the Muslim Quarter''s Beiyuanmen Street for a feast of roujiamo meat sandwiches, lamb paomo soup, and persimmon cakes sizzling on iron griddles.', '["Cycle the full circuit of the ancient Ming-dynasty city wall","Sunset over the guard towers from the wall''s southern gate","Feast on roujiamo and biangbiang noodles in the Muslim Quarter","Visit the Great Mosque''s tranquil garden courtyards"]', '/images/tour-8.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  39, 2, 'Terracotta Warriors & Huaqing Palace', 'Lintong District, Xi''an', 
  'Stand before Pit 1''s 6,000 warriors — each face unique, each hairstyle a clue to rank and regiment — and feel the scale of Qin Shi Huang''s ambition. Afterward, visit Huaqing Palace''s hot spring pools where Tang emperor Xuanzong famously bathed with his concubine Yang Guifei.', '["Walk the edge of Pit 1 and study the warriors'' individual expressions","See the bronze chariots in the museum''s climate-controlled hall","Soak in history at Huaqing Palace''s imperial hot springs","Evening Tang Dynasty music and dance performance"]', '/images/dest-12.jpg', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  39, 3, 'Wild Goose Pagoda & Shaanxi Museum', 'Xi''an South, Shaanxi', 
  'Begin at the Big Wild Goose Pagoda, a seventh-century brick tower built to house Buddhist sutras carried overland from India. Cross to the Shaanxi History Museum, whose collection of Tang gold and silver, jade burial suits, and Silk Road artifacts ranks among China''s finest.', '["Climb the Big Wild Goose Pagoda for rooftop views of Xi''an","Marvel at Tang dynasty gold and jade in Shaanxi History Museum","Watch the musical fountain show at Big Wild Goose Pagoda Square","Taste yangrou paomo lamb soup at a local specialty restaurant"]', '/images/about-5.jpg', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  39, 4, 'Mount Huashan Sacred Climb', 'Huashan, Shaanxi Province', 
  'Take the early train to Huashan and ascend via the west peak gondola, then hike across plank walks bolted to sheer cliff faces and knife-edge ridges connecting the mountain''s five peaks. The Plank Walk in the Sky — narrow boards suspended over a 2,000-meter drop — is one of the world''s most thrilling trails.', '["Ride the gondola to Huashan''s west peak above the clouds","Traverse the legendary Plank Walk in the Sky","Summit the south peak, Huashan''s highest point at 2,155 meters","Photograph the chain-lined trail along the knife-edge ridge"]', '/images/explor-4.jpg', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  39, 'Terracotta Army Discovery', 'Stand inches from 2,200-year-old soldiers with individually sculpted faces, one of archaeology''s most astonishing encounters.', 'Landmark', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  39, 'Muslim Quarter Food Tour', 'Devour roujiamo, biangbiang noodles, lamb skewers, and persimmon cakes along the Hui community''s centuries-old food streets.', 'Utensils', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  39, 'City Wall Cycling', 'Pedal the full 14-kilometer loop atop the Ming-dynasty ramparts at golden hour, passing watchtowers and overlooking rooftop courtyards.', 'MapPin', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  39, 'Mount Huashan Trek', 'Challenge one of China''s five sacred mountains, from chain-assisted cliff paths to the vertigo-inducing Plank Walk in the Sky.', 'Mountain', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  39, 'Tang Dynasty Show', 'Watch a lavish evening performance of Tang-era music and dance in a theater modeled on an imperial palace banquet hall.', 'Heart', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  39, 'Book Terracotta Warriors tickets online in advance — entry is timed and slots fill quickly during peak season.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  39, 'Visit the warriors early in the morning or late afternoon to avoid the worst tour-group congestion.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  39, 'The Muslim Quarter is busiest (and best) in the evening; go after 6 p.m. for the full sensory experience.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  39, 'Wear hiking boots and gloves for Mount Huashan — the chain-assisted sections require a good grip.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  39, 'Xi''an''s metro is efficient; Line 2 connects the train station to the city center and the Wild Goose Pagoda area.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  39, 'Carry small cash for street food stalls — not all vendors in the Muslim Quarter accept mobile payment.', 5
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  39, '/images/banner-4.jpg', 0
);
