INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'guilin', 'Guilin', 'China', 'East Asia', 
  'Karst mountains, Li River cruises, otherworldly landscapes', 'https://images.pexels.com/photos/131398/pexels-photo-131398.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 'Guilin''s landscape looks like a Chinese ink painting come to life. Hundreds of karst limestone peaks — some draped in mist, others reflected in mirror-still rice paddies — rise abruptly from a patchwork of emerald fields along the Li River, creating a scenery so iconic it graces the back of the 20-yuan banknote. Poets and painters have rhapsodized about Guilin for over a thousand years, and standing on the banks of the Li River at dawn, it is easy to understand why.

The classic experience is the four-hour bamboo-raft cruise from Guilin to Yangshuo, drifting past water-buffalo farmers, fishermen casting nets from narrow boats, and karst formations with evocative names like Nine Horses Fresco Hill and Yellow Cloth Shoal. Yangshuo itself is a traveler''s haven — a compact town where you can rent a bicycle and pedal through rice terraces to the ancient village of Xingping, or rock-climb limestone cliffs that attract climbers from around the globe.

Beyond the river corridor, Guilin offers the staggering Longji Rice Terraces, where Zhuang and Yao minority villages perch on mountainsides sculpted into curved stairways of water and grain stretching from valley floor to summit. These terraces, built over 700 years ago, are at their most magical in May when flooded paddies reflect the sky, and in October when ripened rice turns the hillsides to gold.', 
  110.29, 25.27, 'Nature', 'bg-teal-500', 
  'Karst mountains, Li River cruises, and otherworldly landscapes.', '/images/trand-1.jpg', 
  'published', '', '5 Days', 
  NULL, 'Chinese Yuan (¥ / CNY)', 'Subtropical monsoon with warm, humid summers and mild winters', 'April–October; May for flooded rice terraces, October for golden harvest', 
  'Mandarin Chinese, Zhuang, Yao', 'CST (UTC+8)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  40, 1, 'Guilin Arrival & Elephant Trunk Hill', 'Guilin City Center', 
  'Arrive in Guilin and head to Elephant Trunk Hill, the city''s most recognizable landmark, where a karst formation resembles an elephant drinking from the Li River. Spend the evening strolling the Two Rivers and Four Lakes waterway, where illuminated pagodas and bridges reflect in the still water.', '["Photograph Elephant Trunk Hill''s iconic arch at sunset","Evening boat cruise through the Two Rivers and Four Lakes","Sample Guilin rice noodles at a local breakfast stall","Walk Zhengyang Pedestrian Street''s night market"]', 'https://images.pexels.com/photos/131398/pexels-photo-131398.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  40, 2, 'Li River Cruise to Yangshuo', 'Li River, Guilin to Yangshuo', 
  'Board a bamboo raft at dawn and drift downstream on the Li River as karst peaks emerge from morning mist like the teeth of sleeping dragons. Pass water-buffalo wading through shallows, cormorant fishermen, and the famous 20-yuan banknote view at Xingping, arriving in Yangshuo by midday.', '["Bamboo raft through the Li River''s most dramatic karst corridor","Photograph the 20-yuan banknote view at Xingping","Spot cormorant fishermen and water buffalo along the banks","Arrive in Yangshuo for an afternoon of exploration"]', 'https://images.pexels.com/photos/36398300/pexels-photo-36398300.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  40, 3, 'Yangshuo Cycling & Impression Liu Sanjie', 'Yangshuo, Guangxi', 
  'Rent a bicycle and pedal the countryside loop past Moon Hill''s natural limestone arch, through rice paddies dotted with karst towers, and along the Yulong River where locals punt bamboo rafts through knee-deep water. At nightfall, watch Impression Liu Sanjie — Zhang Yimou''s open-air spectacular performed on the river with 600 cast members and twelve karst peaks as the backdrop.', '["Cycle through rice paddies to Moon Hill''s limestone arch","Float the Yulong River on a hand-punted bamboo raft","Rock climb limestone cliffs at one of Yangshuo''s outdoor crags","Impression Liu Sanjie nighttime river performance"]', 'https://images.pexels.com/photos/36398292/pexels-photo-36398292.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  40, 4, 'Longji Rice Terraces', 'Longsheng County, Guangxi', 
  'Drive two hours north to the Longji (Dragon''s Backbone) Rice Terraces, where stepped paddies climb from valley floor to misty summit in sinuous curves. Hike between Zhuang and Yao minority villages, share a farmhouse lunch of bamboo-tube rice, and watch Yao women with waist-length hair perform traditional weaving.', '["Hike the terraces from Ping''an to Dazhai village","Lunch with a Zhuang family in a wooden stilted house","Watch Yao women demonstrate indigo-dyeing and weaving","Panoramic sunrise or sunset from Viewpoint No. 2"]', 'https://images.pexels.com/photos/2362085/pexels-photo-2362085.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  40, 5, 'Reed Flute Cave & Departure', 'Guilin, Guangxi', 
  'Return to Guilin for a morning visit to Reed Flute Cave, a 240-meter-deep limestone cavern illuminated by multicolored lights that reveal stalactites, stalagmites, and underground pools. Enjoy a final bowl of Guilin rice noodles before departing.', '["Explore Reed Flute Cave''s illuminated underground galleries","See the Crystal Palace chamber''s vast stalactite formations","Final Guilin rice noodle breakfast with pickled beans and chili","Browse local ink paintings and calligraphy at Guilin art shops"]', 'https://images.pexels.com/photos/6343452/pexels-photo-6343452.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  40, 'Li River Bamboo Rafting', 'Drift on a bamboo raft through the heart of China''s most iconic karst landscape, a four-hour journey through living poetry.', 'Waves', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  40, 'Yangshuo Rock Climbing', 'Scale limestone cliffs above emerald rice paddies at world-class crags like Swiss Cheese and Moon Hill, suitable for beginners and experts alike.', 'Mountain', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  40, 'Rice Terrace Photography', 'Capture the Longji Terraces at dawn when flooded paddies mirror the sky, creating an endless stairway of reflected clouds.', 'Camera', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  40, 'Guilin Rice Noodle Tasting', 'Slurp your way through variations of Guilin''s iconic mifen rice noodles — in broth, dry-tossed, or with horse-meat topping — at stalls where the recipe hasn''t changed in decades.', 'Utensils', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  40, 'Cormorant Fishing Demonstration', 'Watch traditional fishermen work with trained cormorants at dusk on the Li River, a practice dating back 1,300 years.', 'Globe', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  40, 'Minority Village Homestay', 'Stay overnight with a Zhuang or Yao family in the Longji Terraces, learning traditional weaving, sharing home-cooked meals, and waking to rice-terrace panoramas.', 'Heart', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  40, 'Book the Li River cruise or bamboo raft in advance during peak season (April–October); early morning departures offer the best light and thinnest crowds.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  40, 'Bring rain gear year-round — Guilin''s subtropical climate means sudden showers, and misty conditions actually enhance the scenery.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  40, 'Rent an electric scooter in Yangshuo for maximum countryside freedom, but carry your international driving permit.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  40, 'Haggle gently at Yangshuo''s West Street market — initial prices are typically double the fair rate.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  40, 'For Longji Rice Terraces, stay overnight in a village guesthouse to experience sunrise without the day-tripper crowds.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  40, 'The high-speed train connects Guilin to Guangzhou in under three hours — a convenient onward connection.', 5
);
