INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'kyoto', 'Kyoto', 'Japan', 'East Asia', 
  'Zen temples, bamboo groves, geisha districts, tea ceremonies', 'https://images.pexels.com/photos/3995905/pexels-photo-3995905.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 'Kyoto is the soul of Japan — a city of 2,000 temples and shrines, 17 UNESCO World Heritage Sites, and a cultural continuity stretching back 1,200 years to when Emperor Kanmu chose this mountain-ringed valley as his imperial capital. Walk through the vermillion tunnel of 10,000 torii gates at Fushimi Inari, sit in meditation before Ryoan-ji''s enigmatic rock garden, or follow a geiko in full regalia through Gion''s lantern-lit cobblestones, and you begin to understand why Kyoto was deliberately spared from bombing in World War II.

The city''s rhythm follows the seasons with almost ceremonial precision. Spring arrives in an explosion of cherry blossoms along the Philosopher''s Path and the Kamo River; summer brings firefly-lit evenings and the spectacular Gion Matsuri float procession; autumn transforms the gardens of Tofuku-ji and Eikan-do into tunnels of crimson and gold; winter drapes Kinkaku-ji''s golden pavilion in snow, creating perhaps Japan''s most photographed scene.

Beyond the famous sights, Kyoto rewards slow exploration. Duck into a machiya townhouse converted into a matcha café, watch a master potter throw Kiyomizu-yaki ceramics on a hand-spun wheel, or reserve a seat at a seven-course kaiseki dinner where each dish is a miniature landscape reflecting the current season. Kyoto doesn''t just preserve tradition — it lives and breathes it.', 
  135.77, 35.01, 'Spiritual', 'bg-violet-500', 
  'Zen temples, bamboo groves, geisha districts, and ancient tea ceremonies.', '/images/tour-6.jpg', 
  'published', '', '5 Days', 
  NULL, 'Japanese Yen (¥)', 'Humid subtropical with hot, humid summers and cold winters', 'Late March–April (cherry blossom) & mid-November (peak autumn color)', 
  'Japanese', 'JST (UTC+9)', 'Left'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  41, 1, 'Fushimi Inari & Eastern Higashiyama', 'Fushimi & Higashiyama, Kyoto', 
  'Arrive early at Fushimi Inari Taisha and hike the winding trail through 10,000 vermillion torii gates up Mount Inari before the crowds descend. In the afternoon, wander the preserved streets of Higashiyama — the Ninenzaka and Sannenzaka stone-paved slopes — stopping at Kiyomizu-dera for panoramic views from its cantilevered wooden stage.', '["Walk through the endless vermillion torii tunnel at dawn","Summit Mount Inari for views over southern Kyoto","Stroll the stone-paved Ninenzaka and Sannenzaka lanes","Sunset from Kiyomizu-dera''s wooden stage overlooking the city"]', 'https://images.pexels.com/photos/3995905/pexels-photo-3995905.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  41, 2, 'Arashiyama Bamboo & Zen Gardens', 'Arashiyama & Northwest Kyoto', 
  'Enter the towering bamboo grove of Arashiyama as morning light filters through the swaying culms, then cross the Togetsukyo Bridge for views of Monkey Park''s macaques against the mountains. Spend the afternoon contemplating Ryoan-ji''s fifteen-stone rock garden and Kinkaku-ji, whose golden pavilion gleams above its mirror-like pond.', '["Walk through Arashiyama''s soaring bamboo grove at sunrise","Feed wild macaques at Iwatayama Monkey Park","Meditate before Ryoan-ji''s enigmatic dry rock garden","Photograph Kinkaku-ji''s gold reflection in the pond"]', 'https://images.pexels.com/photos/36352205/pexels-photo-36352205.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  41, 3, 'Gion, Tea Ceremony & Kaiseki', 'Gion & Central Kyoto', 
  'Spend the morning at a traditional tea ceremony in a century-old machiya townhouse, learning the precise choreography of whisking matcha. Explore Nishiki Market''s 400-meter arcade of 130 food stalls, then dress in a rental kimono for an evening walk through Gion''s Hanami-koji, where geiko and maiko shuffle between teahouses in the twilight.', '["Participate in a matcha tea ceremony in a machiya townhouse","Graze through Nishiki Market''s pickles, mochi, and dashimaki tamago","Stroll Gion''s Hanami-koji in a rented kimono at dusk","Seven-course kaiseki dinner showcasing seasonal Kyoto cuisine"]', 'https://images.pexels.com/photos/36352182/pexels-photo-36352182.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  41, 4, 'Philosopher''s Path & Nara Day Trip', 'Northern Higashiyama & Nara', 
  'Walk the Philosopher''s Path along a cherry-tree-lined canal from Ginkaku-ji''s silver pavilion to Nanzen-ji''s brick aqueduct. Board the train to Nara, where sacred deer bow for crackers in the park surrounding Todai-ji, home to the world''s largest bronze Buddha.', '["Stroll the Philosopher''s Path beneath cherry or maple canopy","Explore Nanzen-ji''s imposing Sanmon gate and brick aqueduct","Feed bowing deer in Nara Park","Stand before Todai-ji''s 15-meter-tall Great Buddha"]', 'https://images.pexels.com/photos/28157162/pexels-photo-28157162.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  41, 5, 'Uji Tea Town & Byodo-in', 'Uji, Kyoto Prefecture', 
  'Take the short train to Uji, Japan''s tea capital, for a stone-grinding matcha workshop and a walk along the Uji River to Byodo-in — the phoenix-hall temple immortalized on the 10-yen coin. Return to Kyoto for a final soak in a sento bathhouse.', '["Grind your own matcha at a Uji tea farm workshop","Visit Byodo-in''s Phoenix Hall, featured on the 10-yen coin","Walk the Uji River path lined with tea merchant shops","Evening soak at a traditional Kyoto sento bathhouse"]', 'https://images.pexels.com/photos/6226209/pexels-photo-6226209.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  41, 'Torii Gate Hike', 'Ascend Mount Inari through 10,000 vermillion torii gates, a mystical two-hour hike that winds through forest shrines and fox statues.', 'Mountain', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  41, 'Kaiseki Dining Experience', 'Savor a multi-course kaiseki meal where each dish is a seasonal work of art, served in a private tatami room overlooking a Zen garden.', 'Utensils', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  41, 'Geisha District Evening Walk', 'Wander Gion''s lantern-lit cobblestone streets at twilight, catching glimpses of geiko and maiko gliding between ochaya teahouses.', 'Heart', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  41, 'Matcha Tea Ceremony', 'Learn the 400-year-old art of preparing matcha from a tea master in a hushed machiya, every movement a meditation.', 'BookOpen', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  41, 'Temple Garden Photography', 'Capture Kyoto''s iconic scenes — the golden pavilion''s reflection, Ryoan-ji''s raked gravel, Tofuku-ji''s autumn fire — in changing seasonal light.', 'Camera', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  41, 'Nishiki Market Food Tour', 'Taste your way through Kyoto''s Kitchen — grilled mochi, matcha soft-serve, soy-milk donuts, and uni-topped rice crackers along 130 stalls.', 'MapPin', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  41, 'Visit Fushimi Inari and the bamboo grove before 8 a.m. to experience them without crowds — they are open 24/7.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  41, 'Buy a one-day Kyoto bus pass for ¥700 — most major temples are reachable by the comprehensive city bus network.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  41, 'Reserve kaiseki restaurants at least two weeks ahead; top establishments like Kikunoi require a month''s notice.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  41, 'Rent a bicycle for the Philosopher''s Path area — Kyoto is flat and cycling is the fastest way to temple-hop.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  41, 'Carry cash; many traditional shops, temples, and smaller restaurants don''t accept credit cards.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  41, 'Gion etiquette: do not stop, touch, or block geiko and maiko for photographs — observe respectfully from a distance.', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  41, 'If visiting during cherry blossom or autumn foliage, book accommodation three to six months in advance.', 6
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  41, 'https://images.pexels.com/photos/3995905/pexels-photo-3995905.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
