INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'osaka', 'Osaka', 'Japan', 'East Asia', 
  'Japan''s kitchen, street food capital, vibrant nightlife', 'https://images.pexels.com/photos/4456247/pexels-photo-4456247.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 'If Tokyo is Japan''s head, Osaka is its stomach. The people here greet each other with ''mokari makka?'' — ''are you making money?'' — a reflection of the city''s merchant roots and its frank, no-nonsense warmth. Osaka invented or perfected many of Japan''s most beloved street foods: the crispy-shelled takoyaki octopus ball, the layered okonomiyaki savory pancake, and the deep-fried kushikatsu skewer. In Dotonbori, where neon signs and mechanical crabs compete for attention over a glittering canal, eating is not just encouraged — it''s the entire point.

But Osaka is far more than a food city. Its castle — a gleaming white-and-gold keep rising from massive stone foundations — anchors a sprawling park that erupts in pink each cherry blossom season. The Shinsekai district, modeled after early-20th-century New York and Paris, retains a retro charm with its Tsutenkaku Tower, old-school game parlors, and kushikatsu joints where the golden rule is ''no double-dipping.'' Underground, the city hides a parallel world in its vast shopping arcades — Shinsaibashi-suji stretches for 600 meters of boutiques, vintage stores, and dessert counters.

As night falls, Osaka transforms. The bars of Ura-Namba pour expertly crafted highballs in rooms that seat six, the comedy clubs of Namba Grand Kagetsu showcase Japan''s capital of stand-up humor, and the late-night ramen counters keep steaming until dawn. Osaka doesn''t sleep — it just changes course.', 
  135.5, 34.69, 'Food', 'bg-orange-500', 
  'Japan''s kitchen — street food capital with a vibrant nightlife scene.', '/images/city-6.jpg', 
  'published', '', '4 Days', 
  NULL, 'Japanese Yen (¥)', 'Humid subtropical with hot, sticky summers and cool winters', 'March–May (cherry blossom) & October–November (autumn festivals)', 
  'Japanese (Kansai dialect)', 'JST (UTC+9)', 'Left'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  42, 1, 'Dotonbori & Shinsekai Food Crawl', 'Dotonbori & Shinsekai, Osaka', 
  'Plunge straight into Osaka''s neon-lit food paradise. Start at Dotonbori''s canal, where the giant Glico Running Man sign and mechanical Kani Doraku crab mark the entrance to Japan''s densest concentration of street-food stalls. Cross to Shinsekai for kushikatsu — breaded, deep-fried skewers of everything from lotus root to quail egg — washed down with draft beer under the glow of Tsutenkaku Tower.', '["Taste takoyaki at the legendary Kukuru stall by the canal","Eat fluffy okonomiyaki griddled before you at Mizuno","Double-dip-forbidden kushikatsu feast in Shinsekai''s Daruma","Photograph the Glico Man and canal reflections at night"]', 'https://images.pexels.com/photos/4456247/pexels-photo-4456247.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  42, 2, 'Osaka Castle & Kuromon Market', 'Chuo Ward, Osaka', 
  'Explore Osaka Castle''s eight-floor museum tracing the rise and fall of Toyotomi Hideyoshi, then stroll the surrounding park where 600 cherry trees bloom in early April. In the afternoon, graze through Kuromon Ichiba Market''s 170 stalls — slurp sea-urchin from the shell, try A5 wagyu seared on a countertop grill, and sample fugu blowfish sashimi.', '["Climb Osaka Castle''s keep for panoramic city views","Walk beneath 600 cherry trees in Nishinomaru Garden","Eat sea urchin straight from the shell at Kuromon Market","Taste A5 wagyu beef seared on a tabletop charcoal grill"]', 'https://images.pexels.com/photos/5288650/pexels-photo-5288650.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  42, 3, 'Nara Day Trip & Sake Tasting', 'Nara & Fushimi, Kansai Region', 
  'Take the 45-minute train to Nara, where over 1,200 sacred deer roam freely in the park. Visit Todai-ji''s Great Buddha Hall, then continue to the Fushimi sake district of southern Kyoto, touring Gekkeikan''s Edo-period brewery and tasting daiginjo sake straight from the cedar vat.', '["Feed bowing deer at Nara''s ancient park","Stand beneath Todai-ji''s colossal bronze Daibutsu","Tour Gekkeikan Okura Sake Museum''s Edo-period brewery","Taste fresh daiginjo sake from traditional cedar cups"]', 'https://images.pexels.com/photos/6249413/pexels-photo-6249413.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  42, 4, 'Ura-Namba Nightlife & Cooking Class', 'Namba, Osaka', 
  'Join a morning cooking class to master the art of Osaka-style okonomiyaki and takoyaki, learning the precise batter ratios and wrist-flick techniques. Spend the evening bar-hopping through Ura-Namba''s intimate standing bars — try a lemon sour at a six-seat counter bar, then end the night with tonkotsu ramen at Ichiran''s solo-booth experience.', '["Learn to flip takoyaki in an Osaka cooking class","Bar-hop Ura-Namba''s intimate standing-bar scene","Catch live comedy at Namba Grand Kagetsu theater","Late-night tonkotsu ramen at Ichiran''s solo booths"]', 'https://images.pexels.com/photos/4456237/pexels-photo-4456237.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  42, 'Dotonbori Street Food Crawl', 'Eat your way along Japan''s most famous food street — takoyaki, okonomiyaki, gyoza, and taiyaki — under a canyon of neon signs and animatronic mascots.', 'Utensils', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  42, 'Osaka Castle & Cherry Blossoms', 'Explore the gold-crested castle keep and its surrounding moat, especially magical during hanami season when 600 cherry trees bloom simultaneously.', 'Landmark', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  42, 'Kuromon Market Grazing', 'Wander Osaka''s ''kitchen'' market, sampling fresh sashimi, grilled scallops, wagyu skewers, and seasonal fruit from 170 specialist stalls.', 'MapPin', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  42, 'Comedy & Nightlife', 'Experience Osaka''s title as Japan''s comedy capital at Namba Grand Kagetsu, then dive into Ura-Namba''s intimate bar scene.', 'Heart', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  42, 'Retro Shinsekai District', 'Step back in time in this early-20th-century entertainment district, with its Tsutenkaku Tower, old-school game parlors, and legendary kushikatsu restaurants.', 'Globe', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  42, 'Get the Osaka Amazing Pass (1 or 2 day) for free entry to 50+ attractions including Osaka Castle and river cruises, plus unlimited subway rides.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  42, 'Dotonbori is best experienced after dark when the neon fully illuminates — arrive around 6 p.m. for dinner crowds and energy.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  42, 'The golden rule at kushikatsu restaurants: never double-dip your skewer in the communal sauce. Use the cabbage leaf to scoop extra sauce instead.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  42, 'Osaka''s subway closes around midnight; plan late-night returns by taxi or stay near Namba for walkable nightlife.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  42, 'Kuromon Market stalls close by 5 p.m. and some close on Wednesdays — go before noon for the freshest selection.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  42, 'Osaka is an excellent base for day trips to Nara (45 min), Kyoto (15 min by shinkansen), and Kobe (20 min).', 5
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  42, 'https://images.pexels.com/photos/4456247/pexels-photo-4456247.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  42, 'https://images.pexels.com/photos/5288650/pexels-photo-5288650.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  42, 'https://images.pexels.com/photos/6249413/pexels-photo-6249413.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_images` (
