INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'seoul', 'Seoul', 'South Korea', 'East Asia', 
  'K-culture, historic palaces, tech innovation, universities', 'https://images.pexels.com/photos/380707/pexels-photo-380707.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 'Seoul is a city running at two speeds simultaneously — a dynamo of K-pop studios, tech campuses, and 24-hour neon districts layered atop 600 years of Joseon dynasty palaces, Confucian shrines, and fortress walls that still trace the mountain ridges above the city. Gyeongbokgung Palace''s throne hall commands the same north-south axis it has since 1395, while just blocks away, Gangnam''s glass towers and underground malls pulse with the energy that birthed Samsung, BTS, and the global hallyu wave.

Food is Seoul''s universal language. From the sizzling barbecue tables of Mapo-gu — where thick slabs of samgyeopsal pork belly char over charcoal — to the elegant banchan spreads of a Jongno hanok restaurant, the city delivers intensity in every bite. Night markets in Myeongdong overflow with hotteok pancakes, tteokbokki spicy rice cakes, and tornado potatoes on sticks, while Michelin-starred temples like Jungsik reimagine Korean cuisine with foams, gels, and precision plating.

Beyond eating and sightseeing, Seoul''s creative districts reward wandering. Ikseon-dong''s hanok alleys hide craft-cocktail bars in century-old tiled-roof houses, Hongdae''s streets vibrate with indie musicians and mural art, and the Dongdaemun Design Plaza — Zaha Hadid''s silvery mothership — hosts cutting-edge fashion shows inside a building that looks beamed in from the future.', 
  126.98, 37.57, 'Education', 'bg-indigo-500', 
  'Field trips to Samsung & Hyundai factories, DMZ border tours, historic palace visits, and K-culture immersion.', '/images/dest-1.jpg', 
  'published', '', '5 Days', 
  'Seoul (national capital)', 'South Korean Won (₩)', 'Humid continental with hot, humid summers and cold, dry winters', 'April–May (cherry blossom) & September–November (golden autumn)', 
  'Korean', 'KST (UTC+9)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  44, 1, 'Gyeongbokgung Palace & Bukchon Hanok Village', 'Jongno-gu, Seoul', 
  'Watch the royal guard-changing ceremony at Gyeongbokgung, then explore the palace''s grand throne hall and lotus-pond pavilion. Walk to Bukchon Hanok Village, where 600 traditional tiled-roof houses line steep lanes with views of both palaces and the Seoul Tower skyline.', '["Witness the Gwanghwamun royal guard-changing ceremony","Explore Gyeongbokgung''s throne hall and Hyangwonjeong Pavilion","Photograph the hanok rooftops of Bukchon''s hilltop lanes","Rent a hanbok and receive free palace admission"]', 'https://images.pexels.com/photos/380707/pexels-photo-380707.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  44, 2, 'DMZ & War Memorial', 'DMZ & Yongsan, Seoul', 
  'Join a guided tour to the Demilitarized Zone, peering into North Korea from the Joint Security Area''s blue negotiation huts and descending into a North Korean infiltration tunnel. Return to Seoul for the sobering War Memorial of Korea, where fighter jets, tanks, and personal testimonies trace the peninsula''s divided history.', '["Stand at the JSA conference table straddling the border","Descend the Third Tunnel of Aggression beneath the DMZ","Look into North Korea from the Dora Observatory","Reflect at the War Memorial of Korea''s Hall of Remembrance"]', 'https://images.pexels.com/photos/36022528/pexels-photo-36022528.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  44, 3, 'Hongdae, Ikseon-dong & K-Culture', 'Mapo-gu & Jongno-gu, Seoul', 
  'Explore Hongdae''s indie music scene — buskers on every corner, vintage shops, and mural-covered alleys. Cross to Ikseon-dong, Seoul''s oldest hanok neighborhood reinvented as a hipster hub of craft-cocktail bars and artisan coffee roasters in tiled-roof houses. End with a K-pop dance class or a visit to a noraebang singing room.', '["Watch street performers and buskers in Hongdae''s plaza","Browse vintage and K-fashion boutiques in Hongdae alleys","Sip craft cocktails in Ikseon-dong''s hanok courtyard bars","Sing your heart out in a private noraebang room"]', 'https://images.pexels.com/photos/11869782/pexels-photo-11869782.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  44, 4, 'Gangnam, Starfield Library & Night Markets', 'Gangnam & Myeongdong, Seoul', 
  'Cross the Han River to Gangnam, visiting the soaring Starfield Library''s two-story bookshelves in COEX Mall and the sleek Bongeunsa Temple tucked behind glass towers. At night, dive into Myeongdong''s buzzing street-food market for hotteok, egg bread, and tornado potatoes, then browse ten floors of K-beauty at Olive Young.', '["Photograph Starfield Library''s towering book columns in COEX","Visit Bongeunsa Temple''s serene grounds amid Gangnam''s towers","Feast on Myeongdong street food — hotteok, tteokbokki, egg bread","Shop K-beauty products at Myeongdong''s flagship stores"]', 'https://images.pexels.com/photos/2128042/pexels-photo-2128042.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  44, 5, 'Namsan Tower & Korean BBQ Farewell', 'Jung-gu & Mapo-gu, Seoul', 
  'Hike or cable-car up Namsan Mountain to N Seoul Tower, where love-lock fences and panoramic city views await. Descend through Myeong-dong for last-minute shopping, then close your Seoul chapter with a legendary Korean BBQ feast — thick-cut samgyeopsal and marinated galbi sizzling over charcoal in Mapo-gu.', '["Panoramic views from N Seoul Tower''s observation deck","Lock a love padlock on Namsan''s famous fence","Last-minute K-beauty and fashion shopping in Myeongdong","Farewell samgyeopsal and galbi BBQ feast in Mapo-gu"]', 'https://images.pexels.com/photos/1637776/pexels-photo-1637776.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  44, 'Palace & Hanbok Experience', 'Rent a traditional hanbok and receive free entry to Seoul''s five grand palaces, posing for photos amid Joseon-era architecture.', 'Landmark', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  44, 'Korean BBQ Feast', 'Grill thick-cut samgyeopsal pork belly and marinated galbi ribs over charcoal at a Mapo-gu barbecue institution, wrapped in lettuce with ssamjang and garlic.', 'Utensils', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  44, 'K-Pop & Hallyu Immersion', 'Take a K-pop dance class in Gangnam, visit HYBE Insight for BTS artifacts, and catch a live music show in Hongdae''s indie venues.', 'Heart', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  44, 'DMZ Border Tour', 'Stand at the world''s most heavily fortified border, peering into North Korea from the Joint Security Area''s blue negotiation huts.', 'Globe', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  44, 'Jjimjilbang Spa Night', 'Spend an evening at a Korean jjimjilbang spa — rotating between hot pools, cold plunges, salt saunas, and sleeping on heated ondol floors.', 'Dumbbell', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  44, 'Street Food Night Tour', 'Graze through Gwangjang Market''s legendary stalls — bindaetteok mung-bean pancakes, mayak gimbap, and yukhoe raw beef tartare.', 'MapPin', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  44, 'Get a T-money card at any convenience store — it works on all subways, buses, and even taxis across the city.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  44, 'Seoul''s subway is world-class; free Wi-Fi is available on all trains and in most stations.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  44, 'Wearing a hanbok grants free entry to all five royal palaces — rental shops cluster near Gyeongbokgung.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  44, 'Book DMZ tours at least a week in advance; bring your passport, as military checkpoints require identification.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  44, 'Many restaurants and shops accept credit cards, but carry some cash for traditional markets and street food stalls.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  44, 'Download Naver Map or KakaoMap — Google Maps has limited functionality in South Korea due to national mapping regulations.', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  44, 'Tipping is not customary in South Korea and can sometimes cause confusion.', 6
);
