INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'busan', 'Busan', 'South Korea', 'East Asia', 
  'Coastal temples, colorful villages, seafood markets', 'https://images.pexels.com/photos/5051604/pexels-photo-5051604.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 'Busan is South Korea''s sun-and-salt counterweight to Seoul''s landlocked intensity — a sprawling port city where forested mountains tumble into the sea, Buddhist temples perch on ocean cliffs, and the country''s best seafood arrives on ice each dawn at Jagalchi Market. Korea''s second city has a swagger all its own: rougher-edged, more laid-back, and fiercely proud of its distinct dialect, its beaches, and its fiery dwaeji gukbap pork soup.

The city''s landscapes shift dramatically block by block. Haeundae Beach draws summer crowds to its crescent of golden sand flanked by glass-tower hotels, while just around the headland, the Haedong Yonggungsa Temple clings to seaside rocks where crashing waves spray mist onto prayer-bell visitors. Inland, the Gamcheon Culture Village — once a hillside war-refugee settlement — has reinvented itself as a pastel labyrinth of street art, tiny galleries, and rooftop cafés cascading down the slope like a Korean Santorini.

Busan''s culinary identity centers on the ocean. Jagalchi Fish Market''s second floor is a vast seafood restaurant where you choose your fish alive from the tanks below and it arrives at your table minutes later as sashimi. Milmyeon — cold wheat noodles in icy broth — is the city''s summer obsession, while ssiat hotteok (seed-filled sweet pancakes) from BIFF Square''s street carts have achieved near-religious status among locals.', 
  129.07, 35.18, 'Beach', 'bg-blue-500', 
  'Coastal temples, colorful villages, and fresh seafood markets.', '/images/dest-2.jpg', 
  'published', '', '4 Days', 
  NULL, 'South Korean Won (₩)', 'Humid subtropical with warm summers, mild winters, and monsoon rains in July', 'April–June & September–November for beach weather and clear skies', 
  'Korean (Gyeongsang dialect)', 'KST (UTC+9)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  45, 1, 'Jagalchi Market & BIFF Square', 'Nampo-dong, Busan', 
  'Start at Jagalchi Fish Market, Korea''s largest, where ajumma fishmongers slice live octopus at tableside and tanks hold everything from king crab to sea squirt. Cross to BIFF Square for ssiat hotteok — crispy pancakes stuffed with sunflower seeds, sugar, and cinnamon — then browse the vintage alleys of Gukje International Market.', '["Choose your fish alive at Jagalchi and eat it as sashimi upstairs","Try live sannakji octopus with sesame oil","Bite into a piping-hot ssiat hotteok at BIFF Square","Browse Gukje Market''s maze of vintage goods and street food"]', 'https://images.pexels.com/photos/5051604/pexels-photo-5051604.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  45, 2, 'Gamcheon Village & Taejongdae Cliffs', 'Saha-gu & Yeongdo-gu, Busan', 
  'Climb the pastel stairways of Gamcheon Culture Village, a hillside labyrinth of murals, miniature galleries, and rooftop cafés that earned its nickname as Busan''s Santorini. In the afternoon, hike the coastal trail at Taejongdae, a clifftop park where you can spot Japan''s Tsushima Island on clear days.', '["Photograph the pastel houses and street art of Gamcheon Village","Find the Little Prince statue hidden among the rooftops","Hike Taejongdae''s coastal cliff trail through pine forest","Spot Tsushima Island from the Taejongdae lighthouse viewpoint"]', 'https://images.pexels.com/photos/36612265/pexels-photo-36612265.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  45, 3, 'Haedong Yonggungsa & Haeundae Beach', 'Haeundae & Gijang, Busan', 
  'Descend the stone stairway to Haedong Yonggungsa Temple, spectacularly sited on ocean-battered rocks where spray from the East Sea mingles with incense smoke. Spend the afternoon at Haeundae Beach, walking the Moontan Road coastal trail or watching surfers ride the late-afternoon swell.', '["Visit Haedong Yonggungsa Temple perched on ocean cliffs","Walk the Moontan Road coastal boardwalk at Haeundae","Swim or surf at Haeundae''s crescent-shaped golden beach","Sunset seafood dinner at Haeundae''s beachfront raw-fish row"]', 'https://images.pexels.com/photos/5863417/pexels-photo-5863417.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  45, 4, 'Beomeosa Temple & Spa Land', 'Geumjeong-gu & Haeundae, Busan', 
  'Hike through the forested foothills of Geumjeongsan to Beomeosa, a 1,300-year-old mountain temple where monks chant at dawn beneath ancient wisteria. Descend and reward yourself at Spa Land in Centum City — Korea''s largest department-store spa complex — with Finnish saunas, bade pools, and heated jade rooms.', '["Hike through Geumjeongsan forest to the Beomeosa temple gates","Witness morning Buddhist chanting at the 1,300-year-old temple","Relax in Spa Land''s 22 themed hot-spring baths and saunas","Farewell milmyeon cold noodles at a legendary Busan noodle shop"]', 'https://images.pexels.com/photos/3643406/pexels-photo-3643406.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  45, 'Jagalchi Seafood Experience', 'Select your seafood from the ground-floor tanks and have it prepared as sashimi, grilled, or in spicy stew on the floor above — the freshest meal of your life.', 'Utensils', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  45, 'Gamcheon Village Art Walk', 'Wander Busan''s pastel-painted hillside village, discovering murals, sculptures, and tiny galleries tucked into a maze of stairways and alleys.', 'Camera', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  45, 'Haedong Yonggungsa Temple', 'Visit this oceanside temple where crashing waves, stone lanterns, and a golden Buddha create one of Korea''s most dramatic sacred settings.', 'Landmark', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  45, 'Haeundae Beach Day', 'Swim, surf, or stroll the Moontan Road boardwalk at Korea''s most famous beach, backed by a strip of raw-fish restaurants and ocean-view cafés.', 'Waves', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  45, 'Korean Spa Immersion', 'Spend hours rotating through Spa Land''s Finnish saunas, charcoal rooms, jade beds, and bade pools — a quintessential Korean wellness ritual.', 'Dumbbell', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  45, 'Gwangalli Night Views', 'Sip craft beer on Gwangalli Beach as the Diamond Bridge lights up in a rainbow of LED colors, framing the nighttime ocean.', 'Heart', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  45, 'The KTX high-speed train connects Seoul to Busan in under 2.5 hours — book in advance for window seats with the best views.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  45, 'Jagalchi Market is best visited early morning (before 9 a.m.) when the catch is freshest and the energy is highest.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  45, 'Busan''s beaches have strong currents; swim only within the designated buoy zones and heed lifeguard warnings.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  45, 'The Busan City Tour Bus (red or blue line) is an efficient way to hit spread-out attractions like Taejongdae and Haedong Yonggungsa.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  45, 'Gamcheon Village is a residential neighborhood — keep noise levels respectful and avoid photographing into private homes.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  45, 'Pack a light rain jacket from June through August; Busan''s monsoon season brings sudden, heavy downpours.', 5
);
