INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'khovsgol-lake', 'Khövsgöl Lake', 'Mongolia', 'East Asia', 
  'Mongolia''s Blue Pearl — horseback riding, kayaking, and reindeer herder encounters', 'https://images.pexels.com/photos/36103492/pexels-photo-36103492.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 'Lake Khövsgöl is Mongolia''s most beloved natural wonder — a deep, impossibly blue alpine lake in the country''s far north, cradled by pine-forested mountains and fed by more than 90 rivers. Nicknamed the ''Blue Pearl of Mongolia,'' it holds over 70% of the country''s freshwater and about 1% of the world''s fresh surface water. Its water is so pure that it is drunk directly from the shore, and on still days the reflected sky makes it difficult to tell where the lake ends and the heavens begin.

The lake sits within the Khövsgöl Nuur National Park, a wilderness of Siberian taiga forest, sub-alpine meadows carpeted with wildflowers in summer, and the high Sayan Mountain border with Russia. Brown bears roam the forest; elk and argali wild sheep graze the treeline; and the endangered Mongolian saiga antelope migrates through the northern steppe in autumn. The national park is one of the last places in the world where you can experience true untamed wilderness without crowds, permanent infrastructure, or a mobile signal.

The lake''s western shores are home to the Tsaatan — the reindeer people — a small community of perhaps 400 individuals who are among the last nomadic reindeer herders on Earth. Living in tepees (urts) in the high taiga forests, they migrate seasonally with their herds, practicing a way of life that has survived from the deep prehistory of Central Asia. Visiting a Tsaatan camp, riding their reindeer, and sitting with a family around their fire is a travel experience of extraordinary rarity and profound human connection.', 
  100.4, 51.1, 'Sports', 'bg-orange-500', 
  'Mongolia''s ''Blue Pearl'' — horseback riding, kayaking, and reindeer herder encounters.', '/images/dest-11.jpg', 
  'published', '', '5 Days', 
  'Mörön (Khövsgöl Province capital, 100 km south of the lake)', 'Mongolian Tögrög (₮ / MNT)', 'Subarctic — very cold winters (–30 °C), cool green summers (15–25 °C); snow possible any month', 'June–August (warm, wildflowers, accessible trails) & February (ice festival, reindeer herders)', 
  'Mongolian, Tsaatan (Dukha)', 'HOVT (UTC+7)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  48, 1, 'Arrival at Mörön & Lakeside Ger Camp', 'Mörön & Lake Khövsgöl Shore', 
  'Fly from Ulaanbaatar to Mörön, then drive 100 km through pine forests and river valleys to the lake''s southern shore. Arrive at Khatgal village and settle into a ger camp on the lakeside. Walk the shore at sunset, drinking in the extraordinary blue of the lake against the dark forested mountains, then dine on fresh Khövsgöl fish in the camp dining ger.', '["Fly into Mörön and drive through Mongolian pine forests to the lake","Arrive at the lakeshore as the evening light turns the water gold and indigo","Stay in a lakeside ger camp with views over the water and forested mountains","Taste fresh taimen, lenok, and Siberian grayling caught in the lake that day"]', 'https://images.pexels.com/photos/36103492/pexels-photo-36103492.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  48, 2, 'Horseback Ride Along the Western Shore', 'Western Lake Shore', 
  'Mount a Mongolian horse for a full-day ride along Khövsgöl''s western shoreline, passing through pine and larch forest, across meadow clearings, and along cliff edges above the brilliant blue water. Stop to swim — the lake is remarkably clear, though cold — and camp for lunch beside a river mouth where grayling leap in the shallows.', '["Ride a Mongolian horse along the cliff-top western shoreline above the lake","Swim in the extraordinarily clear, pure waters of the Blue Pearl","Picnic beside a river mouth watching grayling rise to insects","Gallop across open meadows filled with summer wildflowers in the afternoon"]', 'https://images.pexels.com/photos/4326848/pexels-photo-4326848.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  48, 3, 'Tsaatan Reindeer Herders Visit', 'Northern Taiga, Khövsgöl', 
  'Journey by horse or jeep deep into the taiga forest to visit a Tsaatan family in their camp. These reindeer people — fewer than 400 remain — live in tepees year-round, migrating seasonally with their herds. Feed reindeer from your hand, hear shamanic stories told around the fire, and if the shaman is present, witness a brief spirit-calling ceremony.', '["Enter a Tsaatan tepee camp hidden in the ancient taiga forest","Hand-feed reindeer and hear stories of their seasonal migrations","Sit with a Tsaatan family around their fire for tea, dried meat, and conversation","Witness a shamanic drum ceremony if a shaman is present in the camp"]', 'https://images.pexels.com/photos/3846452/pexels-photo-3846452.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  48, 4, 'Kayaking & Lake Wildlife', 'Lake Khövsgöl', 
  'Paddle a kayak across the glass-like morning surface of Khövsgöl, drifting between forested headlands and tiny uninhabited islands. Spot brown bear tracks on the muddy shore, watch Eurasian otters dive from boulders, and look up for Mongolian eagle owls and osprey over the treetops. Afternoon, hike into the national park forest above the lake.', '["Kayak across the mirror-still lake surface at dawn when it perfectly reflects the sky","Look for brown bear tracks, Eurasian otters, and osprey along the shoreline","Hike into the Siberian taiga forest above the lake for panoramic views","Photograph the lake''s extraordinary blue from a hilltop at sunset"]', 'https://images.pexels.com/photos/36236713/pexels-photo-36236713.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  48, 5, 'Winter Ice Festival (February) or Forest Trek & Departure', 'Lake Khövsgöl', 
  'In February, experience the Khövsgöl Ice Festival — reindeer racing on the frozen lake, ice sculptures, shamanic ceremonies, and the wild spectacle of the Tsaatan riding their reindeer across the ice. In summer, take a final forest trek to a viewpoint above the lake before returning to Mörön for your onward flight.', '["Watch reindeer racing and ice sculpture at the Khövsgöl Ice Festival (February)","See the Tsaatan ride their reindeer across the frozen lake in traditional dress","Hike to a high viewpoint for a final panorama of the entire lake and its mountains","Collect lake water in a bottle — one of the world''s cleanest fresh water sources"]', 'https://images.pexels.com/photos/5656634/pexels-photo-5656634.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  48, 'Tsaatan Reindeer Herder Visit', 'Journey into the deep taiga to meet one of the world''s last nomadic reindeer-herding peoples — a community of fewer than 400 living as their ancestors did for millennia.', 'Heart', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  48, 'Horseback Riding', 'Ride Mongolian horses along cliff-top shoreline paths above the Blue Pearl, galloping across wildflower meadows and through ancient pine forests.', 'Mountain', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  48, 'Kayaking on Khövsgöl', 'Paddle across the glassy surface of Mongolia''s most pristine lake, exploring forested headlands, hidden bays, and wildlife-rich river mouths.', 'Waves', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  48, 'Khövsgöl Ice Festival', 'Experience reindeer racing, ice sculpture, and shamanic ceremonies on the frozen lake each February in one of Central Asia''s most atmospheric winter festivals.', 'Globe', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  48, 'Wildlife Watching', 'Spot brown bears, Eurasian otters, osprey, and elk in one of Mongolia''s last great wilderness ecosystems — the Siberian taiga of Khövsgöl National Park.', 'Camera', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  48, 'Shamanic Ceremony', 'Witness a traditional Tsaatan or Mongolian shamanic drum ceremony — an ancient spiritual practice still alive in the forests around Lake Khövsgöl.', 'Lightbulb', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  48, 'Fly Mörön–Ulaanbaatar (1 hour) rather than driving the 750 km road, which takes 12+ hours on rough terrain.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  48, 'The lake road is unpaved and sometimes impassable after rain — travel in a properly equipped 4WD with an experienced driver.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  48, 'To visit the Tsaatan, book through a registered Mongolian tour operator who works ethically with the community — independent visits can be exploitative.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  48, 'Bring all your own food and supplies — shops in Khatgal village are very basic; stock up in Mörön before heading to the lake.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  48, 'The water is clean enough to drink directly from the lake — bring a reusable bottle and fill it, an extraordinary experience.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  48, 'Pack warm clothes at all times of year — summer nights drop well below 10 °C and storms can arrive without warning from the Sayan Mountains.', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  48, 'Respect the national park rules: no campfires outside designated areas, pack out all waste, and never disturb wildlife or their habitats.', 6
);
