INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'grand-canyon', 'Grand Canyon', 'United States', 'Americas', 
  'A mile-deep cathedral carved by time and the Colorado River', '/images/dest-7.jpg', 'The Grand Canyon is not simply a geological formation — it is a 277-mile-long, mile-deep open book of Earth''s history, exposing nearly two billion years of rock layers in ribbons of crimson, ochre, and violet. Standing at the South Rim at dawn, watching the first light ignite the Vishnu Basement Rocks far below, you realize that no photograph has ever done this place justice. The scale is incomprehensible; the silence, profound.

The Colorado River, barely visible as a jade thread from the rim, is the patient sculptor that carved this masterpiece over six million years. Hikers descending the Bright Angel Trail pass through climate zones equivalent to traveling from Mexico to Canada, encountering prickly pear cactus near the top and cottonwood groves at Phantom Ranch on the canyon floor. Rafters on multi-day river trips navigate legendary rapids like Lava Falls while camping on sandy beaches beneath billion-year-old walls.

Beyond the well-trodden South Rim, the remote North Rim offers cooler temperatures and a fraction of the crowds, while the Havasupai Reservation guards the turquoise waterfalls of Havasu Creek — among the most breathtaking swimming holes on the planet. Whether you arrive by mule, helicopter, or on foot, the Grand Canyon humbles every visitor who peers over its edge.', 
  -112.11, 36.1, 'Nature', 'bg-teal-500', 
  'A geological wonder — layered red rock revealing millions of years of Earth''s history.', '/images/about-2.jpg', 
  'published', '', '5 Days', 
  NULL, 'US Dollar ($)', 'Arid; rim temperatures 30–80°F, inner canyon up to 120°F in summer', 'March–May & September–November for moderate rim temperatures', 
  'English', 'MST (UTC−7, no daylight saving)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  50, 1, 'South Rim Arrival & Sunset at Mather Point', 'Grand Canyon Village, South Rim', 
  'Arrive at Grand Canyon Village and check into the historic El Tovar Hotel, perched just twenty feet from the rim. Spend the afternoon walking the paved Rim Trail between Mather Point and Yavapai Geology Museum, where interpretive panels decode the rock layers visible across the chasm. As the sun sets, watch the canyon walls transform through every shade of red and gold.', '["First breathtaking view from Mather Point overlook","Learn billion-year geology at Yavapai Geology Museum","Walk the Rim Trail with unobstructed canyon views","Sunset color show from Hopi Point"]', '/images/dest-8.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  50, 2, 'Bright Angel Trail to Indian Garden', 'Bright Angel Trail, Grand Canyon', 
  'Lace up your boots for the iconic Bright Angel Trail, descending 3,000 feet through the Coconino Sandstone and Redwall Limestone to the shady oasis of Indian Garden. Rest beside the cottonwood trees and Garden Creek before the challenging ascent back to the rim. The trail switchbacks offer constantly shifting perspectives of the canyon''s architecture.', '["Descend through layered geological epochs on the Bright Angel Trail","Rest at the 1.5-Mile and 3-Mile Resthouses","Reach the cottonwood oasis at Indian Garden","Spot California condors soaring on thermal updrafts"]', '/images/tour-3.jpg', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  50, 3, 'Desert View Drive & Watchtower', 'Desert View, East Rim', 
  'Drive the 25-mile Desert View Drive, stopping at overlooks like Grandview Point and Lipan Point where the Colorado River reveals its serpentine path. The drive culminates at the Desert View Watchtower, Mary Colter''s 1932 masterpiece inspired by Ancestral Puebloan architecture, offering 360-degree panoramas that stretch into the Painted Desert and Navajo Nation.', '["Photograph the river from Lipan Point at sunrise","Explore Mary Colter''s Desert View Watchtower murals","Visit Tusayan Museum''s 800-year-old Puebloan ruins","Panoramic views into the Painted Desert"]', '/images/dest-9.jpg', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  50, 4, 'Havasu Falls & Havasupai Village', 'Havasupai Reservation', 
  'Embark on the unforgettable 10-mile hike into the Havasupai Reservation, descending through red-walled Hualapai Canyon to the village of Supai, then continuing to the otherworldly turquoise cascade of Havasu Falls. The calcium-carbonate-rich water creates vivid blue-green pools against rust-colored travertine, a scene that seems plucked from a tropical fantasy.', '["Hike through Hualapai Canyon''s towering red walls","Swim beneath the 100-foot Havasu Falls","Explore the cascading terraces of Mooney Falls","Camp beside the turquoise waters of Havasu Creek"]', '/images/explor-1.jpg', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  50, 5, 'Colorado River Rafting', 'Colorado River, Inner Gorge', 
  'Experience the canyon from its deepest point on a guided raft trip through the Inner Gorge. Navigate exhilarating rapids while floating past polished Vishnu Schist walls that are 1.7 billion years old. Stop at hidden side canyons with crystal-clear streams and ancient granaries left by the Ancestral Puebloans.', '["Raft through Granite Rapids in the Inner Gorge","Touch 1.7-billion-year-old Vishnu Schist walls","Discover hidden side canyons and springs","Beach lunch beneath towering canyon walls"]', '/images/tour-4.jpg', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  50, 'Rim-to-Rim Hiking', 'Tackle the legendary 21-mile rim-to-rim traverse from South Kaibab Trail to North Rim, descending through two billion years of geological history.', 'Mountain', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  50, 'Stargazing at the Dark Sky Park', 'The Grand Canyon''s International Dark Sky Park designation means the Milky Way blazes overhead with zero light pollution on clear nights.', 'Globe', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  50, 'Mule Rides to Phantom Ranch', 'Follow the tradition of early canyon explorers aboard sure-footed mules descending to Phantom Ranch, the only lodge below the rim.', 'MapPin', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  50, 'Helicopter Tours', 'Soar over the Dragon Corridor, the canyon''s widest and deepest section, for an aerial perspective that reveals the full enormity of the gorge.', 'Camera', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  50, 'Native American Heritage', 'Visit the Hopi House and attend ranger-led talks about the eleven tribes who have called the canyon home for millennia.', 'BookOpen', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  50, 'Skywalk at Grand Canyon West', 'Step onto the glass-bottomed horseshoe bridge extending 70 feet over the canyon''s edge on Hualapai tribal land for vertigo-inducing views.', 'Landmark', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  50, 'Book Havasupai permits months in advance — they sell out within minutes of release each February.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  50, 'Carry at least one gallon of water per person per day when hiking below the rim; heat exhaustion is the leading cause of rescue calls.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  50, 'The North Rim is closed from mid-October to mid-May due to snow; plan South Rim visits year-round.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  50, 'Wear layered clothing — temperatures can differ by 25°F between the rim and the canyon floor.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  50, 'Free shuttle buses run along the South Rim; private vehicles are restricted on Hermit Road March through November.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  50, 'Thunderstorms are common July through September; avoid exposed overlooks during lightning.', 5
);
