INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'hawaii', 'Hawaii', 'United States', 'Americas', 
  'Where molten earth meets turquoise sea under the spirit of aloha', '/images/dest-10.jpg', 'Hawaii is the most isolated archipelago on Earth, a chain of volcanic islands rising from the mid-Pacific where molten lava still pours into the ocean, creating new land in real time. From the snow-capped summit of Mauna Kea to the bioluminescent bays of the Big Island, from Maui''s winding Road to Hana to Kauai''s impossibly green Nā Pali Coast, each island offers a radically different landscape united by the warmth of aloha.

Beneath the surface, Hawaii''s coral reefs teem with spinner dolphins, green sea turtles, and humpback whales that migrate from Alaska each winter to calve in the warm Maui Channel. Snorkelers at Molokini Crater peer into 150-foot visibility while surfers at Pipeline on Oahu''s North Shore ride some of the most powerful waves on the planet. The cultural heartbeat is equally vibrant — traditional hula isn''t mere entertainment but a sacred storytelling art, and a plate of laulau pork steamed in taro leaves connects you to centuries of Polynesian culinary tradition.

Whether you''re watching sunrise above the clouds at Haleakalā, hiking to the hidden Hanakāpīʻai Falls on the Kalalau Trail, or simply swaying in a hammock as trade winds rustle through coconut palms, Hawaii offers a rare combination of raw natural power and profound tranquility.', 
  -155.5, 19.9, 'Beach', 'bg-blue-500', 
  'Volcanic islands, pristine reefs, and the spirit of aloha.', '/images/about-3.jpg', 
  'published', '', '5 Days', 
  NULL, 'US Dollar ($)', 'Tropical, with dry and wet seasons; trade winds keep temperatures pleasant year-round', 'April–June & September–November for fewer crowds and ideal weather', 
  'English, Hawaiian', 'HST (UTC−10)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  51, 1, 'Waikiki Beach & Diamond Head', 'Honolulu, Oahu', 
  'Begin on Oahu with a dawn hike up Diamond Head crater, where the 360-degree summit panorama sweeps from downtown Honolulu to the sapphire open Pacific. Descend to Waikiki Beach for an outrigger canoe surf lesson, then explore the moving exhibits at the Pearl Harbor National Memorial and the USS Arizona.', '["Summit Diamond Head for panoramic Honolulu views","Take an outrigger canoe surfing lesson at Waikiki","Pay respects at the USS Arizona Memorial","Feast on garlic shrimp at a North Shore food truck"]', '/images/dest-11.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  51, 2, 'North Shore Surf Culture', 'North Shore, Oahu', 
  'Drive to the legendary North Shore where winter swells produce 30-foot waves at Pipeline and Sunset Beach. Visit the Polynesian Cultural Center to experience authentic village demonstrations from across the Pacific Islands. End the day with shave ice at Matsumoto''s in Haleiwa, a colorful surf town with galleries and boutiques.', '["Watch pro surfers at Banzai Pipeline","Explore Polynesian Cultural Center''s living villages","Snorkel with sea turtles at Laniakea Beach","Try rainbow shave ice at Matsumoto''s in Haleiwa"]', '/images/tour-5.jpg', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  51, 3, 'Haleakalā Sunrise & Road to Hana', 'Maui', 
  'Rise at 3 AM and drive to the 10,023-foot summit of Haleakalā to witness a sunrise that Mark Twain called ''the sublimest spectacle I ever witnessed.'' After descending through the otherworldly crater landscape, begin the legendary Road to Hana with its 620 curves, 59 bridges, and countless waterfall stops including the twin cascades at Upper Waikani Falls.', '["Watch sunrise above the clouds at Haleakalā summit","Drive the 620 curves of the Road to Hana","Swim beneath Upper Waikani Falls","Sample fresh banana bread at the Halfway to Hana stand"]', '/images/dest-12.jpg', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  51, 4, 'Volcanoes National Park', 'Big Island, Hawaii', 
  'Fly to the Big Island and enter Hawaiʻi Volcanoes National Park, where Kīlauea — one of the world''s most active volcanoes — continues to reshape the island. Walk through the Thurston Lava Tube, peer into the steaming Halemaʻumaʻu Crater at sunset when the glow of molten lava illuminates the sulfurous plume, and hike across the surreal Devastation Trail.', '["Peer into the glowing Halemaʻumaʻu Crater at dusk","Walk through the ancient Thurston Lava Tube","Hike the Devastation Trail across volcanic cinder fields","Attend a ranger talk on Pele and Hawaiian volcanic mythology"]', '/images/explor-2.jpg', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  51, 5, 'Nā Pali Coast by Catamaran', 'Kauai', 
  'Reach the Garden Isle of Kauai for a catamaran cruise along the Nā Pali Coast, where emerald cathedral cliffs plunge 4,000 feet into the cobalt Pacific. Dolphins bow-ride alongside the boat, spinner dolphins leap in synchronized arcs, and sea caves punctuate the fluted pali walls. Snorkel a pristine reef before returning to Hanalei Bay.', '["Cruise beneath the 4,000-foot Nā Pali sea cliffs","Snorkel pristine reefs teeming with tropical fish","Spot spinner dolphins and humpback whales (seasonal)","Sunset on the golden crescent of Hanalei Bay"]', '/images/dest-13.jpg', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  51, 'Snorkeling at Molokini Crater', 'Float above vibrant coral gardens inside a half-submerged volcanic crater with visibility exceeding 150 feet.', 'Waves', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  51, 'Traditional Luau', 'Experience an authentic Hawaiian feast with kālua pig unearthed from an underground imu oven, poi, and sacred hula performances.', 'Utensils', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  51, 'Kalalau Trail Hiking', 'Trek the 11-mile cliffside trail along Kauai''s Nā Pali Coast to the remote Kalalau Beach, accessible only by foot or boat.', 'Mountain', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  51, 'Stargazing on Mauna Kea', 'Ascend to the 13,796-foot summit of Mauna Kea, home to the world''s premier astronomical observatories, for unmatched stargazing.', 'Globe', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  51, 'Whale Watching', 'From December to April, the Maui Channel fills with 10,000 humpback whales breaching, tail-slapping, and nursing calves.', 'Camera', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  51, 'Learn to Surf', 'Catch your first wave at Waikiki, the birthplace of modern surfing where Duke Kahanamoku introduced the sport to the world.', 'Dumbbell', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  51, 'Haleakalā sunrise reservations sell out 60 days in advance — book through recreation.gov immediately.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  51, 'Reef-safe sunscreen is required by law in Hawaii; products containing oxybenzone and octinoxate are banned.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  51, 'Respect kapu (forbidden) signs at sacred sites and heiau (temples); some areas are still used for ceremony.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  51, 'Rental cars on Maui and Kauai book out months ahead during peak season; reserve early.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  51, 'The Road to Hana is best driven starting before 7 AM to avoid congestion on the single-lane bridges.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  51, 'Altitude sickness can strike at Mauna Kea and Haleakalā; acclimatize and avoid if you have respiratory conditions.', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  51, 'Jellyfish arrive on south-facing beaches 8–10 days after each full moon; check local advisories.', 6
);
