INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'yellowstone', 'Yellowstone', 'United States', 'Americas', 
  'America''s first national park — where the earth still breathes fire', '/images/dest-14.jpg', 'Yellowstone is a land of primordial forces, a place where the thin crust of the Earth buckles and hisses over one of the planet''s largest volcanic hotspots. The park contains more than half the world''s active geysers — from the clockwork eruptions of Old Faithful to the rainbow-ringed Grand Prismatic Spring, whose thermophilic bacteria paint concentric bands of orange, yellow, and green around a scalding azure center. It is a landscape that feels less like a national park and more like another planet.

Beyond the geothermal spectacle, Yellowstone shelters the greatest concentration of large mammals in the lower 48 states. Herds of bison lumber across the Lamar Valley at dawn, grizzly bears forage on cutthroat trout at LeHardy Rapids, and the reintroduced wolf packs of the Druid Peak area have become one of wildlife biology''s greatest success stories. Elk bugle through misty September mornings, and bald eagles circle above the Yellowstone River''s Grand Canyon.

The park''s 2.2 million acres offer over 900 miles of hiking trails — from the boardwalks of Norris Geyser Basin to the backcountry solitude of the Thorofare region, the most remote spot in the contiguous United States, 30 miles from the nearest road. Whether you camp under the stars at Slough Creek or watch Old Faithful erupt against a sky full of stars, Yellowstone reminds you that wild America still exists.', 
  -110.59, 44.43, 'Sports', 'bg-orange-500', 
  'Geysers, bison herds, backcountry hiking, and America''s first national park.', '/images/about-4.jpg', 
  'published', '', '5 Days', 
  NULL, 'US Dollar ($)', 'Continental with harsh winters; summer highs 70–80°F, winter lows well below 0°F', 'June–September for road access; January–March for snowcoach and wolf-watching', 
  'English', 'MST (UTC−7)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  52, 1, 'Old Faithful & Upper Geyser Basin', 'Upper Geyser Basin, Yellowstone', 
  'Arrive at the world''s most famous geyser and time your visit for an eruption — Old Faithful shoots 3,700 to 8,400 gallons of boiling water up to 185 feet every 44 to 125 minutes. Walk the boardwalk loop past Morning Glory Pool, Doublet Pool, and the explosive Grand Geyser. The historic Old Faithful Inn, a log-and-stone masterpiece, is worth exploring even if you don''t stay the night.', '["Watch Old Faithful erupt from the observation deck","Peer into the deep blue Morning Glory Pool","Explore the 1904 Old Faithful Inn lobby and fireplace","Hike the Observation Point Trail for aerial geyser views"]', '/images/dest-14.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  52, 2, 'Grand Prismatic Spring & Midway Geyser Basin', 'Midway Geyser Basin, Yellowstone', 
  'Hike the Fairy Falls Trail to the Grand Prismatic Overlook for a bird''s-eye view of the park''s largest hot spring — 370 feet across and ringed with psychedelic bands of thermophilic color. Descend to the boardwalk where steam billows off Excelsior Geyser Crater and the turquoise Turquoise Pool shimmers in the midday sun.', '["Overlook the Grand Prismatic Spring from the Fairy Falls Trail","Walk the steaming Midway Geyser Basin boardwalk","Photograph the vivid bacterial mats at close range","Visit Firehole River swimming area for a warm-water dip"]', '/images/explor-3.jpg', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  52, 3, 'Lamar Valley Wildlife Safari', 'Lamar Valley, Yellowstone', 
  'Rise before dawn and drive into the Lamar Valley, known as America''s Serengeti. Set up spotting scopes alongside veteran wolf-watchers to observe the Junction Butte pack hunting elk across the frosted sagebrush. Bison herds stretch to the horizon, pronghorn sprint across the flats, and grizzly bears occasionally appear on distant hillsides.', '["Spot wolf packs through spotting scopes at dawn","Watch bison herds cross the Lamar River","Photograph pronghorn on the open sagebrush flats","Visit the Lamar Buffalo Ranch for naturalist programs"]', '/images/tour-6.jpg', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  52, 4, 'Grand Canyon of the Yellowstone', 'Canyon Village, Yellowstone', 
  'Stand at the brink of the Lower Falls as 63,500 gallons of water plunge 308 feet into the gold-and-rust-colored Grand Canyon of the Yellowstone. Hike Uncle Tom''s Trail — 328 steel steps bolted into the canyon wall — for a spray-soaked vantage point. The canyon''s yellow rhyolite walls inspired the park''s name and glow like burnished copper at sunset.', '["View the 308-foot Lower Falls from Artist Point","Descend Uncle Tom''s Trail for a spray-level perspective","Spot osprey nesting on canyon pinnacles","Drive both North and South Rim roads for varied viewpoints"]', '/images/dest-15.jpg', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  52, 5, 'Mammoth Hot Springs & Norris Geyser Basin', 'Mammoth & Norris, Yellowstone', 
  'Explore the surreal travertine terraces of Mammoth Hot Springs, where mineral-laden water sculpts white limestone formations that change shape daily. Continue south to Norris Geyser Basin, the hottest and most dynamic thermal area in the park, where Steamboat Geyser — the world''s tallest active geyser — occasionally erupts over 300 feet.', '["Walk the boardwalk through Mammoth''s travertine terraces","Watch elk graze on the Mammoth parade ground","Visit Norris Geyser Basin''s Porcelain and Back Basins","Hope for a rare Steamboat Geyser eruption"]', '/images/tour-7.jpg', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  52, 'Wolf Watching', 'Join rangers and biologists in the Lamar Valley for dawn wolf-watching sessions with professional-grade spotting scopes.', 'Camera', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  52, 'Fly Fishing', 'Cast a line into the legendary Madison, Firehole, or Yellowstone rivers for native cutthroat trout amid steaming thermal features.', 'Waves', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  52, 'Backcountry Camping', 'Secure a permit and hike into the Thorofare or Bechler regions for total solitude among hot springs and alpine meadows.', 'Mountain', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  52, 'Snowcoach Tours', 'In winter, ride heated snowcoaches through a frost-encrusted wonderland where bison are frosted with rime ice and geysers steam dramatically.', 'Car', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  52, 'Ranger-Led Programs', 'Attend free evening campfire talks and guided walks with Yellowstone''s knowledgeable rangers on geology, ecology, and history.', 'GraduationCap', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  52, 'Photography Workshops', 'Join Yellowstone Forever''s multi-day photography courses to capture geysers, wildlife, and night skies with expert guidance.', 'Lightbulb', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  52, 'Most park roads close from early November to mid-April; only the North Entrance via Gardiner, Montana stays open year-round.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  52, 'Always stay 100 yards from bears and wolves and 25 yards from bison and elk — more people are injured by bison than any other animal.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  52, 'Carry bear spray and know how to use it; grizzly encounters are a real possibility on backcountry trails.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  52, 'Book lodging inside the park 12–13 months in advance through Yellowstone National Park Lodges.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  52, 'Boardwalks near thermal features exist for your safety — the ground can be thin crust over boiling water.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  52, 'Gas stations inside the park are limited and expensive; fill up in gateway towns like West Yellowstone or Gardiner.', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  52, 'Cell service is extremely limited; download offline maps and let someone know your itinerary.', 6
);
