INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'sedona', 'Sedona', 'United States', 'Americas', 
  'Red rock cathedrals where desert silence meets spiritual renewal', '/images/dest-16.jpg', 'Sedona rises from the high desert of central Arizona like a gallery of monumental sandstone sculpture — Cathedral Rock, Bell Rock, and the towering spires of Courthouse Butte glow in shades of vermillion that intensify at sunset until the entire landscape seems to pulse with inner fire. The Yavapai-Apache and Sinagua people have revered these formations for centuries, and today seekers from around the world come to experience the four famous energy vortexes said to radiate from the red earth.

Beyond the mystique, Sedona is a genuine outdoor paradise. Over 200 miles of trails wind through red rock canyons, juniper forests, and creek-carved swimming holes. The West Fork of Oak Creek Trail leads hikers through a narrow canyon where autumn maples blaze against crimson cliffs, while the challenging Cathedral Rock scramble rewards with one of the most photographed vistas in the American Southwest. Mountain bikers find world-class singletrack, and Slide Rock State Park offers natural sandstone water slides.

The town itself blends luxury resorts, artist studios, and independent restaurants serving Southwestern fusion cuisine with the region''s famed prickly pear and mesquite flavors. Stargazing here is spectacular — Sedona is an International Dark Sky Community — and the combination of natural beauty, spiritual tradition, and creative energy makes it unlike any other destination in the Americas.', 
  -111.76, 34.87, 'Spiritual', 'bg-violet-500', 
  'Red rock vortexes, healing energy centers, and desert meditation retreats.', '/images/about-5.jpg', 
  'published', '', '4 Days', 
  NULL, 'US Dollar ($)', 'Semi-arid with mild winters and warm summers; 300+ days of sunshine', 'March–May & September–November for ideal hiking temperatures', 
  'English', 'MST (UTC−7, no daylight saving)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  53, 1, 'Cathedral Rock & Red Rock Crossing', 'Cathedral Rock, Sedona', 
  'Begin with the iconic Cathedral Rock Trail, a hands-and-feet scramble up smooth sandstone to a saddle between twin spires offering 360-degree red rock panoramas. Descend and wade across Oak Creek to Red Rock Crossing for the classic reflection photograph of Cathedral Rock mirrored in still water at golden hour.', '["Scramble to the saddle of Cathedral Rock","Photograph Cathedral Rock reflected in Oak Creek","Explore the creek-side picnic area at Red Rock Crossing","Watch sunset paint the buttes in deepening reds"]', '/images/dest-16.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  53, 2, 'Vortex Tour & Spiritual Exploration', 'Bell Rock & Airport Mesa, Sedona', 
  'Join a guided vortex tour visiting the four primary energy sites: Airport Mesa, Bell Rock, Cathedral Rock, and Boynton Canyon. Feel the subtle electromagnetic shifts that practitioners describe as spiraling energy. Many visitors meditate, practice yoga, or simply sit in silence. The afternoon is free for a crystal shop visit and an aura photography session in the Tlaquepaque Arts Village.', '["Meditate at the Airport Mesa vortex at sunrise","Hike the Bell Rock Pathway feeling the upflow vortex energy","Browse Tlaquepaque Arts & Shopping Village''s galleries","Experience an aura photography or sound healing session"]', '/images/about-5.jpg', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  53, 3, 'West Fork Trail & Slide Rock', 'Oak Creek Canyon, Sedona', 
  'Drive the scenic Oak Creek Canyon highway to the West Fork Trail, a gentle 6.9-mile round-trip through a narrow slot canyon where the creek meanders between 200-foot sandstone walls draped in ferns and wild columbine. Afterward, cool off at Slide Rock State Park, where natural algae-slicked sandstone chutes create a wild waterslide into emerald pools.', '["Hike the serene West Fork of Oak Creek Trail","Cross the creek 13 times through the narrows","Slide down natural sandstone chutes at Slide Rock","Picnic beneath towering red canyon walls"]', '/images/explor-4.jpg', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  53, 4, 'Jeep Tour & Stargazing', 'Broken Arrow Trail & Sedona', 
  'Buckle in for a Pink Jeep Tour along the Broken Arrow Trail, bouncing over slickrock ledges and through washes as your guide explains the geology of the Schnebly Hill Formation. In the evening, join a professional astronomer for a stargazing session with high-powered telescopes — Sedona''s dark skies reveal the Milky Way, planets, and distant galaxies with crystalline clarity.', '["Ride the iconic Pink Jeep over Broken Arrow slickrock","See the Submarine Rock and Chicken Point formations","Stargaze with telescopes under certified dark skies","Spot the Milky Way and Andromeda Galaxy"]', '/images/about-6.jpg', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  53, 'Vortex Meditation', 'Sit in contemplation at one of Sedona''s four famous energy vortexes, where many visitors report heightened awareness and emotional release.', 'Heart', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  53, 'Mountain Biking', 'Ride world-class singletrack through red rock terrain on trails like Hiline, Hangover, and the flowy Slim Shady.', 'Dumbbell', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  53, 'Southwestern Cuisine', 'Savor prickly pear margaritas, mesquite-grilled elk, and Navajo tacos at Sedona''s acclaimed Southwestern fusion restaurants.', 'Utensils', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  53, 'Art Gallery Hopping', 'Browse over 80 galleries in the Tlaquepaque and Gallery Row districts showcasing Southwestern painting, sculpture, and Native American jewelry.', 'Camera', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  53, 'Hot Air Balloon Rides', 'Float silently above the red rock formations at sunrise with champagne toast upon landing in the desert.', 'Globe', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  53, 'Native Ruins at Palatki', 'Visit the 800-year-old Sinagua cliff dwellings and rock art at Palatki Heritage Site hidden among red rock alcoves.', 'Landmark', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  53, 'A Red Rock Pass ($5/day or $15/week) is required for parking at most trailheads; purchase at visitor centers or self-service kiosks.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  53, 'Summer temperatures regularly exceed 100°F — start hikes before 7 AM and carry extra water.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  53, 'The Cathedral Rock Trail involves steep scrambling on slickrock; wear grippy-soled shoes and avoid when wet.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  53, 'Book Pink Jeep Tours and helicopter rides at least two weeks in advance during peak season.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  53, 'Sedona''s altitude (4,350 ft) can cause mild shortness of breath for visitors from sea level; hydrate well.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  53, 'Visit during the Sedona International Film Festival (February) or the Red Rocks Music Festival for bonus cultural experiences.', 5
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  53, '/images/dest-16.jpg', 0
);
