INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'chichen-itza', 'Chichén Itzá', 'Mexico', 'Americas', 
  'Where the feathered serpent descends at equinox — a New Wonder of the World', '/images/dest-17.jpg', 'Chichén Itzá is the crown jewel of the ancient Maya world, a vast ceremonial city that flourished from the 7th to the 13th century in the limestone lowlands of Mexico''s Yucatán Peninsula. At its center, El Castillo — the Pyramid of Kukulkán — rises 79 feet in nine terraced platforms, its 365 steps a stone calendar of breathtaking precision. Twice a year, at the spring and autumn equinoxes, the late afternoon sun casts a serpentine shadow down the northern staircase that appears to slither toward the carved stone serpent head at the base — a feat of astronomical architecture that still draws tens of thousands of awestruck visitors.

Beyond El Castillo, the site unfolds across nearly five square miles of restored and unrestored structures. The Great Ball Court — the largest in Mesoamerica at 545 feet long — features acoustic properties so precise that a whisper at one end can be heard clearly at the other. The Sacred Cenote, a 200-foot-wide natural sinkhole, served as a place of offering where jade, gold, and ceramics were deposited to appease the rain god Chaak. The Observatory, known as El Caracol, contains window alignments that track Venus with extraordinary accuracy.

A visit here is best paired with the nearby colonial city of Valladolid, the crystalline waters of Cenote Ik Kil, and the lesser-visited ruins of Ek'' Balam, where you can still climb the Acropolis pyramid for sweeping jungle views.', 
  -88.57, 20.68, 'Historical', 'bg-amber-600', 
  'Iconic Mayan pyramid, equinox light phenomena, and one of the New Seven Wonders.', '/images/about-6.jpg', 
  'published', '', '4 Days', 
  'Mérida (Yucatán state capital)', 'Mexican Peso (MXN)', 'Hot and humid tropical; rainy season June–October', 'November–March for cooler, drier weather; equinoxes (March 20 & September 22) for the serpent shadow', 
  'Spanish, Yucatec Maya', 'CST (UTC−6)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  54, 1, 'Chichén Itzá at Dawn', 'Chichén Itzá Archaeological Zone', 
  'Arrive at the gates before the 8 AM opening to experience the ruins in morning solitude before tour buses arrive from Cancún. Stand before El Castillo as the rising sun gilds its limestone surfaces, then explore the Platform of the Eagles, the Temple of the Warriors with its thousand columns, and the hypnotic acoustics of the Great Ball Court where hand-claps produce seven echoes.', '["Photograph El Castillo in golden morning light","Test the seven-echo acoustics of the Great Ball Court","Study the carved warrior columns at the Temple of Warriors","Learn about the Sacred Cenote''s ritual offerings"]', '/images/dest-17.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  54, 2, 'Cenote Ik Kil & Valladolid', 'Cenote Ik Kil & Valladolid, Yucatán', 
  'Descend a carved staircase into Cenote Ik Kil, a stunning open-air cenote where vines cascade 85 feet from the jungle rim to jade-green waters. Swim in the sacred sinkhole once used by the Maya. Then continue to the pastel-colored colonial town of Valladolid to stroll the zócalo, visit the Convent of San Bernardino, and taste papadzules — egg-stuffed tortillas in pumpkin-seed sauce.', '["Swim in the vine-draped Cenote Ik Kil","Stroll Valladolid''s pastel colonial streets","Visit the 16th-century Convent of San Bernardino","Taste authentic papadzules and salbutes at the market"]', '/images/tour-8.jpg', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  54, 3, 'Ek'' Balam & Underground Cenotes', 'Ek'' Balam, Yucatán', 
  'Drive to the lesser-known ruins of Ek'' Balam, where the 100-foot Acropolis pyramid is still open for climbing. From the summit, the jungle canopy extends unbroken to the horizon. The site''s elaborate stucco frieze of a monster mouth doorway is one of the finest surviving examples of Maya architectural sculpture. Cool off in the nearby Cenote X''canché, accessed by a forest path or bicycle.', '["Climb the Acropolis for panoramic jungle views","Marvel at the intricate stucco monster-mouth frieze","Swim in the secluded Cenote X''canché","Cycle through the forest to reach hidden cenotes"]', '/images/explor-5.jpg', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  54, 4, 'Mérida''s Cultural Riches', 'Mérida, Yucatán', 
  'Explore the White City of Mérida, Yucatán''s vibrant capital. Visit the Gran Museo del Mundo Maya to contextualize everything you''ve seen, wander the bustling Mercado Lucas de Gálvez for handwoven hammocks and chili-rubbed cochinita pibil, and catch a Jarana dance performance on the Plaza Grande. The Paseo de Montejo boulevard showcases grand Porfirian-era mansions.', '["Tour the Gran Museo del Mundo Maya''s immersive exhibits","Feast on cochinita pibil at Mercado Lucas de Gálvez","Watch folk dancers perform Jarana on Plaza Grande","Stroll the grand Paseo de Montejo boulevard"]', '/images/city-2.jpg', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  54, 'Equinox Light Show', 'Witness the feathered serpent shadow descend El Castillo''s staircase during the spring or autumn equinox — an event 1,100 years in the making.', 'Landmark', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  54, 'Cenote Swimming', 'Plunge into the Yucatán''s network of thousands of cenotes — natural sinkholes filled with crystal-clear groundwater and stalactite formations.', 'Waves', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  54, 'Yucatecan Cooking Class', 'Learn to prepare cochinita pibil, papadzules, and sopa de lima with local chefs using achiote, sour orange, and habanero.', 'Utensils', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  54, 'Light & Sound Show', 'Return to Chichén Itzá after dark for the evening light and sound show that projects Maya cosmology onto El Castillo in vivid color.', 'Lightbulb', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  54, 'Birdwatching at Celestún', 'Boat through the Ría Celestún biosphere reserve to see flocks of flamingos turning the estuary pink against mangrove-lined channels.', 'Camera', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  54, 'Maya Astronomical Heritage', 'Tour El Caracol observatory with an archaeoastronomer guide to understand how the Maya tracked Venus, eclipses, and solstices.', 'GraduationCap', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  54, 'Arrive at 8 AM sharp when the gates open to beat the midday tour-bus crowds from Cancún and Riviera Maya.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  54, 'Bring a hat, sunscreen, and at least 2 liters of water — the open site has almost no shade and temperatures easily reach 95°F.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  54, 'Equinox events (March 20 & September 22) attract 30,000+ visitors; book Valladolid or Pisté hotels months ahead.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  54, 'Climbing El Castillo has been prohibited since 2006 — enjoy it from the ground and climb Ek'' Balam instead.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  54, 'Hire a local guide at the entrance for $50–80 USD; their knowledge of Maya history and astronomy transforms the visit.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  54, 'Combine with Cenote Ik Kil (5 minutes away) and Valladolid (40 minutes) for a full day.', 5
);
