INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'mexico-city', 'Mexico City', 'Mexico', 'Americas', 
  'An ancient Aztec capital reborn as a modern cultural powerhouse', '/images/city-3.jpg', 'Mexico City is a metropolis of staggering depth — literally built atop the ruins of Tenochtitlán, the Aztec island capital that Hernán Cortés described as more magnificent than anything in Europe. Today, the Templo Mayor excavation in the Zócalo reveals the foundations of the great pyramid that once anchored the Aztec universe, while the Palacio Nacional''s walls blaze with Diego Rivera''s epic murals narrating Mexico''s history from pre-Columbian creation myths to the Revolution.

The city''s culinary scene has earned global recognition, from the avant-garde tasting menus of Pujol and Quintonil — both perennial fixtures on the World''s 50 Best Restaurants list — to the street-corner taquerías where al pastor pork shaved from a vertical spit onto warm tortillas costs 15 pesos and rivals anything served on white tablecloths. Between meals, wander through the turquoise-walled Casa Azul where Frida Kahlo was born and died, float on a flower-decorated trajinera through the ancient Aztec canals of Xochimilco, or lose yourself in the Museo Nacional de Antropología, perhaps the finest archaeological museum in the Western Hemisphere.

Neighborhoods tell individual stories: Roma Norte''s tree-lined boulevards host hip cafés and bookshops; Coyoacán''s cobblestone plazas feel like a colonial village; and Condesa''s art deco architecture frames buzzing mezcalerías. Mexico City is not one city but dozens layered atop each other, each era leaving its mark on the next.', 
  -99.13, 19.43, 'Education', 'bg-indigo-500', 
  'Field trips to Aztec archaeological sites, Templo Mayor excavation, UNAM campus, and industrial brewery tours.', '/images/about-7.jpg', 
  'published', '', '5 Days', 
  'Mexico City (national capital)', 'Mexican Peso (MXN)', 'Subtropical highland; mild year-round with rainy season June–October', 'October–May for dry, clear skies and comfortable temperatures', 
  'Spanish, Nahuatl (indigenous communities)', 'CST (UTC−6)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  55, 1, 'Zócalo, Templo Mayor & Palacio Nacional', 'Centro Histórico, Mexico City', 
  'Begin at the vast Zócalo, one of the largest public squares in the world, flanked by the Metropolitan Cathedral and the Palacio Nacional. Step inside the palace to see Diego Rivera''s breathtaking mural cycle, then walk next door to the Templo Mayor Museum where Aztec artifacts — including the massive Coyolxauhqui stone — are displayed exactly where they were unearthed.', '["Stand in the Zócalo, the heart of the Aztec and modern capital","View Diego Rivera''s epic murals in the Palacio Nacional","Explore the Templo Mayor archaeological excavation","Visit the Metropolitan Cathedral''s tilting colonial grandeur"]', '/images/city-3.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  55, 2, 'Museo Nacional de Antropología & Chapultepec', 'Chapultepec, Mexico City', 
  'Spend a full morning in the Museo Nacional de Antropología, where the Sun Stone, Aztec feathered headdress replica, and Maya jade death mask of Pakal are among thousands of treasures. Afterward, stroll through the centuries-old Bosque de Chapultepec, visit the hilltop Chapultepec Castle — the only royal castle in the Americas — and rent a paddleboat on the park''s lake.', '["Marvel at the Aztec Sun Stone and Olmec colossal heads","Tour Chapultepec Castle''s imperial rooms and murals","Stroll the ancient ahuehuete trees of Chapultepec Park","Visit the Museo de Arte Moderno for Kahlo and Rivera works"]', '/images/tour-9.jpg', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  55, 3, 'Coyoacán, Frida Kahlo & Xochimilco', 'Coyoacán & Xochimilco, Mexico City', 
  'Wander the cobblestone streets of Coyoacán to the Casa Azul, Frida Kahlo''s vivid blue childhood home filled with her paintings, personal artifacts, and lush gardens. After lunch of tostadas at the Coyoacán market, head to Xochimilco to board a colorful trajinera gondola, drifting along pre-Hispanic canals while mariachi bands serenade from passing boats and vendors sell elotes and micheladas.', '["Tour the Casa Azul — Frida Kahlo''s life and art","Eat fresh tostadas at Coyoacán''s market stalls","Float the ancient canals of Xochimilco on a trajinera","Be serenaded by passing mariachi boats"]', '/images/city-4.jpg', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  55, 4, 'Roma Norte, Condesa & Mezcal Culture', 'Roma Norte & Condesa, Mexico City', 
  'Explore the hip, tree-canopied neighborhoods of Roma Norte and Condesa. Browse Roma''s independent bookshops and street art, visit the Mercado Roma food hall for gourmet tacos and artisan mezcal, then walk the circular Parque México past art deco facades. End the evening at a mezcalería like Bósforo, sampling single-village mezcals from Oaxaca alongside sal de gusano and orange slices.', '["Walk Roma Norte''s Álvaro Obregón boulevard","Taste artisan mezcals at Mercado Roma and Bósforo","Admire art deco architecture along Condesa''s avenues","Dine at one of the city''s world-ranked restaurants"]', '/images/about-7.jpg', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  55, 5, 'Teotihuacán — City of the Gods', 'Teotihuacán, State of Mexico', 
  'Drive 30 miles northeast to the awe-inspiring ruins of Teotihuacán, a city that once held 125,000 residents and rivaled Rome in size. Climb the Pyramid of the Sun — the third-largest pyramid in the world — for a commanding view down the two-mile Avenue of the Dead to the Pyramid of the Moon. Explore the Temple of the Feathered Serpent''s carved facades and the vivid murals of the Tepantitla compound.', '["Climb the Pyramid of the Sun for panoramic views","Walk the two-mile Avenue of the Dead","Study carved serpent heads at the Feathered Serpent Temple","View the Paradise of Tláloc murals at Tepantitla"]', '/images/dest-18.jpg', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  55, 'Street Taco Crawl', 'Follow the smoke to legendary taquerías — al pastor at El Huequito, suadero at Los Cocuyos, and barbacoa at the Saturday market in San Juan.', 'Utensils', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  55, 'Lucha Libre Wrestling', 'Cheer the masked luchadores at Arena México on a Friday night for a quintessential CDMX experience of theatrics, acrobatics, and rowdy crowds.', 'Dumbbell', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  55, 'Muralism & Street Art', 'Trace the legacy of Rivera, Orozco, and Siqueiros in public buildings, then explore the vibrant street art scene in Roma and Juárez neighborhoods.', 'Camera', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  55, 'Teotihuacán Hot Air Balloon', 'Float above the Pyramids of the Sun and Moon at dawn in a hot air balloon, followed by a traditional breakfast with pulque.', 'Globe', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  55, 'Mezcal Tasting', 'Attend guided mezcal tastings to learn about agave varieties, ancestral distillation, and the difference between espadín and tobalá.', 'BookOpen', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  55, 'Day of the Dead Celebrations', 'Visit during late October and early November for the spectacular Día de los Muertos parades, altar installations, and cemetery vigils.', 'Heart', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  55, 'The metro is extensive, safe during daytime, and costs 5 pesos — but avoid rush hours (7–9 AM, 6–8 PM) with luggage.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  55, 'Tap water is not potable; drink bottled or purified water, and be cautious with street-vendor ice.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  55, 'Mexico City sits at 7,350 feet — take it easy the first day to acclimate and avoid alcohol until adjusted.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  55, 'Use Uber or DiDi rather than hailing street taxis, especially at night, for safety and transparent pricing.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  55, 'Tipping 10–15% at restaurants is standard; at taquerías, a few pesos per taco is appreciated.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  55, 'Visit Teotihuacán on weekday mornings; weekends and holidays can attract 10,000+ visitors.', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  55, 'Earthquake protocols are well-practiced — note your hotel''s exit routes and the nearest assembly point.', 6
);
