INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'cancun', 'Cancún', 'Mexico', 'Americas', 
  'Caribbean turquoise meets ancient Maya along the Riviera Maya', '/images/dest-19.jpg', 'Cancún sits at the northeastern tip of the Yucatán Peninsula where the Caribbean Sea glows in impossible shades of turquoise against powder-white sand. What began as a government-planned resort development in the 1970s has become Mexico''s most-visited destination, but beneath the all-inclusive hotel strip lies a world of natural and archaeological wonders that most visitors barely scratch.

The Mesoamerican Barrier Reef — the second-largest coral reef system on Earth — begins just offshore, offering world-class diving at sites like the MUSA underwater sculpture museum, where over 500 life-sized statues rest on the seabed colonized by coral and sponges. Beyond the hotel zone, the cenote-riddled jungle conceals thousands of crystal-clear sinkholes connected by the world''s longest underground river system, perfect for snorkeling and cave diving. The ruins of Tulum perch on a cliff above the sea, and the eco-archaeological park of Xcaret combines underground rivers with a Maya village and a spectacular evening show.

The real magic lies in the contrast: you can spend the morning diving a cenote 60 feet underground, the afternoon exploring a thousand-year-old pyramid, and the evening dining on ceviche as the Caribbean sun melts into the horizon. Cancún is the gateway, but the Riviera Maya is the destination.', 
  -86.85, 21.16, 'Beach', 'bg-blue-500', 
  'Caribbean turquoise waters, cenote dives, and Mayan riviera adventures.', '/images/trand-2.jpg', 
  'published', '', '4 Days', 
  NULL, 'Mexican Peso (MXN)', 'Tropical with warm, humid weather year-round; hurricane season June–November', 'December–April for dry weather and calm seas', 
  'Spanish, English widely spoken in tourist areas', 'EST (UTC−5)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  56, 1, 'Isla Mujeres & Caribbean Snorkeling', 'Isla Mujeres, Quintana Roo', 
  'Take the 20-minute ferry to Isla Mujeres, a laid-back island where golf carts replace cars and the northern beach, Playa Norte, consistently ranks among the world''s best. Snorkel the MUSA underwater museum with its haunting submerged sculptures, then rent a golf cart to explore the island''s southern cliffs, the tiny Mayan temple to Ixchel, and a fresh ceviche lunch at a beachfront palapa.', '["Snorkel the MUSA underwater sculpture museum","Relax on the world-famous Playa Norte","Golf-cart around the island''s colorful streets","Fresh ceviche lunch at a beachfront palapa restaurant"]', '/images/dest-19.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  56, 2, 'Cenote Hopping & Underground Rivers', 'Ruta de los Cenotes, Puerto Morelos', 
  'Drive the Ruta de los Cenotes near Puerto Morelos, visiting a curated selection of the Yucatán''s 6,000+ cenotes. Swim in the open-air Cenote Verde Lucero, rappel into the cavern-style Cenote Zapote where an ancient underwater bell-shaped formation defies belief, and float through a partially enclosed cenote illuminated by shafts of sunlight piercing through jungle canopy above.', '["Swim in the crystal-clear Cenote Verde Lucero","Rappel into the cavern cenote Zapote","Float through sunlit underground rivers","Zipline over cenotes between jungle platforms"]', '/images/explor-6.jpg', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  56, 3, 'Tulum Ruins & Beach', 'Tulum, Quintana Roo', 
  'Arrive early at the clifftop ruins of Tulum, the only major Maya city built directly on the Caribbean coast. The Castillo pyramid stands on a 40-foot bluff overlooking a postcard-perfect cove of turquoise water and white sand. After touring the ruins, descend the wooden staircase to the beach below for a swim with the ancient walls looming above.', '["Tour the clifftop Maya ruins overlooking the Caribbean","Swim in the cove below the Tulum Castillo","Photograph the iconic cliffside temple framed by palms","Browse Tulum town''s bohemian shops and restaurants"]', '/images/dest-20.jpg', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  56, 4, 'Xcaret Eco-Archaeological Park', 'Xcaret, Riviera Maya', 
  'Spend a full day at Xcaret, where underground rivers flow through illuminated caverns, a coral reef aquarium teems with tropical fish, and a reconstructed Maya village brings ancient life into focus. The evening culminates in the spectacular México Espectacular show — a 300-performer production tracing the country''s history from pre-Hispanic ceremonies to modern-day fiesta.', '["Float through Xcaret''s underground rivers","Snorkel the coral reef inlet aquarium","Watch the 300-performer México Espectacular show","See butterfly pavilion and jaguar sanctuary"]', '/images/tour-10.jpg', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  56, 'Scuba Diving the Reef', 'Dive the Mesoamerican Barrier Reef at sites like Manchones Reef, encountering nurse sharks, eagle rays, and sea turtles in warm, clear water.', 'Waves', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  56, 'Cenote Cave Diving', 'Explore the world''s longest underwater cave system — Sac Actun — with certified cave-diving guides through crystal-clear freshwater passages.', 'Mountain', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  56, 'Cochinita Pibil Feast', 'Seek out traditional Yucatecan cochinita pibil — slow-roasted pork in banana leaves with pickled red onion and habanero — at Parque de las Palapas vendors.', 'Utensils', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  56, 'Whale Shark Swimming', 'From June to September, swim alongside the world''s largest fish — gentle whale sharks — that gather by the hundreds near Isla Holbox.', 'Heart', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  56, 'Nightlife at Coco Bongo', 'Experience the legendary Coco Bongo club, a Cirque du Soleil–meets–nightclub spectacle with acrobats, confetti cannons, and non-stop energy.', 'Landmark', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  56, 'Hurricane season runs June–November with peak risk in September and October; purchase travel insurance for these months.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  56, 'Avoid timeshare presentations aggressively pitched at the airport and hotel zone — they consume half your vacation day.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  56, 'Take ADO buses from the Cancún bus station for cheap, comfortable rides to Tulum ($8), Playa del Carmen ($4), and Chichén Itzá ($20).', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  56, 'Negotiate taxi prices before entering the cab; alternatively use Uber, which operates in Cancún despite some taxi-union friction.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  56, 'Apply reef-safe sunscreen before cenote swims — chemical sunscreens are prohibited at most cenotes to protect the ecosystem.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  56, 'Visit Tulum ruins at 8 AM opening to avoid the midday heat and cruise-ship crowds.', 5
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  56, '/images/dest-19.jpg', 0
);
