INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'tulum', 'Tulum', 'Mexico', 'Americas', 
  'Cliffside Maya ruins and jungle ceremonies where the ancient world breathes', '/images/dest-20.jpg', 'Tulum exists at a rare intersection of ancient history, natural beauty, and modern wellness culture. The clifftop Maya ruins — the only major pre-Columbian city built overlooking the sea — gaze eternally across the Caribbean from their limestone perch, while below, turquoise waves break against a crescent of white sand framed by coconut palms. It is one of the most photographed archaeological sites in the Americas, and despite its fame, the sight of El Castillo against that impossible blue still takes your breath away.

Beyond the ruins, Tulum''s jungle interior hides a labyrinth of cenotes — sacred sinkholes that the Maya considered portals to the underworld. Gran Cenote''s crystalline waters reveal stalactites and freshwater turtles, while Cenote Calavera''s three skull-like openings invite cliff jumps into emerald depths. The Sian Ka''an Biosphere Reserve, a UNESCO World Heritage Site stretching south of Tulum, protects 1.3 million acres of mangroves, marshes, and reef that harbor jaguars, manatees, and over 300 bird species.

Tulum has also become a center for wellness and ancestral healing practices. Temazcal sweat lodge ceremonies led by Maya shamans, cacao ceremonies connecting participants to the heart through sacred drink, and sound healing sessions in jungle palapas draw travelers seeking transformation. Whether you come for the archaeology, the ecology, or the inner journey, Tulum delivers an experience that lingers long after you leave.', 
  -87.46, 20.21, 'Spiritual', 'bg-violet-500', 
  'Cliffside Mayan ruins, cacao ceremonies, and temazcal sweat lodge rituals.', '/images/trand-3.jpg', 
  'published', '', '4 Days', 
  NULL, 'Mexican Peso (MXN)', 'Tropical; warm and humid year-round with a rainy season from June to October', 'November–April for dry weather and comfortable temperatures', 
  'Spanish, English, Yucatec Maya', 'EST (UTC−5)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  57, 1, 'Tulum Ruins & Beach Cove', 'Tulum Archaeological Zone', 
  'Enter the walled city at opening time and explore the Temple of the Frescoes with its surviving Maya murals, the Temple of the Descending God with its upside-down carved figure, and El Castillo commanding its cliff. Then descend the wooden staircase to the idyllic beach cove for a swim beneath the ancient watchtower, feeling the salt breeze that Maya traders once navigated by.', '["Study surviving Maya murals at the Temple of the Frescoes","Photograph El Castillo from the beach cove below","Learn about Tulum''s role as a Maya trading port","Swim in the turquoise cove beneath the ruins"]', '/images/dest-20.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  57, 2, 'Cenote Circuit — Gran Cenote, Calavera & Caracol', 'Tulum Cenote Zone', 
  'Spend the day hopping between Tulum''s best cenotes. Begin at Gran Cenote, snorkeling among stalactites and freshwater turtles in crystalline water. Continue to Cenote Calavera for adrenaline cliff jumps through three skull-shaped openings, then end at Cenote Caracol, a quieter spiral-shaped pool hidden in the jungle where you''ll likely have the water to yourself.', '["Snorkel among stalactites at Gran Cenote","Cliff jump through Cenote Calavera''s skull openings","Discover the hidden spiral pool of Cenote Caracol","Photograph jungle light filtering into cenote chambers"]', '/images/banner-1.jpg', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  57, 3, 'Sian Ka''an Biosphere Reserve', 'Sian Ka''an, Quintana Roo', 
  'Enter the UNESCO-listed Sian Ka''an Biosphere on a guided boat tour through mangrove channels teeming with frigatebirds, crocodiles, and dolphins. Float the ancient Maya canal — hand-dug centuries ago — down a lazy river of crystal-clear water. The reserve protects one of the most biodiverse coastal ecosystems in the Caribbean, with pristine reef, seagrass beds, and nesting sea turtles.', '["Float the ancient Maya canal through the biosphere","Spot crocodiles and dolphins in mangrove channels","Snorkel pristine reef inside the protected reserve","Birdwatch for roseate spoonbills and jabiru storks"]', '/images/banner-2.jpg', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  57, 4, 'Temazcal Ceremony & Cacao Ritual', 'Tulum Jungle Zone', 
  'Participate in a traditional temazcal ceremony — a Maya sweat lodge guided by a shaman using copal incense, medicinal herbs, and chanting to purify body and spirit in volcanic-heated steam. Follow it with a cacao ceremony where ceremonial-grade cacao is prepared with intention and consumed in a circle of meditation, connecting you to the Maya''s sacred relationship with the cacao plant.', '["Experience a traditional Maya temazcal sweat lodge","Drink ceremonial cacao in a guided heart-opening ritual","Learn about copal incense and medicinal herbs","Journal and reflect in a jungle palapa setting"]', '/images/about-8.jpg', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  57, 'Cenote Diving', 'Dive the Dos Ojos or Sac Actun cave systems — the world''s longest underwater caves — through crystal passages lit by haloclines and light shafts.', 'Waves', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  57, 'Temazcal Ceremony', 'Enter the womb-like temazcal sweat lodge for a traditional Maya purification ritual with volcanic stones, herbs, and chanting.', 'Heart', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  57, 'Jungle Cycling', 'Rent a bicycle and pedal the jungle road from Tulum town to the beach zone, stopping at cenotes, art installations, and smoothie bars.', 'Car', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  57, 'Farm-to-Table Dining', 'Dine at jungle restaurants like Arca and Hartwood, where wood-fired cooking and local ingredients create unforgettable open-air meals.', 'Utensils', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  57, 'Cobá Pyramid Climb', 'Cycle or walk to the Nohoch Mul pyramid at Cobá — at 138 feet, the tallest climbable pyramid in the Yucatán — for panoramic jungle views.', 'Landmark', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  57, 'Rent a bicycle — it''s the best way to move between the beach zone, town, and cenotes without traffic headaches.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  57, 'Book restaurants like Hartwood and Arca well in advance; they fill up nightly even in low season.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  57, 'Apply biodegradable sunscreen and bug repellent before cenote visits; chemical products are prohibited.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  57, 'The beach road floods during heavy rains; waterproof sandals are more practical than sneakers.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  57, 'Carry cash in pesos — many beach clubs, cenotes, and small shops don''t accept cards.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  57, 'Visit the ruins at 8 AM opening; by 10 AM the heat and crowds make the experience much less pleasant.', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  57, 'Sian Ka''an tours leave early morning; book through community cooperatives for the most authentic experience.', 6
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  57, '/images/dest-20.jpg', 0
);
