INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'cusco', 'Cusco', 'Peru', 'Americas', 
  'The navel of the Inca world — living archaeology at 11,000 feet', '/images/dest-21.jpg', 'Cusco was Qosqo — the navel of the world — to the Inca Empire, a city of gold-plated temples and astronomical precision set high in the Peruvian Andes at 11,152 feet. When the Spanish arrived in 1533, they dismantled the Inca palaces and temples but could not remove the massive stone foundations, so they built their colonial churches and mansions directly on top. The result is one of the world''s most extraordinary architectural palimpsests: baroque cathedrals rising from perfectly fitted Inca walls where not a blade of grass can slip between the stones.

The Plaza de Armas, once the Inca ceremonial center of Huacaypata, is now flanked by the ornate Cathedral of Santo Domingo and the Jesuit Iglesia de la Compañía. Below the plaza, the Qorikancha — once the holiest shrine in the Inca Empire, its walls sheathed in gold — now bears the Convent of Santo Domingo on its shoulders. The famous twelve-angled stone in the wall along Hatunrumiyoc Street demonstrates the Inca''s unmatched masonry skill, while the massive fortress of Sacsayhuamán on the hillside above the city features boulders weighing up to 200 tons fitted together with laser precision.

Beyond its archaeological treasures, Cusco is a vibrant Andean city where Quechua-speaking vendors sell choclo con queso (giant-kernel corn with cheese) in the San Pedro Market, where Pisco sours flow in colonial-courtyard bars, and where the annual Inti Raymi festival in June reenacts the Inca Festival of the Sun with thousands of costumed performers filling the Sacsayhuamán esplanade.', 
  -71.97, -13.52, 'Education', 'bg-indigo-500', 
  'Field trips to Inca archaeological digs, Sacsayhuamán fortress, colonial-era churches, and textile-weaving demonstrations.', '/images/about-9.jpg', 
  'published', '', '5 Days', 
  'Cusco (former Inca capital; regional capital of Cusco Region)', 'Peruvian Sol (PEN)', 'Dry and wet seasons; cool year-round at altitude (40–65°F)', 'May–September (dry season) for clear skies and trekking', 
  'Spanish, Quechua', 'PET (UTC−5)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  58, 1, 'Acclimatize & Explore the Plaza de Armas', 'Centro Histórico, Cusco', 
  'Arrive in Cusco and spend the first day acclimatizing to the 11,152-foot altitude with gentle walking. Sip coca tea at a plaza-view café, then visit the Cathedral of Santo Domingo, whose interior glows with 400 colonial paintings including a famous Last Supper where Christ is served cuy (guinea pig). Walk Hatunrumiyoc Street to find the celebrated twelve-angled Inca stone.', '["Sip coca tea while overlooking the Plaza de Armas","See the Last Supper with cuy at the Cathedral","Find the twelve-angled stone on Hatunrumiyoc Street","Wander the cobblestone streets of the San Blas artisan quarter"]', '/images/dest-21.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  58, 2, 'Qorikancha & San Pedro Market', 'Cusco Centro', 
  'Visit the Qorikancha, the Inca Temple of the Sun, where the few remaining original walls reveal the technical mastery behind what was once a building lined with 700 sheets of solid gold. The Spanish convent above provides a fascinating study in cultural layering. Afterward, plunge into the sensory overload of San Pedro Market — juice stalls blending tropical fruits, vendors serving steaming bowls of caldo de gallina, and sacks of quinoa in every color.', '["Tour the Inca stonework beneath the Convent of Santo Domingo","Learn how the Qorikancha''s gold once reflected sunlight","Taste fresh tropical juices at San Pedro Market","Sample caldo de gallina and choclo con queso from market vendors"]', '/images/city-5.jpg', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  58, 3, 'Sacsayhuamán & Tambomachay', 'Archaeological Park above Cusco', 
  'Hike or taxi to the monumental fortress of Sacsayhuamán, where three tiers of zigzagging walls built from boulders weighing up to 200 tons stretch across the hillside. The precision of the joints — no mortar, no gaps — defies easy explanation. Continue to the nearby sites of Q''enqo (a carved limestone shrine), Puca Pucara (a red-hued military outpost), and Tambomachay (the Inca water temple with its flowing fountains).', '["Marvel at Sacsayhuamán''s 200-ton precision-cut boulders","Explore the carved ritual cave at Q''enqo","Walk the ridgeline between Puca Pucara and Tambomachay","Photograph panoramic views of Cusco from the fortress walls"]', '/images/tour-11.jpg', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  58, 4, 'Rainbow Mountain & Andean Highlands', 'Vinicunca (Rainbow Mountain), Cusco Region', 
  'Depart before dawn for the 3-hour drive to the trailhead of Vinicunca, the Rainbow Mountain. The 5-mile round-trip hike climbs to 17,100 feet, where the mountain''s mineral-rich slopes reveal striations of red, yellow, green, and lavender. The thin air makes every step an effort, but the surreal landscape — with herds of alpacas grazing in the foreground — is a reward beyond words.', '["Hike to the 17,100-foot summit of Rainbow Mountain","See the vivid mineral striations of Vinicunca","Photograph alpaca herds against the rainbow slopes","Experience the high Andean puna ecosystem"]', '/images/dest-22.jpg', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  58, 5, 'Machu Picchu — The Lost City', 'Machu Picchu, Urubamba Province', 
  'Take the early morning train through the Urubamba River gorge to Aguas Calientes, then bus up the switchbacks to the Sun Gate entrance of Machu Picchu. The first glimpse of the citadel nestled between Huayna Picchu and Machu Picchu mountain, wreathed in cloud, is one of travel''s most transcendent moments. Explore the Temple of the Sun, the Intihuatana stone, and the Room of the Three Windows with a licensed guide.', '["Witness the first reveal of Machu Picchu from the Sun Gate","Touch the Intihuatana astronomical stone","Explore the Temple of the Sun and Royal Tomb","Optional: climb Huayna Picchu for aerial citadel views"]', '/images/dest-23.jpg', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  58, 'Machu Picchu Trek', 'Hike the classic 4-day Inca Trail through cloud forest and high passes, arriving at the Sun Gate at dawn for the ultimate Machu Picchu reveal.', 'Mountain', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  58, 'Pisco Sour Tasting', 'Compare Peru''s national cocktail at Cusco''s best bars — Museo del Pisco serves over 100 varieties of pisco with expert-led tastings.', 'Utensils', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  58, 'Textile Weaving Workshop', 'Visit Chinchero''s weaving cooperatives where Quechua women demonstrate ancient techniques using natural dyes from cochineal, indigo, and local plants.', 'BookOpen', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  58, 'San Pedro Market Food Tour', 'Join a guided food walk through San Pedro Market tasting ceviche, fresh juice, empanadas, and the Andean superfood dish quinua chaufa.', 'MapPin', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  58, 'Inti Raymi Festival', 'If visiting in June, witness the Inti Raymi — the Festival of the Sun — a spectacular reenactment of Inca ceremony with thousands of performers at Sacsayhuamán.', 'Landmark', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  58, 'Planetarium & Andean Cosmology', 'Visit the Cusco Planetarium to learn how the Inca mapped dark cloud constellations in the Milky Way to guide agriculture and ceremony.', 'Globe', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  58, 'Spend at least 2 days acclimatizing in Cusco before any strenuous trekking — altitude sickness is real and potentially dangerous at 11,000+ feet.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  58, 'Drink coca tea (mate de coca) freely — it''s legal, culturally traditional, and genuinely helps with altitude adjustment.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  58, 'Book Inca Trail permits at least 6 months in advance through a licensed operator; only 500 people per day are allowed on the trail.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  58, 'Machu Picchu now requires timed entry tickets and a licensed guide; book through the official government portal.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  58, 'Carry small bills (S/1–5) for tips at restaurants and markets; street vendors rarely have change for S/100 notes.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  58, 'The Boleto Turístico (S/130) grants entry to 16 archaeological sites and museums — it''s essential for multi-day exploration.', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  58, 'Dress in layers — Cusco mornings can be near freezing, afternoons sunny and warm, and evenings cold again.', 6
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  58, '/images/dest-21.jpg', 0
);
