INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'sacred-valley', 'Sacred Valley', 'Peru', 'Americas', 
  'Andean peaks and shamanic wisdom in the heartland of the Inca', '/images/banner-3.jpg', 'The Sacred Valley of the Incas — the Urubamba Valley — stretches between Cusco and Machu Picchu in a fertile corridor carved by the Urubamba River and flanked by snow-dusted Andean peaks exceeding 18,000 feet. For the Inca, this was the empire''s breadbasket, its terraced hillsides producing the maize and potatoes that sustained millions. Today, those same terraces at Moray — concentric stone circles that functioned as an agricultural laboratory — still descend into the earth like a natural amphitheater, each tier creating a distinct microclimate.

The valley''s towns are living extensions of Inca heritage. Ollantaytambo''s cobblestone streets follow the original Inca grid plan, and water still flows through stone channels carved five centuries ago. The massive fortress above the town features six monolithic rose-colored stones transported from a quarry across the valley — a feat of engineering that remains unexplained to modern scholars. In Pisac, Sunday''s market fills the colonial plaza with textiles, pottery, and produce, while the terraced ruins above the town offer panoramic valley views in solitude.

The Sacred Valley is also the heartland of Andean spiritual tradition. Q''ero shamans — descendants of the Inca — still perform despacho offerings to Pachamama (Mother Earth) using coca leaves, seeds, and alpaca fat. Visitors can participate in plant-medicine ceremonies, sweat lodge rituals, and multi-day pilgrimages to sacred mountain apus. The valley invites not just sightseeing but a genuine encounter with one of the world''s oldest living spiritual traditions.', 
  -72.15, -13.33, 'Spiritual', 'bg-violet-500', 
  'Andean shamanic ceremonies, plant medicine rituals, and mountain pilgrimages.', '/images/trand-4.jpg', 
  'published', '', '4 Days', 
  NULL, 'Peruvian Sol (PEN)', 'Mild and dry (May–Sep); warm days (65–75°F) and cool nights (35–45°F)', 'May–September for dry season; June for Inti Raymi festivities', 
  'Spanish, Quechua', 'PET (UTC−5)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  59, 1, 'Pisac Market & Ruins', 'Pisac, Sacred Valley', 
  'Arrive in the valley town of Pisac, where the famous market overflows with hand-woven textiles, painted ceramics, and sacks of kiwicha and purple corn. After browsing, hike the switchback trail to the Pisac archaeological complex — a sprawling series of agricultural terraces, ceremonial baths, and a sun temple perched on a ridgeline with commanding views of the valley floor.', '["Browse the vibrant Pisac artisan market","Hike to the Pisac ruins and Intihuatana temple","View the Inca cemetery carved into the cliff face","Sample fresh bread from Pisac''s wood-fired ovens"]', '/images/banner-3.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  59, 2, 'Moray Terraces & Maras Salt Mines', 'Moray & Maras, Sacred Valley', 
  'Visit the enigmatic circular terraces of Moray, believed to be an Inca agricultural research station where temperature differences between the top and bottom tiers allowed experimentation with crops at various altitudes. Continue to the salt mines of Maras, where over 5,000 shallow pools cascade down the mountainside, each evaporating salt-rich spring water into pink crystals just as they have since pre-Inca times.', '["Descend into the concentric terraces of Moray","Photograph the 5,000 cascading salt pools at Maras","Learn about Inca agricultural engineering","Taste freshly harvested Maras pink salt"]', '/images/about-9.jpg', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  59, 3, 'Ollantaytambo Fortress & Living Inca Town', 'Ollantaytambo, Sacred Valley', 
  'Explore Ollantaytambo, the last living Inca town where water still runs through original stone channels and families inhabit buildings with Inca foundations. Climb the steep terraces to the Temple Hill where six massive rose-colored monoliths stand in perfect alignment. The view from the top encompasses the valley, the quarry across the river, and the mysterious granaries (qolqas) carved into the opposite cliff.', '["Walk Ollantaytambo''s original Inca street grid","Climb to the six monolithic temple stones","Spot the carved face of Wiracocha in the mountainside","Visit the Pinkuylluna granaries on the opposite cliff"]', '/images/tour-12.jpg', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  59, 4, 'Shamanic Ceremony & Despacho Offering', 'Q''ero Community, Sacred Valley', 
  'Participate in a despacho ceremony led by a Q''ero paqo (shaman), the highest-altitude indigenous community in Peru and direct keepers of Inca spiritual wisdom. The ceremony involves creating an elaborate offering bundle of coca leaves, seeds, sweets, and symbolic items arranged on paper, each element representing gratitude to Pachamama. The bundle is then burned as a prayer ascending to the apus (mountain spirits).', '["Create a despacho offering with a Q''ero shaman","Learn the sacred significance of coca leaf readings","Participate in prayers to Pachamama and the mountain apus","Share a communal meal of Andean potatoes and herbs"]', '/images/about-10.jpg', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  59, 'Inca Trail Trekking', 'Begin the 4-day classic Inca Trail from Km 82 near Ollantaytambo, passing through cloud forest, dead woman''s pass, and arriving at the Sun Gate of Machu Picchu.', 'Mountain', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  59, 'Plant Medicine Ceremony', 'Participate in guided ayahuasca or San Pedro ceremonies with experienced curanderos in purpose-built retreat centers throughout the valley.', 'Heart', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  59, 'Textile Weaving in Chinchero', 'Visit Chinchero''s women''s weaving cooperatives to see backstrap loom demonstrations and learn how natural dyes are extracted from insects and plants.', 'BookOpen', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  59, 'Mountain Biking Maras to Moray', 'Ride downhill single track from the Maras salt mines to the Moray terraces with stunning Andean mountain backdrops.', 'Dumbbell', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  59, 'Via Ferrata & Skylodge', 'Climb a 400-meter via ferrata and sleep in transparent hanging pods bolted to a cliff face 1,200 feet above the Sacred Valley floor.', 'Landmark', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  59, 'The Sacred Valley sits lower than Cusco (around 9,500 ft vs 11,152 ft), making it a better first stop for altitude acclimatization.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  59, 'Hire a private driver or join a group tour — valley sites are spread across 60 miles and public transport between them is infrequent.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  59, 'Respect shamanic ceremonies deeply — they are living spiritual practices, not tourist entertainment; approach with genuine intention.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  59, 'Buy the Boleto Turístico in Cusco (S/130) which covers Pisac, Moray, Ollantaytambo, and other valley sites.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  59, 'Sunday is the best day to visit Pisac for the full market experience; weekday markets are much smaller.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  59, 'Carry small soles bills; rural vendors and colectivo drivers rarely accept cards or make change for large notes.', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  59, 'The Skylodge via ferrata experience must be booked weeks in advance and requires moderate physical fitness.', 6
);
