INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'rio-de-janeiro', 'Rio de Janeiro', 'Brazil', 'Americas', 
  'Where jungle-clad mountains plunge into golden beaches and samba fills the night', '/images/city-6.jpg', 'Rio de Janeiro is a city of dramatic natural beauty and infectious energy — a place where granite monoliths erupt from tropical forest, golden beaches sweep between jungle headlands, and the sounds of samba and bossa nova drift through warm evening air. Christ the Redeemer stands atop Corcovado mountain with outstretched arms, a 98-foot art deco sentinel watching over a city that seems to celebrate life with every breath.

The geography alone is staggering. Sugarloaf Mountain — Pão de Açúcar — rises 1,299 feet from the mouth of Guanabara Bay, connected to the city by a cable car that offers sunset views rivaling any on Earth. Copacabana''s four-kilometer promenade and Ipanema''s fashionable sands are postcard icons, but the real magic lies in Tijuca National Park, the world''s largest urban rainforest, where toucans screech through cecropia trees just minutes from downtown traffic.

Carnival is Rio''s crowning spectacle — four days in February or March when the entire city transforms into a pageant of feathered costumes, thundering drums, and samba schools competing in the purpose-built Sambódromo. But even outside Carnival, Rio pulses with street music: live samba circles (rodas de samba) in Lapa on Friday nights, bossa nova in Copacabana''s jazz clubs, and forró dancing in Santa Teresa''s bohemian bars. Rio doesn''t just welcome you — it sweeps you up in its rhythm.', 
  -43.17, -22.91, 'City', 'bg-emerald-500', 
  'Christ the Redeemer, Copacabana, Carnival energy, and samba in the streets.', '/images/about-10.jpg', 
  'published', '', '5 Days', 
  NULL, 'Brazilian Real (BRL)', 'Tropical; hot and humid with a rainy season from December to March', 'May–September for drier weather; February–March for Carnival', 
  'Portuguese', 'BRT (UTC−3)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  60, 1, 'Christ the Redeemer & Santa Teresa', 'Corcovado & Santa Teresa, Rio', 
  'Ride the cog railway through the Tijuca rainforest to the summit of Corcovado, where Christ the Redeemer opens his 92-foot arms above the city. The 360-degree panorama encompasses Sugarloaf, Copacabana, the lagoon, and the distant Serra do Mar mountains. Descend to the bohemian hilltop neighborhood of Santa Teresa, where crumbling colonial mansions house art studios, vintage bars, and the Museu Chácara do Céu.', '["Stand at the feet of Christ the Redeemer","Panoramic views of Sugarloaf, Copacabana, and the bay","Explore Santa Teresa''s art galleries and colonial streets","Ride the historic bonde (streetcar) through the hillside"]', '/images/city-6.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  60, 2, 'Sugarloaf Mountain & Copacabana', 'Urca & Copacabana, Rio', 
  'Take the two-stage cable car to the summit of Sugarloaf Mountain for sunrise or sunset — the view of Rio spread between mountains and sea is one of the world''s great urban panoramas. Descend and walk the Urca waterfront promenade before spending the afternoon on Copacabana Beach, sipping açaí bowls from kiosk vendors and watching cariocas play footvolley on the sand.', '["Cable car to Sugarloaf''s summit for sunset panorama","Spot marmosets on the Urca hill nature trail","Stroll the iconic Copacabana promenade","Sip fresh coconut water from beach vendors"]', '/images/banner-4.jpg', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  60, 3, 'Ipanema, Lagoa & Jardim Botânico', 'Ipanema & Jardim Botânico, Rio', 
  'Begin at Ipanema Beach, the strip immortalized in the bossa nova classic ''The Girl from Ipanema,'' where Posto 9 is the gathering point for artists and locals. Walk inland to the Jardim Botânico, a 340-acre garden founded in 1808 with imperial palm avenues, orchid greenhouses, and Amazon Victoria water lilies. End with a sunset jog or bike ride around the Rodrigo de Freitas Lagoon.', '["Sunbathe at Ipanema''s iconic Posto 9","Walk the imperial palm avenue at Jardim Botânico","Cycle around the Rodrigo de Freitas Lagoon at sunset","Dine at one of Leblon''s acclaimed seafood restaurants"]', '/images/offer-1.jpg', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  60, 4, 'Lapa Arches & Samba Night', 'Lapa & Centro, Rio', 
  'Explore the historic center''s mix of baroque churches, imperial libraries, and vibrant street art. Visit the Real Gabinete Português — one of the world''s most beautiful libraries — and the ornate Theatro Municipal. As night falls, head to Lapa, where the iconic white arches frame a neighborhood that transforms into an open-air samba party. Join a roda de samba circle, drink caipirinhas, and dance until the early hours.', '["Photograph the iconic Lapa Arches (Arcos da Lapa)","Visit the stunning Real Gabinete Português de Leitura","Dance at a live samba circle in Lapa''s streets","Sip caipirinhas made with cachaça from Minas Gerais"]', '/images/offer-2.jpg', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  60, 5, 'Tijuca Forest & Hang Gliding', 'Tijuca National Park, Rio', 
  'Hike through Tijuca National Park, the world''s largest urban forest, to cascading waterfalls and the Mirante Dona Marta viewpoint. For the ultimate thrill, take a tandem hang-gliding flight from the Pedra Bonita ramp in São Conrado, soaring above the forest canopy with Copacabana and Sugarloaf spread below — an experience that defines the exhilarating spirit of Rio.', '["Hike to waterfalls in Tijuca National Park","Tandem hang glide from Pedra Bonita over São Conrado","Spot toucans and capuchin monkeys in the canopy","Watch paragliders circle above the jungle"]', '/images/offer-3.jpg', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  60, 'Carnival Celebrations', 'Join the world''s largest party during Carnival — watch samba schools parade through the Sambódromo or dance in the enormous street blocos across the city.', 'Heart', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  60, 'Samba & Bossa Nova', 'Attend a live roda de samba in Lapa, or catch intimate bossa nova performances in Copacabana jazz clubs where the genre was born.', 'Landmark', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  60, 'Brazilian Cuisine', 'Feast on feijoada (black bean and pork stew) at Casa da Feijoada, fresh açaí bowls on the beach, and churrasco at a traditional rodízio.', 'Utensils', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  60, 'Hang Gliding', 'Soar tandem from Pedra Bonita over Tijuca Forest, landing on the beach at São Conrado — Rio''s most exhilarating activity.', 'Globe', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  60, 'Favela Community Tours', 'Take a community-led tour of Rocinha or Vidigal to understand favela culture, art, and resilience — always through ethical operators who reinvest locally.', 'MapPin', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  60, 'Avoid displaying expensive jewelry, phones, or cameras on the beach — petty theft is common in tourist areas.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  60, 'Use Uber or 99 (a local ride app) rather than hailing taxis; they''re cheaper and safer with tracked routes.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  60, 'Book Carnival accommodation at least 6 months ahead; prices triple and availability vanishes.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  60, 'Learn basic Portuguese phrases — English is not widely spoken outside upscale hotels and tourist spots.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  60, 'Apply strong sunscreen — Rio sits in the tropics and UV index regularly exceeds 11, even on overcast days.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  60, 'Visit favelas only with reputable, community-endorsed guides; never enter independently.', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  60, 'Keep copies of your passport at your hotel — carry a photocopy or phone photo instead of the original.', 6
);
