INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'amazon-rainforest', 'Amazon Rainforest', 'Brazil', 'Americas', 
  'The lungs of the Earth — where biodiversity reaches its zenith', '/images/explor-5.jpg', 'The Amazon Rainforest is the largest tropical rainforest on Earth, spanning 2.1 million square miles across nine countries and containing one in ten of all known species. The Brazilian Amazon alone is larger than India, and the Amazon River — the world''s greatest by volume — discharges one-fifth of all fresh water that enters the oceans. To enter the Amazon is to step into a world where the scale of life is almost incomprehensible: a single hectare can harbor 750 species of trees, and the canopy teems with macaws, howler monkeys, three-toed sloths, and poison dart frogs in a symphony of color and sound.

Most visitors base themselves in Manaus, the unlikely metropolis of two million that sits at the confluence of the dark Rio Negro and the sandy-brown Rio Solimões — a phenomenon called the Meeting of the Waters where the two rivers flow side by side without mixing for six miles. From Manaus, riverboats and floatplane transfers reach remote jungle lodges where guides — often from indigenous Caboclo communities — lead dawn canoe paddles through flooded várzea forests, night caiman-spotting excursions by flashlight, and piranha fishing expeditions on blackwater tributaries.

The Amazon is also home to hundreds of indigenous communities who have inhabited the forest for millennia, maintaining traditions of plant medicine, sustainable harvesting, and ecological knowledge that modern science is only beginning to appreciate. A visit here is not just a wildlife adventure — it is a confrontation with the fragility and magnificence of the planet''s most critical ecosystem.', 
  -60.02, -3.12, 'Nature', 'bg-teal-500', 
  'The lungs of the Earth — biodiversity, indigenous communities, and river expeditions.', '/images/offer-1.jpg', 
  'published', '', '4 Days', 
  'Manaus (gateway city; capital of Amazonas state)', 'Brazilian Real (BRL)', 'Equatorial; hot and humid year-round (80–95°F), with a wet season December–May', 'June–November (dry season) for hiking and wildlife; December–May for flooded-forest canoeing', 
  'Portuguese, various indigenous languages (Ticuna, Tucano, Yanomami)', 'AMT (UTC−4)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  61, 1, 'Manaus & Meeting of the Waters', 'Manaus, Amazonas', 
  'Explore the opulent Teatro Amazonas, an Italian Renaissance opera house built with rubber-boom wealth in 1896 — its dome tiled in 36,000 ceramic pieces in the Brazilian flag''s colors. Then board a speedboat to witness the Meeting of the Waters, where the black Rio Negro and tan Rio Solimões flow side by side without mixing, a visible boundary between two distinct river ecosystems.', '["Tour the opulent Teatro Amazonas opera house","Witness the Meeting of the Waters from the boat","Visit the bustling Mercado Adolpho Lisboa fish market","Transfer to your jungle lodge by riverboat"]', '/images/tour-13.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  61, 2, 'Canopy Walkway & Jungle Trek', 'Amazon Jungle Lodge', 
  'Rise at dawn for a canopy walkway experience 100 feet above the forest floor, where toucans, macaws, and howler monkeys inhabit the upper story. Descend for a guided jungle trek where your indigenous guide identifies medicinal plants — the bark of the cinchona tree (source of quinine), the sap of the copaíba used for wounds, and the towering Brazil nut trees that support entire ecosystems.', '["Walk a suspended canopy bridge 100 feet above the forest","Identify medicinal plants with an indigenous guide","Spot howler monkeys and toucans in the upper canopy","Learn jungle survival techniques and water sourcing"]', '/images/banner-5.jpg', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  61, 3, 'Flooded Forest Canoeing & Piranha Fishing', 'Várzea Flooded Forest', 
  'Paddle a dugout canoe through the flooded várzea forest, where trees stand in water up to their crowns and the reflections create a mirror world of green and sky. Your guide points out three-toed sloths draped over cecropia branches, pink river dolphins surfacing in the dark water, and the massive Victoria amazonica water lilies whose pads can span six feet. Afternoon brings piranha fishing on a blackwater tributary.', '["Canoe through the mirror-like flooded várzea forest","Spot pink river dolphins and three-toed sloths","See giant Victoria amazonica water lily pads","Catch piranhas on a blackwater river tributary"]', '/images/offer-4.jpg', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  61, 4, 'Night Safari & Caiman Spotting', 'Amazon River tributaries', 
  'After sunset, board a motorized canoe for a night safari along the river''s edge. Your guide sweeps a powerful flashlight across the water, revealing the orange eye-shine of caimans lurking at the surface. Frogs chorus deafeningly, bats swoop for insects, and the occasional splash of a large fish — perhaps an arapaima, the world''s largest freshwater fish — breaks the darkness. The star field above the unlit forest is breathtaking.', '["Spot caiman eyes glowing in the flashlight beam","Listen to the overwhelming nocturnal frog chorus","Stargaze from the river with zero light pollution","Learn about the arapaima — the Amazon''s giant fish"]', '/images/offer-5.jpg', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  61, 'Pink Dolphin Encounters', 'Observe the Amazon''s endemic boto (pink river dolphin) in their natural habitat — these intelligent creatures are central to Amazonian folklore and mythology.', 'Waves', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  61, 'Indigenous Community Visits', 'Spend time with indigenous communities learning about traditional fishing, plant medicine, body painting, and the oral histories that preserve forest knowledge.', 'BookOpen', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  61, 'Birdwatching', 'The Amazon holds over 1,500 bird species; early-morning canoe trips yield sightings of scarlet macaws, hoatzins, harpy eagles, and dozens of hummingbird species.', 'Camera', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  61, 'Rubber Boom History', 'Explore Manaus''s grand rubber-era architecture — the Teatro Amazonas, the Customs House, and the Iron Market designed by Eiffel''s workshop.', 'Landmark', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  61, 'Amazonian Cuisine', 'Taste tacacá (tucupi and jambu soup), pirarucu grilled over charcoal, açaí with tapioca, and the dozens of exotic fruits found nowhere else on Earth.', 'Utensils', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  61, 'Yellow fever vaccination is required for Amazon travel; carry your International Certificate of Vaccination.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  61, 'Pack long-sleeved shirts, long pants, and DEET-based repellent — mosquitoes carry malaria and dengue in remote areas.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  61, 'Choose a lodge affiliated with indigenous communities to ensure your visit supports local livelihoods and conservation.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  61, 'Bring a dry bag for electronics — humidity exceeds 90% and afternoon downpours are almost guaranteed.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  61, 'Anti-malaria prophylaxis (Malarone or doxycycline) is recommended; consult a travel medicine doctor 4–6 weeks before departure.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  61, 'Cash is essential outside Manaus — jungle lodges and river communities rarely accept credit cards.', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  61, 'The dry season (June–November) is best for jungle hikes; the wet season (December–May) is best for flooded-forest canoeing and water access.', 6
);
