INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'salvador', 'Salvador', 'Brazil', 'Americas', 
  'Afro-Brazilian soul in a colonial jewel on the Bay of All Saints', '/images/dest-1.jpg', 'Salvador da Bahia was Brazil''s first capital and the largest slave port in the Americas, a history that forged one of the most distinctive cultures in the Western Hemisphere. The Pelourinho — the cobblestoned historic center and UNESCO World Heritage Site — cascades down a hillside in a riot of pastel-painted colonial facades, baroque churches dripping with gold leaf, and open squares where the percussive thunder of Olodum drum circles fills the tropical air. It is here that African, Portuguese, and indigenous traditions fused into something entirely new.

That fusion defines everything in Salvador. Candomblé — an Afro-Brazilian religion blending Yoruba orixás with Catholic saints — is openly practiced in terreiros (temples) throughout the city, and public festivals honoring Yemanjá (goddess of the sea) and other orixás draw millions. Capoeira, the martial art disguised as dance that enslaved Africans developed to resist their captors, was born in Salvador''s streets and is still practiced in rodas (circles) in the Pelourinho every evening. The food is equally distinctive — acarajé (black-eyed pea fritters stuffed with vatapá shrimp paste), moqueca baiana (coconut-milk fish stew), and bobó de camarão (shrimp in cassava cream) are dishes found nowhere else with this depth of flavor.

Salvador''s Carnival — though less internationally famous than Rio''s — is widely considered the more authentic celebration, with six days of trio elétrico sound trucks rolling through streets packed with two million revelers dancing axé music in organized blocos. It is raw, joyous, and overwhelming — much like Salvador itself.', 
  -38.51, -12.97, 'Historical', 'bg-amber-600', 
  'Afro-Brazilian heritage, colonial Pelourinho district, and capoeira in the streets.', '/images/trand-5.jpg', 
  'published', '', '4 Days', 
  'Salvador (capital of Bahia state)', 'Brazilian Real (BRL)', 'Tropical; warm and humid year-round (75–90°F), wetter April–July', 'September–March for sunny weather; February for Carnival', 
  'Portuguese', 'BRT (UTC−3)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  62, 1, 'Pelourinho — The Historic Heart', 'Pelourinho, Salvador', 
  'Wander the UNESCO-listed Pelourinho, a cascade of cobblestoned streets and plazas flanked by 17th- and 18th-century colonial buildings in candy shades of blue, pink, and yellow. Visit the gold-encrusted interior of the São Francisco Church — one of the most ornate baroque churches in the world — and the Jorge Amado Foundation dedicated to Bahia''s beloved novelist. As evening falls, the Terreiro de Jesus fills with drum circles and capoeira rodas.', '["Admire the gold-leaf interior of São Francisco Church","Visit the Jorge Amado Foundation and museum","Watch capoeira rodas in the Terreiro de Jesus","Listen to Olodum drummers echo through the squares"]', '/images/dest-1.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  62, 2, 'Lacerda Elevator & Mercado Modelo', 'Cidade Baixa, Salvador', 
  'Ride the Art Deco Elevador Lacerda — Salvador''s iconic 236-foot public elevator connecting the upper and lower cities — for sweeping views of the Bay of All Saints. At the base, explore the Mercado Modelo, a bustling market selling Bahian handicrafts, berimbaus (capoeira instruments), and colorful beaded necklaces representing Candomblé orixás. Lunch on acarajé from a traditional baiana vendor in her white lace dress.', '["Ride the Lacerda Elevator for bay panoramas","Shop for berimbaus and Candomblé beads at Mercado Modelo","Eat acarajé from a traditional baiana street vendor","Explore the Bonfim Church with its colorful wish ribbons"]', '/images/about-1.jpg', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  62, 3, 'Candomblé Terreiro & Afro-Brazilian Heritage', 'Engenho Velho de Brotas, Salvador', 
  'Visit a Candomblé terreiro (temple) with a knowledgeable guide to understand this living Afro-Brazilian religion that syncretized Yoruba orixás with Catholic saints during slavery. See the sacred space where initiates dance to the rhythms of atabaques drums, wearing white garments and beaded necklaces representing their patron orixá. Continue to the Museu Afro-Brasileiro for an immersive exploration of the transatlantic slave trade''s cultural legacy.', '["Visit a Candomblé terreiro with a cultural guide","Learn about the Yoruba orixás and their Catholic syncretism","Explore the Museu Afro-Brasileiro''s powerful exhibitions","Attend a public Candomblé ceremony (when available)"]', '/images/about-2.jpg', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  62, 4, 'Capoeira Workshop & Bahian Cooking', 'Santo Antônio & Pelourinho, Salvador', 
  'Spend the morning in a capoeira workshop with a master (mestre) from one of Salvador''s historic academies, learning the basic ginga movement, kicks, and the musical instruments — berimbau, pandeiro, and atabaque — that drive the rhythm. Afternoon brings a Bahian cooking class where you prepare moqueca, vatapá, and cocada under the guidance of a local chef, learning the African roots of each recipe.', '["Learn the ginga and basic kicks in a capoeira roda","Play the berimbau under a mestre''s instruction","Cook moqueca and vatapá in a hands-on Bahian class","Taste your creations with ice-cold coconut water"]', '/images/about-3.jpg', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  62, 'Carnival in Salvador', 'Join two million revelers for six days of axé music, trio elétrico sound trucks, and organized blocos dancing through the streets of Campo Grande and Barra.', 'Heart', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  62, 'Capoeira Roda', 'Watch or participate in a traditional capoeira circle in the Pelourinho, where mestres and students play this Afro-Brazilian martial art to live berimbau music.', 'Dumbbell', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  62, 'Bahian Street Food', 'Follow the baianas in white lace frying acarajé at their street stalls — stuff yours with vatapá, caruru, and dried shrimp for the authentic experience.', 'Utensils', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  62, 'Island Hopping in the Bay', 'Catch a ferry to Ilha de Itaparica or a schooner to the smaller islands in the Bay of All Saints for deserted beaches and fresh seafood.', 'Waves', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  62, 'Olodum Drum Performance', 'Attend an Olodum rehearsal in the Pelourinho — the Afro-Brazilian drum corps whose rhythms inspired Paul Simon and Michael Jackson.', 'Landmark', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  62, 'Bonfim Wish Ribbons', 'Tie a colorful fita ribbon to the fence of the Church of Nosso Senhor do Bonfim and make three wishes — a beloved Salvador tradition.', 'CheckCircle2', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  62, 'Stay in the Pelourinho or Santo Antônio neighborhoods for walkability and cultural immersion; avoid isolated streets after dark.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  62, 'Salvador''s Carnival is less commercialized than Rio''s — buy an abadá (bloco T-shirt) to join an organized group for safety and fun.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  62, 'Ask permission before photographing Candomblé ceremonies and practitioners; some rituals are private and sacred.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  62, 'Learn a few Portuguese phrases — English is rarely spoken outside upscale hotels; Bahians warmly reward any effort.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  62, 'Carry minimal valuables when walking the historic center; use your hotel safe for passports and excess cash.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  62, 'Try the local beer Itaipava ice-cold from a corner bar, paired with petiscos (snacks) like bolinhos de bacalhau.', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  62, 'The Lacerda Elevator is free and runs constantly — use it to commute between Cidade Alta and Cidade Baixa.', 6
);
