INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'buenos-aires', 'Buenos Aires', 'Argentina', 'South America', 
  'Tango, steak, European grandeur, and the passionate soul of Latin America', 'https://images.pexels.com/photos/1392732/pexels-photo-1392732.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 'Buenos Aires is a city that seduces slowly — through the smoky haze of a parrilla grilling prime cuts of grass-fed beef, through the embrace of a tango milonga where strangers move as one, through the peeling facades of San Telmo''s colonial buildings and the painted murals of Palermo''s leafy barrios. Founded twice — the second time for good in 1580 — this city of 15 million wears its European DNA proudly, with wide Haussmann-style boulevards, ornate French-inspired mansions, and a café culture that treats conversation as high art.

Avenida 9 de Julio, one of the world''s widest avenues, bisects the city with an eight-lane swagger, framed by the iconic pink Casa Rosada where Eva Perón addressed the masses. The working-class La Boca neighborhood bursts with corrugated iron houses painted in vivid yellows, greens, and reds — a tradition born from leftover ship paint — while the nearby Caminito street market is a living stage for street tango performances. Recoleta''s necropolis rivals Paris''s Père Lachaise in elaborate marble mausoleums, and Evita herself rests here beneath a thicket of flowers.

Beyond the landmarks, Buenos Aires rewards the wanderer: a Sunday afternoon at the vast San Telmo antiques market, an asado at a private home where the host tends the grill for hours, a late-night empanada at 3 a.m. after a milonga — because in Buenos Aires, dinner rarely starts before 9 p.m. and the night is always just beginning.', 
  -58.38, -34.6, 'City', 'bg-emerald-500', 
  'Tango, steak, colorful La Boca neighborhoods, and European-style grandeur.', '/images/trand-5.jpg', 
  'published', '', '5 Days', 
  'Buenos Aires (federal capital)', 'Argentine Peso (ARS); USD accepted informally', 'Humid subtropical; hot summers, mild winters; rain year-round', 'March–May & September–November for pleasant temperatures and fewer crowds', 
  'Spanish (Argentine dialect)', 'ART (UTC−3)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  63, 1, 'La Boca, San Telmo & the Tango Heartbeat', 'La Boca & San Telmo', 
  'Start in La Boca''s Caminito street, where dancers perform tango beneath painted houses and artists sell watercolors of the Río de la Plata docks. Walk north to San Telmo for the Sunday antiques market and your first taste of choripán — grilled chorizo in crusty bread — before a candlelit milonga lesson in the evening.', '["Watch street tango performers at the Caminito outdoor stage","Browse 1,000 stalls at the San Telmo Sunday Antiques Market","Take a beginner tango lesson at a traditional milonga","Sample choripán and medialunas from a street stall"]', 'https://images.pexels.com/photos/1392732/pexels-photo-1392732.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  63, 2, 'Recoleta, the Casa Rosada & Centro', 'Recoleta & Microcentro', 
  'Visit the Recoleta Cemetery, a city within a city where marble angels watch over Argentina''s elite — Evita''s tomb draped in fresh flowers. Walk the wide Avenida 9 de Julio to the Casa Rosada, where the pink government palace''s balcony once hosted Perón and Madonna alike.', '["Find Evita Perón''s tomb in the labyrinthine Recoleta Cemetery","Photograph the Obelisk on Avenida 9 de Julio at golden hour","Tour the Casa Rosada museum and see the famous balcony","Browse the Recoleta weekend fair for artisan leather goods"]', 'https://images.pexels.com/photos/5609528/pexels-photo-5609528.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  63, 3, 'Palermo Barrios & Local Foodie Culture', 'Palermo Soho & Hollywood', 
  'Palermo''s tree-lined streets hide boutique concept stores, craft beer bars, and the Buenos Aires Ecological Reserve. Spend the morning in the Japanese Garden, afternoons sipping cortado at a café, and evenings at a mercado trying chimichurri-drenched skewers and artisan dulce de leche ice cream.', '["Wander the Japanese Garden and rose garden of the Palermo Parks","Browse boutique design shops in Palermo Soho for leather belts and bags","Sample Mercado de Pulgas (flea market) for vintage finds","Dine at a parrilla restaurant for a full Argentine asado experience"]', 'https://images.pexels.com/photos/35895230/pexels-photo-35895230.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  63, 4, 'Puerto Madero & Tigre Delta Day Trip', 'Puerto Madero & Tigre', 
  'Walk the converted red-brick docks of Puerto Madero, now a sleek waterfront promenade of restaurants and offices. In the afternoon, take the suburban train to Tigre and board a lancha (water taxi) to explore the Paraná Delta''s jungle-lined channels, wooden river houses, and floating artisan markets.', '["Walk the Puente de la Mujer (Woman''s Bridge) at Puerto Madero","Ride the suburban train along the Río de la Plata to Tigre","Navigate the Paraná Delta by lancha and stop at a riverside café","Browse the Tigre Artisan Market for handmade crafts and preserves"]', 'https://images.pexels.com/photos/35994507/pexels-photo-35994507.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  63, 5, 'Tango Show & Farewell Asado', 'Palermo & San Telmo', 
  'Spend the morning browsing the MALBA (Museum of Latin American Art), home to Frida Kahlo and Diego Rivera originals. In the evening, attend a world-class dinner tango show at a historic milonga before a final late-night asado at a local parrilla, sharing a Malbec with new friends.', '["Explore Frida Kahlo and Xul Solar works at MALBA","Attend a professional dinner-tango show with live orchestra","Toast with a glass of Mendoza Malbec at a corner wine bar","Finish the night dancing at an open-air milonga in San Telmo"]', 'https://images.pexels.com/photos/1709920/pexels-photo-1709920.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  63, 'Tango at a Milonga', 'Join a late-night milonga — a tango dance hall — where strangers connect through this passionate Argentine dance form.', 'Heart', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  63, 'Parrilla Asado Dinner', 'Experience a traditional Argentine asado at a parrilla where slow-grilled beef, morcilla, and mollejas are served with chimichurri.', 'Utensils', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  63, 'Recoleta Cemetery Walk', 'Wander through this ornate city of the dead where Argentina''s most famous citizens rest in elaborate marble mausoleums.', 'Landmark', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  63, 'Tigre Delta Boat Tour', 'Explore the lush Paraná Delta by wooden lancha, passing floating cafés, weekend mansions, and jungle waterways.', 'Waves', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  63, 'San Telmo Antiques Market', 'Hunt for vintage silver, antique maps, and tango memorabilia at the legendary Sunday market in colonial San Telmo.', 'Globe', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  63, 'Malbec Wine Tasting', 'Join a guided Argentine wine tasting session and discover how Mendoza''s altitude produces some of the world''s finest Malbec.', 'Heart', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  63, 'Argentina''s currency situation is complex — research the ''blue dollar'' exchange rate and use ATMs wisely to maximize your budget.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  63, 'Dinner before 9 p.m. is unusual; embrace the local schedule and enjoy a late-night culture where restaurants fill after 10 p.m.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  63, 'Taxis from the street can be unsafe — use licensed remis taxis booked through your hotel or ride-hailing apps like Cabify.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  63, 'Carry small bills for markets and empanada shops; large notes are often refused in small establishments.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  63, 'The Metro (Subte) is cheap and reliable for central neighborhoods; buy a rechargeable SUBE card from a kiosk.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  63, 'Learn a few words of Rioplatense Spanish — ''vos'' replaces ''tú'' and porteños appreciate any attempt at the local dialect.', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  63, 'Buenos Aires is one of the safest major cities in South America — but remain vigilant in crowded markets and on busy avenues.', 6
);
