INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'patagonia', 'Patagonia', 'Argentina', 'South America', 
  'Glaciers, granite towers, and the raw edge of the world at the tip of South America', 'https://images.pexels.com/photos/4346709/pexels-photo-4346709.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 'Patagonia is the world''s idea of wilderness made real — a sweep of wind-scoured steppes, turquoise glacial lakes, and granite towers so sharp they seem to pierce the clouds. Straddling the southern tip of Argentina and Chile, this vast region covers roughly 400,000 square miles and holds some of the most dramatic landscapes on Earth: the Torres del Paine massif rising like a fortress from the Patagonian steppe, the Perito Moreno Glacier advancing into Lago Argentino with a thunderous crack and calve, and the mythical Route 40 stitching together remote estancias and forgotten Tehuelche petroglyphs.

El Chaltén, a village born in 1985 to assert Argentine sovereignty, has grown into the trekking capital of South America, its trails leading directly from wooden guesthouses to the base of Cerro Torre and Monte Fitz Roy — two of the most technically demanding peaks on the planet. For those who prefer horizontal adventure, the Perito Moreno Glacier offers guided ice walks across its crevassed blue surface, while sea kayaking in the Beagle Channel near Ushuaia — the southernmost city in the world — places paddlers alongside Magellanic penguins and southern fur seals.

Patagonia rewards patience and layering: the weather changes within minutes, wind gusts have been measured at 200 km/h, and the light — when it breaks through storm clouds — illuminates the peaks in shades of copper and gold that no filter can replicate. This is a place where nature holds final authority, and humans are grateful visitors.', 
  -69, -50, 'Nature', 'bg-teal-500', 
  'Glaciers, dramatic peaks, and some of the most remote hiking on Earth.', '/images/offer-1.jpg', 
  'published', '', '5 Days', 
  NULL, 'Argentine Peso (ARS) in Argentina; Chilean Peso (CLP) in Chile', 'Cold, windy, and unpredictable year-round; summers (Dec–Feb) are mildest', 'November–March for trekking; June–August for winter silence and snowscapes', 
  'Spanish', 'ART (UTC−3) Argentina; CLT (UTC−3) Chile', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  64, 1, 'Arrival in El Calafate & Perito Moreno Glacier', 'El Calafate, Santa Cruz Province', 
  'Arrive in El Calafate, gateway to Los Glaciares National Park, and head directly to the Perito Moreno Glacier — one of the few glaciers on Earth that is still advancing. Walk the elevated boardwalks as ice towers crash into Lago Argentino with explosive booms, and if conditions allow, join a minitrekking tour on the ice itself.', '["Watch massive ice towers calve into Lago Argentino from boardwalk viewpoints","Walk on Perito Moreno''s surface with crampons on a guided mini-trekking tour","Photograph the glacier''s electric-blue crevasses and ice caves","Dine on Patagonian lamb stew at a lakeside restaurant in El Calafate"]', 'https://images.pexels.com/photos/4346709/pexels-photo-4346709.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  64, 2, 'Lago Argentino Boat Tour & Upsala Glacier', 'Lago Argentino', 
  'Board a catamaran on Lago Argentino to reach the remote Upsala Glacier, navigating through a floating iceberg field of cathedral-sized blue ice. Stop at Estancia Cristina for a guided walk through lenga beech forests before returning across the wind-whipped lake.', '["Navigate icebergs the size of office buildings on a Lago Argentino catamaran","Walk the moraine fields above Upsala Glacier for panoramic views","Visit Estancia Cristina and its pioneer-era museum","Spot condors riding thermals above the glacial valley"]', 'https://images.pexels.com/photos/7116638/pexels-photo-7116638.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  64, 3, 'Drive to El Chaltén & Fitz Roy Trek', 'El Chaltén, Santa Cruz Province', 
  'Drive north through the steppe to El Chaltén, where the granite spires of Monte Fitz Roy and Cerro Torre define the skyline. Hike the Laguna de los Tres trail for the iconic close-up view of Fitz Roy reflected in a glacial lake, and explore the town''s artisan chocolate shops and micro-breweries in the evening.', '["Hike the Laguna de los Tres trail (8-hour round trip) to Fitz Roy''s base","Photograph the ''Smoking Mountain'' (Cerro Torre) from Laguna Torre","Sample locally brewed Patagonian craft beers at a wood-panelled hostel","Watch the alpenglow turn Fitz Roy orange and pink at sunset"]', 'https://images.pexels.com/photos/7476116/pexels-photo-7476116.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  64, 4, 'Ushuaia & the End of the World', 'Ushuaia, Tierra del Fuego', 
  'Fly south to Ushuaia — the world''s southernmost city — wedged between the Martial Mountains and the Beagle Channel. Cruise past sea lions and cormorant colonies on the Beagle Channel, visit the Prison Museum in the old penitentiary, and hike in Tierra del Fuego National Park through forests of lenga beech to Lapataia Bay.', '["Cruise the Beagle Channel past sea lion rocks and Les Éclaireurs Lighthouse","Visit Lapataia Bay, the end of the Panamericana Highway, at the national park","Tour the restored 1896 Ushuaia Prison and its fascinating exhibit","Eat centolla (king crab) chowder at a dockside restaurant"]', 'https://images.pexels.com/photos/6721004/pexels-photo-6721004.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  64, 5, 'Torres del Paine Base Towers Hike', 'Torres del Paine, Chile', 
  'Cross into Chile for the legendary Base Las Torres hike in Torres del Paine National Park. The 8-hour round-trip rewards with the sight of three granite towers mirrored in a teal glacial lake — arguably the most photographed image in Patagonia. Return via bus to Puerto Natales for a final Patagonian lamb asado.', '["Hike the steep trail to Base Las Torres and the iconic mirrored lake","Cross a swinging suspension bridge over a glacial river","Spot guanacos, Andean foxes, and condors along the trail","Celebrate the day''s achievement with a lamb asado in Puerto Natales"]', 'https://images.pexels.com/photos/4599300/pexels-photo-4599300.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  64, 'Perito Moreno Ice Trek', 'Strap on crampons and walk the surface of one of the world''s largest glaciers with a certified guide on a minitrekking tour.', 'Mountain', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  64, 'Torres del Paine Base Trek', 'Complete the legendary hike to the base of Patagonia''s three granite towers and their ice-blue mirror lake.', 'MapPin', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  64, 'Beagle Channel Kayaking', 'Paddle the Beagle Channel near Ushuaia, sharing waters with Magellanic penguins, sea lions, and southern fur seals.', 'Waves', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  64, 'Estancia Life Experience', 'Stay overnight at a working estancia and experience lamb herding, gaucho horsemanship, and traditional Patagonian asado.', 'Landmark', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  64, 'Lago Argentino Iceberg Cruise', 'Navigate through cathedral-sized drifting icebergs on a catamaran tour of Lago Argentino''s remote glacier arms.', 'Globe', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  64, 'Monte Fitz Roy Sunrise', 'Wake at 4 a.m. and hike to Laguna de los Tres to witness Fitz Roy''s granite towers turn copper-gold at first light.', 'Mountain', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  64, 'Book accommodation in El Chaltén and Torres del Paine months in advance — peak season (Dec–Feb) fills up extremely quickly.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  64, 'Layer constantly — Patagonian weather can change from sun to blizzard in 20 minutes; always carry a waterproof shell.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  64, 'Wind gusts can be violent and dangerous on exposed ridges; crouch low and hold trekking poles horizontally in extreme gusts.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  64, 'Carry Argentine pesos and Chilean pesos separately — ATMs in small towns frequently run out of cash.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  64, 'Purchase National Park entry tickets online before arriving at Torres del Paine to avoid queues at the gate.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  64, 'Hire a local guide for Fitz Roy treks if you''re not experienced — trail markings can be obscured by snow and fog.', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  64, 'Drink directly from glacial streams on backcountry trails — Patagonia''s river water is among the cleanest on Earth.', 6
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  64, 'https://images.pexels.com/photos/4346709/pexels-photo-4346709.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  64, 'https://images.pexels.com/photos/7116638/pexels-photo-7116638.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  64, 'https://images.pexels.com/photos/7476116/pexels-photo-7476116.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  64, 'https://images.pexels.com/photos/6721004/pexels-photo-6721004.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_images` (
