INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'banff', 'Banff', 'Canada', 'North America', 
  'Turquoise glacier lakes, Rocky Mountain peaks, and iconic wilderness trails', 'https://images.pexels.com/photos/36185626/pexels-photo-36185626.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 'Banff National Park — Canada''s oldest and most celebrated park — is a place where the Rocky Mountains display their full theatrical authority: glaciers calving into lakes of impossible turquoise, elk wandering hotel parking lots with regal indifference, and the Trans-Canada Highway threading through valleys watched over by 3,000-metre peaks. Established in 1885 around a chance discovery of hot springs, Banff has evolved into one of the world''s most visited natural destinations without losing its wild, vertiginous soul.

Lake Louise, often called the ''Gem of the Rockies,'' turns photographers into pilgrims: its glacier-fed waters shift from green to teal to cobalt depending on the angle of the sun, backed by the Victoria Glacier and flanked by the Fairmont Château Lake Louise, whose walls of windows reflect the spectacle perfectly. Moraine Lake, with its ring of ten peaks and even more vivid blue-green water, graced the back of the Canadian twenty-dollar bill and rewards the 5 a.m. pilgrim with a parking space and solitude before the crowds arrive.

Beyond the postcard scenes, Banff offers world-class skiing on three interconnected mountains, backcountry camping along the Rockwall Trail, grizzly bear sightings in the Bow Valley, and the Icefields Parkway — one of the world''s great scenic drives — linking Banff to Jasper through 230 kilometres of unbroken mountain grandeur. Whether you arrive in winter dusted with snow or summer blazing with wildflowers, Banff rewards every visit with moments that make the rest of the world feel small.', 
  -115.57, 51.18, 'Nature', 'bg-teal-500', 
  'Turquoise glacier lakes, Rocky Mountain peaks, and iconic wilderness trails.', '/images/about-2.jpg', 
  'published', '', '5 Days', 
  NULL, 'Canadian Dollar (CAD)', 'Continental mountain climate; cold winters (−20°C), warm summers (up to 30°C)', 'June–September for hiking; December–March for skiing', 
  'English, French', 'MST (UTC−7) / MDT (UTC−6) in summer', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  65, 1, 'Banff Townsite & Bow Valley Exploration', 'Banff Townsite', 
  'Arrive in Banff and begin with the Cave and Basin National Historic Site, where the hot spring discovery that created the park still bubbles. Walk the Bow River Loop trail through pine forest, soak in the Upper Hot Springs, and enjoy Banff Avenue''s restaurants and outdoor gear shops before dinner overlooking the Bow Valley.', '["Visit Cave and Basin Historic Site — the park''s founding thermal hot spring","Walk the Bow River Loop trail through mixed forest for elk sightings","Soak in the Upper Hot Springs against a mountain backdrop","Watch for bighorn sheep grazing on Mount Norquay slopes at dusk"]', 'https://images.pexels.com/photos/36185626/pexels-photo-36185626.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  65, 2, 'Lake Louise & Moraine Lake', 'Lake Louise Area', 
  'Rise at 5 a.m. to beat crowds at Moraine Lake — the ten-peak amphitheatre reflected in otherworldly teal water. Drive the short distance to Lake Louise for a mid-morning canoe rental, paddling toward the Victoria Glacier while hoarfrost clings to the surrounding peaks. Afternoon hike to Lake Agnes Tea House, perched on a cliff above the lake.', '["Photograph Moraine Lake''s teal water surrounded by the Valley of the Ten Peaks","Paddle a red canoe across Lake Louise toward the Victoria Glacier","Hike to Lake Agnes Tea House for a scone and glacier views","Walk the lakeshore trail through larches turning gold in September"]', 'https://images.pexels.com/photos/2916817/pexels-photo-2916817.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  65, 3, 'Icefields Parkway & Athabasca Glacier', 'Icefields Parkway, Jasper National Park', 
  'Drive the 230-km Icefields Parkway — repeatedly named the world''s most scenic road — stopping at Peyto Lake''s wolf-shaped overlook and the Columbia Icefield. Walk on the Athabasca Glacier with crampons, then visit the Columbia Icefield Skywalk for glass-floored views over a 280-metre cliff.', '["Stop at Peyto Lake Lookout for the turquoise wolf-shaped lake panorama","Walk on the Athabasca Glacier surface on a guided tour with crampons","Stand on the Columbia Icefield Skywalk glass floor above a glacial valley","Photograph Bow Lake and Bow Glacier reflected in wind-still water"]', 'https://images.pexels.com/photos/5635734/pexels-photo-5635734.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  65, 4, 'Sulphur Mountain Gondola & Johnston Canyon', 'Banff & Bow Valley Parkway', 
  'Ride the Banff Gondola to Sulphur Mountain''s summit for 360-degree views of six mountain ranges, then hike the ridgeline boardwalk to a restored 1903 cosmic ray station. Afternoon at Johnston Canyon, where two spectacular waterfalls crash through narrow limestone walls, and the canyon walls are draped in ice in winter.', '["Ride the gondola to Sulphur Mountain for panoramic six-range views","Walk the summit ridgeline boardwalk to the historic cosmic ray station","Hike through Johnston Canyon''s slot canyon to Upper and Lower Falls","Spot dippers (aquatic birds) nesting behind the canyon waterfall spray"]', 'https://images.pexels.com/photos/36287405/pexels-photo-36287405.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  65, 5, 'Banff Wildlife Safari & Farewell Hike', 'Bow Valley & Vermilion Lakes', 
  'Join a dawn wildlife safari along the Bow Valley Parkway, where wolves, coyotes, and bears are most active. Canoe the Vermilion Lakes at sunrise for Mount Rundle reflections, then hike the Tunnel Mountain trail — a gentle 2-hour loop — for your final panoramic farewell to the Rockies.', '["Dawn wildlife safari along Bow Valley Parkway for wolves, elk, and bears","Canoe the Vermilion Lakes at sunrise for Mount Rundle reflections","Hike Tunnel Mountain trail for 360-degree views of the Banff valley","Final dinner at a log-cabin steakhouse with a view of Cascade Mountain"]', 'https://images.pexels.com/photos/36282616/pexels-photo-36282616.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  65, 'Moraine Lake Sunrise', 'Wake before dawn and witness the ten peaks turn rose-gold above Moraine Lake''s teal water — Canada''s most photographed scene.', 'Mountain', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  65, 'Lake Louise Canoeing', 'Paddle a red canoe across the glacier-fed emerald waters of Lake Louise with the Victoria Glacier as your backdrop.', 'Waves', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  65, 'Icefields Parkway Drive', 'Drive 230 km of the world''s most scenic road, stopping at turquoise lakes, glaciers, and mountain passes all the way to Jasper.', 'MapPin', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  65, 'Athabasca Glacier Walk', 'Strap on crampons and walk the surface of the Athabasca Glacier, one of the most accessible ice fields in North America.', 'Mountain', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  65, 'Wildlife Safari', 'Join a guided dawn wildlife tour along Bow Valley Parkway for sightings of wolves, elk, black bears, and grizzlies.', 'Camera', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  65, 'Banff Hot Springs Soak', 'Relax in the mineralized waters of the Upper Hot Springs with mountain views — the thermal springs that founded the park.', 'Heart', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  65, 'Purchase a Parks Canada Discovery Pass before arrival — it covers entry to Banff, Jasper, and dozens of other national parks for one year.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  65, 'Arrive at Moraine Lake before 6 a.m. or after 5 p.m. in summer — Parks Canada may restrict vehicle access during peak hours.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  65, 'Bears are very active in the park; carry bear spray on every hike and store all food in bear-resistant containers or lockers.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  65, 'Book accommodation in Banff and Lake Louise 6–12 months ahead — the Fairmont and other popular lodges sell out within hours of release.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  65, 'Download the Banff trail map offline via the AllTrails app — cell service is unreliable in remote areas of the park.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  65, 'The Icefields Parkway can be closed by snowfall even in June — check Alberta 511 road conditions before driving.', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  65, 'Wildlife on roads is extremely common; drive slowly, never stop in the middle of the road, and never approach or feed animals.', 6
);
