INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'vancouver', 'Vancouver', 'Canada', 'North America', 
  'Ocean-meets-mountain cityscape with world-class dining and outdoor adventures', 'https://images.pexels.com/photos/6644046/pexels-photo-6644046.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 'Vancouver is a city that cheats geography in the best possible way — where urban skyline, Pacific Ocean, and snow-capped mountains exist in the same frame, sometimes within the same smartphone photograph. Routinely ranked among the world''s most livable cities, Vancouver is a place where a morning ski run at Whistler Blackcomb transitions seamlessly into an afternoon kayak around Indian Arm, and where the evening might unfold over omakase sushi in Richmond — North America''s most celebrated Japanese dining city outside Japan.

Stanley Park, a 405-hectare old-growth temperate rainforest on a peninsula jutting into Burrard Inlet, is the city''s green heart: its 8.8-kilometre seawall encircles ancient western red cedars, sandy beaches, and blue herons fishing in tidal pools, all within ten minutes of the downtown financial district. Granville Island, once an industrial peninsula, now buzzes as one of Canada''s great public markets — where Vietnamese spring rolls, house-made cheese, artisan gin, and handmade kayaks share cramped aisles under corrugated-iron roofs.

In the winter months, Vancouver is a ski city: two local mountains (Cypress and Grouse) are accessible by car in under an hour, while Whistler — a 90-minute drive north — is a world-class resort with 200+ marked runs and a legendary après-ski culture. In summer, the same mountains become mountain-biking terrain, while the Capilano River and Squamish provide world-class rock climbing and wind-surfing. The food scene reflects a multicultural city built on Pacific Rim immigration, and what Vancouver lacks in European history it more than compensates for in natural grandeur.', 
  -123.12, 49.28, 'Corporate', 'bg-slate-600', 
  'Tech-industry offsites, mountain-lodge team retreats, and convention facilities with ocean-and-mountain backdrops.', '/images/about-3.jpg', 
  'published', '', '5 Days', 
  NULL, 'Canadian Dollar (CAD)', 'Mild oceanic; rainy winters (7°C), warm dry summers (22°C)', 'June–September for outdoor activities; December–March for skiing', 
  'English; Mandarin, Cantonese, Punjabi widely spoken', 'PST (UTC−8) / PDT (UTC−7) in summer', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  66, 1, 'Stanley Park & Gastown Exploration', 'Downtown Vancouver', 
  'Cycle or walk Stanley Park''s 8.8-km seawall loop at dawn when the old-growth forest meets the ocean in silence. Stop at the Totem Poles, Third Beach, and Siwash Rock before heading to Gastown for brunch near the famous steam clock and artisan coffee roasters.', '["Cycle the Stanley Park seawall loop with mountain and ocean views","Visit the totem poles and Brockton Point Lighthouse in Stanley Park","Photograph the historic Gastown Steam Clock and cobblestone streets","Brunch on eggs Benedict at a Gastown heritage building café"]', 'https://images.pexels.com/photos/6644046/pexels-photo-6644046.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  66, 2, 'Granville Island & Kitsilano Beach', 'Granville Island & Kitsilano', 
  'Take the tiny Aquabus ferry to Granville Island Public Market for a morning of tasting artisan cheese, fresh Dungeness crab, and Okanagan fruit preserves. Walk or cycle to Kitsilano Beach for an afternoon swim in a heated outdoor pool overlooking English Bay, followed by dinner on 4th Avenue''s global restaurant strip.', '["Taste artisan food at Granville Island Public Market — cheese, fish, and preserves","Cross Burrard Inlet to Granville Island on the tiny Aquabus passenger ferry","Swim in the heated saltwater Kitsilano Pool with mountain backdrop views","Dine on fresh Pacific salmon at a Kitsilano seafood restaurant"]', 'https://images.pexels.com/photos/2782485/pexels-photo-2782485.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  66, 3, 'North Shore Mountains & Capilano Suspension Bridge', 'North Vancouver', 
  'Cross the Lions Gate Bridge to North Vancouver for the Capilano Suspension Bridge — 137 metres long, 70 metres above the rainforest river — then walk the Cliffwalk cantilevered platforms along the granite cliff face. In the afternoon, hike the Grouse Grind (''Mother Nature''s Stairmaster'') for city views from 1,100 metres.', '["Cross the swaying Capilano Suspension Bridge above the old-growth canyon","Walk the cantilevered Cliffwalk platforms through the rainforest granite cliff","Hike the Grouse Grind trail (2.9 km vertical) for panoramic city views","Take the Grouse Mountain gondola down and watch wild wolf ambassadors"]', 'https://images.pexels.com/photos/6272214/pexels-photo-6272214.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  66, 4, 'Whistler Day Trip & Sea-to-Sky Highway', 'Squamish & Whistler', 
  'Drive the breathtaking Sea-to-Sky Highway north of Vancouver, stopping at Shannon Falls (335 metres) and the Stawamus Chief granite monolith, a premier rock climbing destination. Continue to Whistler Village for mountain biking, gondola rides to the peak, and a leisurely village stroll with craft beer and poutine.', '["Stop at Shannon Falls — BC''s third-highest waterfall — on the Sea-to-Sky","Photograph the granite face of Stawamus Chief rising above Howe Sound","Ride the Whistler Village Gondola to the Roundhouse for peak views","Mountain bike the World Cup trails of Whistler Bike Park (seasonal)"]', 'https://images.pexels.com/photos/5727513/pexels-photo-5727513.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  66, 5, 'Richmond Night Market & Pacific Rim Cuisine', 'Richmond & Vancouver Waterfront', 
  'Drive south to Richmond''s Steveston Village — a historic salmon cannery turned waterfront town — for fresh fish and chips on the dock. In the evening, explore the Richmond Night Market for pan-Asian street food, bubble tea experiments, and handmade goods before a farewell sunset from Canada Place''s harbor promenade.', '["Eat fish and chips dockside at Steveston Fisherman''s Wharf in Richmond","Sample 100+ Asian street food vendors at the Richmond Night Market","Walk Canada Place''s harbor promenade for a final Vancouver skyline sunset","Spot bald eagles fishing in the Fraser River delta at dusk"]', 'https://images.pexels.com/photos/5745903/pexels-photo-5745903.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  66, 'Stanley Park Seawall Cycle', 'Ride or walk the 8.8 km seawall loop around Stanley Park with views of mountains, ocean, and old-growth rainforest simultaneously.', 'MapPin', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  66, 'Capilano Suspension Bridge', 'Cross a 137-metre suspension bridge over a rainforest canyon and walk the Cliffwalk platforms embedded in the granite cliff.', 'Mountain', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  66, 'Whistler Ski or Bike', 'Hit the slopes of North America''s top ski resort in winter, or descend legendary mountain bike trails in summer.', 'Dumbbell', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  66, 'Granville Island Market', 'Browse one of Canada''s best public markets for fresh Pacific seafood, artisan cheese, craft gin, and handmade goods.', 'Globe', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  66, 'Sea-to-Sky Gondola', 'Ride the gondola above Squamish for aerial views of Howe Sound''s fjord, glaciers, and the Stawamus Chief granite monolith.', 'Camera', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  66, 'Pacific Rim Dining', 'Explore Vancouver''s celebrated food scene — from Japanese omakase in Richmond to Dungeness crab and Okanagan wine pairings.', 'Utensils', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  66, 'Vancouver is expensive — book accommodation early and consider staying in Kitsilano or East Vancouver for better value than downtown.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  66, 'Public transit (SkyTrain and buses) is excellent and affordable; a Compass Card is cheaper than buying single tickets.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  66, 'Weather is notoriously grey in winter — pack a packable waterproof jacket as an absolute essential year-round.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  66, 'Richmond''s Lansdowne and Aberdeen areas offer exceptional and authentic Asian cuisine at surprisingly low prices.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  66, 'The Grouse Grind is a one-way strenuous hike — take the gondola back down and have the exact $15 CAD fare ready.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  66, 'Book the Sea-to-Sky Gondola tickets online for a small discount and to avoid peak-hour queues on summer weekends.', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  66, 'Bears do visit North Shore neighborhoods at night — follow local guidelines and never leave food waste accessible.', 6
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  66, 'https://images.pexels.com/photos/6644046/pexels-photo-6644046.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  66, 'https://images.pexels.com/photos/2782485/pexels-photo-2782485.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  66, 'https://images.pexels.com/photos/6272214/pexels-photo-6272214.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  66, 'https://images.pexels.com/photos/5727513/pexels-photo-5727513.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  66, 'https://images.pexels.com/photos/5745903/pexels-photo-5745903.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 4
);

INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'abu-dhabi', 'Abu Dhabi', 'United Arab Emirates', 'Middle East', 
  'Where desert grandeur meets visionary ambition on the Arabian Gulf', 'https://images.pexels.com/photos/415648/pexels-photo-415648.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 'Abu Dhabi is a city that defies expectation — a shimmering mirage made real on the edge of the Rub'' al Khali, the world''s largest uninterrupted sand desert. The gleaming white domes of the Sheikh Zayed Grand Mosque, one of the planet''s most magnificent places of worship, set the tone for a capital that treats beauty as policy and hospitality as creed. From the contemporary galleries of Saadiyat Island''s Louvre Abu Dhabi to the aromatic spice stalls of the Mina Fish Market, the city moves fluidly between ultramodern ambition and deep-rooted Bedouin tradition.

Beyond the skyline, the mangrove forests of Jubail Island teem with herons and flamingos, while the dunes of the Liwa Oasis rise to heights that dwarf ten-storey buildings. Kayak through mangrove channels at dawn, dine on slow-roasted lamb ouzi in a desert camp at dusk, or wander the Abrahamic Family House — a mosque, church, and synagogue sharing a single campus — to witness interfaith dialogue made architecture.

Abu Dhabi rewards those who look beyond the glittering surface: the heritage village of Al Ain, a UNESCO site of ancient falaj irrigation channels, the falcon hospitals where Emirati hunting culture is preserved, and the date farms of Al Dhafra, where sticky khalas dates are picked by hand. This is a destination where tomorrow is being built without forgetting yesterday.', 
  54.4, 24.45, 'Spiritual', 'bg-violet-500', 
  'Sheikh Zayed Grand Mosque, Louvre museum, and interfaith cultural districts.', '/images/city-4.jpg', 
  'published', '', '5 Days', 
  'Abu Dhabi (national capital)', 'UAE Dirham (AED)', 'Arid desert with scorching summers and mild, pleasant winters', 'November–March (cooler temperatures, outdoor festivals)', 
  'Arabic, English widely spoken', 'GST (UTC+4)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  67, 1, 'Sheikh Zayed Mosque & Saadiyat Cultural Quarter', 'Abu Dhabi Island & Saadiyat Island', 
  'Begin at the Sheikh Zayed Grand Mosque, where 82 marble domes and the world''s largest hand-knotted carpet leave visitors breathless. Spend the afternoon at the Louvre Abu Dhabi, a Jean Nouvel masterpiece where a lattice dome casts a ''rain of light'' over galleries spanning 12,000 years of human creativity.', '["Walk the reflective pools surrounding the Sheikh Zayed Grand Mosque at sunset","Admire Da Vinci''s Salvator Mundi and ancient Mesopotamian artifacts at the Louvre","Photograph the geometric ''rain of light'' beneath the Louvre''s lattice dome","Dine on Emirati machboos at a waterfront restaurant on Saadiyat"]', 'https://images.pexels.com/photos/415648/pexels-photo-415648.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  67, 2, 'Mangroves, Markets & Maritime Heritage', 'Jubail Island & Mina District', 
  'Paddle a kayak through the tangled mangrove channels of Jubail Island at sunrise, spotting herons and crabs in the tidal flats. Return to the city for the Mina Fish Market and the spice-scented alleys of the old souk, where frankincense and saffron are weighed on brass scales.', '["Kayak through Jubail Mangrove Park''s eco-boardwalks and channels","Haggle for Persian saffron and Omani frankincense in Mina Souk","Sample fresh hammour grilled dockside at the fish market","Visit the Dhow Harbour where traditional wooden boats are still built by hand"]', 'https://images.pexels.com/photos/7252278/pexels-photo-7252278.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  67, 3, 'Desert Dunes & Bedouin Traditions', 'Liwa Oasis & Al Dhafra', 
  'Drive south into the Empty Quarter for a morning of dune bashing over amber-gold crescents that tower 300 metres high. Lunch on slow-roasted lamb ouzi and Arabic coffee in a Bedouin-style camp before trying your hand at falconry, the region''s ancient hunting art.', '["Ride a 4x4 over the towering dunes of Moreeb Hill in Liwa","Taste fresh khalas dates straight from an Al Dhafra palm farm","Learn the art of falconry from a licensed Emirati falconer","Stargaze in the unpolluted desert sky after a campfire dinner"]', 'https://images.pexels.com/photos/2867771/pexels-photo-2867771.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  67, 4, 'Al Ain Oasis & Heritage Sites', 'Al Ain', 
  'Explore the UNESCO-listed Al Ain Oasis, where 147,000 date palms are irrigated by ancient falaj water channels. Ascend Jebel Hafeet for panoramic views, then visit the Al Ain National Museum to trace the region''s Bronze Age origins.', '["Walk through the shaded palm groves of Al Ain Oasis on elevated walkways","Drive the winding road to the summit of Jebel Hafeet at sunset","Explore Hili Archaeological Park''s 5,000-year-old tomb structures","Soak in the natural hot springs at the base of Jebel Hafeet"]', 'https://images.pexels.com/photos/1117481/pexels-photo-1117481.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  67, 5, 'Abrahamic Family House & Yas Island', 'Saadiyat Island & Yas Island', 
  'Begin at the Abrahamic Family House, a landmark campus uniting a mosque, church, and synagogue in a single architectural dialogue. Spend the afternoon on Yas Island — ride the Formula Rossa coaster at Ferrari World, the fastest in the world, or cool off at Yas Waterworld.', '["Tour the mosque, church, and synagogue of the Abrahamic Family House","Experience the 240 km/h launch of Formula Rossa at Ferrari World","Stroll the marina promenade of Yas Bay at golden hour","End the trip with a farewell dinner at a rooftop lounge overlooking the Gulf"]', 'https://images.pexels.com/photos/36329344/pexels-photo-36329344.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  67, 'Desert Safari & Dune Bashing', 'Charge over towering golden dunes in a 4x4 before settling into a Bedouin camp for henna, falconry, and a feast under desert stars.', 'Car', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  67, 'Sheikh Zayed Grand Mosque Visit', 'Explore one of the world''s largest mosques, adorned with 24-carat gold chandeliers and the largest hand-knotted carpet ever made.', 'Landmark', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  67, 'Emirati Culinary Trail', 'Taste machboos, luqaimat drizzled in date syrup, and camel milk chocolate across the capital''s heritage restaurants and modern bistros.', 'Utensils', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  67, 'Mangrove Kayaking', 'Paddle silently through Jubail''s mangrove channels at sunrise, spotting herons, crabs, and juvenile sharks in the shallow tidal flats.', 'Waves', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  67, 'Louvre Abu Dhabi & Art Scene', 'Wander 23 permanent galleries spanning ancient Egyptian sarcophagi to Mondrian canvases beneath Jean Nouvel''s iconic lattice dome.', 'GraduationCap', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  67, 'Falcon Hospital Tour', 'Visit the world''s largest falcon hospital, where Emirati veterinarians care for prized hunting birds and guests can hold a falcon on a gloved hand.', 'Heart', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  67, 'Dress modestly when visiting mosques — women must wear an abaya and headscarf (provided free at Sheikh Zayed Mosque).', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  67, 'Tap water is desalinated and safe to drink, but most locals prefer bottled water.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  67, 'Alcohol is only served in licensed hotels and restaurants; public intoxication carries strict penalties.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  67, 'The Hafilat bus network and taxis are affordable, but renting a car is ideal for day trips to Liwa or Al Ain.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  67, 'Friday is the main prayer day — malls and restaurants may open later; plan museum visits for Saturday–Thursday.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  67, 'Summer temperatures exceed 45 °C; if visiting June–September, schedule outdoor activities for early morning or after sunset.', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  67, 'Always ask before photographing people, especially Emirati women, and never photograph military or government buildings.', 6
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  67, 'https://images.pexels.com/photos/415648/pexels-photo-415648.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  67, 'https://images.pexels.com/photos/7252278/pexels-photo-7252278.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
