INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'cappadocia', 'Cappadocia', 'Turkey', 'Middle East', 
  'A surreal landscape where fairy chimneys pierce the dawn and balloons paint the sky', 'https://images.pexels.com/photos/7445847/pexels-photo-7445847.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 'Cappadocia is a geological fever dream etched into the Anatolian plateau — a land of honeycombed rock towers, subterranean cities carved eight storeys deep, and valleys so colourful they bear names like Rose, Red, and Love. Millennia of volcanic eruption, wind, and rain sculpted the tuff into the iconic fairy chimneys that now house boutique cave hotels, Byzantine frescoed churches, and artisan pottery studios.

At dawn, hundreds of hot air balloons rise in silent procession above the town of Göreme, casting kaleidoscopic shadows across a terrain that seems borrowed from another planet. Below, the Open-Air Museum reveals 10th-century rock-cut chapels adorned with vivid depictions of saints and apostles, while the underground city of Derinkuyu stretches deep enough to have sheltered 20,000 people during Byzantine-era sieges.

Beyond the iconic vistas, Cappadocia rewards the curious: hike through the lush Ihlara Valley alongside a murmuring river, watch a potter shape Avanos red clay on a hand-cranked wheel, or share a slow-cooked testi kebab cracked open at your table in a candlelit cave restaurant. Here, the earth itself tells the story.', 
  34.83, 38.64, 'Sports', 'bg-orange-500', 
  'Hot air balloon flights, cave trekking, and mountain biking through fairy chimneys.', '/images/tour-4.jpg', 
  'published', '', '5 Days', 
  NULL, 'Turkish Lira (₺)', 'Semi-arid continental with cold winters and warm, dry summers', 'April–June & September–October (mild weather, clear balloon flights)', 
  'Turkish', 'TRT (UTC+3)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  68, 1, 'Göreme Open-Air Museum & Fairy Chimneys', 'Göreme, Cappadocia', 
  'Arrive in Göreme and check into a cave hotel hollowed from volcanic tuff. Walk to the UNESCO-listed Open-Air Museum to explore rock-cut churches adorned with 10th-century Byzantine frescoes, then hike to Sunset Point for a panoramic view as the fairy chimneys blush amber.', '["Admire the Dark Church frescoes, among the best-preserved in Cappadocia","Walk among the towering fairy chimneys of Monks Valley (Paşabağ)","Photograph the panoramic Göreme Valley from Sunset Point","Settle into a candlelit cave restaurant for your first testi kebab"]', 'https://images.pexels.com/photos/7445847/pexels-photo-7445847.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  68, 2, 'Hot Air Balloon Flight & Rose Valley Hike', 'Göreme & Rose Valley', 
  'Rise before dawn for the once-in-a-lifetime experience of floating silently over Cappadocia''s surreal landscape in a hot air balloon. After landing with a champagne toast, hike through Rose Valley''s pink-and-apricot rock tunnels, pausing at hidden cave churches.', '["Float above fairy chimneys and pigeon houses at sunrise in a hot air balloon","Toast your landing with Turkish sparkling wine in a meadow","Hike the Rose-to-Red Valley trail through pink-hued rock tunnels","Discover the Column Church hidden inside a Rose Valley cliff"]', 'https://images.pexels.com/photos/4973584/pexels-photo-4973584.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  68, 3, 'Underground City & Ihlara Valley', 'Derinkuyu & Ihlara Valley', 
  'Descend into Derinkuyu Underground City, an eight-storey labyrinth of tunnels, churches, and stables that once sheltered 20,000 people. In the afternoon, hike the lush Ihlara Valley, a 14-kilometre canyon carved by the Melendiz River, dotted with cave churches and wildflowers.', '["Explore Derinkuyu''s ventilation shafts, wine cellars, and rolling stone doors","Lunch at a riverside restaurant beside the Melendiz in Ihlara Valley","Visit Ağaçaltı Church with its vivid Ascension fresco inside the canyon","Spot kingfishers and poplars along the valley''s riverside trail"]', 'https://images.pexels.com/photos/6599165/pexels-photo-6599165.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  68, 4, 'Avanos Pottery & Uçhisar Castle', 'Avanos & Uçhisar', 
  'Cross the Kızılırmak River to Avanos, Cappadocia''s pottery capital, and shape your own vessel on a traditional wheel using the region''s distinctive red clay. Afternoon, climb to the pinnacle of Uçhisar Castle — the highest point in Cappadocia — for a 360-degree panorama.', '["Throw a pot on a hand-cranked wheel in a centuries-old Avanos workshop","Browse the Avanos Hair Museum, one of the world''s quirkiest collections","Climb through tunnels to the summit of Uçhisar Castle rock fortress","Sip Turkish tea as the sun sets over Pigeon Valley from Uçhisar"]', 'https://images.pexels.com/photos/4727123/pexels-photo-4727123.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  68, 5, 'Love Valley, Horseback Ride & Farewell', 'Love Valley & Çavuşin', 
  'Explore the phallic rock pillars of Love Valley on horseback — the region''s name, Cappadocia, derives from the ancient Persian for ''land of beautiful horses.'' Visit the ancient basilica at Çavuşin, then savour a farewell dinner of Anatolian manti dumplings in a vine-draped courtyard.', '["Ride through Love Valley''s towering pillar formations on horseback","Explore the 5th-century Çavuşin Church, one of the region''s oldest","Shop for hand-woven Turkish carpets in a Göreme cooperative","End with a Turkish night show featuring whirling dervish ceremony"]', 'https://images.pexels.com/photos/6243251/pexels-photo-6243251.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  68, 'Hot Air Balloon Flight', 'Drift silently over fairy chimneys, pigeon valleys, and rock-cut churches as the Cappadocian dawn paints the landscape in gold and rose.', 'Globe', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  68, 'Cave Trekking & Valley Hikes', 'Explore Rose, Red, Love, and Ihlara valleys on foot, discovering hidden cave churches, rock tunnels, and wildflower meadows.', 'Mountain', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  68, 'Underground City Exploration', 'Descend into Derinkuyu or Kaymaklı to navigate eight-storey labyrinths of tunnels, churches, and rolling-stone blast doors.', 'MapPin', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  68, 'Anatolian Cuisine', 'Crack open a clay-sealed testi kebab, fold gözleme over wood fires, and sip local Cappadocian wine in candlelit cave restaurants.', 'Utensils', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  68, 'Pottery Workshop in Avanos', 'Shape the region''s famous red clay on a hand-cranked wheel guided by a master potter whose family has worked the craft for generations.', 'Lightbulb', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  68, 'Horseback Riding', 'Ride through Love Valley and Sword Valley on Anatolian horses, experiencing the landscape the way ancient Persians named it.', 'Heart', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  68, 'Book your balloon flight at least 2 weeks in advance during peak season (April–October); flights depend on weather and are cancelled for high winds.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  68, 'Wear sturdy shoes with grip — the tuff rock is slippery when wet and trails are uneven.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  68, 'Cappadocia can drop below freezing in winter; bring layers from November to March.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  68, 'Rent an ATV or scooter to explore remote valleys independently — the terrain is gentle and well-marked.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  68, 'The Göreme Open-Air Museum''s Dark Church requires a separate ticket — it''s worth the extra fee for the frescoes.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  68, 'Carry cash for small pottery workshops and village markets; card acceptance outside hotels is limited.', 5
);
