INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'petra', 'Petra', 'Jordan', 'Middle East', 
  'The Rose City carved from living rock, where history breathes through stone', 'https://images.pexels.com/photos/36283918/pexels-photo-36283918.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 'Petra is not merely a ruin — it is a revelation. Approaching through the Siq, a narrow gorge flanked by 80-metre sandstone walls streaked in crimson and ochre, the first glimpse of Al-Khazneh (the Treasury) hits like a physical force. This Nabatean masterpiece, carved directly into the cliff face over 2,000 years ago, once served as a royal tomb and now stands as one of the New Seven Wonders of the World, its Hellenistic columns glowing pink in the morning light.

But the Treasury is only the prologue. Petra''s archaeological park sprawls across 264 square kilometres of wadis and ridges, sheltering over 800 carved structures: the colonnaded Roman-era Street of Façades, the massive Monastery (Ad-Deir) perched atop 800 hand-carved steps, royal tombs with swirling polychrome interiors, and a Byzantine church with exquisite floor mosaics. The Nabateans were master hydraulic engineers, and their system of dams, channels, and cisterns turned this arid canyon into a flourishing trade capital on the incense route.

Modern Petra is equally compelling: the Bedouin community of Umm Sayhoun offers homestay dinners of mansaf and zarb cooked underground, while Petra by Night illuminates the Treasury with 1,500 candles and Bedouin flute music echoing through the Siq. To stand here is to feel the weight and wonder of human ambition carved into eternity.', 
  35.44, 30.33, 'Historical', 'bg-amber-600', 
  'The Rose City — carved rock facades and an ancient Nabatean wonder.', '/images/tour-8.jpg', 
  'published', '', '5 Days', 
  'Amman', 'Jordanian Dinar (JOD)', 'Arid with hot summers, cool winters, and occasional flash floods in the Siq', 'March–May & September–November (mild temperatures for hiking)', 
  'Arabic, English widely understood in tourist areas', 'EET (UTC+2) / EEST (UTC+3 in summer)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  69, 1, 'The Siq & The Treasury at Dawn', 'Petra Archaeological Park', 
  'Enter the park at sunrise before the crowds and walk the 1.2-kilometre Siq as light pierces the narrow gorge, painting the sandstone walls in shades of rose and tangerine. Emerge to the full glory of Al-Khazneh, then explore the Street of Façades and the Roman Theatre carved for 8,500 spectators.', '["Walk the Siq at dawn as light filters through the 80-metre canyon walls","Stand before Al-Khazneh (the Treasury) in the golden morning light","Explore the Street of Façades with its rows of Nabatean tomb fronts","Sit in the Roman Theatre carved entirely from the cliff face"]', 'https://images.pexels.com/photos/36283918/pexels-photo-36283918.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  69, 2, 'The Monastery & High Place of Sacrifice', 'Petra Highlands', 
  'Climb 800 rock-cut steps to Ad-Deir, the Monastery — even grander than the Treasury at 47 metres wide. Reward yourself with sage tea at the clifftop café. Descend via the High Place of Sacrifice trail for sweeping views over the Wadi Araba rift valley.', '["Ascend the 800-step trail to the colossal Monastery (Ad-Deir)","Sip Bedouin sage tea at the cliff-edge café overlooking the valley","Hike the High Place of Sacrifice trail with panoramic Wadi Araba views","Discover the Lion Triclinium and Garden Temple along the descent"]', 'https://images.pexels.com/photos/720254/pexels-photo-720254.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  69, 3, 'Royal Tombs & Byzantine Mosaics', 'Petra Central Valley', 
  'Spend the morning exploring the Royal Tombs — the Urn Tomb, Silk Tomb, and Palace Tomb — whose interiors reveal swirling bands of natural sandstone colour. Visit the Byzantine Church with its stunning 6th-century floor mosaics, then walk the Colonnaded Street to the Qasr al-Bint temple.', '["Enter the Urn Tomb''s vast interior, later converted into a Byzantine church","Marvel at the polychrome swirls inside the Silk Tomb''s carved chamber","Examine 6th-century floor mosaics in the Petra Byzantine Church","Walk the Colonnaded Street to the Qasr al-Bint, Petra''s only freestanding temple"]', 'https://images.pexels.com/photos/36283918/pexels-photo-36283918.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  69, 4, 'Petra by Night & Bedouin Cultural Evening', 'Petra & Umm Sayhoun', 
  'Spend the day on lesser-known trails — Wadi Farasa, the Snake Monument, and the Turkmaniyya Tomb. As night falls, join Petra by Night: 1,500 candles line the Siq and illuminate the Treasury while Bedouin musicians play haunting flute melodies. End with a mansaf dinner in a Bedouin tent.', '["Hike the quiet Wadi Farasa trail past the Renaissance Tomb and Soldier''s Tomb","Walk the candlelit Siq during the magical Petra by Night experience","Listen to Bedouin oud and flute music before the glowing Treasury","Feast on mansaf (lamb in fermented yoghurt) at a Bedouin homestay in Umm Sayhoun"]', 'https://images.pexels.com/photos/3214958/pexels-photo-3214958.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  69, 5, 'Little Petra & Dana Nature Reserve', 'Siq al-Barid & Dana', 
  'Visit Siq al-Barid (Little Petra), a miniature canyon with Nabatean dining halls and the only surviving Nabatean painted ceiling fresco. Drive to the Dana Biosphere Reserve for a hike through sandstone canyons where ibex and eagles roam among juniper forests.', '["Explore the Painted House in Little Petra with its rare Nabatean frescoes","Spot Nubian ibex and Bonelli''s eagles on Dana''s Wadi Dana trail","Hike from Dana village through red sandstone canyons to Feynan","Pick up handmade silver jewellery and leather goods from the Dana co-op"]', 'https://images.pexels.com/photos/36283918/pexels-photo-36283918.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  69, 'Petra by Night', 'Walk the candlelit Siq to the Treasury, where 1,500 candles and Bedouin flute music create an atmosphere of haunting beauty.', 'Landmark', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  69, 'Hiking the Monastery Trail', 'Climb 800 hand-carved steps to Ad-Deir, a colossal facade even wider than the Treasury, perched high above the valley.', 'Mountain', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  69, 'Bedouin Cuisine & Homestays', 'Share mansaf, zarb underground-cooked lamb, and cardamom coffee with Bedouin families in Umm Sayhoun village.', 'Utensils', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  69, 'Photography in the Siq', 'Capture the interplay of light and shadow as sunbeams pierce the narrow canyon, illuminating the sandstone in ever-changing hues.', 'Camera', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  69, 'Dana Biosphere Trekking', 'Hike through Jordan''s largest nature reserve, a mosaic of sandstone canyons, juniper forests, and rare wildlife.', 'Globe', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  69, 'Wadi Rum Excursion', 'Combine Petra with a jeep safari through Wadi Rum''s red desert, where Lawrence of Arabia once rode among towering rock arches.', 'Car', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  69, 'Buy the Jordan Pass online before arrival — it includes your visa fee and Petra entry for 1, 2, or 3 days.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  69, 'Enter the park at 6 AM opening to have the Treasury nearly to yourself for 30–45 minutes.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  69, 'Bring at least 3 litres of water per person per day — the site is vast, exposed, and brutally hot in summer.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  69, 'Petra by Night runs Monday, Wednesday, and Thursday only — check schedules and book ahead.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  69, 'Wear sturdy hiking boots; the 800 steps to the Monastery are rough-cut and uneven.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  69, 'Carry Jordanian Dinar in small bills for Bedouin tea stalls and handicraft vendors inside the park.', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  69, 'Flash floods can occur in the Siq during rainy months (December–February) — always check weather advisories.', 6
);
