INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'dead-sea', 'Dead Sea', 'Jordan', 'Middle East', 
  'Float weightlessly at the lowest point on Earth, where minerals heal and time slows', 'https://images.pexels.com/photos/6477401/pexels-photo-6477401.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 'The Dead Sea lies 430 metres below sea level — the lowest point on any continent — a shimmering, mineral-laden body of water so dense that swimmers float effortlessly on its surface like corks on a pond. Fed by the Jordan River and ringed by the tawny cliffs of the Judean and Moabite mountains, this ancient lake has drawn pilgrims, monarchs, and wellness seekers for millennia. Cleopatra herself dispatched envoys to secure exclusive rights to its therapeutic mud and salt.

The water''s salinity, roughly ten times that of the ocean, creates a buoyancy unlike anything else on Earth. Coating yourself in the mineral-rich black mud that lines the shore — packed with magnesium, calcium, potassium, and bromine — is believed to ease psoriasis, improve skin elasticity, and soothe aching joints. Luxury resorts along the Jordanian shore have built entire wellness philosophies around this natural pharmacy, offering Dead Sea salt scrubs, sulfur spring soaks, and mineral wrap treatments.

Beyond floating, the Dead Sea corridor is rich with history: the hillside fortress of Masada rises dramatically to the west, the Baptism Site of Bethany-beyond-the-Jordan lies at the northern tip, and the mosaics of Madaba — the ''City of Mosaics'' — are a short drive inland. The landscape itself is haunting: salt pillars emerge from the receding shoreline, sinkholes open in patterns of blue and white, and the air, rich in oxygen and low in allergens, feels softer than anywhere else you''ve breathed.', 
  35.55, 31.5, 'Medical', 'bg-teal-500', 
  'Therapeutic mineral mud, ultra-saline flotation therapy, and skin-healing springs.', '/images/tour-9.jpg', 
  'published', '', '4 Days', 
  'Amman', 'Jordanian Dinar (JOD)', 'Hot desert with year-round sunshine and exceptionally dry air', 'October–April (comfortable temperatures for floating and hiking)', 
  'Arabic, English at resorts', 'EET (UTC+2) / EEST (UTC+3 in summer)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  70, 1, 'Arrival & First Float', 'Dead Sea Eastern Shore, Jordan', 
  'Check into a Dead Sea resort and take your first iconic float — the water''s density makes sinking physically impossible. Coat yourself in mineral-rich black mud from the shoreline, let it dry in the sun, then rinse to reveal impossibly soft skin. Watch the sunset paint the Judean hills gold from an infinity pool that seems to merge with the sea itself.', '["Experience effortless flotation in the world''s saltiest body of water","Apply mineral-rich black mud from the shoreline for a natural skin treatment","Watch the sun set over the Judean Mountains from a cliffside infinity pool","Dine on mezze and grilled meats at a resort overlooking the Dead Sea"]', 'https://images.pexels.com/photos/6477401/pexels-photo-6477401.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  70, 2, 'Bethany Baptism Site & Hot Springs', 'Bethany-beyond-the-Jordan & Ma''in Hot Springs', 
  'Visit the UNESCO-listed Baptism Site of Jesus at Bethany-beyond-the-Jordan, where ancient steps descend to the river. Afternoon, drive to the Ma''in Hot Springs, where steaming waterfalls cascade down basalt cliffs into warm therapeutic pools surrounded by lush canyon vegetation.', '["Walk to the exact spot on the Jordan River where Jesus was baptised","Soak under the steaming waterfalls of Ma''in Hot Springs","Float in warm sulfur pools set into a dramatic basalt canyon","Enjoy a traditional Jordanian lunch of maqluba at a local restaurant"]', 'https://images.pexels.com/photos/20333851/pexels-photo-20333851.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  70, 3, 'Madaba Mosaics & Mount Nebo', 'Madaba & Mount Nebo', 
  'Drive to Madaba, the City of Mosaics, to see the famous 6th-century mosaic map of the Holy Land on the floor of St. George''s Church. Continue to Mount Nebo, where Moses is said to have glimpsed the Promised Land — on clear days the view stretches to Jerusalem and the Jordan Valley.', '["Study the 6th-century Madaba Mosaic Map in St. George''s Church","Stand at Moses'' viewpoint on Mount Nebo overlooking the Promised Land","Visit the Madaba Archaeological Museum for Roman-era mosaic floors","Shop for hand-crafted mosaic art in Madaba''s artisan workshops"]', 'https://images.pexels.com/photos/5522722/pexels-photo-5522722.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  70, 4, 'Wadi Mujib Canyon Adventure', 'Wadi Mujib Biosphere Reserve', 
  'Embark on the Siq Trail of Wadi Mujib, Jordan''s Grand Canyon — wade through waist-deep turquoise water between towering sandstone walls, scramble over boulders, and swim through natural pools to reach a hidden waterfall deep inside the gorge.', '["Wade and swim through the narrow Siq Trail of Wadi Mujib canyon","Scramble over boulders to a hidden waterfall inside the gorge","Spot ibex and eagles in Jordan''s lowest nature reserve","Cool off in the crystalline blue pools at the canyon''s heart"]', 'https://images.pexels.com/photos/5559878/pexels-photo-5559878.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  70, 'Dead Sea Floating', 'Experience the surreal sensation of floating effortlessly on water ten times saltier than the ocean, at the lowest point on Earth.', 'Waves', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  70, 'Mineral Mud Therapy', 'Coat yourself in the Dead Sea''s famous black mineral mud, rich in magnesium and potassium, for natural skin healing and rejuvenation.', 'Heart', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  70, 'Ma''in Hot Springs Soak', 'Bathe beneath steaming waterfalls that cascade down basalt cliffs into warm sulfur pools in a lush canyon setting.', 'Dumbbell', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  70, 'Wadi Mujib Canyoneering', 'Wade, swim, and scramble through the dramatic Siq Trail of Jordan''s Grand Canyon to a hidden waterfall.', 'Mountain', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  70, 'Bethany Baptism Site', 'Visit the UNESCO World Heritage site where Jesus was baptised, walking ancient pilgrimage paths along the Jordan River.', 'Landmark', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  70, 'Mosaic Art in Madaba', 'Explore the City of Mosaics, home to the oldest surviving cartographic depiction of the Holy Land on a 6th-century church floor.', 'BookOpen', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  70, 'Do not shave or wax within 24 hours of entering the Dead Sea — the salt will sting any micro-cuts intensely.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  70, 'Keep the water away from your eyes; if splashed, rinse immediately with fresh water (available at shoreline stations).', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  70, 'Limit floating sessions to 20 minutes to avoid dehydration and mineral overload on your skin.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  70, 'Wear old swimwear — the high mineral content can discolour fabric permanently.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  70, 'The Dead Sea is receding rapidly; sinkholes form along the shore, so only swim at designated resort beaches.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  70, 'Carry cash for roadside stalls selling Dead Sea salt products and handmade soaps at much lower prices than resort shops.', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  70, 'Wadi Mujib''s Siq Trail is only open April–October and closes after heavy rain — confirm conditions the morning of your visit.', 6
);
