INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'muscat', 'Muscat', 'Oman', 'Middle East', 
  'Where rugged mountains plunge into turquoise waters and frankincense perfumes the air', 'https://images.pexels.com/photos/36549111/pexels-photo-36549111.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 'Muscat is the antithesis of its flashier Gulf neighbours — a capital that has chosen restraint over spectacle, weaving its whitewashed, low-rise buildings into the folds of the craggy Al Hajar mountains that tumble directly into the Gulf of Oman. No structure is permitted to be taller than the Sultan Qaboos Grand Mosque''s minaret, and the result is a city that feels both majestic and intimate, where the scent of burning frankincense drifts from open doorways and the call to prayer echoes off ancient watchtowers.

The Muttrah Corniche, a crescent-shaped waterfront backed by the Muttrah Souq — one of the oldest marketplaces in the Arab world — offers a sensory immersion of silver khanjars (daggers), fragrant oils, embroidered kumma caps, and Omani halwa sweets. Behind the souq''s labyrinthine alleys, the Al Alam Royal Palace gleams in gold and blue between the twin Portuguese forts of Mirani and Jalali, reminders of Oman''s centuries-long role as a maritime superpower.

Beyond the city, Muscat''s governorate is a natural playground: the fjord-like inlets of Bandar Khayran harbour dolphins and hawksbill turtles, the limestone sinkholes of Bimmah host crystalline turquoise pools, and the Wadi Shab gorge requires swimming through emerald pools to reach a hidden cave waterfall. Oman''s culture of generous hospitality — expressed in endless cups of kahwa coffee and dates offered to every guest — makes Muscat not just a destination, but a welcome.', 
  58.54, 23.59, 'Heritage', 'bg-purple-500', 
  'Grand mosques, souqs, and dramatic mountain-meets-sea landscapes.', '/images/tour-10.jpg', 
  'published', '', '5 Days', 
  'Muscat (national capital)', 'Omani Rial (OMR)', 'Hot arid desert along the coast with humid summers and mild winters', 'October–March (pleasant temperatures, whale shark season)', 
  'Arabic, English widely spoken', 'GST (UTC+4)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  71, 1, 'Sultan Qaboos Mosque & Muttrah Souq', 'Muscat City Centre', 
  'Begin at the Sultan Qaboos Grand Mosque, where the world''s second-largest hand-woven carpet covers the prayer hall and a Swarovski crystal chandelier weighing eight tonnes glitters overhead. Walk the Muttrah Corniche to the souq, bargaining for frankincense, silver, and Omani halwa in its centuries-old alleys.', '["Stand beneath the eight-tonne Swarovski chandelier of the Grand Mosque","Walk the ancient alleys of Muttrah Souq for frankincense and silver","Photograph Al Alam Royal Palace flanked by Mirani and Jalali forts","Sample Omani halwa and kahwa coffee at a traditional sweet shop"]', 'https://images.pexels.com/photos/36549111/pexels-photo-36549111.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  71, 2, 'Bandar Khayran & Coastal Snorkelling', 'Bandar Khayran & Daymaniyat Islands', 
  'Board a traditional dhow for the fjord-like inlets of Bandar Khayran, where dolphins race alongside the bow and hawksbill turtles glide through the clear water. Snorkel over coral gardens teeming with parrotfish and clownfish, then anchor in a secluded cove for a grilled seafood lunch on deck.', '["Cruise the fjord-like inlets of Bandar Khayran on a traditional dhow","Snorkel with hawksbill turtles and parrotfish over pristine coral reefs","Spot spinner dolphins leaping alongside your boat","Feast on freshly grilled hammour and lobster on the dhow deck"]', 'https://images.pexels.com/photos/36195013/pexels-photo-36195013.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  71, 3, 'Wadi Shab & Bimmah Sinkhole', 'Sur Road, Muscat Governorate', 
  'Hike into Wadi Shab, swimming through emerald pools flanked by palm-fringed cliffs to reach a hidden waterfall cascading inside a cave. Stop at the Bimmah Sinkhole, a limestone crater filled with turquoise water where locals and travellers swim together in a natural infinity pool.', '["Swim through three emerald pools to reach Wadi Shab''s hidden cave waterfall","Leap into the turquoise waters of Bimmah Sinkhole","Hike through palm groves and over boulders in the dramatic wadi gorge","Buy honey and dates from roadside stalls in the villages along the coast"]', 'https://images.pexels.com/photos/5559878/pexels-photo-5559878.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  71, 4, 'Nizwa Fort & Jebel Akhdar', 'Nizwa & Jebel Akhdar', 
  'Drive inland to Nizwa, Oman''s ancient capital, where a 17th-century fort towers above a bustling Friday goat market. Ascend to Jebel Akhdar, the ''Green Mountain,'' where terraced rose gardens produce the precious Omani rosewater distilled in copper stills each spring.', '["Explore the circular tower of Nizwa Fort with its trap-door defences","Experience the raucous Nizwa Livestock Market (Fridays)","Walk the terraced rose gardens of Jebel Akhdar at 2,000 metres","Watch rosewater being distilled in traditional copper stills"]', 'https://images.pexels.com/photos/36245709/pexels-photo-36245709.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  71, 5, 'Royal Opera & Farewell Seafood Feast', 'Qurum & Shatti Al Qurum', 
  'Explore the Royal Opera House Muscat, a marble masterpiece that hosts world-class performances from Arabic opera to Omani folk dance. Stroll the galleries of Bait Al Zubair Museum, then end your journey with a lavish seafood feast at a beachside restaurant in Shatti Al Qurum as the sun sets over the Gulf.', '["Tour the Royal Opera House Muscat''s Italian marble interiors","Browse traditional Omani dress and maritime artefacts at Bait Al Zubair","Walk the sunset beach of Shatti Al Qurum with the mountains behind","Savour shuwa-spiced lobster and kingfish at a beachside restaurant"]', 'https://images.pexels.com/photos/36584501/pexels-photo-36584501.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  71, 'Wadi Swimming & Canyoneering', 'Swim through emerald pools and palm-shaded gorges in Wadi Shab and Wadi Bani Khalid to discover hidden cave waterfalls.', 'Waves', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  71, 'Frankincense & Souq Exploration', 'Wander the ancient Muttrah Souq for Omani frankincense, silver khanjars, and hand-stitched kumma caps in a labyrinth of spice-scented alleys.', 'MapPin', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  71, 'Dhow Cruises & Marine Life', 'Sail the coastline on a traditional wooden dhow, spotting dolphins, turtles, and whale sharks (October–February) in the Gulf of Oman.', 'Globe', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  71, 'Omani Culinary Traditions', 'Taste shuwa (slow-roasted lamb), Omani halwa, and kahwa coffee spiced with cardamom and saffron — hospitality poured into every cup.', 'Utensils', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  71, 'Mountain Trekking on Jebel Akhdar', 'Hike terraced villages and rose gardens at 2,000 metres, where the air is cool and rosewater is distilled in copper stills each April.', 'Mountain', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  71, 'Sultan Qaboos Grand Mosque', 'Visit one of the world''s most beautiful mosques, home to a hand-woven carpet measuring 4,343 square metres and an eight-tonne crystal chandelier.', 'Landmark', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  71, 'Dress modestly outside resorts — shoulders and knees should be covered, especially in mosques and souqs.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  71, 'The Sultan Qaboos Grand Mosque is open to non-Muslims Saturday–Thursday 8:00–11:00 AM only; arrive early.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  71, 'Rent a 4x4 if planning wadi and mountain trips — many roads require high clearance.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  71, 'Oman is one of the safest countries in the Middle East; petty crime is extremely rare.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  71, 'Carry cash in smaller denominations — many smaller shops and wadi entry points don''t accept cards.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  71, 'Fridays are best for the Nizwa Livestock Market, but many shops close until after Friday prayers.', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  71, 'Whale sharks gather off the Daymaniyat Islands October–February — book snorkelling trips in advance.', 6
);
