INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'barcelona', 'Barcelona', 'Spain', 'Europe', 
  'Gaudí''s dreamscape by the Mediterranean, where art and life are indistinguishable', 'https://images.pexels.com/photos/6480298/pexels-photo-6480298.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 'Barcelona is a city that refuses to colour inside the lines. From the dripping, organic towers of Antoni Gaudí''s unfinished Sagrada Família — under construction since 1882 and not expected to be complete until 2026 — to the psychedelic mosaics of Park Güell crowning the hillside, the Catalan capital treats every surface as a canvas and every corner as an opportunity for beauty. This is a city where Gothic stone alleys open suddenly onto sun-drenched plazas, where modernist apartments undulate like ocean waves, and where the Mediterranean glitters at the end of nearly every boulevard.

The Barri Gòtic, Barcelona''s medieval heart, hides a Roman temple, a 14th-century cathedral, and bars that have poured vermouth since before the Spanish Civil War. Steps away, La Boqueria market on La Rambla erupts with jamón ibérico, fresh sea urchin, and towers of tropical fruit. The Born neighbourhood channels contemporary cool — concept stores, natural-wine bars, and the Picasso Museum, housing the artist''s formative Barcelona works.

Barcelona''s identity is inseparable from Catalan culture: the human towers of castellers rising in Plaça de Sant Jaume, the sardana folk dance circling in front of the cathedral on Sunday mornings, and FC Barcelona''s Camp Nou, where 99,000 fans roar ''Més que un club.'' Add the urban beaches of Barceloneta, the avant-garde kitchens of El Born, and the sunset views from Bunkers del Carmel, and you have a city that nourishes every sense.', 
  2.17, 41.39, 'Education', 'bg-indigo-500', 
  'Field trips to Gaudí''s architectural masterworks, Maritime Museum, Cava wine production facilities, and design studios.', '/images/explor-5.jpg', 
  'published', '', '4 Days', 
  NULL, 'Euro (€)', 'Mediterranean with hot summers, mild winters, and year-round sunshine', 'May–June & September–October (warm, fewer crowds than peak summer)', 
  'Catalan, Spanish (Castellano), English in tourist areas', 'CET (UTC+1) / CEST (UTC+2 in summer)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  72, 1, 'Gaudí''s Masterworks', 'Eixample & Gràcia, Barcelona', 
  'Spend the day immersed in the genius of Antoni Gaudí. Enter the Sagrada Família to see light stream through stained glass in every colour of the spectrum, then stroll Passeig de Gràcia to admire Casa Batlló''s skeletal balconies and Casa Milà''s undulating stone rooftop. End at Park Güell for sunset over the city and the sea.', '["Stand beneath the Sagrada Família''s forest-like columns as light floods through the stained glass","Explore Casa Batlló''s dragon-spine rooftop and bone-like façade","Walk the wavy stone rooftop of Casa Milà (La Pedrera) at golden hour","Watch the sunset from the mosaic serpentine bench at Park Güell"]', 'https://images.pexels.com/photos/6480298/pexels-photo-6480298.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  72, 2, 'Gothic Quarter & La Boqueria', 'Barri Gòtic & La Rambla, Barcelona', 
  'Plunge into the medieval labyrinth of the Gothic Quarter: pass the Temple of Augustus hidden in a courtyard, visit the Barcelona Cathedral and its cloister of 13 white geese, and wander Plaça Reial''s palm-studded arcade. Walk La Rambla to La Boqueria for jamón, fresh juice, and grilled razor clams at a market counter.', '["Discover the Roman Temple of Augustus tucked inside a Gothic courtyard","Count the 13 geese in Barcelona Cathedral''s Gothic cloister","Eat fresh sea urchin and razor clams at La Boqueria market counters","Sip vermouth at a century-old bar on Carrer del Parlament"]', 'https://images.pexels.com/photos/4544955/pexels-photo-4544955.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  72, 3, 'Picasso Museum & Born Neighbourhood', 'El Born & Barceloneta, Barcelona', 
  'Begin at the Picasso Museum, set across five medieval palaces, to trace the artist''s formative years in Barcelona. Wander El Born''s concept shops and natural-wine bars, then cross to the Barceloneta beachfront for a seafood paella lunch with your feet in the sand.', '["Trace Picasso''s evolution from child prodigy to cubist pioneer across five medieval palaces","Browse independent boutiques and natural-wine bars in El Born","Eat seafood paella on the sand at a Barceloneta chiringuito","Walk the beachfront promenade from Port Olímpic to W Hotel at sunset"]', 'https://images.pexels.com/photos/5472431/pexels-photo-5472431.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  72, 4, 'Montjuïc, MNAC & Bunkers del Carmel', 'Montjuïc & El Carmel, Barcelona', 
  'Take the cable car to Montjuïc for the Fundació Joan Miró and the MNAC, whose Romanesque art collection is unrivalled. Explore the 1992 Olympic complex, then cross the city to the Bunkers del Carmel — a Civil War anti-aircraft battery turned Barcelona''s best-kept secret viewpoint.', '["Ride the Montjuïc cable car for aerial views over the port and city","Admire Joan Miró''s vibrant works at his hillside foundation","Explore the world''s finest Romanesque art collection at the MNAC","Watch the city light up from the Bunkers del Carmel at sunset"]', 'https://images.pexels.com/photos/36043035/pexels-photo-36043035.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  72, 'Gaudí Architecture Trail', 'From Sagrada Família to Park Güell, Casa Batlló to Palau Güell — trace the full arc of modernisme''s most visionary architect.', 'Landmark', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  72, 'Catalan Gastronomy', 'Feast on pa amb tomàquet, seafood suquet, and crema catalana at traditional taverns and avant-garde tasting menus alike.', 'Utensils', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  72, 'Beach & Mediterranean Life', 'Swim, paddleboard, and eat paella on Barceloneta''s urban beach, where the city meets the sea in golden-sand perfection.', 'Waves', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  72, 'La Boqueria & Market Culture', 'Graze through Barcelona''s most famous market for jamón ibérico, fresh juice, sea urchin, and grilled razor clams.', 'Camera', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  72, 'Gothic Quarter Exploration', 'Get lost in medieval stone alleys hiding Roman ruins, candle-lit bars, and plaças where castellers build human towers.', 'MapPin', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  72, 'FC Barcelona & Camp Nou', 'Tour Camp Nou — Europe''s largest stadium — and feel the passion of ''Més que un club'' in the club museum.', 'Globe', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  72, 'Book Sagrada Família tickets online at least 2 weeks ahead — walk-up entry is almost never available.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  72, 'Watch for pickpockets on La Rambla and in the metro; keep valuables in a front pocket or cross-body bag.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  72, 'Lunch is 1:30–3:30 PM, dinner starts at 9 PM — arriving at a restaurant at 7 PM will find you eating alone.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  72, 'The T-Casual card gives 10 metro/bus rides and is far cheaper than single tickets.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  72, 'Most museums are free on the first Sunday of the month — plan accordingly for MNAC and Picasso Museum.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  72, 'Barcelona''s tap water is safe but tastes heavily of chlorine; most locals buy filtered or bottled water.', 5
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  72, 'https://images.pexels.com/photos/6480298/pexels-photo-6480298.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  72, 'https://images.pexels.com/photos/4544955/pexels-photo-4544955.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  72, 'https://images.pexels.com/photos/5472431/pexels-photo-5472431.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_images` (
