INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'madrid', 'Madrid', 'Spain', 'Europe', 
  'The soul of Spain — royal grandeur, old-world taverns, and nights that never end', 'https://images.pexels.com/photos/6139145/pexels-photo-6139145.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 'Madrid is a city that lives with fierce intensity and refuses to sleep. The Spanish capital sprawls elegantly around grand boulevards and intimate plazas, its skyline punctuated by the ornate towers of the Palacio de Cibeles, the Baroque dome of the Royal Palace, and the Beaux-Arts splendour of the Prado Museum — home to Velázquez''s Las Meninas, Goya''s Black Paintings, and Bosch''s Garden of Earthly Delights, one of the most extraordinary collections of European art assembled under a single roof.

But Madrid''s magic lives equally in the tiled taverns of La Latina, where patatas bravas sizzle alongside glasses of vermú on Sunday afternoons, and in the covered stalls of Mercado de San Miguel, where you can eat oysters, croquetas, and Manchego in one glorious graze. The city''s golden triangle of art — the Prado, Reina Sofía (home to Picasso''s Guernica), and Thyssen-Bornemisza — forms the densest concentration of masterpieces in Europe, while the Retiro Park offers rowboats, peacocks, and a crystal palace shimmering in the green heart of the city.

As the sun sets, Madrid transforms: rooftop cocktail bars overlooking Gran Vía fill with the after-work crowd, flamenco tablaos in Lavapiés pulse with raw duende, and the tapas crawl through Calle de la Cava Baja becomes a communal feast that might not end until 3 AM. In Madrid, late nights are not an indulgence — they are a way of life.', 
  -3.7, 40.42, 'Historical', 'bg-amber-600', 
  'Royal palaces, Prado masterpieces, and centuries of Spanish imperial legacy.', '/images/explor-6.jpg', 
  'published', '', '4 Days', 
  'Madrid (national capital)', 'Euro (€)', 'Continental Mediterranean with hot, dry summers and cold winters', 'April–June & September–October (mild weather, cultural festivals)', 
  'Spanish (Castellano), English in tourist areas', 'CET (UTC+1) / CEST (UTC+2 in summer)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  73, 1, 'Royal Palace & the Golden Triangle of Art', 'Centro & Paseo del Arte, Madrid', 
  'Start at the Royal Palace of Madrid — with over 3,400 rooms, it is the largest functioning royal palace in Europe. Walk through the Hall of Mirrors and the Royal Armoury, then descend to the Prado Museum for an afternoon with Velázquez, Goya, and El Greco. End at the Retiro Park Crystal Palace as light fades.', '["Tour the Royal Palace''s Hall of Mirrors and Throne Room","Stand before Las Meninas and Goya''s Black Paintings at the Prado","Stroll through the Retiro Park to the Crystal Palace and rose garden","Watch street musicians perform in the Puerta del Sol at dusk"]', 'https://images.pexels.com/photos/6139145/pexels-photo-6139145.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  73, 2, 'Reina Sofía, Guernica & Lavapiés', 'Atocha & Lavapiés, Madrid', 
  'Dedicate the morning to Reina Sofía, where Picasso''s monumental Guernica — the most powerful anti-war painting ever created — dominates an entire gallery. Explore the Thyssen-Bornemisza next door, then wander into the multicultural neighbourhood of Lavapiés for street art, global cuisine, and an evening flamenco tablao.', '["Stand before Picasso''s Guernica in the Reina Sofía''s Gallery 206","Trace art history from Van Eyck to Lichtenstein at the Thyssen-Bornemisza","Explore Lavapiés'' street art murals and independent bookshops","Feel the raw duende of live flamenco at a Lavapiés tablao"]', 'https://images.pexels.com/photos/19693243/pexels-photo-19693243.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  73, 3, 'La Latina Tapas Trail & Mercado de San Miguel', 'La Latina & Plaza Mayor, Madrid', 
  'Spend a leisurely Sunday on Calle de la Cava Baja, Madrid''s legendary tapas street, hopping between century-old taverns for patatas bravas, jamón ibérico croquetas, and chilled vermouth. Visit the Mercado de San Miguel for gourmet bites, then cross Plaza Mayor and the San Fernando flea market in El Rastro.', '["Bar-hop Calle de la Cava Baja for Madrid''s best patatas bravas and croquetas","Graze through Mercado de San Miguel for oysters, Manchego, and churros","Hunt for treasures at El Rastro flea market (Sundays only)","Toast with vermú in a tiled La Latina tavern dating to 1870"]', 'https://images.pexels.com/photos/5267663/pexels-photo-5267663.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  73, 4, 'Gran Vía, Rooftops & Nightlife', 'Gran Vía & Malasaña, Madrid', 
  'Walk the grand sweep of Gran Vía — Madrid''s answer to Broadway — past Art Deco cinemas and flagship stores. Ride to a rooftop bar for sunset cocktails overlooking the Schweppes sign and the Metropolis building. After dinner in Malasaña''s neo-taverns, close the night at a live jazz club or the city''s legendary nightclub scene.', '["Photograph the iconic Metrópolis building and Schweppes sign on Gran Vía","Sip cocktails on a rooftop bar with views across Madrid''s skyline at sunset","Dine at a creative neo-tavern in the bohemian Malasaña quarter","Experience Madrid''s legendary nightlife that rarely starts before midnight"]', 'https://images.pexels.com/photos/919282/pexels-photo-919282.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  73, 'Prado Museum & Spanish Masters', 'Wander the Prado''s galleries housing Velázquez''s Las Meninas, Goya''s Third of May, and Bosch''s Garden of Earthly Delights.', 'BookOpen', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  73, 'Tapas Crawl in La Latina', 'Bar-hop Calle de la Cava Baja for patatas bravas, croquetas de jamón, and glasses of chilled vermú in century-old tiled taverns.', 'Utensils', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  73, 'Flamenco in Lavapiés', 'Feel the visceral energy of duende in an intimate tablao, where raw guitar, voice, and dance collide in the night.', 'Heart', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  73, 'Retiro Park & Crystal Palace', 'Row a boat on the lake, stroll the rose garden, and visit the Crystal Palace — a glass-and-iron greenhouse hosting rotating art installations.', 'Globe', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  73, 'Rooftop Bar Circuit', 'Climb to Madrid''s rooftop terraces for sunset cocktails with views spanning from the Royal Palace to the Sierra de Guadarrama.', 'Camera', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  73, 'El Rastro Sunday Market', 'Hunt for vintage finds, antique maps, and leather goods in Spain''s largest open-air flea market, spilling down the streets of La Latina.', 'MapPin', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  73, 'Adjust to Madrid time: lunch at 2 PM, dinner at 9:30 PM, nightlife from midnight — eating ''early'' marks you as a tourist.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  73, 'The Prado is free 6:00–8:00 PM Monday–Saturday and 3:00–5:00 PM Sundays — arrive early to beat the queue.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  73, 'Madrid''s metro is fast and cheap; buy a 10-ride Metrobús card for the best value.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  73, 'El Rastro flea market (Sundays, 9 AM–3 PM) is pickpocket territory — keep bags zipped and in front.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  73, 'Tap water in Madrid is excellent (from the Sierra de Guadarrama) — no need to buy bottled.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  73, 'Summer heat regularly exceeds 40 °C; siesta between 2–5 PM is not laziness, it''s survival strategy.', 5
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  73, 'https://images.pexels.com/photos/6139145/pexels-photo-6139145.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  73, 'https://images.pexels.com/photos/19693243/pexels-photo-19693243.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  73, 'https://images.pexels.com/photos/5267663/pexels-photo-5267663.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  73, 'https://images.pexels.com/photos/919282/pexels-photo-919282.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);

INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'rome', 'Rome', 'Italy', 'Europe', 
  'The Eternal City — where every cobblestone whispers two thousand years of story', 'https://images.pexels.com/photos/36581134/pexels-photo-36581134.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 'Rome is not a city you visit; it is a city that claims you. Walking its streets is an act of time travel: turn a corner from a buzzing espresso bar and find yourself face-to-face with a 2,000-year-old temple; toss a coin into the Trevi Fountain where Baroque marble cascades in an almost absurd display of sculptural excess; stand inside the Pantheon and watch a single beam of sunlight rotate through the oculus, illuminating the exact same marble floor that Roman emperors once trod.

The Colosseum anchors the ancient heart of the city — a colossal amphitheatre where 50,000 spectators once roared, now standing open to the sky like a giant''s broken crown. Nearby, the Roman Forum and Palatine Hill unfold layers of republic and empire, while the Vatican, technically a sovereign city-state, houses Michelangelo''s Sistine Chapel ceiling, Raphael''s School of Athens, and St. Peter''s Basilica — the largest church in Christendom, crowned by a dome that defines the Roman skyline.

But Rome is also carbonara eaten at midnight in Trastevere, a gelato from a back-street gelateria that changes your understanding of frozen dessert, a Sunday morning passeggiata through the Villa Borghese gardens, and a Negroni on the Spanish Steps as the city turns golden. Romans have perfected the art of la dolce vita, and they invite you — generously, loudly, with abundant hand gestures — to join them.', 
  12.5, 41.9, 'Historical', 'bg-amber-600', 
  'Colosseum, Vatican, Pantheon — the Eternal City where every street is a museum.', '/images/tour-4.jpg', 
  'published', '', '4 Days', 
  'Rome (national capital)', 'Euro (€)', 'Mediterranean with hot, dry summers and mild, wet winters', 'April–June & September–October (mild temperatures, fewer crowds)', 
  'Italian, English in tourist areas', 'CET (UTC+1) / CEST (UTC+2 in summer)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  74, 1, 'Colosseum, Forum & Palatine Hill', 'Ancient Rome', 
  'Begin where Rome began. Enter the Colosseum''s arena floor, imagining 50,000 spectators above. Walk through the Roman Forum past the Temple of Saturn and the Arch of Titus, then ascend Palatine Hill for the ruins of imperial palaces and a view that stretches from the Forum to the Circus Maximus.', '["Stand on the Colosseum''s reconstructed arena floor at the centre of the amphitheatre","Walk the Via Sacra through the Roman Forum past the Temple of Saturn","Climb Palatine Hill for panoramic views over the ancient city","Photograph the Arch of Constantine at golden hour"]', 'https://images.pexels.com/photos/36581134/pexels-photo-36581134.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  74, 2, 'Vatican City — Sistine Chapel & St. Peter''s', 'Vatican City', 
  'Arrive early at the Vatican Museums to witness the Gallery of Maps, Raphael Rooms, and the overwhelming majesty of the Sistine Chapel before the crowds thicken. Cross into St. Peter''s Basilica to stand beneath Bernini''s baldachin and, for the brave, climb the 551 steps to the dome for the finest view in Rome.', '["Gaze up at Michelangelo''s Sistine Chapel ceiling in quiet awe","Admire Raphael''s School of Athens in the Stanza della Segnatura","Stand beneath Bernini''s bronze baldachin inside St. Peter''s Basilica","Climb 551 steps to the dome of St. Peter''s for a skyline panorama"]', 'https://images.pexels.com/photos/36581252/pexels-photo-36581252.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  74, 3, 'Pantheon, Piazzas & Trastevere', 'Centro Storico & Trastevere, Rome', 
  'Begin at the Pantheon, the best-preserved Roman building, and watch sunlight beam through the open oculus. Wander to Piazza Navona''s Bernini fountains, toss a coin at the Trevi Fountain, and cross the Tiber to Trastevere for cobblestoned alleys, ivy-draped trattorias, and the finest carbonara in the city.', '["Watch the beam of light move through the Pantheon''s ancient oculus","Admire Bernini''s Fountain of the Four Rivers in Piazza Navona","Toss a coin over your shoulder into the Trevi Fountain","Eat authentic cacio e pepe in a candlelit Trastevere trattoria"]', 'https://images.pexels.com/photos/36396955/pexels-photo-36396955.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  74, 4, 'Borghese, Spanish Steps & Dolce Vita', 'Villa Borghese & Tridente, Rome', 
  'Reserve a timed slot at the Galleria Borghese for Bernini''s Apollo and Daphne and Canova''s Pauline Bonaparte. Stroll through Villa Borghese''s landscaped gardens to the Pincian Hill viewpoint, descend the Spanish Steps, and conclude with a Negroni on Via Condotti as Rome glows in the evening light.', '["Marvel at Bernini''s Apollo and Daphne in the Galleria Borghese","Stroll through Villa Borghese gardens to the Pincian Hill viewpoint","Descend the Spanish Steps into the designer boutiques of Via Condotti","Sip a Negroni at a sidewalk café as the Eternal City lights up"]', 'https://images.pexels.com/photos/36595933/pexels-photo-36595933.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  74, 'Ancient Rome Walking Tour', 'Explore the Colosseum, Roman Forum, and Palatine Hill — the monumental core of an empire that shaped Western civilisation.', 'Landmark', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  74, 'Vatican Museums & Sistine Chapel', 'Witness Michelangelo''s ceiling, Raphael''s frescoes, and the vast papal collections culminating in St. Peter''s Basilica.', 'BookOpen', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  74, 'Roman Cuisine', 'Master the four pastas of Rome — carbonara, cacio e pepe, amatriciana, and gricia — in Trastevere''s best trattorias.', 'Utensils', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  74, 'Piazza & Fountain Hopping', 'Wander from the Trevi Fountain to Piazza Navona, Piazza di Spagna, and the Pantheon in an afternoon of Baroque splendour.', 'Camera', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  74, 'Gelato Tasting Trail', 'Sample artisanal gelato at Fatamorgana, Giolitti, and Come il Latte — Roman gelaterias that redefine frozen dessert.', 'Heart', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  74, 'Sunset at Pincian Hill', 'Watch the sun set over St. Peter''s dome from the Pincian Hill terrace, the most romantic viewpoint in Rome.', 'Globe', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  74, 'Book Colosseum and Vatican tickets online weeks in advance — walk-up queues can exceed 3 hours.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  74, 'Dress code is enforced at Vatican City and major churches: knees and shoulders must be covered for both men and women.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  74, 'Avoid ''tourist menu'' restaurants near major sights; walk 2–3 blocks into residential streets for authentic, affordable trattorias.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  74, 'Tap water in Rome is safe and delicious — fill your bottle at the city''s 2,500+ nasoni (public drinking fountains).', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  74, 'Beware of fake gladiators near the Colosseum who demand money for photos.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  74, 'The Roma Pass gives free metro rides and skip-the-line access to your first 2 museums — excellent value for a 3-day stay.', 5
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  74, 'https://images.pexels.com/photos/36581134/pexels-photo-36581134.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  74, 'https://images.pexels.com/photos/36581252/pexels-photo-36581252.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
