INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'amalfi-coast', 'Amalfi Coast', 'Italy', 'Europe', 
  'Cliffside villages tumbling into turquoise waters along Italy''s most dramatic shoreline', 'https://images.pexels.com/photos/36426022/pexels-photo-36426022.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 'The Amalfi Coast is a 50-kilometre ribbon of drama carved into the vertical face of the Lattari Mountains, where pastel-coloured villages cling to cliffs hundreds of metres above the Tyrrhenian Sea and lemon groves cascade down terraced hillsides scented with bougainvillea and wild rosemary. Designated a UNESCO World Heritage Site, this stretch of the Sorrentine Peninsula has seduced writers, artists, and travellers since the days of the Grand Tour — and not a single element of its charm has faded.

Positano, the coast''s poster child, tumbles from the coastal road to a crescent beach in a cascade of terracotta, pink, and amber. Amalfi town, once the capital of a powerful maritime republic, centres on its Arab-Norman cathedral and a warren of alleys where paper mills once thrummed. Ravello, perched high above, offers the gardens of Villa Rufolo and Villa Cimbrone — terraces where Wagner composed, where Gore Vidal wrote, and where infinity seems to begin at the balustrade.

Beyond the famous villages, the Sentiero degli Dei (Path of the Gods) traces a ridgeline trail that offers views so spectacular they feel earned by every step. Below, hidden coves accessible only by boat shelter emerald grottoes and swimming holes. This is a coast where every plate of fresh linguine alle vongole, every limoncello made from fat Amalfi lemons, and every sunset viewed from a tiled terrace becomes a memory that refuses to fade.', 
  14.6, 40.63, 'Beach', 'bg-blue-500', 
  'Cliffside villages, turquoise waters, and Italian charm.', '/images/explor-2.jpg', 
  'published', '', '4 Days', 
  NULL, 'Euro (€)', 'Mediterranean with hot, sunny summers and mild, rainy winters', 'May–June & September–October (warm, fewer crowds, boat services running)', 
  'Italian, English in hotels and restaurants', 'CET (UTC+1) / CEST (UTC+2 in summer)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  75, 1, 'Positano — Cascade Village & Beach Life', 'Positano', 
  'Arrive in Positano and descend through its steep, flowered stairways to the Spiaggia Grande. Swim in the turquoise water, browse hand-made sandal shops along the terraced lanes, and watch the sun set behind Li Galli islands from a clifftop restaurant with a glass of local Falanghina wine.', '["Descend Positano''s flowered stairways to Spiaggia Grande beach","Commission custom leather sandals from an artisan on Via Pasitea","Photograph the iconic pastel cascade from the coastal path above","Watch the sunset behind Li Galli islands with a glass of Falanghina"]', 'https://images.pexels.com/photos/36426022/pexels-photo-36426022.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  75, 2, 'Path of the Gods Hike', 'Agerola to Nocelle', 
  'Set out from Agerola on the Sentiero degli Dei, a ridgeline trail that traverses cliffs 500 metres above the sea with views stretching to Capri. The 7-kilometre walk passes through terraced lemon groves and wild herb meadows before descending stone steps into the hamlet of Nocelle, where a cold limoncello awaits.', '["Hike the legendary Path of the Gods ridgeline trail at 500 metres above the sea","Spot Capri, the Faraglioni, and the entire coastline from the trail","Walk through fragrant lemon groves and wild rosemary along the path","Reward yourself with fresh limoncello in the hilltop village of Nocelle"]', 'https://images.pexels.com/photos/358223/pexels-photo-358223.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  75, 3, 'Amalfi Town & Ravello''s Gardens', 'Amalfi & Ravello', 
  'Explore Amalfi''s Duomo with its striped Arab-Norman façade and the Chiostro del Paradiso cloister. Visit the Museum of Paper in a medieval mill, then wind uphill to Ravello for the gardens of Villa Rufolo, where a terrace seems to float above the coast, and Villa Cimbrone''s Terrace of Infinity.', '["Climb the grand staircase to Amalfi''s 9th-century Arab-Norman Cathedral","Discover traditional papermaking at Amalfi''s Museum of Paper","Stroll the Moorish gardens of Villa Rufolo where Wagner found inspiration","Stand at Villa Cimbrone''s Terrace of Infinity — arguably Italy''s finest viewpoint"]', 'https://images.pexels.com/photos/4147762/pexels-photo-4147762.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  75, 4, 'Boat Trip to Emerald Grotto & Hidden Coves', 'Amalfi Coast by Sea', 
  'Charter a traditional gozzo boat from Amalfi harbour and hug the coastline, dipping into the Grotta dello Smeraldo (Emerald Grotto), where sunlight refracts through an underwater cavity to paint the water an unearthly green. Anchor in secluded coves for swimming, then finish at a seaside restaurant in Praiano for the coast''s best seafood.', '["Cruise by traditional gozzo boat along the dramatic Amalfi cliffs","Enter the Emerald Grotto where sunlight turns the water supernatural green","Swim in secluded coves only accessible by boat","Dine on linguine alle vongole at a cliffside restaurant in Praiano"]', 'https://images.pexels.com/photos/5043638/pexels-photo-5043638.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  75, 'Path of the Gods Hike', 'Trek the legendary ridgeline trail from Agerola to Nocelle, 500 metres above the sea, with views to Capri and beyond.', 'Mountain', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  75, 'Boat Tours & Hidden Grottoes', 'Cruise the coast by gozzo boat, swim in hidden coves, and enter the luminous Emerald Grotto where light paints the water green.', 'Waves', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  75, 'Lemon-Infused Cuisine', 'Taste fresh lemon pasta, delizia al limone pastry, and artisanal limoncello made from the fat, fragrant lemons that define the coast.', 'Utensils', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  75, 'Ravello Concert Season', 'Attend an open-air classical concert at Villa Rufolo during the Ravello Festival, performed on a stage suspended above the sea.', 'Heart', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  75, 'Positano Shopping', 'Browse hand-made leather sandals, flowing linen dresses, and locally crafted ceramics in Positano''s terraced boutiques.', 'MapPin', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  75, 'Amalfi Cathedral & History', 'Explore the Arab-Norman cathedral, the Chiostro del Paradiso, and the medieval paper mills of a former maritime republic.', 'Landmark', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  75, 'The coastal road (SS163) is narrow and hair-raising — take SITA buses or ferries between towns instead of driving.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  75, 'Wear sturdy shoes with grip; the villages are vertical and most ''streets'' are steep staircases.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  75, 'Ferries between Positano, Amalfi, and Salerno run April–October only — check timetables the night before.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  75, 'Book restaurants for dinner, especially in Positano and Ravello, at least a day in advance in summer.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  75, 'Visit in May–June or September–October to avoid peak-season prices and crowds while enjoying warm swimming weather.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  75, 'Carry cash for smaller restaurants and beach clubs — card acceptance is improving but not universal.', 5
);
