INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'swiss-alps', 'Swiss Alps', 'Switzerland', 'Europe', 
  'Pristine peaks, legendary railways, and alpine villages frozen in storybook perfection', 'https://images.pexels.com/photos/418842/pexels-photo-418842.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 'The Swiss Alps are the roof of Europe — a staggering expanse of snow-capped summits, crystalline lakes, and meadows so green they seem digitally enhanced. From the north face of the Eiger, one of mountaineering''s most feared walls, to the gentle cowbell-dotted pastures of the Bernese Oberland, this landscape has defined the word ''alpine'' for every language that borrowed it. Whether you come to carve powder on the slopes of Zermatt, ride the Glacier Express through 91 tunnels and across 291 bridges, or simply sit on a chalet terrace with a fondue pot and a view that makes you forget to eat, the Swiss Alps deliver an intensity of beauty that borders on the overwhelming.

Interlaken, wedged between the turquoise mirrors of Lake Thun and Lake Brienz, is the gateway to the Jungfrau Region — home to the Jungfraujoch, Europe''s highest railway station at 3,454 metres, where you stand on the Aletsch Glacier and see three countries. Grindelwald offers the First Cliff Walk, a vertiginous steel walkway bolted to a cliff face, while Lauterbrunnen''s 72 waterfalls cascade into a valley Tolkien reportedly used as inspiration for Rivendell.

In winter, the Alps transform into a white wonderland of world-class skiing, snowshoeing, and Christmas markets glowing in timber villages. In summer, wildflower hiking trails, paragliding over emerald valleys, and cheese-making demonstrations in alpine huts reveal a gentler, equally magical side. The Swiss Alps do not merely meet expectations — they render them irrelevant.', 
  8, 46.6, 'Sports', 'bg-orange-500', 
  'Skiing, snowboarding, alpine hiking, and scenic mountain railways.', '/images/dest-11.jpg', 
  'published', '', '5 Days', 
  'Bern (federal capital)', 'Swiss Franc (CHF)', 'Alpine with cold, snowy winters and mild, sunny summers; varies greatly with altitude', 'December–March (skiing) & June–September (hiking, wildflowers)', 
  'German, French, Italian, Romansh', 'CET (UTC+1) / CEST (UTC+2 in summer)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  76, 1, 'Interlaken & Lake Cruise', 'Interlaken & Lake Thun', 
  'Arrive in Interlaken, cradled between Lake Thun and Lake Brienz, and board a paddle steamer across the turquoise waters of Lake Thun. Disembark at Spiez Castle for a wine tasting of Oberländer Blauburgunder, then return for a stroll along the Höheweg promenade with the Jungfrau massif glowing pink at sunset.', '["Cruise Lake Thun on a historic paddle steamer with mountain views","Visit the medieval Spiez Castle perched above the lake''s southern shore","Walk the Höheweg promenade as the Jungfrau turns pink at sunset","Sample local Blauburgunder wine at a lakeside vineyard"]', 'https://images.pexels.com/photos/418842/pexels-photo-418842.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  76, 2, 'Jungfraujoch — Top of Europe', 'Jungfrau Region', 
  'Ride the Jungfrau Railway through the Eiger''s interior to the Jungfraujoch at 3,454 metres — Europe''s highest railway station. Step onto the Aletsch Glacier, visit the Ice Palace carved inside the glacier, and gaze across the Alps to the Black Forest. Descend to Kleine Scheidegg for hot chocolate with the Eiger''s north face looming overhead.', '["Ride the cog railway through the inside of the Eiger to the Jungfraujoch","Stand on the Aletsch Glacier, the longest in the Alps","Explore the Ice Palace carved deep inside the glacier","Sip hot chocolate at Kleine Scheidegg with the Eiger north face above you"]', 'https://images.pexels.com/photos/5210421/pexels-photo-5210421.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  76, 3, 'Lauterbrunnen Valley & Schilthorn', 'Lauterbrunnen & Mürren', 
  'Descend into Lauterbrunnen Valley, where 72 waterfalls plummet from vertical cliffs — Staubbach Falls drops 297 metres in a single veil. Take the cable car to the car-free village of Mürren, then ride the revolving gondola to the Schilthorn summit for a 360-degree panorama of 200 peaks, including Eiger, Mönch, and Jungfrau.', '["Stand beneath the 297-metre veil of Staubbach Falls in Lauterbrunnen","Wander the car-free alpine village of Mürren perched on a cliff edge","Ride to the Schilthorn summit for a revolving restaurant panorama","Spot the Eiger, Mönch, and Jungfrau in a single 360-degree view"]', 'https://images.pexels.com/photos/5210144/pexels-photo-5210144.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  76, 4, 'Grindelwald First & Adventure Activities', 'Grindelwald', 
  'Ride the Grindelwald-First gondola to the First Cliff Walk, a steel-and-glass walkway jutting out over a 2,000-metre drop. Try the First Flyer zipline or the mountain cart descent, then hike to Bachalpsee, a mirror-still alpine lake reflecting the Schreckhorn and Wetterhorn in its glassy surface.', '["Walk the glass-floored First Cliff Walk suspended above a 2,000-metre void","Ride the First Flyer zipline at 84 km/h over the Grindelwald valley","Hike to Bachalpsee for mirror reflections of the Schreckhorn","Feast on cheese fondue in a traditional Grindelwald chalet"]', 'https://images.pexels.com/photos/4762984/pexels-photo-4762984.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  76, 5, 'Glacier Express or Scenic Railway', 'Bernese Oberland to Zermatt (or return)', 
  'Board the Glacier Express or GoldenPass Line for one of the world''s most spectacular rail journeys. The panoramic train crosses 291 bridges, passes through 91 tunnels, and climbs to the Oberalp Pass at 2,033 metres. Arrive in Zermatt for a final glimpse of the Matterhorn or return through the rolling green of the Emmental.', '["Travel by panoramic train across 291 bridges and through 91 tunnels","Cross the Oberalp Pass at 2,033 metres with views over the Rhine Gorge","Dine on a multi-course meal in the Glacier Express dining car","Glimpse the iconic pyramid of the Matterhorn as you approach Zermatt"]', 'https://images.pexels.com/photos/5641349/pexels-photo-5641349.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  76, 'Scenic Railway Journeys', 'Ride the Glacier Express, GoldenPass, or Bernina Express through tunnels, over viaducts, and past peaks in panoramic carriages.', 'Car', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  76, 'Skiing & Winter Sports', 'Carve powder in Zermatt, St. Moritz, or Verbier — world-class resorts with runs stretching above 4,000 metres.', 'Mountain', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  76, 'Alpine Hiking', 'Trek through wildflower meadows, past glacial lakes, and along ridgelines with views of Eiger, Mönch, and Jungfrau.', 'Globe', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  76, 'Swiss Cheese & Fondue', 'Dip crusty bread into bubbling Gruyère fondue in a timber chalet, or visit an alpine dairy to watch cheese being made by hand.', 'Utensils', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  76, 'Paragliding over Interlaken', 'Tandem paraglide from Beatenberg or Niederhorn, soaring above the twin lakes and landing in the meadows of Interlaken.', 'Waves', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  76, 'Jungfraujoch — Top of Europe', 'Ride to Europe''s highest railway station at 3,454 metres and stand on the Aletsch Glacier with views across three countries.', 'Landmark', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  76, 'Buy the Swiss Travel Pass for unlimited train, bus, and boat travel plus free museum entry — it pays for itself in 2 days.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  76, 'Mountain weather changes rapidly; always carry a rain jacket and warm layer, even in July.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  76, 'The Jungfraujoch is popular — book the first train (6:35 AM from Interlaken Ost) for the clearest views and thinnest crowds.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  76, 'Switzerland is expensive: budget CHF 50–80 per meal and consider self-catering from Coop or Migros supermarkets.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  76, 'Altitude sickness can affect some visitors above 3,000 metres — ascend slowly and stay hydrated.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  76, 'Tipping is not expected in Switzerland (service is included), but rounding up is appreciated.', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  76, 'Check the SBB app for real-time train schedules — Swiss trains run with legendary punctuality.', 6
);
