INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'luxor', 'Luxor', 'Egypt', 'Africa', 
  'The world''s greatest open-air museum, where pharaohs built for eternity', 'https://images.pexels.com/photos/36518565/pexels-photo-36518565.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 'Luxor is ancient Thebes reborn — a city bisected by the Nile into the East Bank of the living and the West Bank of the dead, where the sheer density of monumental ruins surpasses any archaeological site on Earth. On the East Bank, the Karnak Temple Complex sprawls across 200 acres of hypostyle halls, obelisks, and sacred lakes — its Great Hypostyle Hall alone contains 134 columns, each 23 metres tall, carved with hieroglyphs that have survived 3,300 years of sun and sand.

Cross the Nile at dawn and the West Bank reveals the Valley of the Kings, where 63 pharaonic tombs burrow deep into the limestone cliffs. Tutankhamun''s tomb, though small, still resonates with gold-painted walls and the young king''s stone sarcophagus. Nearby, the mortuary temple of Hatshepsut rises in three terraced colonnades against a sheer cliff — Egypt''s most elegant architectural statement — while the Colossi of Memnon, two 18-metre seated pharaohs, stand sentinel over the floodplain.

Luxor rewards slowness: a felucca sail at sunset, when the river turns molten gold and the call to prayer drifts from East Bank minarets; a hot air balloon ride at dawn over the West Bank temples; a horse-drawn caleche clip-clopping down the Corniche. This is not a city that preserves the past — it is a city where the past has never left.', 
  32.64, 25.69, 'Education', 'bg-indigo-500', 
  'Field trips to Valley of the Kings, Karnak Temple complex, active archaeology excavations, and hieroglyphic workshops.', '/images/tour-14.jpg', 
  'published', '', '4 Days', 
  'Cairo', 'Egyptian Pound (EGP)', 'Hot desert with scorching summers and warm, dry winters; rain is extremely rare', 'October–April (cooler temperatures for temple exploration)', 
  'Arabic, English in tourist areas', 'EET (UTC+2)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  77, 1, 'Karnak Temple & Luxor Temple by Night', 'Luxor East Bank', 
  'Arrive on the East Bank and enter Karnak Temple in the late afternoon, when the low sun ignites the sandstone columns in amber. Walk the Avenue of Sphinxes — recently restored — the 2.7-kilometre processional road linking Karnak to Luxor Temple. Return after dark for the Sound and Light Show that illuminates the Great Hypostyle Hall.', '["Walk among the 134 towering columns of Karnak''s Great Hypostyle Hall","Stroll the restored 2.7 km Avenue of Sphinxes between Karnak and Luxor Temple","Photograph the obelisk of Hatshepsut, the tallest surviving in Egypt","Watch the Sound and Light Show illuminate the temple ruins after dark"]', 'https://images.pexels.com/photos/36518565/pexels-photo-36518565.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  77, 2, 'Valley of the Kings & Hatshepsut''s Temple', 'Luxor West Bank', 
  'Cross the Nile at dawn to the West Bank. Descend into the painted tombs of the Valley of the Kings — Ramesses VI''s astronomical ceiling and Seti I''s vivid reliefs are among the most spectacular. Visit the terraced mortuary temple of Hatshepsut at Deir el-Bahari, then pause at the Colossi of Memnon.', '["Enter the tomb of Ramesses VI with its breathtaking astronomical ceiling","Stand inside Tutankhamun''s burial chamber in the Valley of the Kings","Admire Hatshepsut''s temple rising in three elegant terraces against the cliff","Photograph the twin 18-metre Colossi of Memnon at the floodplain edge"]', 'https://images.pexels.com/photos/5572512/pexels-photo-5572512.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  77, 3, 'Hot Air Balloon & Medinet Habu', 'Luxor West Bank (aerial & ground)', 
  'Rise before dawn for a hot air balloon flight over the West Bank, watching temples, tombs, and the Nile unfold in the golden first light. After landing, explore Medinet Habu — the mortuary temple of Ramesses III — whose vivid colour relief is the best-preserved of any Luxor temple.', '["Float over the Valley of the Kings and Hatshepsut''s Temple at sunrise by balloon","Explore the vividly coloured reliefs of Medinet Habu, often overlooked by crowds","Visit the Valley of the Queens and the tomb of Nefertari (if open)","Lunch at a rooftop restaurant overlooking the Nile and the Theban hills"]', 'https://images.pexels.com/photos/35870087/pexels-photo-35870087.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  77, 4, 'Felucca Sail & Banana Island', 'Nile River, Luxor', 
  'Spend a leisurely morning sailing the Nile on a traditional felucca, passing palm-fringed banks and buffalo wading in the shallows. Stop at Banana Island, a lush plantation where you can taste fresh bananas, sugarcane juice, and hibiscus tea. Return at sunset as the East Bank skyline turns to silhouette.', '["Sail a traditional felucca as the Nile turns molten gold at sunset","Visit Banana Island for fresh sugarcane juice and tropical fruit","Watch buffalo and egrets along the palm-fringed riverbanks","Sip hibiscus tea (karkade) on deck as the call to prayer echoes from shore"]', 'https://images.pexels.com/photos/5727263/pexels-photo-5727263.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  77, 'Valley of the Kings', 'Descend into pharaonic tombs adorned with astronomical ceilings, vivid murals, and hieroglyphic spells from the Book of the Dead.', 'Landmark', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  77, 'Hot Air Balloon at Sunrise', 'Float over the West Bank temples and the Nile at dawn, watching 3,000 years of history unfold from above.', 'Globe', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  77, 'Karnak Temple Exploration', 'Walk the Great Hypostyle Hall''s 134 colossal columns and trace 2,000 years of pharaonic construction across the vast complex.', 'BookOpen', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  77, 'Felucca Sailing', 'Glide down the Nile on a lateen-rigged felucca, watching the sun set behind the Theban hills as egrets take flight.', 'Waves', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  77, 'Egyptian Street Food', 'Feast on koshari (lentils, rice, and crispy onions), foul medames, and freshly baked aish baladi from Luxor''s street stalls.', 'Utensils', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  77, 'Sound & Light Show', 'Watch Karnak Temple come alive after dark as coloured lights and narration recount the story of Thebes across the ancient stones.', 'Lightbulb', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  77, 'Visit the Valley of the Kings first thing in the morning — by 10 AM the tombs become stifling and crowded.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  77, 'Your standard ticket covers 3 tombs; Tutankhamun, Seti I, and Nefertari require separate, pricier tickets — they''re worth it.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  77, 'Hire a licensed guide for the West Bank — the stories behind the reliefs transform the experience.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  77, 'Bargain hard with caleche (horse carriage) drivers and agree a round-trip price before boarding.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  77, 'Carry small bills (EGP 10–20) for baksheesh (tips) to tomb guards and boat crew.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  77, 'Drink at least 3 litres of water per day and wear a hat — Luxor regularly exceeds 40 °C in summer.', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  77, 'The restored Avenue of Sphinxes is best walked at sunset, when it''s cooler and dramatically lit.', 6
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  77, 'https://images.pexels.com/photos/36518565/pexels-photo-36518565.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  77, 'https://images.pexels.com/photos/5572512/pexels-photo-5572512.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  77, 'https://images.pexels.com/photos/35870087/pexels-photo-35870087.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  77, 'https://images.pexels.com/photos/5727263/pexels-photo-5727263.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);

INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'mount-sinai', 'Mount Sinai', 'Egypt', 'Africa', 
  'The sacred mountain of Moses, where pilgrims climb through starlight to greet the dawn', 'https://images.pexels.com/photos/35997094/pexels-photo-35997094.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 'Mount Sinai — Jebel Musa to the Bedouin — rises 2,285 metres from the rust-red granite of the southern Sinai Peninsula, a peak revered equally by Judaism, Christianity, and Islam as the place where God delivered the Ten Commandments to Moses. The pre-dawn pilgrimage to its summit is one of the world''s most profound travel experiences: climbing by torchlight through a silence broken only by the crunch of gravel and the murmur of prayer, then watching the first light of day spill across a vast wilderness of jagged peaks and desert valleys stretching to the Gulf of Aqaba.

At the mountain''s base sits St. Catherine''s Monastery, founded in the 6th century by order of Emperor Justinian and now the oldest continuously inhabited Christian monastery on Earth. Its library holds the second-largest collection of ancient manuscripts after the Vatican, and within its walls grows the Burning Bush — or so tradition holds — a living thorny shrub venerated for millennia. The monastery''s mosaic of the Transfiguration, glittering in gold above the altar, is a masterpiece of early Byzantine art.

The Sinai itself is a landscape of austere, raw beauty: wadis cut deep into red granite, Bedouin gardens appear in hidden oases, and the silence of the high desert envelops you like a physical presence. Whether you come for faith, adventure, or simply the desire to stand where history and legend converge, Mount Sinai delivers an experience that transcends the ordinary.', 
  33.97, 28.54, 'Spiritual', 'bg-violet-500', 
  'Sacred mountain of Moses — sunrise pilgrimage and ancient St. Catherine''s Monastery.', '/images/breadcrumb-1.jpg', 
  'published', '', '4 Days', 
  'Cairo', 'Egyptian Pound (EGP)', 'Desert highland; freezing at the summit before dawn, hot by midday in the valleys', 'March–May & September–November (moderate temperatures for the climb)', 
  'Arabic, Bedouin Sinai Arabic, some English', 'EET (UTC+2)', NULL
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  78, 1, 'Arrival at St. Catherine''s Village', 'St. Catherine''s, Sinai', 
  'Arrive at the small settlement of St. Catherine''s, nestled in a valley ringed by granite peaks. Meet your Bedouin guide, settle into a guesthouse, and share a communal dinner of bedouin bread baked in sand embers, grilled chicken, and sweet Sinai tea. Rest early — the summit climb begins at 2 AM.', '["Meet your Bedouin guide and learn about Jabaliya tribal traditions","Taste Bedouin flat bread baked in sand-covered embers","Stargaze in the unpolluted Sinai sky — one of the darkest in the Middle East","Rest in a stone guesthouse with the monastery visible below"]', 'https://images.pexels.com/photos/35997094/pexels-photo-35997094.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  78, 2, 'Summit Climb & Sunrise Pilgrimage', 'Mount Sinai Summit', 
  'Begin the ascent at 2 AM by torchlight along the Camel Path, a gradual switchback trail used by pilgrims for centuries. The final 750 Steps of Repentance are steeper — carved into the granite by monks. Arrive at the summit chapel as the horizon begins to glow, then watch one of the most spectacular sunrises on Earth unfold across the desert ranges.', '["Climb the Camel Path by torchlight with fellow pilgrims from around the world","Ascend the 750 Steps of Repentance carved into the granite face","Watch the sunrise from 2,285 metres as the desert turns gold and copper","Visit the small chapel of the Holy Trinity at the summit"]', 'https://images.pexels.com/photos/35966438/pexels-photo-35966438.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  78, 3, 'St. Catherine''s Monastery & Burning Bush', 'St. Catherine''s Monastery', 
  'Descend from the mountain and enter St. Catherine''s Monastery, a 6th-century fortress-church housing priceless icons, illuminated manuscripts, and the Burning Bush. Admire the Transfiguration mosaic above the altar, explore the charnel house of the monks'' ossuary, and browse the monastery''s small museum of religious art.', '["Enter the basilica to see the 6th-century Transfiguration mosaic in gold","View the Burning Bush, the living plant venerated for over 1,500 years","Browse the monastery museum''s collection of early Christian icons","Walk among the fortified walls that have protected the monastery since 565 AD"]', 'https://images.pexels.com/photos/35966498/pexels-photo-35966498.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  78, 4, 'Wadi Trails & Bedouin Gardens', 'Sinai High Desert', 
  'Hike with Bedouin guides into the surrounding wadis, where hidden gardens irrigated by ancient stone channels grow almonds, olives, and herbs amid the barren granite. Visit the Blue Desert, where a Belgian artist painted boulders blue as a peace memorial, and lunch in a shaded wadi on grilled goat and fresh herb tea.', '["Discover hidden Bedouin wadi gardens growing almonds and herbs amid granite","Visit the Blue Desert and its painted boulder peace memorial","Lunch on grilled goat and fresh sage tea in a shaded wadi","Learn about Bedouin medicinal plant knowledge from your guide"]', 'https://images.pexels.com/photos/35966438/pexels-photo-35966438.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  78, 'Sunrise Summit Pilgrimage', 'Climb through starlight to the peak of Mount Sinai and witness a sunrise that has drawn pilgrims of three faiths for millennia.', 'Mountain', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  78, 'St. Catherine''s Monastery', 'Explore the world''s oldest continuously inhabited monastery, with its Byzantine mosaics, ancient manuscripts, and the Burning Bush.', 'Landmark', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  78, 'Bedouin Cultural Immersion', 'Share meals, stories, and tea with Jabaliya Bedouin guides whose ancestors have lived in the shadow of the mountain for centuries.', 'Heart', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  78, 'Desert Stargazing', 'Lie back on granite slabs in one of the darkest skies in the northern hemisphere, where the Milky Way arcs overhead in vivid detail.', 'Globe', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  78, 'Wadi Trekking', 'Hike through red granite wadis to hidden oases, ancient rock inscriptions, and the surreal Blue Desert art installation.', 'MapPin', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  78, 'Start the summit climb by 2 AM to arrive for sunrise — the ascent takes 2.5–3 hours at a moderate pace.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  78, 'Temperatures at the summit can drop below freezing even in summer; bring warm layers, gloves, and a hat.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  78, 'Hire a Bedouin guide — it''s respectful, supports the local economy, and they know the mountain intimately.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  78, 'Bring a headlamp with spare batteries; the trail is unlit and torchlight is essential.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  78, 'St. Catherine''s Monastery is open to visitors only from 9 AM–12 PM; modest dress is required.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  78, 'Carry all your water (at least 2 litres for the climb) — there are no reliable water sources on the mountain.', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  78, 'The camel option covers only part of the trail; the 750 Steps of Repentance must be done on foot.', 6
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  78, 'https://images.pexels.com/photos/35997094/pexels-photo-35997094.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  78, 'https://images.pexels.com/photos/35966438/pexels-photo-35966438.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_images` (
