INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'serengeti', 'Serengeti', 'Tanzania', 'Africa', 
  'Endless plains where the greatest wildlife spectacle on Earth unfolds', 'https://images.pexels.com/photos/36372121/pexels-photo-36372121.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 'The Serengeti is a name that echoes with the cadence of migration — derived from the Maasai word ''siringet,'' meaning ''endless plains,'' it describes a landscape so vast that the horizon dissolves into heat shimmer and sky. This 14,750-square-kilometre national park, together with Kenya''s adjacent Masai Mara, hosts the Great Migration: an annual procession of over two million wildebeest, zebra, and gazelle circling the ecosystem in search of rain-greened grass, pursued by the full roster of African predators.

A single game drive can yield sightings that defy belief: a leopard draped languidly over a sausage tree branch, a pride of lions stalking through golden grass, a cheetah accelerating to 110 km/h in pursuit of a Thomson''s gazelle, and — in the far north — thousands of wildebeest leaping into the crocodile-infested Mara River in a chaos of spray and survival. The Serengeti''s southern plains, around Ndutu, are the calving grounds where 8,000 wildebeest are born daily in January and February, attracting hyenas, jackals, and raptors to a feast of new life.

Beyond the migration, the Serengeti holds resident prides, elephant herds, giraffe, hippo pods in the Grumeti River, and over 500 bird species. Luxury tented camps and mobile safari camps put you within earshot of lions roaring at night. A Serengeti sunset — silhouetting an acacia tree against a sky striped in coral and violet — is among the most iconic images in all of nature.', 
  34.8, -2.3, 'Safari', 'bg-green-600', 
  'Endless plains, dramatic wildlife, and unforgettable sunsets.', '/images/tour-2.jpg', 
  'published', '', '5 Days', 
  'Dodoma', 'Tanzanian Shilling (TZS), USD widely accepted', 'Tropical savanna with a dry season (June–October) and two wet seasons', 'June–October (dry season, river crossings) & January–February (calving season)', 
  'Swahili, English', 'EAT (UTC+3)', 'Left'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  79, 1, 'Arrival & First Game Drive', 'Seronera, Central Serengeti', 
  'Fly into Seronera airstrip in the heart of the Serengeti and transfer to your tented camp. An afternoon game drive along the Seronera River reveals hippo pods, crocodiles, and resident lion prides that use the riverine woodland as hunting cover. End the day watching the sunset from your camp''s elevated deck.', '["Land at Seronera airstrip in the heart of the Serengeti","Spot hippos, crocodiles, and monitor lizards along the Seronera River","Encounter a resident lion pride resting in the shade of a kopje","Watch a Serengeti sunset from your elevated tented camp deck"]', 'https://images.pexels.com/photos/36372121/pexels-photo-36372121.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  79, 2, 'Big Cat Country & Kopje Exploration', 'Central Serengeti & Simba Kopjes', 
  'Set out before dawn to find cheetahs hunting on the short-grass plains. Drive to the Simba Kopjes — granite outcrops where lions and leopards rest — and scan for rock hyrax and agama lizards. Afternoon, visit a Maasai community for a cultural exchange and learn about their coexistence with wildlife.', '["Witness a cheetah stalk or chase on the open plains at dawn","Search for leopards and lions lounging on the Simba Kopjes","Visit a Maasai boma to learn about pastoralist life alongside wildlife","Photograph giraffe, topi, and eland silhouetted against the setting sun"]', 'https://images.pexels.com/photos/7205267/pexels-photo-7205267.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  79, 3, 'Northern Serengeti & Mara River Crossing', 'Kogatende, Northern Serengeti', 
  'Fly or drive north to Kogatende, the epicentre of the Great Migration river crossings (July–October). Position yourself on the banks of the Mara River and wait for the dramatic moment when thousands of wildebeest plunge into crocodile-patrolled waters. The chaos, sound, and scale are unforgettable.', '["Witness wildebeest leaping into the Mara River during the Great Migration","Watch Nile crocodiles and hippos patrol the crossing points","See the vast herds stretching to the horizon on the northern plains","Enjoy a bush breakfast beside the river as the migration swirls around you"]', 'https://images.pexels.com/photos/5369453/pexels-photo-5369453.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  79, 4, 'Balloon Safari & Grumeti River', 'Western Corridor, Serengeti', 
  'Rise before dawn for a hot air balloon safari over the Western Corridor, drifting silently above herds, rivers, and acacia woodlands. After a champagne bush breakfast, drive along the Grumeti River to find massive Nile crocodiles, olive baboon troops, and colobus monkeys in the riverine forest.', '["Float silently over the Serengeti at sunrise in a hot air balloon","Toast your landing with champagne at a bush breakfast in the savanna","Spot giant Nile crocodiles basking along the Grumeti River","Photograph black-and-white colobus monkeys in the Grumeti riverine forest"]', 'https://images.pexels.com/photos/7780132/pexels-photo-7780132.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  79, 5, 'Southern Plains & Departure', 'Ndutu & Southern Serengeti', 
  'If visiting January–March, drive to the Ndutu calving grounds to witness thousands of wildebeest giving birth on the short-grass plains — an astonishing daily spectacle of new life and predators. Take a final morning game drive, then fly out from Seronera with the endless plains etched into memory.', '["Witness the calving season with thousands of newborn wildebeest (Jan–Mar)","Watch hyenas, jackals, and eagles converge on the calving plains","Spot flamingos at Lake Ndutu on the migration route","Take a final game drive as the Serengeti bids farewell in golden light"]', 'https://images.pexels.com/photos/35981578/pexels-photo-35981578.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  79, 'Great Migration River Crossings', 'Watch over two million wildebeest and zebra plunge into the crocodile-patrolled Mara River in one of nature''s most dramatic spectacles.', 'Globe', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  79, 'Big Five Game Drives', 'Track lion, leopard, elephant, buffalo, and rhinoceros across the Serengeti''s grasslands, kopjes, and riverine forests.', 'Camera', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  79, 'Hot Air Balloon Safari', 'Float silently over the savanna at sunrise, watching herds, predators, and the Serengeti''s endless landscape from above.', 'Mountain', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  79, 'Maasai Cultural Visit', 'Enter a Maasai boma to learn about warrior traditions, cattle herding, and the community''s coexistence with Serengeti wildlife.', 'Heart', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  79, 'Bush Dining & Sundowners', 'Enjoy candlelit bush dinners, champagne sundowners, and campfire storytelling beneath a sky blazing with stars.', 'Utensils', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  79, 'Birdwatching', 'Spot over 500 species including lilac-breasted rollers, secretary birds, martial eagles, and crowned cranes on the plains.', 'BookOpen', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  79, 'The Great Migration river crossings happen July–October in the north; calving season is January–February in the south — plan your visit accordingly.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  79, 'Book safari lodges and camps 6–12 months in advance for peak season (July–October).', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  79, 'Bring binoculars, a telephoto lens (at least 200mm), and a bean bag for stabilising shots from the vehicle roof.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  79, 'Wear neutral-coloured clothing (khaki, green, beige) — bright colours can disturb wildlife.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  79, 'Malaria is present; take prophylaxis and use insect repellent, especially at dusk and dawn.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  79, 'Tip your guide and camp staff — USD 15–20 per person per day for guides is standard.', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  79, 'Keep all limbs inside the vehicle during game drives — wild animals are unpredictable and distances are deceiving.', 6
);
