INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'zanzibar', 'Zanzibar', 'Tanzania', 'Africa', 
  'The Spice Island — where turquoise tides meet ancient stone and fragrant clove breezes', 'https://images.pexels.com/photos/7101641/pexels-photo-7101641.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 'Zanzibar is a name that tastes of cloves, nutmeg, and sea salt — an archipelago off the Tanzanian coast that has served as a crossroads of African, Arab, Indian, and European cultures for over a thousand years. Stone Town, the island''s UNESCO-listed historic heart, is a labyrinth of coral-stone buildings, intricately carved wooden doors, rooftop terraces, and narrow alleys where the scent of spice and grilled seafood mingles with the sound of Taarab music drifting from open windows.

Beyond Stone Town, Zanzibar''s coastline unspools in a sequence of powdery white-sand beaches fringed by coconut palms and lapped by water so clear it seems like swimming in glass. Nungwi and Kendwa on the north coast offer sunset dhow cruises and fire-dance beach parties, while the east coast''s Paje and Jambiani are kite-surfing havens where low tide reveals a vast sandbar stretching to the reef. Off the western shore, Prison Island harbours giant Aldabra tortoises, some over 100 years old.

The Spice Tour is quintessential Zanzibar: walk through plantations where cloves, vanilla, cinnamon, black pepper, and lemongrass grow in fragrant profusion, tasting each one fresh from the plant. At night, Forodhani Gardens in Stone Town transforms into an open-air food market where Zanzibari pizza, octopus skewers, sugarcane juice, and urojo soup sizzle under lamplight. Zanzibar is not just a beach destination — it is a sensory immersion.', 
  39.2, -6.2, 'Beach', 'bg-blue-500', 
  'Spice island paradise with pristine beaches and rich history.', '/images/explor-4.jpg', 
  'published', '', '5 Days', 
  'Zanzibar City (Stone Town)', 'Tanzanian Shilling (TZS), USD widely accepted', 'Tropical maritime with warm temperatures year-round; two rainy seasons', 'June–October (dry season, best diving) & December–February (warm, sunny)', 
  'Swahili, English, Arabic', 'EAT (UTC+3)', 'Left'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  80, 1, 'Stone Town Heritage Walk', 'Stone Town, Zanzibar City', 
  'Plunge into the labyrinth of Stone Town: pass the House of Wonders, the Old Fort, and the former slave market — now the site of the Anglican Cathedral — to understand the island''s complex history. Photograph the ornately carved wooden doors that distinguish each merchant house, and end at Forodhani Gardens as the night food market fires up its grills.', '["Explore the UNESCO-listed coral-stone alleys of Stone Town","Visit the former slave market and Anglican Cathedral memorial","Photograph Zanzibar''s famous intricately carved wooden doors","Feast on Zanzibari pizza and octopus skewers at Forodhani night market"]', 'https://images.pexels.com/photos/7101641/pexels-photo-7101641.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  80, 2, 'Spice Tour & Jozani Forest', 'Central Zanzibar', 
  'Join a spice plantation tour to taste cloves, vanilla, cinnamon, black pepper, and lemongrass straight from the plant as a guide weaves leaves into jewellery and crowns. Afternoon, visit Jozani Chwaka Bay National Park, home to the rare red colobus monkey found nowhere else on Earth.', '["Taste cloves, nutmeg, cinnamon, and vanilla fresh from the plant","Wear a crown woven from palm and spice leaves by your guide","Spot endangered Zanzibar red colobus monkeys in Jozani Forest","Walk the mangrove boardwalk through Jozani''s tidal ecosystem"]', 'https://images.pexels.com/photos/5769698/pexels-photo-5769698.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  80, 3, 'Nungwi Beach & Dhow Sunset Cruise', 'Nungwi, Northern Zanzibar', 
  'Travel to Nungwi, where white sand meets water that shifts from turquoise to sapphire. Swim, snorkel over the reef, and visit the Mnarani Marine Turtle Conservation Pond to see hawksbill and green turtles. At dusk, board a traditional dhow for a sunset cruise as the sky burns orange over the Indian Ocean.', '["Swim in the turquoise shallows of Nungwi''s powdery white-sand beach","Meet rescued hawksbill turtles at Mnarani Marine Conservation","Cruise on a traditional dhow as the Indian Ocean sunset blazes","Join a beach bonfire and drum circle under the stars at Nungwi"]', 'https://images.pexels.com/photos/5859000/pexels-photo-5859000.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  80, 4, 'Prison Island & Snorkelling', 'Changuu (Prison Island) & Bawe Reef', 
  'Boat to Prison Island to meet giant Aldabra tortoises, some over a century old, in the shade of baobab trees. Continue to Bawe Island or Mnemba Atoll for world-class snorkelling over coral gardens teeming with lionfish, moray eels, and green turtles gliding through the warm current.', '["Hand-feed 100-year-old Aldabra giant tortoises on Prison Island","Snorkel Mnemba Atoll or Bawe Reef among lionfish and sea turtles","Swim in the gin-clear water of a deserted sandbar","Spot bottlenose dolphins on the boat ride between islands"]', 'https://images.pexels.com/photos/36468476/pexels-photo-36468476.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  80, 5, 'Paje Kitesurfing & Farewell', 'Paje, East Coast', 
  'Head to Paje on the east coast, Zanzibar''s kite-surfing capital, where steady trade winds and a vast low-tide sandbar create perfect conditions. Take a lesson or watch from a beachfront café with a fresh coconut. End with a farewell seafood dinner at The Rock, a restaurant perched on a tiny rock in the ocean.', '["Try kite-surfing on Paje''s flat, shallow sandbar at low tide","Walk the endless low-tide sand flats with seaweed farmers at work","Dine at The Rock restaurant, perched on a tiny ocean boulder","Watch the moon rise over the Indian Ocean on your final Zanzibar evening"]', 'https://images.pexels.com/photos/36468231/pexels-photo-36468231.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  80, 'Stone Town Heritage Walk', 'Wander the UNESCO-listed labyrinth of coral-stone alleys, carved doors, rooftop cafés, and the former slave market that shaped Zanzibar''s history.', 'Landmark', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  80, 'Spice Plantation Tour', 'Taste cloves, vanilla, cinnamon, and lemongrass fresh from the plant on a guided walk through Zanzibar''s legendary spice farms.', 'Lightbulb', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  80, 'Beach & Water Sports', 'Swim, snorkel, kitesurf, and sail on beaches ranked among the world''s finest, from Nungwi''s turquoise north to Paje''s kite-surfing east.', 'Waves', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  80, 'Forodhani Night Market', 'Graze through Stone Town''s legendary outdoor food market for Zanzibari pizza, urojo soup, grilled octopus, and fresh sugarcane juice.', 'Utensils', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  80, 'Dolphin & Turtle Encounters', 'Meet giant Aldabra tortoises on Prison Island and snorkel with dolphins and green turtles off Mnemba Atoll.', 'Heart', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  80, 'Jozani Forest Red Colobus Monkeys', 'Trek through Zanzibar''s only national park to see the endemic red colobus monkey, found nowhere else on the planet.', 'Globe', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  80, 'Zanzibar is predominantly Muslim — dress modestly in Stone Town (cover shoulders and knees) and save swimwear for the beach.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  80, 'Bargain at markets and with taxi drivers — agree on a price before getting in the car.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  80, 'The best diving and snorkelling visibility is during the dry season (June–October).', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  80, 'Avoid the heavy rains of April–May (masika season) when many beach hotels close and roads flood.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  80, 'Use reef-safe sunscreen to protect the coral — Zanzibar''s reefs are fragile and under pressure.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  80, 'Malaria is present; take prophylaxis and use mosquito repellent, especially at dusk.', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  80, 'Carry USD in small bills for tips, transport, and small purchases — many vendors don''t carry change for large notes.', 6
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  80, 'https://images.pexels.com/photos/7101641/pexels-photo-7101641.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
