INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'moscow', 'Moscow', 'Russia', 'Europe', 
  'Red Square, the Kremlin, Bolshoi Theatre, and centuries of imperial grandeur', 'https://images.pexels.com/photos/7015780/pexels-photo-7015780.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 'Moscow is a city of extraordinary contrasts — Soviet-era monuments rise beside gilded Orthodox domes, underground metro stations rival palace ballrooms in their marble splendour, and the ancient Kremlin watches over a skyline of glass towers and neon-lit boulevards. As Russia''s sprawling capital, Moscow has reinvented itself across centuries of tsars, revolution, and renewal, yet its core remains unchanged: a city of immense ambition, profound culture, and a deep-rooted pride in its endurance.

At its heart lies Red Square, arguably the most recognisable plaza on Earth. On one side rises the brick parapets of the Kremlin — a fortified complex housing cathedrals with gilded onion domes, Tsar Cannon, Tsar Bell, and the seat of Russian power. Opposite stands the candy-striped spires of St. Basil''s Cathedral, commissioned by Ivan the Terrible in 1555 to commemorate a military victory and still one of the most photographed buildings in the world. Between them, Lenin''s Mausoleum marks the resting place of the Soviet Union''s founding leader.

Beyond the square, Moscow rewards exploration: the Bolshoi Theatre offers world-class ballet and opera in a gilded auditorium; the Tretyakov Gallery houses the world''s greatest collection of Russian art; and the Gorky Park riverside promenade buzzes year-round with food stalls, art installations, and ice skating in winter. The city''s metro system alone is worth descending into — palatial stations with mosaics, sculptures, and chandeliers built as ''people''s palaces'' in the Stalin era.', 
  37.62, 55.75, 'Historical', 'bg-amber-600', 
  'Red Square, the Kremlin, Bolshoi Theatre, and centuries of imperial grandeur.', '/images/city-5.jpg', 
  'published', '', '5 Days', 
  'Moscow (national capital)', 'Russian Ruble (₽ / RUB)', 'Humid continental — cold winters (avg. -10 °C), warm summers (avg. 24 °C)', 'May–June (White Nights approach) & September–October (golden autumn foliage)', 
  'Russian', 'MSK (UTC+3)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  81, 1, 'Red Square, Kremlin & St. Basil''s', 'Central Moscow', 
  'Begin at Red Square at dawn when it is nearly empty and at its most atmospheric. Enter the Kremlin to see the Ivan the Great Bell Tower, the Assumption Cathedral with its golden iconostasis, and the staggeringly large Tsar Bell and Tsar Cannon. End the afternoon inside St. Basil''s Cathedral, marvelling at its maze of spiralling staircases and painted vaulted chapels.', '["Experience Red Square at dawn — almost no crowds, extraordinary atmosphere","Tour the Kremlin''s cathedrals and armory housing imperial regalia","See the 200-tonne Tsar Bell that was never rung and the Tsar Cannon never fired","Explore the candy-striped interior of St. Basil''s Cathedral"]', 'https://images.pexels.com/photos/7015780/pexels-photo-7015780.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  81, 2, 'Bolshoi Theatre & Metro Palace Tour', 'Central Moscow', 
  'Attend a daytime tour of the Bolshoi Theatre, the gilded symbol of Russian classical arts, and book an evening performance of ballet or opera if available. Between visits, descend into Moscow''s legendary metro system to visit Komsomolskaya, Mayakovskaya, and Novoslobodskaya stations — each a palatial hall of marble, stained glass, and Soviet-era mosaics.', '["Tour the Bolshoi Theatre''s imperial-gold main hall and backstage areas","Attend an evening ballet or opera — book ahead as tickets sell out fast","Visit Komsomolskaya metro station, often called the most beautiful in the world","Photograph the Art Deco mosaics of Mayakovskaya station"]', 'https://images.pexels.com/photos/7316643/pexels-photo-7316643.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  81, 3, 'Tretyakov Gallery & Gorky Park', 'Moscow', 
  'Spend the morning at the State Tretyakov Gallery, home to over 130,000 works of Russian art from medieval icons to avant-garde masterpieces by Kandinsky and Malevich. Afternoon, walk along the Moscow River to Gorky Park for open-air art installations, riverside cafés, and people-watching. In winter, strap on skates at the park''s famous outdoor rink.', '["See Rublev''s Holy Trinity icon and Surikov''s massive historical canvases at the Tretyakov","Walk the Krymskaya Embankment open-air gallery between Gorky Park and the city","Rent a bike or skates at Gorky Park depending on the season","Try Borodinsky black bread with smoked salmon at a riverside café"]', 'https://images.pexels.com/photos/11922103/pexels-photo-11922103.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  81, 4, 'Arbat Street, Novodevichy & Night City', 'Moscow', 
  'Stroll the pedestrian Arbat Street, Moscow''s historic bohemian quarter lined with street musicians, portraitists, souvenir stalls, and 19th-century mansions. Visit the UNESCO-listed Novodevichy Convent and its cemetery — resting place of Chekhov, Gogol, Stalin''s wife, and Khrushchev. Evening, take a river cruise for illuminated views of the Kremlin.', '["Walk the full length of Arbat Street, picking up matryoshka dolls and Soviet pins","Tour Novodevichy Convent''s white-and-gold Smolensk Cathedral","Find the graves of Chekhov and Gogol in Novodevichy Cemetery","Take a night river cruise to see the Kremlin towers lit against the night sky"]', 'https://images.pexels.com/photos/10311704/pexels-photo-10311704.png?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  81, 5, 'Kolomenskoye & Izmailovo Market', 'Moscow Outskirts', 
  'Escape central Moscow for Kolomenskoye, a UNESCO-listed former royal estate where the 16th-century Ascension Church rises above the Moscow River on a dramatic escarpment. In the afternoon, explore Izmailovo Market — Moscow''s largest open-air flea market for Soviet memorabilia, antique samovars, vintage propaganda posters, and handmade crafts.', '["Stand before the soaring Ascension Church of Kolomenskoye, a UNESCO World Heritage Site","Walk the apple and cherry orchards of the former tsars'' summer estate","Bargain for Soviet badges, matryoshkas, and antique maps at Izmailovo Market","Taste medovukha (honey mead) poured from wooden barrels at the market entrance"]', 'https://images.pexels.com/photos/36388161/pexels-photo-36388161.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  81, 'Red Square & Kremlin', 'Walk the cobblestones of the world''s most iconic plaza and enter the medieval fortress housing Russia''s greatest cathedrals and imperial treasures.', 'Landmark', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  81, 'Bolshoi Theatre Ballet', 'Attend a performance in one of the world''s great opera houses — gilded, acoustically perfect, and still the benchmark for classical Russian ballet.', 'BookOpen', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  81, 'Palace Metro Stations', 'Descend into Moscow''s underground palaces — marble halls, crystal chandeliers, and Socialist Realist mosaics that rival any museum above ground.', 'Globe', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  81, 'Tretyakov Gallery', 'Trace Russian art from Byzantine icons to 20th-century avant-garde in the world''s most comprehensive collection of Russian painting and sculpture.', 'Camera', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  81, 'Izmailovo Flea Market', 'Hunt for Soviet-era medals, vintage samovars, propaganda posters, and hand-painted lacquer boxes at Moscow''s sprawling open-air antiques bazaar.', 'MapPin', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  81, 'Gorky Park Riverside', 'Stroll, cycle, or skate along the Moscow River embankment through Gorky Park''s open-air galleries, food stalls, and cultural pavilions.', 'Heart', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  81, 'A Russian tourist e-Visa is available for many nationalities — apply at least two weeks before travel.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  81, 'Moscow''s metro is the fastest way to get around — buy a Troika card and top it up; trains run every 90 seconds at peak hours.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  81, 'Pre-book the Kremlin and Bolshoi Theatre well in advance — both sell out, especially during holidays.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  81, 'Winter (November–February) is bitterly cold but magical — Red Square under snow is unforgettable; pack thermal layers.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  81, 'Many restaurants expect cash — carry rubles as not all places accept foreign cards.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  81, 'English signage is limited outside tourist zones; download a Russian offline map and translation app.', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  81, 'The Kremlin requires airport-style security; no large bags, and modest dress is required for cathedral entry.', 6
);
