INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'st-petersburg', 'St. Petersburg', 'Russia', 'Europe', 
  'Hermitage Museum, Winter Palace, White Nights, and baroque waterfront splendour', 'https://images.pexels.com/photos/6865593/pexels-photo-6865593.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 'St. Petersburg was built to astonish. Peter the Great founded it in 1703 on a marshy delta of the Neva River, then assembled the greatest architects of Europe — Italian, French, German — and set them to work creating a Russian Venice of palaces, canals, and boulevards on a scale to rival any capital on the continent. The result is a city of staggering visual magnificence: pastel-painted baroque facades reflected in dark waterways, golden spires rising from islands connected by hundreds of ornate bridges, and an unbroken riverfront of imperial grandeur stretching along the Neva.

At the city''s heart stands the Winter Palace — home to the tsars for nearly two centuries and now the centrepiece of the Hermitage Museum, one of the largest and most visited art museums on Earth. Its five interconnected buildings hold over three million items: Rembrandts, Leonardos, Picassos, and an entire room of Matisse canvases, displayed in gilded halls where Nicholas II once held court. A single day is barely enough to graze the surface; many visitors return repeatedly and still feel they''ve missed half of it.

The city''s signature phenomenon is the White Nights — from late May to mid-July, when the sun barely sets and the sky stays luminous around midnight. Drawbridges along the Neva rise in the small hours to let cargo ships pass, and Petersburgers fill the embankments in a spontaneous street festival that lasts for weeks. The White Nights Classical Music Festival, staged at the Mariinsky Theatre, draws the world''s greatest conductors and soloists to perform under a sky that never fully darkens.', 
  30.32, 59.93, 'Heritage', 'bg-purple-500', 
  'Hermitage Museum, Winter Palace, white nights, and baroque waterfront architecture.', '/images/city-6.jpg', 
  'published', '', '5 Days', 
  'Moscow (national capital; St. Petersburg is Russia''s cultural capital)', 'Russian Ruble (₽ / RUB)', 'Humid continental — cold winters, mild summers; White Nights from late May to mid-July', 'Late May–July (White Nights) & September (golden autumn, fewer crowds)', 
  'Russian', 'MSK (UTC+3)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  82, 1, 'Hermitage Museum & Palace Square', 'Palace Embankment, St. Petersburg', 
  'Arrive at the Winter Palace and spend the full day inside the Hermitage — plan a route in advance to cover the highlights: the Jordan Staircase, the Malachite Room, da Vinci''s two Madonnas, Rembrandt''s Return of the Prodigal Son, and the Impressionist halls. Step out to photograph the Alexander Column and baroque sweep of Palace Square at sunset.', '["Navigate the Hermitage''s gilded State Rooms and Knights Hall","Stand before Rembrandt''s monumental Return of the Prodigal Son","Photograph the baroque Winter Palace facade from Palace Square","Watch the sun set behind the Alexander Column over the vast square"]', 'https://images.pexels.com/photos/6865593/pexels-photo-6865593.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  82, 2, 'Peter & Paul Fortress & Canal Boat Tour', 'Zayachy Island & City Canals', 
  'Cross to Zayachy Island for the Peter and Paul Fortress — the city''s birthplace, housing the cathedral where all Russian emperors from Peter the Great to Nicholas II are buried. Afternoon, board a boat for a canal tour weaving beneath the city''s famous ornamental bridges, past the Church of the Savior on Spilled Blood and the Mikhailovsky Gardens.', '["Visit the Peter and Paul Cathedral, burial place of Russia''s tsars","Walk the Neva-facing ramparts for views of the Winter Palace across the river","Float under gilded bridges and past hidden courtyards on a canal boat tour","See the Church of the Savior on Spilled Blood glittering from the water"]', 'https://images.pexels.com/photos/5058638/pexels-photo-5058638.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  82, 3, 'Peterhof Palace & Fountain Gardens', 'Gulf of Finland, 30 km west', 
  'Take a hydrofoil across the Gulf of Finland to Peterhof, the ''Russian Versailles'' — a palace complex where 64 fountains powered entirely by natural gravity cascade down terraced gardens to the sea. The Grand Cascade, flanked by gilded statues of Samson, is one of the great baroque spectacles of Europe. Walk the Lower Park to the intimate Monplaisir Palace on the water''s edge.', '["Arrive by hydrofoil across the Gulf of Finland for a dramatic first view","Watch the Grand Cascade''s 64 gravity-powered fountains in full flow","Stroll the Lower Park past golden statues to the sea-facing Monplaisir Palace","Explore the golden-domed Grand Palace''s state rooms and Throne Hall"]', 'https://images.pexels.com/photos/5512840/pexels-photo-5512840.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  82, 4, 'Mariinsky Theatre & White Nights', 'Teatralnaya Square & City Embankments', 
  'Attend an evening performance at the Mariinsky Theatre, Russia''s most prestigious opera and ballet stage and home to the Kirov Ballet. If visiting during White Nights (late May–July), stay out late and join the crowds on the embankments to watch the Neva''s drawbridges rise at 1 AM as cargo ships pass beneath a sky that never fully darkens.', '["Attend a ballet or opera in the Mariinsky''s historic hall — buy tickets in advance","Walk the Palace Embankment at midnight under the luminous White Nights sky","Watch the Neva drawbridges rise at 1 AM surrounded by celebrating Petersburgers","Photograph the Church of the Savior on Spilled Blood lit gold against the pale summer night"]', 'https://images.pexels.com/photos/7329481/pexels-photo-7329481.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  82, 5, 'Pushkin Town & Catherine Palace', 'Pushkin (Tsarskoye Selo), 25 km south', 
  'Day-trip to Tsarskoye Selo — ''the tsar''s village'' — to see the electric-blue Catherine Palace with its jaw-dropping Great Hall and the reconstructed Amber Room, one of the world''s greatest lost and found wonders. Stroll Catherine Park''s formal gardens, past the Hermitage Pavilion and the Great Pond, before returning to St. Petersburg for a farewell dinner of blinis with caviar.', '["Marvel at the Great Hall''s mirrors and gilded stucco in Catherine Palace","Stand in the reconstructed Amber Room — 6 tonnes of amber, gold, and mirrors","Walk Catherine Park past formal terraces, ponds, and folly pavilions","Farewell dinner of blinis with red and black caviar in a city-centre restaurant"]', 'https://images.pexels.com/photos/4555622/pexels-photo-4555622.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  82, 'Hermitage Museum', 'Lose yourself in three million artworks across five interconnected winter palaces — da Vinci, Rembrandt, Picasso, and the gilded halls where tsars held court.', 'Landmark', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  82, 'White Nights Nights Out', 'Experience the surreal midnight twilight of late May–July when the sky stays luminous and Petersburgers flood the embankments in spontaneous celebration.', 'Globe', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  82, 'Mariinsky Ballet & Opera', 'Attend a world-class performance at Russia''s most prestigious stage, home to the legendary Kirov Ballet and decades of celebrated conductors.', 'BookOpen', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  82, 'Peterhof Fountains', 'See 64 gravity-powered baroque fountains cascade down gilded terraces to the Gulf of Finland in the Russian answer to Versailles.', 'Waves', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  82, 'Canal Boat Tour', 'Float through the city''s 300-plus bridges and canal network, passing colorful facades, hidden courtyards, and onion-domed churches from the water.', 'MapPin', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  82, 'Catherine Palace & Amber Room', 'Visit the electric-blue rococo palace at Tsarskoye Selo and stand inside the legendary Amber Room, reconstructed after it was looted in World War II.', 'Camera', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  82, 'The Hermitage requires an entire day minimum — buy timed-entry tickets online in advance to avoid the queue.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  82, 'White Nights run roughly from June 11 to July 2; the Scarlet Sails festival (late June) is spectacular but the city is fully booked — reserve accommodation 6 months ahead.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  82, 'Use the metro and canal boat taxis for transport — traffic in the centre is severe and taxis can be slow.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  82, 'The Catherine Palace at Tsarskoye Selo has long queues in summer; book a guided tour that includes skip-the-line entry.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  82, 'Dress for cold even in summer — evenings near the Neva can be windy and cool; a jacket is always useful.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  82, 'Many museums are closed on Mondays; plan your itinerary accordingly.', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  82, 'Bring a physical copy of your hotel''s address in Russian — not all taxi drivers read Latin script.', 6
);
