INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'lake-baikal', 'Lake Baikal', 'Russia', 'Europe', 
  'The deepest lake on Earth — crystal-clear Siberian waters and untouched wilderness', 'https://images.pexels.com/photos/7127420/pexels-photo-7127420.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 'Lake Baikal is a superlative in every dimension. The world''s deepest lake — plunging 1,642 metres into the Earth''s crust — it is also the oldest, estimated at 25–30 million years old, and holds approximately 20% of the world''s unfrozen freshwater. Its water is so clear and pure that you can see objects 40 metres below the surface; indigenous Buryat people have drunk directly from its shores for centuries. In winter, the lake freezes into one of the planet''s most dramatic natural spectacles — a vast plain of cracked, bubbling blue ice stretching to the horizon, so thick that trucks drive across it.

The lake is a UNESCO World Heritage Site and a living laboratory of evolution. Over 80% of its animal species exist nowhere else on Earth, including the Baikal seal — the world''s only exclusively freshwater seal — and the golomyanka, a transparent fish that dissolves in sunlight. The surrounding forests of the Eastern Sayan mountains and the Barguzin Range shelter bears, wolves, and Siberian roe deer, while the lake''s shores host some of Russia''s most pristine taiga wilderness.

Olkhon Island, reached by hovercraft in winter and ferry in summer, is the spiritual heart of Baikal for the Buryat people, who have worshipped its Shamanist spirits for millennia. Its rugged cliffs, turquoise bays, and the sacred Shamanka Rock at Khuzhir Village make it the most rewarding destination on the lake. The Great Baikal Trail, one of Russia''s finest hiking routes, traces the western shoreline through birch and cedar forests, connecting fishing villages and hidden hot springs.', 
  108, 53.5, 'Nature', 'bg-teal-500', 
  'The deepest lake on Earth — crystal-clear Siberian waters and untouched wilderness.', '/images/dest-11.jpg', 
  'published', '', '5 Days', 
  'Irkutsk (gateway city, 65 km west of Baikal)', 'Russian Ruble (₽ / RUB)', 'Continental Siberian — very cold winters (–20 °C), warm dry summers (up to 25 °C)', 'January–March (ice season) & July–August (warmest, greenest, best hiking)', 
  'Russian, Buryat', 'IRKT (UTC+8)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  83, 1, 'Irkutsk Arrival & Old Town Walk', 'Irkutsk, Siberia', 
  'Fly into Irkutsk, gateway to Baikal, and explore the city''s surprising collection of wooden merchant mansions — intricately carved facades in a Siberian vernacular style unlike anywhere else in Russia. Visit the 18th-century Epiphany Cathedral by the Angara River and dine on smoked omul fish from Baikal at one of the old town''s riverside restaurants.', '["Walk Irkutsk''s 130 Quarter, a preserved block of restored wooden merchant houses","See the carved wooden facades of the Trubetskoy Decembrist House museum","Dine on smoked Baikal omul fish — unique to the lake and unlike any other salmon","Stroll the Angara River embankment in the golden Siberian afternoon light"]', 'https://images.pexels.com/photos/7127420/pexels-photo-7127420.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  83, 2, 'Olkhon Island & Shamanka Rock', 'Olkhon Island, Lake Baikal', 
  'Transfer to Olkhon Island by minibus and ferry (summer) or hovercraft (winter). Arrive at Khuzhir Village and walk to Shamanka Rock — a two-headed promontory jutting into the lake, sacred to Buryat shamans for thousands of years. The view from its summit — looking back over the vast lake and the forested cliffs of the island — is one of the most iconic in Siberia.', '["Cross to Olkhon Island on a hovercraft over frozen Baikal (winter) or by ferry (summer)","Climb Shamanka Rock to look out over the world''s largest freshwater lake","Watch the Milky Way from the island''s zero-light-pollution shores at night","Meet the island''s Buryat residents and learn about their shamanist spiritual traditions"]', 'https://images.pexels.com/photos/7039181/pexels-photo-7039181.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  83, 3, 'Great Baikal Trail & Cape Khoboy', 'Northern Olkhon Island', 
  'Hike the northern section of the Great Baikal Trail to Cape Khoboy, the northernmost tip of Olkhon Island, where cliffs plunge into the deepest part of the lake. In summer, the trail passes through meadows of Siberian wildflowers; in winter, walk across the frozen lake surface itself, listening to the deep resonant booms of shifting ice beneath your feet.', '["Hike to Cape Khoboy across Siberian taiga above cliffs dropping into Baikal","Walk on the frozen lake surface in winter, hearing the ice shift and sing below","Spot Baikal seals sunning on ice floes (winter) or swimming from shore (summer)","Photograph the white-and-turquoise ice bubbles trapped beneath the frozen surface"]', 'https://images.pexels.com/photos/7119508/pexels-photo-7119508.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  83, 4, 'Hot Springs & Buryat Culture', 'Baikal Eastern Shore', 
  'Cross to Baikal''s eastern shore to visit Khakusy Bay''s natural hot springs emerging directly from the lakeshore — a surreal experience of soaking in hot mineral water while watching the frozen or sunlit lake metres away. Visit a Buryat village for a cultural lunch of bozi (steamed meat dumplings) and fermented mare''s milk.', '["Soak in natural geothermal hot springs on the shore of the world''s deepest lake","Eat bozi Buryat dumplings stuffed with beef and onion, prepared over an open fire","Learn to identify taiga tree species with a local guide — pine, Siberian cedar, larch","Visit a shaman''s sacred ritual site and hear about Buryat animist traditions"]', 'https://images.pexels.com/photos/7039765/pexels-photo-7039765.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  83, 5, 'Listvianka Village & Departure', 'Listvianka, Baikal Shoreline', 
  'Spend the final morning at Listvianka — the closest Baikal village to Irkutsk — where a vibrant fish market sells smoked omul, dried Baikal grayling, and pickled garlic. Visit the Baikal Museum to meet live Baikal seals in their aquarium and view underwater footage of the lake''s depths. Return to Irkutsk for your onward flight.', '["Shop the Listvianka fish market for smoked omul, grayling, and Siberian honey","Meet live Baikal nerpa seals at the Baikal Limnological Museum aquarium","Watch underwater footage of Baikal''s deep-lake ecosystem at the museum","Take a final photograph of the lake from the Listvianka waterfront as the sun sets"]', 'https://images.pexels.com/photos/5643618/pexels-photo-5643618.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  83, 'Ice Walking in Winter', 'Walk across the frozen surface of the world''s deepest lake, stepping over cracked turquoise ice and listening to the lake boom beneath your feet.', 'Mountain', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  83, 'Olkhon Island Trekking', 'Hike the Great Baikal Trail along Olkhon''s dramatic cliff-top coastline to Cape Khoboy, with panoramic views over the lake''s endless blue expanse.', 'MapPin', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  83, 'Baikal Seal Spotting', 'Spot the world''s only exclusively freshwater seal — the nerpa — sunning on ice floes in winter or swimming near rocky shores in summer.', 'Heart', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  83, 'Hot Spring Soaking', 'Soak in natural geothermal springs on the lakeshore, watching steam rise over ice-blue water in one of Siberia''s most surreal natural experiences.', 'Waves', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  83, 'Buryat Cultural Immersion', 'Eat bozi dumplings in a Buryat village, learn shamanist traditions, and hear ancient stories of the lake spirits from local elders.', 'Globe', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  83, 'Stargazing', 'Olkhon Island has some of Russia''s darkest skies — on clear nights the Milky Way is visible as a solid band of light reflected in Baikal''s still water.', 'Lightbulb', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  83, 'Irkutsk is the gateway — fly from Moscow (5 hours) or take the Trans-Siberian Railway for a legendary 4-day train journey.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  83, 'Winter (January–March) is the most dramatic season — frozen blue ice, ice sculptures, and seals on floes — but temperatures drop to –20 °C or below; dress in layers.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  83, 'Book Olkhon Island accommodation well in advance for July–August; the island has limited guesthouses.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  83, 'The Baikal omul fish is unique to the lake — smoked omul from Listvianka market is a must-try experience and an excellent gift.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  83, 'Hire a local guide on Olkhon Island — many trails are unmarked and local knowledge of weather, ice conditions, and sacred Buryat sites is invaluable.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  83, 'Water straight from Lake Baikal is safe to drink (one of the purest water sources on Earth) — a remarkable experience.', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  83, 'Be aware that some areas near Baikal have restricted access or require permits; check with your guide before exploring off-trail areas.', 6
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  83, 'https://images.pexels.com/photos/7127420/pexels-photo-7127420.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
