INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'marrakech', 'Marrakech', 'Morocco', 'Africa', 
  'The Red City — where Sufi mysticism, vibrant souqs, and Saharan winds converge', 'https://images.pexels.com/photos/36209321/pexels-photo-36209321.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 'Marrakech assaults the senses and then seduces them. The ancient medina, encircled by 19 kilometres of rose-red ramparts, is one of the world''s most intoxicating urban labyrinths: a tangle of alleys where donkeys brush past tourists, the air is thick with cumin, cedar, and tanned leather, and artisans hammer copper, weave silk, and chisel zellige mosaics exactly as their ancestors did centuries ago. At the centre of it all pulses Jemaa el-Fnaa, the medina''s vast central square, a UNESCO-recognised ''Masterpiece of Oral and Intangible Heritage'' where storytellers, musicians, snake charmers, and food vendors create a nightly carnival that has run uninterrupted for a thousand years.

Beyond the mayhem, Marrakech reveals moments of profound calm: the Jardin Majorelle, a cobalt-blue botanical garden lovingly restored by Yves Saint Laurent; the Saadian Tombs, sealed for centuries and rediscovered in 1917 with their cedar ceilings and Italian marble intact; the Ben Youssef Madrasa, whose courtyard of carved stucco and zellige tilework is among the finest in the Islamic world. The Bahia Palace, with 150 rooms arranged around orange-tree courtyards and painted cedar ceilings, captures the opulence of 19th-century Moroccan power.

Marrakech is also a gateway: the snow-capped Atlas Mountains rise just an hour''s drive south, offering trekking to Berber villages and the summit of Jebel Toubkal, North Africa''s highest peak. The Agafay Desert, 30 minutes from the medina, provides a Saharan landscape of stone and sand without the 10-hour drive. In Marrakech, the medieval and the modern exist not in tension but in conversation, making it one of the most creatively alive cities on the planet.', 
  -8, 31.63, 'Spiritual', 'bg-violet-500', 
  'Sufi shrines, medina prayers, vibrant souqs, and Jemaa el-Fnaa magic.', '/images/tour-11.jpg', 
  'published', '', '5 Days', 
  'Rabat', 'Moroccan Dirham (MAD)', 'Semi-arid with hot, dry summers and mild, occasionally rainy winters', 'March–May & September–November (comfortable temperatures for exploration)', 
  'Darija (Moroccan Arabic), French, Tamazight, some English', 'WET (UTC+0) / WEST (UTC+1 in summer)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  84, 1, 'Medina, Ben Youssef & Jemaa el-Fnaa', 'Marrakech Medina', 
  'Plunge into the medina to explore the Ben Youssef Madrasa, whose courtyard of carved stucco, cedar, and zellige tilework is a masterpiece of Islamic art. Wander the dyers'' souk, the copper-workers'' alley, and the tanners'' quarter before ending at Jemaa el-Fnaa as the sun sets and the night market ignites with smoke, music, and story.', '["Admire the carved stucco and zellige courtyard of Ben Youssef Madrasa","Watch leather being dyed in the ancient Chouara Tannery vats","Navigate the copper, spice, and textile souqs of the medina","Experience Jemaa el-Fnaa at night with its musicians, storytellers, and food stalls"]', 'https://images.pexels.com/photos/36209321/pexels-photo-36209321.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  84, 2, 'Bahia Palace, Saadian Tombs & Jardin Majorelle', 'Marrakech', 
  'Tour the Bahia Palace''s 150 painted-cedar rooms and orange-tree courtyards, then visit the Saadian Tombs, hidden for centuries behind a sealed wall. In the afternoon, find peace in the cobalt-blue Jardin Majorelle, Yves Saint Laurent''s botanical sanctuary now housing a Berber Museum and a fashion archive.', '["Walk through the Bahia Palace''s painted cedar ceilings and tiled courtyards","Discover the Saadian Tombs, sealed in 1603 and rediscovered in 1917","Stroll the cobalt-blue pathways of Jardin Majorelle amid cacti and palms","Visit the Musée Yves Saint Laurent next door for haute couture retrospectives"]', 'https://images.pexels.com/photos/36599126/pexels-photo-36599126.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  84, 3, 'Atlas Mountains & Berber Villages', 'Ourika Valley & Imlil', 
  'Drive into the High Atlas through the Ourika Valley, stopping at Berber villages clinging to the mountainside and at a Saffron farm. Continue to Imlil, the base camp for Jebel Toubkal, for a guided hike through walnut groves and terraced fields, followed by a traditional Berber tagine lunch in a village home.', '["Drive through the Ourika Valley with the snow-capped Atlas above","Visit a Berber village and learn how saffron is harvested by hand","Hike from Imlil through walnut groves and terraced fields","Feast on slow-cooked lamb tagine in a Berber mountain home"]', 'https://images.pexels.com/photos/972990/pexels-photo-972990.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  84, 4, 'Agafay Desert & Hammam Ritual', 'Agafay Desert & Marrakech', 
  'Head to the stone desert of Agafay for camel riding, quad biking, and a Saharan-style lunch in a luxury camp with views of the Atlas. Return to the city for a traditional hammam — a Moroccan steam bath with black soap scrub, ghassoul clay mask, and argan oil massage — the perfect end to a dusty desert day.', '["Ride camels across the stone desert of Agafay with Atlas Mountain views","Lunch in a luxury desert camp with Berber music and mint tea","Experience a traditional hammam with black soap and ghassoul clay","Relax with an argan oil massage in a lantern-lit spa"]', 'https://images.pexels.com/photos/35910043/pexels-photo-35910043.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  84, 5, 'Souq Shopping & Rooftop Farewell', 'Marrakech Medina & Guéliz', 
  'Spend the morning shopping the souqs with a local guide who reveals the artisans behind the goods: zellige tile workshops, brass-lamp makers, and leather-goods cooperatives. Cross to the modern Guéliz district for contemporary galleries and a farewell dinner on a rooftop terrace overlooking the Koutoubia Mosque minaret.', '["Visit artisan workshops hidden behind the souq stalls","Commission a custom leather bag or pair of babouche slippers","Explore Guéliz''s contemporary art galleries and concept stores","Toast farewell with a rooftop dinner overlooking the Koutoubia Mosque at night"]', 'https://images.pexels.com/photos/36209446/pexels-photo-36209446.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  84, 'Jemaa el-Fnaa by Night', 'Immerse yourself in the nightly carnival of storytellers, musicians, henna artists, and sizzling food stalls in Africa''s most vibrant square.', 'Globe', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  84, 'Souq Shopping & Artisan Workshops', 'Bargain for lanterns, leather, textiles, and spices in the medina''s labyrinthine souqs, and watch craftsmen at work in hidden ateliers.', 'MapPin', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  84, 'Moroccan Cuisine & Cooking Class', 'Learn to prepare tagine, couscous, and pastilla in a riad cooking class, then eat your creations on a lantern-lit terrace.', 'Utensils', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  84, 'Atlas Mountain Trekking', 'Hike through Berber villages, walnut groves, and terraced fields in the High Atlas, with the option to summit Jebel Toubkal.', 'Mountain', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  84, 'Traditional Hammam Experience', 'Surrender to a Moroccan steam bath ritual of black soap, eucalyptus steam, and ghassoul clay, finishing with argan oil.', 'Heart', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  84, 'Jardin Majorelle & Yves Saint Laurent', 'Wander the cobalt-blue garden paths of Majorelle and the adjacent Musée YSL, where Moroccan colour inspired haute couture.', 'Camera', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  84, 'Agree on a price before any purchase, ride, or service — haggling is expected and part of the culture.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  84, 'Navigate the medina using landmarks (mosques, fondouks) rather than GPS — alleys are narrow and often unnamed.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  84, 'Stay in a riad (traditional courtyard house) for the most authentic experience — many are beautifully restored.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  84, 'Carry small denominations of Moroccan Dirham — many vendors and taxi drivers don''t carry change for large bills.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  84, 'Tap water is not safe to drink; bottled water is cheap and available everywhere.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  84, 'Dress modestly in the medina — women should cover shoulders and knees to avoid unwanted attention.', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  84, 'Friday is the main prayer day; many shops in the medina close for several hours around midday.', 6
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  84, 'https://images.pexels.com/photos/36209321/pexels-photo-36209321.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
