INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'fes', 'Fes', 'Morocco', 'Africa', 
  'The world''s oldest university city — medieval medina, master artisans, and timeless craft traditions', 'https://images.pexels.com/photos/5518970/pexels-photo-5518970.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 'Fes el-Bali is the world''s largest car-free urban zone and, arguably, the planet''s most intact medieval city — a 1,200-year-old living labyrinth of 9,400 alleys where donkeys are still the primary freight transport and the call to prayer from 360 mosques ripples across rooftops in overlapping waves. Founded in 808 CE by Idris II, Fes grew around the Quaraouiyine Mosque and its affiliated university — recognized by UNESCO as the world''s oldest continuously operating university, established in 859 CE by a woman, Fatima al-Fihri.

The tanneries of Fes el-Bali are the city''s most iconic sight: ancient stone vats filled with pigeon dung, pomegranate, saffron, henna, and poppy, where craftsmen dye leather using techniques unchanged since the 11th century. Viewed from the terraces of the surrounding leather shops, the geometric pattern of vats in primary colors is one of the most arresting images in travel photography. In the brass-worker souk, hammers beat out intricate geometric patterns on copper platters by ear; in the carpet souk, Berber weavers produce kilims with a tribal vocabulary encoded in each diamond and chevron.

Beyond the medina walls, the ruins of Merenid tombs on the hill above the city provide the finest overview of Fes at sunset, when the minarets catch the last light and the city''s 10,000 artisans are winding down for the evening. Fes is not a destination that surrenders its secrets quickly — but for travelers willing to get lost, it rewards with the rare sensation of stepping through time.', 
  -5, 34.03, 'Education', 'bg-indigo-500', 
  'Field trips to Al-Qarawiyyin (world''s oldest university), leather tannery workshops, pottery factories, and Moorish architecture.', '/images/tour-12.jpg', 
  'published', '', '5 Days', 
  NULL, 'Moroccan Dirham (MAD)', 'Mediterranean semi-arid; hot summers (up to 40°C), mild winters', 'March–May and September–November for pleasant temperatures', 
  'Darija (Moroccan Arabic), Tamazight, French, some Spanish', 'WET (UTC+1, with WEST UTC+2 in summer)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  85, 1, 'Fes el-Bali — the Ancient Medina', 'Fes el-Bali (Old Fes)', 
  'Enter through Bab Bou Jeloud, the ornate blue-tiled gate to the old medina, and plunge into the warren of alleys. Navigate to the Bou Inania Madrasa, a masterpiece of Marinid architecture covered in zellij tile, carved stucco, and cedarwood — then wind through the brass-workers, spice sellers, and herb markets to the tanneries.', '["Enter Fes el-Bali through the stunning blue-tiled Bab Bou Jeloud gate","Explore Bou Inania Madrasa''s intricate zellij tilework and carved stucco","Watch leather dyers working the medieval tanneries from a rooftop terrace","Navigate the brass and copper souk where artisans work by candlelight"]', 'https://images.pexels.com/photos/5518970/pexels-photo-5518970.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  85, 2, 'Al-Quaraouiyine Mosque & University', 'Fes el-Bali', 
  'Visit the exterior of the Al-Quaraouiyine complex — the world''s oldest continuously operating university, founded 859 CE. Explore the Nejjarine Museum of Wooden Arts and Crafts in a restored 18th-century caravanserai, and spend the afternoon in the carpet souk learning to read Berber tribal symbols in kilim patterns.', '["Stand at the entrance of Al-Quaraouiyine Mosque and University (founded 859 CE)","Visit the Nejjarine Museum in a beautifully restored fondouk caravanserai","Join a carpet merchant for mint tea and a lesson in Berber weaving symbols","Photograph the 14th-century Attarine Madrasa''s honeycomb muqarnas ceiling"]', 'https://images.pexels.com/photos/951832/pexels-photo-951832.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  85, 3, 'Fes el-Jdid & Jewish Quarter', 'Fes el-Jdid', 
  'Explore Fes el-Jdid (New Fes), built in the 13th century as the royal quarter, including the vast Dar al-Makhzen Royal Palace with its ornate brass-studded gates. Walk through the Mellah (Jewish Quarter), one of Morocco''s oldest, with its distinctive overhanging balconied houses and the Ibn Danan Synagogue.', '["Photograph the seven ornate gates of the Dar al-Makhzen Royal Palace","Explore the historic Mellah Jewish Quarter and its ornate balconied streets","Visit the Ibn Danan Synagogue — one of Morocco''s finest 17th-century synagogues","Try bastilla (pigeon and almond pastilla) at a Fes el-Jdid traditional restaurant"]', 'https://images.pexels.com/photos/5518970/pexels-photo-5518970.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  85, 4, 'Merenid Tombs Sunset & Cooking Class', 'Above Fes el-Bali', 
  'Hike up to the 14th-century Merenid Tombs for the finest panoramic view over the medina''s sea of minarets and green-tiled rooftops. Return to the medina for an afternoon Moroccan cooking class — learning to prepare harira, tagine, and msemen flatbread in a riad''s kitchen.', '["Watch sunset over Fes''s 10,000 rooftops from the Merenid Tombs hilltop","Photograph the medina''s green-tiled mosque rooftops and minarets at golden hour","Join a traditional Moroccan cooking class in an old medina riad","Learn to grind spices and fold msemen flatbread with a local chef"]', 'https://images.pexels.com/photos/5505076/pexels-photo-5505076.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  85, 5, 'Volubilis Roman Ruins Day Trip', 'Volubilis & Moulay Idriss', 
  'Drive 60 km to Volubilis — one of the best-preserved Roman outposts in North Africa — where 3rd-century mosaic floors still gleam in the Moroccan sun. Continue to the white hillside town of Moulay Idriss, the most sacred city in Morocco, built around the tomb of the country''s founder.', '["Walk through Volubilis''s Triumphal Arch and mosaic floors (UNESCO World Heritage Site)","See intricate 3rd-century Roman hunting and mythology mosaics in situ","Visit the white hilltop sanctuary town of Moulay Idriss Zerhoun","Return to Fes for a final dinner of mechoui (roasted lamb) in the medina"]', 'https://images.pexels.com/photos/5503391/pexels-photo-5503391.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  85, 'Tannery Rooftop Viewing', 'Watch the ancient leather dyeing process from a rooftop terrace above the Chouara Tanneries — one of travel photography''s most iconic scenes.', 'Camera', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  85, 'Al-Quaraouiyine Visit', 'Stand before the world''s oldest continuously operating university, founded in 859 CE by a Moroccan woman — a living monument to Islamic scholarship.', 'Landmark', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  85, 'Berber Carpet Weaving', 'Sit with a Berber weaver in the carpet souk and learn the tribal language encoded in kilim diamond patterns over mint tea.', 'GraduationCap', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  85, 'Moroccan Cooking Class', 'Master harira soup, chicken tagine with preserved lemon, and msemen flatbread in a medina riad''s traditional kitchen.', 'Utensils', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  85, 'Merenid Tombs Sunset', 'Climb to the 14th-century Merenid Tombs at sunset for a panoramic view over the medina''s minarets and green-tiled rooftops.', 'Mountain', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  85, 'Volubilis Roman Ruins', 'Visit UNESCO-listed Volubilis — North Africa''s finest Roman ruins — where 3rd-century mosaic floors survive beneath the Moroccan sky.', 'MapPin', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  85, 'Hire a licensed guide for your first day in Fes el-Bali — the 9,400 alleys are designed to disorient, and unofficial ''guides'' will lead you to commission shops.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  85, 'Carry a small bundle of fresh mint leaves — hold them to your nose near the tanneries, where the smell of natural dyeing agents is pungent.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  85, 'Bargaining is expected in every souk; the starting price is typically 3–5 times the fair value, so negotiate calmly and walk away if needed.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  85, 'Download offline maps (Maps.me or Google Maps offline) before entering the medina — GPS signals are unreliable inside the dense alleys.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  85, 'Dress modestly — long trousers and covered shoulders for both men and women — as Fes is more conservative than Marrakech.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  85, 'Book a riad inside the medina for the full immersive experience; they are often dramatically underpriced compared to modern hotels.', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  85, 'The best light for photography is early morning (7–9 a.m.) when alleys are quiet and golden light filters through the rooftop gaps.', 6
);
