INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'cape-town', 'Cape Town', 'South Africa', 'Africa', 
  'Table Mountain, Cape Winelands, and stunning coastal drives at Africa''s southern tip', 'https://images.pexels.com/photos/36026470/pexels-photo-36026470.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 'Cape Town is where Africa achieves its most dramatic and seductive expression — a city of 4 million pinned between the flat-topped improbability of Table Mountain and the collision of two oceans, where penguin colonies share beach real estate with sunbathers and great white sharks patrol waters within sight of luxury beach hotels. Nicknamed the ''Mother City,'' Cape Town is South Africa''s oldest European settlement, founded in 1652 as a refreshment station for Dutch East India Company ships rounding the Cape of Good Hope, and its layered history of colonial settlement, apartheid, and remarkable democratic transition is readable in every neighborhood.

Table Mountain — a UNESCO World Heritage Site and one of the New Seven Wonders of Nature finalists — dominates the skyline from every direction, its famous ''tablecloth'' cloud pouring over the edges on summer afternoons. The cable car whisks visitors to the flat summit in seven minutes, where fynbos-covered rock platforms offer 360-degree views extending to Robben Island where Nelson Mandela was imprisoned for 18 years. The island is now a museum, and former political prisoners serve as guides.

Beyond the mountain, the Cape Peninsula drive to the Cape of Good Hope is one of the world''s great road trips: penguins at Boulders Beach, baboons on the clifftop road, enormous surf at Noordhoek, and the convergence of the Indian and Atlantic Oceans at Cape Point. The Winelands town of Stellenbosch — an hour''s drive east — produces Pinotage, Chenin Blanc, and Sauvignon Blanc among oak-lined streets of Dutch colonial architecture. Cape Town is a city that defies single definition and rewards every angle of exploration.', 
  18.42, -33.93, 'Nature', 'bg-teal-500', 
  'Table Mountain, Cape Winelands, and stunning coastal drives.', '/images/dest-21.jpg', 
  'published', '', '5 Days', 
  NULL, 'South African Rand (ZAR)', 'Mediterranean; warm dry summers (Dec–Feb, 25°C), cool wet winters (Jun–Aug)', 'November–March for beaches and outdoor activities; May–September for whale watching', 
  'Afrikaans, Xhosa, English (all widely spoken)', 'SAST (UTC+2)', 'Left'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  86, 1, 'Table Mountain & Waterfront', 'Table Mountain & V&A Waterfront', 
  'Take the rotating aerial cableway to Table Mountain''s flat summit for views of the city, peninsula, and both oceans. Explore the fynbos-covered plateau on marked trails before descending for an afternoon at the V&A Waterfront — Cape Town''s restored Victorian harbor with restaurants, craft markets, and the Two Oceans Aquarium.', '["Ride the rotating cable car to Table Mountain''s 1,086-metre flat summit","Walk the Dassie Trail on the summit for panoramic views over Cape Town and Robben Island","Browse the V&A Waterfront craft market for African artisan goods","Dine at a waterfront restaurant with views of the working harbor and Signal Hill"]', 'https://images.pexels.com/photos/36026470/pexels-photo-36026470.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  86, 2, 'Cape Peninsula & Penguins', 'Cape Peninsula Drive', 
  'Drive the Cape Peninsula''s Atlantic coast from Sea Point through Camps Bay and Hout Bay, stopping at the Boulders Beach African Penguin Colony where 3,000 jackass penguins nest between granite boulders. Continue to Cape Point''s lighthouse for views over both oceans, and return via the False Bay coast past whale-watching spots.', '["Walk among African penguins on the boardwalk at Boulders Beach","Stand at Cape Point Lighthouse where the Atlantic and Indian oceans visually merge","Photograph the surfers at Noordhoek''s endless white-sand beach","Spot southern right whales from the cliffs above False Bay (July–November)"]', 'https://images.pexels.com/photos/2407103/pexels-photo-2407103.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  86, 3, 'Robben Island & Bo-Kaap', 'Robben Island & Bo-Kaap', 
  'Take the ferry to Robben Island where Nelson Mandela spent 18 years — a former political prisoner will guide you through the Maximum Security Prison and Mandela''s lime-quarry cell. Return to the city for the Bo-Kaap neighborhood, where brightly painted Cape Malay houses line cobblestone streets and the Noon Gun has fired daily since 1806.', '["Tour Robben Island Maximum Security Prison with a former political prisoner guide","See Nelson Mandela''s cell and lime quarry in the cold Atlantic island air","Walk the vibrant painted streets of Bo-Kaap and eat Cape Malay curry","Visit the Bo-Kaap Museum for the story of Cape Town''s Islamic community"]', 'https://images.pexels.com/photos/136721/pexels-photo-136721.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  86, 4, 'Stellenbosch Winelands', 'Stellenbosch & Franschhoek', 
  'Drive east through the Winelands to Stellenbosch — South Africa''s second-oldest European settlement — where Dutch colonial homesteads shelter among rolling vineyards producing Pinotage and Chenin Blanc. Tasting sessions at two or three estates, lunch on a wine farm terrace, and a walk through Stellenbosch''s oak-lined streets complete the day.', '["Wine taste at two Cape Winelands estates for Pinotage and Sauvignon Blanc","Walk the oak-canopied streets of Stellenbosch''s historic town center","Lunch on a wine estate terrace with vineyard and mountain views","Drive through Franschhoek Pass for dramatic Cape mountain valley scenery"]', 'https://images.pexels.com/photos/5494693/pexels-photo-5494693.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  86, 5, 'Kalk Bay, Constantia & Final Sunset', 'Southern Suburbs & Kalk Bay', 
  'Browse the antique shops and galleries of Kalk Bay fishing village along the False Bay shore, then visit the Groot Constantia wine estate — South Africa''s oldest wine farm, established in 1685. End the trip on Signal Hill or Lion''s Head at sunset for a 360-degree farewell panorama of the city, mountain, and Atlantic Ocean.', '["Browse Kalk Bay''s eclectic antique shops and fish-and-chip stands by the harbor","Visit Groot Constantia — South Africa''s oldest wine farm and historic Cape Dutch manor","Hike Lion''s Head at sunset for a 360-degree panorama above the city","Watch the sun sink into the Atlantic Ocean from Signal Hill"]', 'https://images.pexels.com/photos/3886665/pexels-photo-3886665.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  86, 'Table Mountain Cable Car', 'Ride the rotating aerial cableway to Table Mountain''s UNESCO-listed flat summit for 360-degree views over Cape Town and both oceans.', 'Mountain', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  86, 'Boulders Beach Penguins', 'Walk among 3,000 African penguins at Boulders Beach — one of very few places in the world where you can get this close to wild penguins.', 'Camera', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  86, 'Robben Island Tour', 'Cross the Atlantic to Robben Island and tour Nelson Mandela''s prison cell with a guide who lived the same history.', 'Landmark', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  86, 'Cape Winelands Tasting', 'Explore the estates of Stellenbosch and Franschhoek for Pinotage, Chenin Blanc, and Cape Malay cuisine among mountain vineyards.', 'Heart', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  86, 'Cape Peninsula Drive', 'Drive from Cape Town to Cape Point — where two oceans meet — passing dramatic coastline, baboons, and surf beaches.', 'MapPin', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  86, 'Whale Watching', 'Between July and November, southern right whales bring their calves to False Bay''s sheltered waters, visible from shore cliffs.', 'Waves', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  86, 'Cape Town is safer in tourist areas than its reputation suggests, but avoid walking alone after dark in the CBD and take Uber or Bolt for transport.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  86, 'Book the Table Mountain cable car for early morning — clouds (''the tablecloth'') roll in by early afternoon and can close the cable car for hours.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  86, 'Book Robben Island ferry tickets at least a week ahead online — daily capacity is limited and tours frequently sell out.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  86, 'The Boulders Beach penguin boardwalk requires an entrance fee; the free beach area gives a partial view but is worth the paid access.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  86, 'Rent a car for the Cape Peninsula drive — public transport doesn''t reach most key stops on the route efficiently.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  86, 'Cape Town''s best restaurant scene is in the City Bowl, De Waterkant, and Woodstock — book ahead for popular spots.', 5
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  86, 'Tipping is expected and important in South Africa — 10–15% at restaurants, R10–20 per bag for car guards and hotel porters.', 6
);
