INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  '5d-4n-phnom-penh-2n-siem-reap-2n', '5D/4N - Phnom Penh 2N + Siem Reap 2N', 'Cambodia', 'Southeast Asia', 
  'Explore Phnom Penh''s royal heritage and Siem Reap''s ancient wonders', '/images/cambodia/3-Cambodia.jpg', 'Experience the best of Cambodia with this 5-day journey. Begin in Phnom Penh, the vibrant capital, where you''ll visit the Royal Palace, Silver Pagoda, and take a sunset cruise on the Mekong River. Next, travel to Siem Reap to marvel at the magnificent Angkor Wat and the ancient city of Angkor Thom, including Bayon, Ta Prohm, and sunset from Bakheng Mountain. This comprehensive tour blends royal heritage, spiritual architecture, and local life.', 
  104.92, 11.56, 'Historical', 'bg-amber-600', 
  'Explore Phnom Penh''s royal heritage and Siem Reap''s ancient wonders.', '/images/dest-5.jpg', 
  'published', '', '5 Days', 
  'Phnom Penh', 'Cambodian Riel (KHR) & US Dollar (USD)', 'Tropical monsoon — hot year-round, wet May–October', 'November–February (cool, dry season)', 
  'Khmer, English', 'ICT (UTC+7)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  90, 1, 'Phnom Penh Arrival, Transfer In / Free Leisure / No Guide', 'Phnom Penh', 
  'Welcome to Phnom Penh Airport or Bus station, welcome and transfer to hotel by driver, Free at own leisure. (Standard Check in time: 1400, Early Check in up on availability) Overnight in your selected hotel, Phnom Penh.', '["Welcome and pickup from airport or bus station in Phnom Penh","Transfer to hotel by private driver","Free at own leisure to rest or explore the capital city"]', '/images/cambodia/Cambodia-2.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  90, 2, 'Phnom Penh Sightseeing (B)', 'Phnom Penh', 
  'Visit The Royal Palace, Silver Pagoda, Independence Monument, Wat Phnom, Central Market for shopping, Wat Ounalom, and later, enjoy a one-hour sunset cruise along the Mekong River to enjoy the sunset. Return to hotel and free at your own time.', '["Visit the Royal Palace complex and Silver Pagoda national treasures","Explore the historic Independence Monument and Wat Phnom hill temple","Shopping at the popular Central Market with local eateries","One-hour Mekong River sunset cruise with fresh breeze"]', '/images/cambodia/Cambodia-1.jpg', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  90, 3, 'Phnom Penh Sightseeing – Transfer to Siem Reap, Local Tour (B)', 'Phnom Penh & Siem Reap', 
  'Breakfast in hotel and check out. Transfer to Bus station for leaving to Siem Reap (6 hours drive/ no guide, bus ticket included). Arrival Siem Reap, welcome and transfer to hotel check in. Afternoon, visit Senteurs d''Angkor Workshop, Wat Bo (one of the oldest Buddhist temples in Siem Reap), Wat Preah Prom Rath, and visit Street food at Street 60 where you can see local people gathering in the evening.', '["6-hour scenic bus transfer from Phnom Penh to Siem Reap (ticket included)","Visit Senteurs d''Angkor Workshop to see natural plant products","Explore the ancient Wat Bo and beautiful Wat Preah Prom Rath pagodas","Mingle with locals and try evening street food at Street 60"]', '/images/cambodia/Cambodia-4.jpg', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  90, 4, 'Angkor Wat, Angkor Thom City Complex (B)', 'Siem Reap', 
  'With your professional tour guide, go discover the world''s Greatest Monument - Angkor Wat. Next, explore the Great Angkor City of Khmer Empire. Start at South gate of Angkor Thom. Visit Bayon Temple, Baphuon, the Terrace of the Elephants, and the Terrace of the Leper King. Afternoon visit to the hidden jungle temple of Ta Prohm. Climb Bakheng Mountain to view the most beautiful sunset.', '["Explore the magnificent and grand temple of Angkor Wat","See the South Gate of Angkor Thom and Bayon''s smiling stone faces","Wander through Ta Prohm, the jungle temple with tree roots","Climb Bakheng Mountain for a panoramic sunset view"]', '/images/cambodia/Cambodia-5.jpg', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  90, 5, 'Transfer to Siem Reap Airport (SAI) (B) / No Guide', 'Siem Reap', 
  'Breakfast in hotel. Free at your own enjoyment till time transfer to airport for flight back home or connecting countries with the unforgettable trip in Cambodia. (A WONDERFUL JOURNEY ☺)', '["Enjoy breakfast at the hotel","Free time for last-minute souvenir shopping in Siem Reap","Driver transfer to Siem Reap Angkor International Airport (SAI)"]', '/images/cambodia/Cambodia-9.jpg', 4
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  90, 'Royal Palace & Pagodas', 'Explore the stunning Royal Palace and Silver Pagoda, featuring a floor of 5,329 solid silver tiles and national treasures.', 'Landmark', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  90, 'Angkor Temple Exploration', 'Discover Angkor Wat, the largest religious monument in the world, along with Bayon and the jungle temple of Ta Prohm.', 'MapPin', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  90, 'Mekong Sunset Cruise', 'Enjoy a peaceful one-hour cruise along the Mekong River, watching the sunset over Phnom Penh''s riverfront.', 'Waves', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  90, 'Local Natural Crafts', 'Visit Senteurs d''Angkor to learn how local soaps, balms, and oils are made from natural Cambodian plants.', 'ShoppingBag', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  90, 'Cambodia E-Visa costs US$ 35 and can be processed online, or obtain a Visa-on-arrival for US$ 30 cash (bring 2 passport photos).', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  90, 'US Dollars (USD) are widely accepted for most transactions; Cambodian Riel is primarily used as change for amounts under $1.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  90, 'Dress modestly when visiting temples: shoulders and knees must be covered at all times.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  90, 'Keep hydrated during the temple walks; carry bottled water and wear comfortable, sturdy shoes.', 3
);
