INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  '3d-2n-siem-reap-2n', '3D/2N - Siem Reap 2N', 'Cambodia', 'Southeast Asia', 
  'A quick getaway to explore the ancient temples of Angkor', '/images/cambodia/CB4-600x350.jpg', 'Perfect for travelers short on time, this 3-day tour takes you straight to the heart of Angkor. Discover the main highlights of the Angkor Archaeological Park, including the majestic Angkor Wat, Bayon Temple, the Terrace of Elephants, and the root-strangled Ta Prohm. Wrap up your evenings enjoying the lively atmosphere of Siem Reap.', 
  103.86, 13.36, 'Historical', 'bg-amber-600', 
  'A quick getaway to explore the ancient temples of Angkor.', '/images/dest-4.jpg', 
  'published', '', '3 Days', 
  'Phnom Penh', 'Cambodian Riel (KHR) & US Dollar (USD)', 'Tropical monsoon — hot and humid year-round', 'November–March (cool, dry season)', 
  'Khmer, English', 'ICT (UTC+7)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  91, 1, 'Siem Reap Airport (SAI) - Arrival, Transfer In / Free Leisure / No Guide', 'Siem Reap', 
  'Welcome to Siem Reap Angkor International Airport, clear your immigration and head to arrival hall where your driver is waiting with your name tag. We drive from airport to city center (one-hour drive). Hotel check in and free at your own leisure. (Standard Check in time: 1400, Early Check in up on availability) Overnight in Siem Reap.', '["Driver pickup from Siem Reap Angkor International Airport (SAI)","1-hour scenic drive to Siem Reap city center","Free leisure to relax or explore the local Pub Street area"]', '/images/cambodia/Cambodia-Map.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  91, 2, 'Angkor Wat, Angkor Thom City Complex (B)', 'Siem Reap', 
  'Discover Angkor Wat, the largest temple in the world. Next, explore the Great Angkor City of Khmer Empire. Start at South gate of Angkor Thom. Visit Bayon Temple, Baphuon, the Terrace of the Elephants, and the Terrace of the Leper King. Afternoon visit to the hidden jungle temple of Ta Prohm. Climb Bakheng Mountain to view the most beautiful sunset.', '["Explore the grand Angkor Wat temple with a guide","See the smiling stone faces of Bayon and South Gate of Angkor Thom","Discover Ta Prohm temple, famous for tree roots growing out of ruins","Enjoy panoramic sunset views from Bakheng Mountain"]', '/images/cambodia/Cambodia-5.jpg', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  91, 3, 'Transfer to Siem Reap Airport (SAI) (B) / No Guide', 'Siem Reap', 
  'Breakfast in hotel. Free at your own enjoyment till time transfer to airport for flight back home or connecting countries with the unforgettable trip in Cambodia. (A WONDERFUL JOURNEY ☺)', '["Enjoy breakfast at the hotel","Free morning in Siem Reap for last-minute shopping","Driver transfer to Siem Reap Airport"]', '/images/cambodia/Cambodia-9.jpg', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  91, 'Angkor Wat Exploration', 'Explore the legendary 12th-century temple complex, renowned for its massive scale and detailed bas-reliefs.', 'Landmark', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  91, 'Bayon Smile Carvings', 'Study the 216 giant smiling stone faces of Bayon, standing tall at the center of ancient Angkor Thom.', 'Smile', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  91, 'Ta Prohm Roots', 'Photograph the trees growing out of ancient temple walls at Ta Prohm, left in its natural state.', 'Trees', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  91, 'Bakheng Sunset Climb', 'Climb Phnom Bakheng temple hill to witness the sunset over the Angkor plains and Tonle Sap in the distance.', 'Sun', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  91, 'Obtain your Cambodia E-Visa online in advance to skip the visa-on-arrival queue at the airport.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  91, 'Bring clean, crisp US Dollar bills — banknotes with even tiny tears may be rejected by merchants.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  91, 'Hire a local tuk-tuk for affordable and breeze-filled transport around Siem Reap town.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  91, 'Wear light, breathable clothing and high-factor sunscreen to handle the daytime heat.', 3
);
