INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  '4d-3n-siem-reap-3n', '4D/3N – Siem Reap 3N', 'Cambodia', 'Southeast Asia', 
  'Ancient temples of Angkor and the floating world of Tonle Sap', '/images/cambodia/CB3-600x350.jpg', 'Delve deeper into the charm of Siem Reap with this 4-day package. Spend one full day uncovering the architectural wonders of Angkor, including Angkor Wat, Bayon, and Ta Prohm. On the third day, embark on a scenic boat ride on Tonle Sap Lake to visit floating villages, explore the West Baray reservoir, and taste delicious Cambodian street food.', 
  103.86, 13.36, 'Historical', 'bg-amber-600', 
  'Ancient temples of Angkor and the floating world of Tonle Sap.', '/images/dest-6.jpg', 
  'published', '', '4 Days', 
  'Phnom Penh', 'Cambodian Riel (KHR) & US Dollar (USD)', 'Tropical monsoon — hot year-round', 'November–February (cool, dry, pleasant)', 
  'Khmer, English', 'ICT (UTC+7)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  92, 1, 'Siem Reap Airport (SAI) - Arrival, Transfer In / Free Leisure / No Guide', 'Siem Reap', 
  'Welcome to Siem Reap Angkor International Airport, clear your immigration and head to arrival hall where your driver is waiting with your name tag. We drive from airport to city center (one-hour drive). Hotel check in and free at your own leisure. (Standard Check in time: 1400, Early Check in up on availability) Overnight in Siem Reap.', '["Airport pickup by private driver at SAI Airport","1-hour drive through Cambodian countryside to the hotel","Free evening to explore the local night markets or Pub Street"]', '/images/cambodia/Cambodia-Map.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  92, 2, 'Angkor Wat, Angkor Thom City Complex (B)', 'Siem Reap', 
  'Discover Angkor Wat, the largest temple in the world. Next, explore the Great Angkor City of Khmer Empire. Start at South gate of Angkor Thom. Visit Bayon Temple, Baphuon, the Terrace of the Elephants, and the Terrace of the Leper King. Afternoon visit to the hidden jungle temple of Ta Prohm. Climb Bakheng Mountain to view the most beautiful sunset.', '["Full day tour of Angkor Archaeological Park","Explore the main structures of Angkor Wat and Angkor Thom","See the giant tree roots reclaiming the stone corridors of Ta Prohm","Spectacular sunset from Bakheng Mountain"]', '/images/cambodia/Cambodia-5.jpg', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  92, 3, 'Boat Trip, Local Tour (B)', 'Siem Reap & Tonle Sap', 
  'Breakfast in hotel and start tour at 08:30. Tour guide picks up from hotel lobby. Visit Tonle Sap, the largest freshwater lake in Asia. Get in a wooden boat, visit floating villages of residents, see how they live and make their living on floating houses. Enjoy the view of floating markets, floating schools, pagodas, health centers. Continue to visit Senteurs d''Angkor Workshop and West Baray, the largest hand-cut water reservoir in Cambodia. In the evening, visit Street food at Street 60.', '["Wooden boat cruise on Tonle Sap Freshwater Lake","See floating villages, schools, and markets of local residents","Visit Senteurs d''Angkor natural craft workshop","Visit West Baray reservoir and enjoy evening street food at Street 60"]', '/images/cambodia/Cambodia-9.jpg', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  92, 4, 'Transfer to Siem Reap Airport (SAI) (B) / No Guide', 'Siem Reap', 
  'Breakfast in hotel. Free at your own enjoyment till time transfer to airport for flight back home or connecting countries with the unforgettable trip in Cambodia. (A WONDERFUL JOURNEY ☺)', '["Enjoy breakfast at the hotel","Free morning for shopping or exploring town","Transfer to airport by private driver"]', '/images/cambodia/Cambodia-Map.jpg', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  92, 'Tonle Sap Boat Cruise', 'Cruise on Southeast Asia''s largest freshwater lake, visiting stilted homes, floating schools, and floating markets.', 'Waves', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  92, 'Angkor Wat & Thom Tour', 'Explore the ancient walled city of Angkor Thom and the massive, beautifully preserved temple of Angkor Wat.', 'Landmark', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  92, 'West Baray Reservoir', 'Visit the enormous 11th-century artificial lake, a historic engineering marvel and local weekend retreat.', 'MapPin', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  92, 'Street 60 Culinary Tour', 'Taste traditional Cambodian street snacks alongside locals at the bustling Street 60 evening market.', 'Utensils', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  92, 'Select a community-based boat tour to ensure your visit directly supports the floating village families.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  92, 'Check the weather beforehand; floating village visits are best during high water levels (September to January).', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  92, 'Always remove hats and footwear before entering active pagoda prayer halls.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  92, 'Ensure you have cash in small bills ($1, $5, $10 USD) for buying snacks and souvenirs at markets.', 3
);
