INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  '4d-3n-phnom-penh-1n-siem-reap-2n', '4D/3N – Phnom Penh 1N + Siem Reap 2N', 'Cambodia', 'Southeast Asia', 
  'A classic journey spanning the capital and ancient Angkor', '/images/cambodia/CB5-600x350.jpg', 'Embark on a classic Cambodian adventure. Start in Phnom Penh, exploring the Royal Palace, Silver Pagoda, and Wat Phnom. Afterward, take a scenic 6-hour bus ride to Siem Reap, the gateway to Angkor. Dedicate a full day to discovering the breathtaking temples of Angkor Wat, Bayon, Ta Prohm, and watching the sunset from Bakheng Mountain.', 
  104.92, 11.56, 'Historical', 'bg-amber-600', 
  'A classic journey spanning the capital and ancient Angkor.', '/images/dest-11.jpg', 
  'published', '', '4 Days', 
  'Phnom Penh', 'Cambodian Riel (KHR) & US Dollar (USD)', 'Tropical monsoon — hot year-round', 'November–February (cool, dry season)', 
  'Khmer, English', 'ICT (UTC+7)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  93, 1, 'Phnom Penh Airport (PNH) - Arrival, Transfer In / Free Leisure / No Guide', 'Phnom Penh', 
  'Welcome to Phnom Penh Airport OR Bus station in Phnom Penh, welcome and transfer to hotel by driver, Free at own leisure. (Standard Check in time: 1400, Early Check in up on availability) Overnight in your selected hotel, Phnom Penh.', '["Driver pickup at Phnom Penh Airport or bus station","Transfer to hotel in Phnom Penh","Explore the Riverside promenade at your own pace"]', '/images/cambodia/Cambodia-2.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  93, 2, 'Phnom Penh Sightseeing – Transfer to Siem Reap (B)', 'Phnom Penh & Siem Reap', 
  'Breakfast in hotel and check out. 08:00: Visit The Royal Palace, Silver Pagoda, Independence Monument, Wat Phnom. Transfer to Bus station for leaving to Siem Reap (6 hours drive / no guide, bus ticket included). Arrival Siem Reap, driver transfer to hotel check in and overnight in Siem Reap.', '["Guided morning tour of Phnom Penh highlights","View the Silver Pagoda and Throne Hall at Royal Palace","6-hour bus transfer to Siem Reap with tickets included","Arrive and check in to Siem Reap hotel"]', '/images/cambodia/Cambodia-1.jpg', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  93, 3, 'Angkor Wat, Angkor Thom City Complex (B)', 'Siem Reap', 
  'Discover Angkor Wat, the largest temple in the world. Next, explore the Great Angkor City of Khmer Empire. Start at South gate of Angkor Thom. Visit Bayon Temple, Baphuon, the Terrace of the Elephants, and the Terrace of the Leper King. Afternoon visit to the hidden jungle temple of Ta Prohm. Climb Bakheng Mountain to view the most beautiful sunset.', '["Guided tour of magnificent Angkor Wat","See the South Gate of Angkor Thom and Bayon''s giant stone faces","Wander the ruined corridors of Ta Prohm overrun by trees","Watch the sunset from the Bakheng Mountain hill temple"]', '/images/cambodia/Cambodia-5.jpg', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  93, 4, 'Transfer to Siem Reap Airport (SAI) (B) / No Guide', 'Siem Reap', 
  'Breakfast in hotel. Free at your own enjoyment till time transfer to airport for flight back home or connecting countries with the unforgettable trip in Cambodia. (A WONDERFUL JOURNEY ☺)', '["Enjoy breakfast at the hotel","Free morning in Siem Reap for shopping","Transfer to airport by private driver"]', '/images/cambodia/Cambodia-9.jpg', 3
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  93, 'Royal Palace Complex', 'Explore the elegant Khmer architecture of Phnom Penh''s Royal Palace and the adjacent Silver Pagoda.', 'Landmark', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  93, 'Angkor Wat Wonders', 'Wander the corridors, courtyards, and libraries of the legendary Angkor Wat temple complex.', 'MapPin', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  93, 'Intercity Bus Journey', 'Travel like a local through Cambodia''s flat agricultural plains on a comfortable bus.', 'Bus', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  93, 'Independence Monument', 'Admire the lotus-spire monument constructed in 1958 to celebrate Cambodia''s independence from France.', 'Award', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  93, 'The intercity bus ride is approximately 6 hours; carry snacks, water, and headphones.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  93, 'Bring modest attire (covering shoulders and knees) for the Royal Palace and temple tours.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  93, 'Cambodia widely accepts US dollars, but notes must be in pristine condition (no markings or tears).', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  93, 'Stay hydrated during temple walks; buy fresh coconuts from vendors outside ruins.', 3
);
