INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  '6d-5n-phnom-penh-2n-siem-reap-3n', '6D/5N - Phnom Penh 2N + Siem Reap 3N', 'Cambodia', 'Southeast Asia', 
  'The ultimate Cambodian journey with Apsara dance and floating villages', '/images/cambodia/CB1-600x350.jpg', 'Experience the ultimate 6-day Cambodian exploration. Discover the grand capital of Phnom Penh, visiting the Royal Palace, Silver Pagoda, and cruising the Mekong River at sunset. Travel to Siem Reap to witness the legendary Angkor Wat and Angkor Thom complex. Cruise Tonle Sap Lake, visit local craft workshops, and culminate your journey with an unforgettable buffet dinner and traditional Apsara dance performance.', 
  104.92, 11.56, 'Historical', 'bg-amber-600', 
  'The ultimate Cambodian journey with Apsara dance and floating villages.', '/images/dest-11.jpg', 
  'published', '', '6 Days', 
  'Phnom Penh', 'Cambodian Riel (KHR) & US Dollar (USD)', 'Tropical monsoon — hot year-round', 'November–February (cool, dry season)', 
  'Khmer, English', 'ICT (UTC+7)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  94, 1, 'Phnom Penh Airport - Arrival, Transfer In / Free Leisure / No Guide', 'Phnom Penh', 
  'Welcome to Phnom Penh Airport OR Bus station in Phnom Penh, welcome and transfer to hotel by driver, Free at own leisure. (Standard Check in time: 1400, Early Check in up on availability) Overnight in your selected hotel, Phnom Penh.', '["Driver pickup at airport or bus station in Phnom Penh","Transfer to hotel in capital city","Free leisure to relax or walk along the riverfront"]', '/images/cambodia/Cambodia-2.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  94, 2, 'Phnom Penh Sightseeing (B)', 'Phnom Penh', 
  'Visit The Royal Palace, Silver Pagoda, Independence Monument, Wat Phnom, Central Market for shopping, Wat Ounalom, and later, enjoy a one-hour sunset cruise along the Mekong River. Overnight in Phnom Penh.', '["Visit the Royal Palace Throne Hall and Silver Pagoda","See Independence Monument and Wat Phnom","Free shopping time at Central Market","1-hour sunset cruise on Mekong River"]', '/images/cambodia/Cambodia-1.jpg', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  94, 3, 'Phnom Penh Sightseeing – Transfer to Siem Reap, Local Tour (B)', 'Phnom Penh & Siem Reap', 
  'Breakfast in hotel and check out. Transfer to Bus station for leaving to Siem Reap (6 hours drive/ no guide, bus ticket included). Arrival Siem Reap, welcome and transfer to hotel check in. Afternoon, visit Wat Bo (one of the oldest temples in Siem Reap) and Wat Preah Prom Rath. Visit Street food at Street 60 where you can see local people gathering.', '["Scenic 6-hour bus ride from Phnom Penh to Siem Reap (tickets included)","Visit Wat Bo pagoda, listed as a cool neighborhood in TimeOut","Visit Wat Preah Prom Rath riverside Buddhist temple","Explore the local evening food market at Street 60"]', '/images/cambodia/Cambodia-4.jpg', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  94, 4, 'Angkor Wat, Angkor Thom City Complex (B)', 'Siem Reap', 
  'Discover Angkor Wat, the largest temple in the world. Next, explore the Great Angkor City of Khmer Empire. Start at South gate of Angkor Thom. Visit Bayon Temple, Baphuon, the Terrace of the Elephants, and the Terrace of the Leper King. Afternoon visit to the hidden jungle temple of Ta Prohm. Climb Bakheng Mountain to view the most beautiful sunset.', '["Guided tour of the world-famous Angkor Wat temple","See the South Gate of Angkor Thom and Bayon''s giant stone faces","Walk through Ta Prohm jungle temple with tree roots","Sunset from the top of Bakheng Mountain"]', '/images/cambodia/Cambodia-5.jpg', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  94, 5, 'Boat Trip to Floating Village, Dinner with Apsara Dance (B/D)', 'Siem Reap & Tonle Sap', 
  'Breakfast in hotel and start tour at 08:30. Visit Tonle Sap, the largest freshwater lake in Asia. Board a private boat, visit floating villages of residents, see how they live and make their living on floating houses. Continue to "Chantiers Ecoles - Les Artisans d''Angkor" wood/stone carving workshops, and visit Senteurs d''Angkor Workshop. Take a short walk near King''s Residence to see the Main Shrine (Yeay Teap, Preah Ang Chek, and Preah Ang Chorm). Enjoy Buffet Dinner with Apsara Dance.', '["Private boat cruise visiting floating villages on Tonle Sap Lake","Visit Artisans d''Angkor carving training center","Visit Senteurs d''Angkor Workshop and Royal Residence Main Shrine","Buffet Dinner with classical Apsara Dance show performance"]', '/images/cambodia/Cambodia-9.jpg', 4
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  94, 6, 'Transfer to Siem Reap Airport (SAI) (B) / No Guide', 'Siem Reap', 
  'Breakfast in hotel. Free at your own enjoyment till time transfer to airport for flight back home or connecting countries with the unforgettable trip in Cambodia. (A WONDERFUL JOURNEY ☺)', '["Enjoy breakfast at the hotel","Free morning in Siem Reap for souvenir shopping","Transfer to SAI airport by private driver"]', '/images/cambodia/Cambodia-Map.jpg', 5
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  94, 'Apsara Dance Dinner', 'Enjoy a traditional Khmer buffet dinner while watching classical Apsara dance performances depicting folklore.', 'Music', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  94, 'Floating Village Boat Tour', 'Observe stilted houses, schools, and markets of local residents floating on the massive Tonle Sap Lake.', 'Waves', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  94, 'Les Artisans d''Angkor', 'Observe young Cambodian artisans training in wood and stone carving, keeping traditional crafts alive.', 'Award', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  94, 'Angkor Wat Temple', 'Explore the architectural grandeur, libraries, and galleries of the world''s largest religious complex.', 'Landmark', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  94, 'Apsara dance dinners are highly popular; reserve your table at least a day in advance.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  94, 'Purchase authentic crafts at Les Artisans d''Angkor to support local training programs.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  94, 'USD is preferred; ensure you have small, crisp bills ($1, $5, $10 USD) for markets.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  94, 'Stay hydrated during the extensive walking tours around the temples.', 3
);
