INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'komodo', 'Komodo', 'Indonesia', 'Southeast Asia', 
  'Lair of the prehistoric dragons and dramatic volcanic islands', '/images/indonesia/8-600x400.jpg', 'Komodo National Park is a dramatic volcanic sanctuary located in the Lesser Sunda Islands of Indonesia. Spanning across three main islands—Komodo, Rinca, and Padar—it was established to protect the endemic Komodo dragon, the largest living species of lizard. The park features pink sand beaches, crystal-clear turquoise waters, and some of the world''s most rich marine biodiversity, making it a legendary haven for scuba divers, snorkelers, and adventure seekers alike.', 
  119.88, -8.45, 'Adventure', 'bg-orange-500', 
  'Volcanic islands, prehistoric dragons, and world-class marine gardens.', '/images/indonesia/8-600x400.jpg', 
  'published', '', '3 Days', 
  'Jakarta', 'Indonesian Rupiah (Rp)', 'Tropical with dry season (April–October) and wet season (November–March)', 'April–October (dry season)', 
  'Indonesian (Bahasa), English', 'WITA (UTC+8)', 'Left'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  95, 1, 'Arrive Labuan Bajo, Transfer to Hotel', 'Labuan Bajo', 
  'Arrive at Komodo Airport in Labuan Bajo, meet and greet, and transfer to your hotel. Rest of the day is at leisure.', '["Airport meet and greet","Transfer to Labuan Bajo hotel","Free time at leisure"]', '/images/indonesia/1-1-600x400.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  95, 2, 'Speedboat Tour of Komodo National Park', 'Komodo Island', 
  'Board a speedboat to explore Padar Island for sunrise views, relax on Pink Beach, trek on Komodo Island to spot the legendary dragons, and snorkel at Manta Point.', '["Sunrise trekking at Padar Island","Relax and swim at Pink Beach","Spot Komodo dragons on Komodo Island","Snorkel with Mantas at Manta Point"]', '/images/indonesia/8-600x400.jpg', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  95, 3, 'Kelor Island & Departure', 'Labuan Bajo', 
  'Visit Kelor Island for scenic views and snorkeling, then return to Labuan Bajo for transfer to airport.', '["Snorkel at Kelor Island","Transfer to Komodo Airport for departure"]', '/images/indonesia/3-indo-600x400.jpg', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  95, 'Dragon Trekking', 'Hike through Komodo or Rinca islands with park rangers to spot Komodo dragons in their natural habitat.', 'Compass', 0
