INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  96, 1, 'ARRIVAL', 'Bali', 
  'Welcome to Bali! Upon arrival at the airport you will be greeted by Flower Garland and transferred to the hotel. Enjoy your leisure by own. Overnight stay at the hotel', '["Welcome to Bali! Upon arrival at the airport you will be greeted by Flower Garland and transferred to the hotel","Enjoy your leisure by own","Overnight stay at the hotel"]', '/images/explor-1.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  96, 2, 'WATER SPORTS – BARAK BEACH A HIDDEN GEM BALI (B)', 'Bali', 
  'After breakfast at hotel, visit to Tanjung Benoa beach to see some water sport activities, where you have the opportunity of participating in a variety of Optional marine sports including Banana Boat. Then visit to Barak Beach a Hidden Gem in Bali, here you''ll be mesmerized by the stunning beach with its super blue waters that blend with colorful coral rocks along the shore. The adorable marine life swimming around adds to the charm of this beach. Overnight stay at the hotel.', '["After breakfast at hotel, visit to Tanjung Benoa beach to see some water sport activities, where you have the opportunity of participating in a variety of Optional marine sports including Banana Boat","Then visit to Barak Beach a Hidden Gem in Bali, here you''ll be mesmerized by the stunning beach with its super blue waters that blend with colorful coral rocks along the shore","The adorable marine life swimming around adds to the charm of this beach"]', '/images/explor-1.jpg', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  96, 3, 'BALI SWING – TAMAN DEDARI – SARI TIMBUL GLASS FACTORY (B)', 'Bali', 
  'After breakfast at hotel, visit to Bali Swing (include 3 swing adult, 1x couple swing, 1x bed swing, 1x swing for kids, 1 circle swing + Photo Spot 1 Cute Chicken Nest, 1 Cute Bird Nest, 1 Big Stone, 1 lovely nest). Then, visit to Taman Dedari is popular destination in Bali. Afterthat, visit to Sari Timbul The Glass Factory, you can explore the charm of the Sari Timbul glass factory and discover mystical forests and wooden crafts. Overnight stay at the hotel.', '["After breakfast at hotel, visit to Bali Swing (include 3 swing adult, 1x couple swing, 1x bed swing, 1x swing for kids, 1 circle swing + Photo Spot 1 Cute Chicken Nest, 1 Cute Bird Nest, 1 Big Stone, 1 lovely nest)","Then, visit to Taman Dedari is popular destination in Bali","Afterthat, visit to Sari Timbul The Glass Factory, you can explore the charm of the Sari Timbul glass factory and discover mystical forests and wooden crafts"]', '/images/explor-1.jpg', 2
);
INSERT INTO `tour_package_itinerary` (
