INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  97, 1, 'ARRIVAL', 'Bali', 
  'Welcome to Bali! Upon arrival at the airport you will be greeted by Flower Garland and transferred to the hotel. Enjoy your leisure by own. Overnight stay at the hotel', '["Welcome to Bali! Upon arrival at the airport you will be greeted by Flower Garland and transferred to the hotel","Enjoy your leisure by own","Overnight stay at the hotel"]', '/images/explor-1.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  97, 2, 'WATER SPORTS – SULUBAN BEACH A HIDDEN CAVES (B)', 'Bali', 
  'After breakfast at hotel, visit to Tanjung Benoa beach to see some water sport activities, where you have the opportunity of participating in a variety of Optional marine sports including Banana Boat. Then visit to Suluban Beach a Hidden Caves is one of Bali’s most unique shores, concealed by natural limestone formations and accessed via steps and log ramps through narrow gaps in the rock, you’ll find the main beach entrance down a narrow crag at the end. The water at Suluban beach has the perfect shade of turquoise blue and no wonder people refer to it as the Blue Point Beach. Overnight stay at the hotel.', '["After breakfast at hotel, visit to Tanjung Benoa beach to see some water sport activities, where you have the opportunity of participating in a variety of Optional marine sports including Banana Boat","Then visit to Suluban Beach a Hidden Caves is one of Bali’s most unique shores, concealed by natural limestone formations and accessed via steps and log ramps through narrow gaps in the rock, you’ll find the main beach entrance down a narrow crag at the end","The water at Suluban beach has the perfect shade of turquoise blue and no wonder people refer to it as the Blue Point Beach"]', '/images/explor-1.jpg', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  97, 3, 'WEST NUSA PENIDA ISLAND TOUR ON SIC BASIS (B)', 'Bali', 
  'At 06.00 am pick you at hotel to  Nusa Penida tour at Nusa Penida Island, processed to harbour then we go by speedboat (ON SIC) our first stop exploring this side of the island is Broken Beach, known in Local language as Pasih Huug. This is not a beach as such, but rather a sinkhole into the ocean which can be seen from above, we reach Paradise Beach which is now better known as Crystal Bay. Truly the archetypal paradise, this beach has white sands, coconut trees and green grassy areas. The beauty of Angel’s Billabong is visible from the cliffs are beautiful and have a meeting estuarine water clear beaches that appear greenish, then visit Kelingking secret point, and we back to harbour. Overnight stay at the hotel.', '["At 06.00 am pick you at hotel to  Nusa Penida tour at Nusa Penida Island, processed to harbour then we go by speedboat (ON SIC) our first stop exploring this side of the island is Broken Beach, known in Local language as Pasih Huug","This is not a beach as such, but rather a sinkhole into the ocean which can be seen from above, we reach Paradise Beach which is now better known as Crystal Bay","Truly the archetypal paradise, this beach has white sands, coconut trees and green grassy areas"]', '/images/explor-1.jpg', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  97, 4, 'FREE PROGRAM/ NO TOUR NO TRANSPORT (B)', 'Bali', 
  'After breakfast, enjoy your leisure by ownself. Stay overnight at hotel', '["After breakfast, enjoy your leisure by ownself","Stay overnight at hotel"]', '/images/explor-1.jpg', 3
);
INSERT INTO `tour_package_itinerary` (
