INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  98, 1, 'ARRIVAL (L/D)', 'Bali', 
  'Welcome to Bali! Upon arrival at the airport you will be greeted by Flower Garland and transferred to the hotel.  Overnight stay at the hotel.', '["Welcome to Bali! Upon arrival at the airport you will be greeted by Flower Garland and transferred to the hotel","Overnight stay at the hotel"]', '/images/explor-1.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  98, 2, 'WATER SPORTS – ULUWATU TEMPLE (B/L/D)', 'Bali', 
  'After breakfast, Your holiday will not complete without tying Bali WATER SPORTS (1x Banana Boat, Jetski, Parasailing). Then visit to ULUWATU TEMPLE is a Balinese Hindu Temple located right on the top ot a steep hill with the right at the side. Overnight stay at the hotel.', '["After breakfast, Your holiday will not complete without tying Bali WATER SPORTS (1x Banana Boat, Jetski, Parasailing)","Then visit to ULUWATU TEMPLE is a Balinese Hindu Temple located right on the top ot a steep hill with the right at the side","Overnight stay at the hotel"]', '/images/explor-1.jpg', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  98, 3, 'UBUD – VOLCANO TOUR (B/L/D)', 'Bali', 
  'After breakfast, A full day excursion to the KINTAMANI Volcano and Ubud Village. This is a favorite tour of any first time visitors to Bali. Visit the Batuan Village (famous for traditional paintings), Mas Village (famous for Wood carving) & then past the Celuk Village (famous for silver and gold works). Thereafter, stop midway at the KINTAMANI penelokan along the foot of Mount Batur with a splendid Batur lake view. On the way stop at Coffe plantation your tour ends in the famous Ubud Village. Here you can look in & around the various shopping options including the Ubud Art Market. Overnight stay at the hotel.', '["After breakfast, A full day excursion to the KINTAMANI Volcano and Ubud Village","This is a favorite tour of any first time visitors to Bali","Visit the Batuan Village (famous for traditional paintings), Mas Village (famous for Wood carving) & then past the Celuk Village (famous for silver and gold works). Thereafter, stop midway at the KINTAMANI penelokan along the foot of Mount Batur with a splendid Batur lake view"]', '/images/explor-1.jpg', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  98, 4, 'GATE OF HEAVEN AT LEMPUYANG TEMPLE – TIRTA GANGGA (B/L/D)', 'Bali', 
  'Pick up time 08.30 AM, Breakfast at hotel, then get morning pick up from your hotel and take you to visit Lempuyang Temple is one of Bali’s oldest and most highly regarded temples. It is also believed to predate the majority of Hindu temples on the island, and the six holiest places of worship on Bali. The entire landscape looks very picturesque from this temple gate, and that gate also known to the western world as "The Gates of Heaven". The gates and its temple located in eastern part of the of Bali within the highlands of Mount Lempuyang, which sitting at a cool 1,775m above sea level. The whole complex complex that is made up of seven different sanctuaries, this temple offers visitors one of the most breathtaking views from any of the temples in Bali. Next stop at Tirta Gangga Water Palace locally known as Taman Tirta Gangga, is a former water palace of Karangasem empire which one of east Bali’s most famous sights. Situated about 6 kilometres north of the town of Amlapura, which feature 1.2ha of pools, ponds and fountains surrounded by tropical gardens. Breathtaking scenery with lush rice paddies back three levels of ornamental gardens with swimming pools, fountains, stone carvings, stepping stones, fish ponds, and airy pavilions. Overnight stay at hotel.', '["Pick up time 08.30 AM, Breakfast at hotel, then get morning pick up from your hotel and take you to visit Lempuyang Temple is one of Bali’s oldest and most highly regarded temples","It is also believed to predate the majority of Hindu temples on the island, and the six holiest places of worship on Bali","The entire landscape looks very picturesque from this temple gate, and that gate also known to the western world as \\"The Gates of Heaven\\""]', '/images/explor-1.jpg', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  98, 5, 'ULUNDANU TEMPLE – TANAH LOT (B/L/D)', 'Bali', 
  'After breakfast, Visit to the BEDUGUL, a cool mountain Resort area. You many encounter the beautiful lake Beratan with ULUNDANU TEMPLE, a lovely Hindu-Buddhist water shrine. The gorgeous panorama and fresh atmosphere will refresh your sight. The last stop is TANAH LOT, an off sea shore temple built in the small promontory. The wave Crash sound is believed could bring us a certain inspiration. You may take a picture of the beautiful sunset when the weather is clear. Overnight stay at the hotel.', '["After breakfast, Visit to the BEDUGUL, a cool mountain Resort area","You many encounter the beautiful lake Beratan with ULUNDANU TEMPLE, a lovely Hindu-Buddhist water shrine","The gorgeous panorama and fresh atmosphere will refresh your sight"]', '/images/explor-1.jpg', 4
);
