INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  99, 1, 'ARRIVAL', 'Bali', 
  'Welcome to Bali! Upon arrival at the airport you will be greeted by Flower Garland and transferred to the hotel. Enjoy your leisure by own. Overnight stay at the hotel', '["Welcome to Bali! Upon arrival at the airport you will be greeted by Flower Garland and transferred to the hotel","Enjoy your leisure by own","Overnight stay at the hotel"]', '/images/explor-1.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  99, 2, 'WATER SPORTS – ULUWATU TEMPLE (B)', 'Bali', 
  'After breakfast at hotel, visit to Tanjung Benoa beach to see some water sport activities, where you have the opportunity of participating in a variety of Optional marine sports including Banana Boat. Then visit to ULUWATU TEMPLE is a Balinese Hindu Temple located right on the top of a steep hill with the right at the side. Overnight stay at the hotel.', '["After breakfast at hotel, visit to Tanjung Benoa beach to see some water sport activities, where you have the opportunity of participating in a variety of Optional marine sports including Banana Boat","Then visit to ULUWATU TEMPLE is a Balinese Hindu Temple located right on the top of a steep hill with the right at the side","Overnight stay at the hotel"]', '/images/explor-1.jpg', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  99, 3, 'BALI SWING – TAMAN DEDARI – SARI TIMBUL GLASS FACTORY (B)', 'Bali', 
  'After breakfast at hotel, visit to Bali Swing (include 3 swing adult, 1x couple swing, 1x bed swing, 1x swing for kids, 1 circle swing + Photo Spot 1 Cute Chicken Nest, 1 Cute Bird Nest, 1 Big Stone, 1 lovely nest). Then, visit to Taman Dedari is popular destination in Bali, you can find some spectacular statue. Of the around 50 statues, there are four large statues with a height of about 10 m. Afterthat, visit to Sari Timbul The Glass Factory, you can explore the charm of the Sari Timbul glass factory and discover mystical forests and wooden crafts. Overnight stay at the hotel.', '["After breakfast at hotel, visit to Bali Swing (include 3 swing adult, 1x couple swing, 1x bed swing, 1x swing for kids, 1 circle swing + Photo Spot 1 Cute Chicken Nest, 1 Cute Bird Nest, 1 Big Stone, 1 lovely nest)","Then, visit to Taman Dedari is popular destination in Bali, you can find some spectacular statue","Of the around 50 statues, there are four large statues with a height of about 10 m"]', '/images/explor-1.jpg', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  99, 4, 'WEST NUSA PENIDA ISLAND TOUR (B)', 'Bali', 
  'At 06.00 am pick you at hotel to  Nusa Penida tour at Nusa Penida Island, processed to harbour then we go by speedboat (ON SIC) our first stop exploring this side of the island is Broken Beach, known in Local language as Pasih Huug. This is not a beach as such, but rather a sinkhole into the ocean which can be seen from above, we reach Paradise Beach which is now better known as Crystal Bay. Truly the archetypal paradise, this beach has white sands, coconut trees and green grassy areas, The beauty of Angel’s Billabong is visible from the cliffs are beautiful and have a meeting estuarine water clear beaches that appear greenish, then visit Kelingking secret point, and we back to harbour. Overnight stay at the hotel.', '["At 06.00 am pick you at hotel to  Nusa Penida tour at Nusa Penida Island, processed to harbour then we go by speedboat (ON SIC) our first stop exploring this side of the island is Broken Beach, known in Local language as Pasih Huug","This is not a beach as such, but rather a sinkhole into the ocean which can be seen from above, we reach Paradise Beach which is now better known as Crystal Bay","Truly the archetypal paradise, this beach has white sands, coconut trees and green grassy areas, The beauty of Angel’s Billabong is visible from the cliffs are beautiful and have a meeting estuarine water clear beaches that appear greenish, then visit Kelingking secret point, and we back to harbour. Overnight stay at the hotel"]', '/images/explor-1.jpg', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  99, 5, 'HALFDAY BALINESSE SPA – CANDLE LIGHT DINNER AT JIMBARAN BEACH (B)', 'Bali', 
  'After Breakfast, spend your time at hotel, at Afternoon will pick up you to Balinesse Spa for 2 hours. Then, we will  processed you to Candle Light Dinner at Jimbaran Beach. Overnight stay at the hotel.', '["After Breakfast, spend your time at hotel, at Afternoon will pick up you to Balinesse Spa for 2 hours","Then, we will  processed you to Candle Light Dinner at Jimbaran Beach","Overnight stay at the hotel"]', '/images/explor-1.jpg', 4
);
