INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  100, 1, 'ARRIVAL', 'Bali', 
  'Welcome to Bali! Upon arrival at the airport you will be greeted by Flower Garland and transferred to the hotel.  Overnight stay at the hotel.', '["Welcome to Bali! Upon arrival at the airport you will be greeted by Flower Garland and transferred to the hotel","Overnight stay at the hotel"]', '/images/explor-1.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  100, 2, 'WATER SPORTS – ULUWATU TEMPLE (B)', 'Bali', 
  'After breakfast, Your holiday will not complete without tying Bali WATER SPORTS (1x Banana Boat). Then visit to ULUWATU TEMPLE is a Balinese Hindu Temple located right on the top ot a steep hill with the right at the side. Overnight stay at the hotel.', '["After breakfast, Your holiday will not complete without tying Bali WATER SPORTS (1x Banana Boat)","Then visit to ULUWATU TEMPLE is a Balinese Hindu Temple located right on the top ot a steep hill with the right at the side","Overnight stay at the hotel"]', '/images/explor-1.jpg', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  100, 3, 'ULUNDANU TEMPLE – TANAH LOT (B)', 'Bali', 
  'After breakfast, Visit to the BEDUGUL, a cool mountain Resort area. You many encounter the beautiful lake Beratan with ULUNDANU TEMPLE, a lovely Hindu-Buddhist water shrine. The gorgeous panorama and fresh atmosphere will refresh your sight. The last stop is TANAH LOT, an off sea shore temple built in the small promontory. The wave Crash sound is believed could bring us a certain inspiration. You may take a picture of the beautiful sunset when the weather is clear. Overnight stay at the hotel.', '["After breakfast, Visit to the BEDUGUL, a cool mountain Resort area","You many encounter the beautiful lake Beratan with ULUNDANU TEMPLE, a lovely Hindu-Buddhist water shrine","The gorgeous panorama and fresh atmosphere will refresh your sight"]', '/images/explor-1.jpg', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  100, 4, 'BALI – GILI TRAWANGAN BY SIC TRANSFER (B)', 'Bali', 
  'After breakfast at Hotel, Start you day with lovely breakfast and get ready to explore the Gili Island. You will be picked up from the hotel for your speed boat transfer to continue your journey to the Gili Island. Upon arrival at the port in Gili Trawangan, make your way on your own to get to the hotel as motor transport is not supported in the Island. Hire local transport (usually horse cart) at cheap rates and enjoy the traditional ride on your way to hotel. Your entire day is at your disposal. Stay overnight at the hotel in Gili Trawangan.', '["After breakfast at Hotel, Start you day with lovely breakfast and get ready to explore the Gili Island","You will be picked up from the hotel for your speed boat transfer to continue your journey to the Gili Island","Upon arrival at the port in Gili Trawangan, make your way on your own to get to the hotel as motor transport is not supported in the Island"]', '/images/explor-1.jpg', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  100, 5, 'GILI TRAWANGAN  - WEST NUSA PENIDA TOUR (B/L)', 'Bali', 
  'After breakfast at Gili Trawangan Hotel, Prepare to Nusa Penida Island by speed boat. After  arrive in Nusa Penida, continue to visit  Crystal Bay, our first stop exploring this side of the island is Broken Beach, known in Local language as Pasih Huug. This is not a beach as such, but rather a sinkhole into the ocean which can be seen from above, we reach Paradise Beach which is now better known as Crystal Bay. Truly the archetypal paradise, this beach has white sands, coconut trees and green grassy areas, The beauty of Angel’s Billabong is visible from the cliffs are beautiful and have a meeting estuarine water clear beaches that appear greenish, then visit Kelingking secret point. Overnight stay at  Nusa Penida hotel.', '["After breakfast at Gili Trawangan Hotel, Prepare to Nusa Penida Island by speed boat. After  arrive in Nusa Penida, continue to visit  Crystal Bay, our first stop exploring this side of the island is Broken Beach, known in Local language as Pasih Huug. This is not a beach as such, but rather a sinkhole into the ocean which can be seen from above, we reach Paradise Beach which is now better known as Crystal Bay","Truly the archetypal paradise, this beach has white sands, coconut trees and green grassy areas, The beauty of Angel’s Billabong is visible from the cliffs are beautiful and have a meeting estuarine water clear beaches that appear greenish, then visit Kelingking secret point. Overnight stay at  Nusa Penida hotel"]', '/images/explor-1.jpg', 4
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  100, 6, 'NUSA PENIDA – BALI (B/L)', 'Bali', 
  'Breakfast at your hotel. Today enjoy your leisure, leisure by own. Check out hotel. back to sanur harbour by speed boat and drop to your hotel. Overnight stay at the hotel.', '["Breakfast at your hotel","Today enjoy your leisure, leisure by own","Check out hotel"]', '/images/explor-1.jpg', 5
);
