INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  101, 3, 'ULUNDANU TEMPLE - TANAH LOT TOUR (B)', 'Bali', 
  'After breakfast, Visit to the BEDUGUL, a cool mountain Resort area. You many encounter the beautiful lake Beratan with ULUNDANU TEMPLE, a lovely Hindu-Buddhist water shrine. The gorgeous panorama and fresh atmosphere will refresh your sight. The last stop is TANAH LOT, an off sea shore temple built in the small promontory. The wave Crash sound is believed could bring us a certain inspiration. You may take a picture of the beautiful sunset when the weather is clear. Overnight stay at the hotel.', '["After breakfast, Visit to the BEDUGUL, a cool mountain Resort area","You many encounter the beautiful lake Beratan with ULUNDANU TEMPLE, a lovely Hindu-Buddhist water shrine","The gorgeous panorama and fresh atmosphere will refresh your sight"]', '/images/explor-1.jpg', 2
