INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  101, 4, 'DENPASAR CITY TOUR (B)', 'Bali', 
  'After breakfast, we will take you to exploring around DENPASAR CITY TOUR. We will going to one of monument in Bali called BAJRA SANDHI MONUMENT (PHOTO STOP ONLY), we will stop for a while to take a picture in front of it. Then, proceed to PUPUTAN SQUARE (PHOTO STOP). After that, you can visit KUTA ART MARKET. Overnight stay at the hotel.', '["After breakfast, we will take you to exploring around DENPASAR CITY TOUR","We will going to one of monument in Bali called BAJRA SANDHI MONUMENT (PHOTO STOP ONLY), we will stop for a while to take a picture in front of it","Then, proceed to PUPUTAN SQUARE (PHOTO STOP)"]', '/images/explor-1.jpg', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  101, 5, 'WEST NUSA PENIDA ISLAND TOUR (B/L)', 'Bali', 
  'At 06.00 am pick you at hotel to  Nusa Penida tour at Nusa Penida Island, processed to sanur harbor then we go by boat our first stop exploring this side of the island is Broken Beach, known in Local language as Pasih Huug. This is not a beach as such, but rather a sinkhole into the ocean which can be seen from above, we reach Paradise Beach which is now better known as Crystal Bay. Truly the archetypal paradise, this beach has white sands, coconut trees and green grassy areas, The beauty of Angel’s Billabong is visible from the cliffs are beautiful and have a meeting estuarine water clear beaches that appear greenish, then visit Kelingking secret point, and the last is love of tree and we back to sanur harbor. Overnight stay at the hotel.. Overnight stay at the hotel.', '["At 06.00 am pick you at hotel to  Nusa Penida tour at Nusa Penida Island, processed to sanur harbor then we go by boat our first stop exploring this side of the island is Broken Beach, known in Local language as Pasih Huug","This is not a beach as such, but rather a sinkhole into the ocean which can be seen from above, we reach Paradise Beach which is now better known as Crystal Bay","Truly the archetypal paradise, this beach has white sands, coconut trees and green grassy areas, The beauty of Angel’s Billabong is visible from the cliffs are beautiful and have a meeting estuarine water clear beaches that appear greenish, then visit Kelingking secret point, and the last is love of tree and we back to sanur harbor"]', '/images/explor-1.jpg', 4
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  101, 6, 'FREE PROGRAM (B)', 'Bali', 
  'Breakfast at your hotel. Today enjoy your leisure, leisure by own. Overnight stay at the hotel.', '["Breakfast at your hotel","Today enjoy your leisure, leisure by own","Overnight stay at the hotel"]', '/images/explor-1.jpg', 5
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  101, 7, 'UBUD – VOLCANO TOUR – TEGENUNGAN WATERFALL (B)', 'Bali', 
  'After breakfast, A full day excursion to the KINTAMANI Volcano and Ubud Village. This is a favorite tour of any first time visitors to Bali. Visit the Batuan Village (famous for traditional paintings), Mas Village (famous for Wood carving) & then past the Celuk Village (famous for silver and gold works). Thereafter, stop midway at the KINTAMANI penelokan along the foot of Mount Batur with a splendid Batur lake view. than the visit Tegenungan Waterfall is a great stopover for nature lovers who happen to be staying in Ubud with cafes nearby. On the way stop at Coffe plantation your tour ends in the famous Ubud Village. Here you can look in & around the various shopping options including the Ubud Art Market. Overnight stay at the hotel. .', '["After breakfast, A full day excursion to the KINTAMANI Volcano and Ubud Village","This is a favorite tour of any first time visitors to Bali","Visit the Batuan Village (famous for traditional paintings), Mas Village (famous for Wood carving) & then past the Celuk Village (famous for silver and gold works). Thereafter, stop midway at the KINTAMANI penelokan along the foot of Mount Batur with a splendid Batur lake view. than the visit Tegenungan Waterfall is a great stopover for nature lovers who happen to be staying in Ubud with cafes nearby"]', '/images/explor-1.jpg', 6
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  101, 8, 'LEMPUYANG TEMPLE – TIRTA GAANGGA WATER PALACE (B)', 'Bali', 
  'After breakfast, visit to Lempuyang Temple is famous for its magnificent majestic mountain scenery, many tourists take pictures at the gate of the Lempuyang Temple with a backdrop of the great mountain scenery. It is truly a spectacular sight offered at Lempuyang Temple. Next stop at Tirta Gangga Water Palace locally known as Taman Tirta Gangga, is a former water palace of Karangasem empire which one of east Bali’s most famous sights. Situated about 6 kilometres north of the town of Amlapura, which feature 1.2ha of pools, ponds and fountains surrounded by tropical gardens. Breathtaking scenery with lush rice paddies back three levels of ornamental gardens with swimming pools, fountains, stone carvings, stepping stones, fish ponds, and airy pavilions. Overnight stay at the hotel.', '["After breakfast, visit to Lempuyang Temple is famous for its magnificent majestic mountain scenery, many tourists take pictures at the gate of the Lempuyang Temple with a backdrop of the great mountain scenery","It is truly a spectacular sight offered at Lempuyang Temple","Next stop at Tirta Gangga Water Palace locally known as Taman Tirta Gangga, is a former water palace of Karangasem empire which one of east Bali’s most famous sights"]', '/images/explor-1.jpg', 7
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  101, 9, 'RAFTING + BALI SWING (B/L)', 'Bali', 
  'Breakfast at the hotel, pick up at the hotel for white water Rafting with local lunch. Then, enjoy ATV Quad Bike Ride for single/tandem ride at Ubud area .. Overnight stay at the Hotel', '["Breakfast at the hotel, pick up at the hotel for white water Rafting with local lunch","Then, enjoy ATV Quad Bike Ride for single/tandem ride at Ubud area ","Overnight stay at the Hotel"]', '/images/explor-1.jpg', 8
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  101, 10, 'BALI SWING – TUKAD CEPUNG WATERFALL (B)', 'Bali', 
  'After breakfast, enjoy a Bali Swing Include ( 3 swing adult, 1x couple swing, 1x bed swing, 1x swing for kids, 1 circle swing + Photo Spot 1 Cute Chicken Nest, 1 Cute Bird Nest, 1 Big Stone, 1 lovely nest) experience which hangs between two palm trees overlooks a picturesque rice terraces.  Next stop at Tukad Cepung Waterfall as one of the most photogenic of all the waterfalls in Bali with sun rays that beam through the falls. The walk to get down to Tukad Cepung Waterfall is straight forward and easy enough. It took all of 15 minutes to get down to the enchanted location. Swim in the pristine water, admire the sun rays shining straight through the top of the falls, and snap a few priceless of amazing photos.  Overnight stay at hotel', '["After breakfast, enjoy a Bali Swing Include ( 3 swing adult, 1x couple swing, 1x bed swing, 1x swing for kids, 1 circle swing + Photo Spot 1 Cute Chicken Nest, 1 Cute Bird Nest, 1 Big Stone, 1 lovely nest) experience which hangs between two palm trees overlooks a picturesque rice terraces","Next stop at Tukad Cepung Waterfall as one of the most photogenic of all the waterfalls in Bali with sun rays that beam through the falls","The walk to get down to Tukad Cepung Waterfall is straight forward and easy enough"]', '/images/explor-1.jpg', 9
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  101, 11, 'DEPARTURE/TRANSFER TO AIRPORT (B)', 'Bali', 
  'Breakfast in hotel , Free at own leisure, Transfer to airport for next destination', '["Breakfast in hotel , Free at own leisure, Transfer to airport for next destination"]', '/images/explor-1.jpg', 10
);
