INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  103, 1, 'Day 1. Ende – Moni village.', 'Komodo', 
  'Pick up at hotel/airport in Ende middle Flores – drive to Wologai unique traditional village of Lio tribe – drive to Moni village for your accommodation.', '["Pick up at hotel/airport in Ende middle Flores – drive to Wologai unique traditional village of Lio tribe – drive to Moni village for your accommodation"]', '/images/explor-1.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  103, 2, 'Day 2. Moni village – Kelimutu Lake – Ende – Bajawa', 'Komodo', 
  'Today is your second day Flores Komodo tour. Begin with an early morning drive to Kelimutu volcano at 04.30. Kelimutu theree lake is the the most mysterious and dramatic sight in the world. it is located in the central of Flores – After enjoying and witness this natural miracle will drive back to hotel for breakfast –  drive to Ndua Ria traditional fresh fruits and vegetable  market – drive to Blue stone beach via Ende – drive to Wogo traditional village to see Ngadhu and Bhaga as symbol of Male and Female ancestor of Ngadha tribe. Continue trip to Bajawa town to check in hotel.', '["Today is your second day Flores Komodo tour. Begin with an early morning drive to Kelimutu volcano at 04.30","Kelimutu theree lake is the the most mysterious and dramatic sight in the world","it is located in the central of Flores – After enjoying and witness this natural miracle will drive back to hotel for breakfast –  drive to Ndua Ria traditional fresh fruits and vegetable  market – drive to Blue stone beach via Ende – drive to Wogo traditional village to see Ngadhu and Bhaga as symbol of Male and Female ancestor of Ngadha tribe"]', '/images/explor-1.jpg', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  103, 3, 'Day 3. Bajawa – Bena village – Aimere village – Ruteng', 'Komodo', 
  'Breakfast at hotel – drive to an impressive traditional village of Bena – continue driving to Aimere village to see the traditional process of local alcohol drink from palm juice – stop at Rana Mese lake to take a picture – drive to Ruteng to check in at hotel.', '["Breakfast at hotel – drive to an impressive traditional village of Bena – continue driving to Aimere village to see the traditional process of local alcohol drink from palm juice – stop at Rana Mese lake to take a picture – drive to Ruteng to check in at hotel"]', '/images/explor-1.jpg', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  103, 4, 'Day 4. Ruteng – Cancar – Labuan Bajo – Rinca island (L,D)', 'Komodo', 
  'This the last of driving on Flores. Breakfast at hotel – drive to Cancar to see the Lodok spectacular view of round rice fields that looks like giant spider’s web – drive to Labuan Bajo harbor to catch a wooden boat leaving for Rinca island – trekking at Rinca island to see Komodo dragon and other wild life. Lunch, Dinner and Overnight are on the boat trip.', '["This the last of driving on Flores","Breakfast at hotel – drive to Cancar to see the Lodok spectacular view of round rice fields that looks like giant spider’s web – drive to Labuan Bajo harbor to catch a wooden boat leaving for Rinca island – trekking at Rinca island to see Komodo dragon and other wild life","Lunch, Dinner and Overnight are on the boat trip"]', '/images/explor-1.jpg', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  103, 5, 'Day 5. Rinca island – Komodo island  – Pink Beach – Labuan Bajo (B,L)', 'Komodo', 
  'Early morning will boat to Komodo island – After breakfast on the boat trip, trekking at Komodo island to see the Komodo dragon and other wild life – boat to Pink Beach to snorkel and relax at spectacular pink color beach – Lunch on the boat while boating back to Labuan Bajo harbor – transfer to the hotel for dinner and overnight.', '["Early morning will boat to Komodo island – After breakfast on the boat trip, trekking at Komodo island to see the Komodo dragon and other wild life – boat to Pink Beach to snorkel and relax at spectacular pink color beach – Lunch on the boat while boating back to Labuan Bajo harbor – transfer to the hotel for dinner and overnight"]', '/images/explor-1.jpg', 4
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  103, 6, 'Day 6. Hotel – chcek out for your next destination (B).', 'Komodo', 
  'Today is the last day of Flores Komodo tour. Breakfast at hotel – free at leisure until time to check out for your next destination.', '["Today is the last day of Flores Komodo tour","Breakfast at hotel – free at leisure until time to check out for your next destination"]', '/images/explor-1.jpg', 5
);
