INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  105, 1, 'Day 01. Ende, Flores Island – Moni village', 'Komodo', 
  'Pick up at hotel or at the airport in Ende – begin your Flores adventure by driving to Saga/Wologai unique traditional village belongs to Lio tribe – continue trip to Moni village to check in at hotel for your accommodation.', '["Pick up at hotel or at the airport in Ende – begin your Flores adventure by driving to Saga/Wologai unique traditional village belongs to Lio tribe – continue trip to Moni village to check in at hotel for your accommodation"]', '/images/explor-1.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  105, 2, 'Day 02. Moni village – Kelimutu Lake – Ende – Blue Stone Beach – Riung (B).', 'Komodo', 
  'Early wake up, then drive to Kelimutu three lake – soft trekking from parking area to Kelimutu’s summit  to witness the most amazing Kelimutu three colored lake and its magnificent landscape surroundings – walking back to parking area and then drive to hotel for breakfast – Continue Ende town. Ende route will stop at traditional market Ndua Ria – drive to Blue Stone Beach – continue to Riung northern coast of Flores. Check in at hotel in Riung for your accommodation.', '["Early wake up, then drive to Kelimutu three lake – soft trekking from parking area to Kelimutu’s summit  to witness the most amazing Kelimutu three colored lake and its magnificent landscape surroundings – walking back to parking area and then drive to hotel for breakfast – Continue Ende town","Ende route will stop at traditional market Ndua Ria – drive to Blue Stone Beach – continue to Riung northern coast of Flores","Check in at hotel in Riung for your accommodation"]', '/images/explor-1.jpg', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  105, 3, 'Day 3. Half-day snorkeling trip at Riung Marine Garden – Bajawa (B)', 'Komodo', 
  'Today is visiting Riung Sea Garden as one one of most spectacular snorkel site in the northern Flores island. Start with the breakfast at hotel – transfer to harbor to catch a local wooden boat – boat to Kalong island to witness thousand of fruit bats flying out of mangrove tree – boat to Bako/Tembang snorkeling spot – boat to Tiga island for snorkeling and BBQ lunch on the white sandy beach – boat back to harbor – continue driving to Bajawa and stop at So’a hot spring for taking a bath if you want. Check in at hotel in Bajawa for accommodation.', '["Today is visiting Riung Sea Garden as one one of most spectacular snorkel site in the northern Flores island","Start with the breakfast at hotel – transfer to harbor to catch a local wooden boat – boat to Kalong island to witness thousand of fruit bats flying out of mangrove tree – boat to Bako/Tembang snorkeling spot – boat to Tiga island for snorkeling and BBQ lunch on the white sandy beach – boat back to harbor – continue driving to Bajawa and stop at So’a hot spring for taking a bath if you want","Check in at hotel in Bajawa for accommodation"]', '/images/explor-1.jpg', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  105, 4, 'Day 04. Bajawa – Bena village – Aimere village – Borong Ruteng (B)', 'Komodo', 
  'Breakfast at hotel – drive to an impressive traditional village of Bena located in the hearth of Flores – continue driving to Aimere village to see the traditional process of local alcohol drink from palm juice – drive to Borong – stop at Rana Mese lake to take a picture – drive to Ruteng to check in at hotel.', '["Breakfast at hotel – drive to an impressive traditional village of Bena located in the hearth of Flores – continue driving to Aimere village to see the traditional process of local alcohol drink from palm juice – drive to Borong – stop at Rana Mese lake to take a picture – drive to Ruteng to check in at hotel"]', '/images/explor-1.jpg', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  105, 5, 'Day 05. Ruteng – Cancar “spider’s web rice field” – Lembor – Labuan Bajo – Rinca island (B/L/D).', 'Komodo', 
  'Today is the ending of Flores island driving. Breakfast at hotel – drive to Labuan Bajo as a western most town on Flores. Visit Cancar  village to see the Lodok spectacular view of round rice fields that looks like giant spider’s web – drive to Labuan Bajo’s harbor for 4 hours to catch a wooden boat leaving for Rinca island – trekking at Rinca island to see Komodo dragon and other wild life. Lunch, Dinner and Overnight are on the boat trip.', '["Today is the ending of Flores island driving","Breakfast at hotel – drive to Labuan Bajo as a western most town on Flores","Visit Cancar  village to see the Lodok spectacular view of round rice fields that looks like giant spider’s web – drive to Labuan Bajo’s harbor for 4 hours to catch a wooden boat leaving for Rinca island – trekking at Rinca island to see Komodo dragon and other wild life"]', '/images/explor-1.jpg', 4
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  105, 6, 'Day 6. Rinca island – Komodo island  – Pink Beach – Labuan Bajo (B,L)', 'Komodo', 
  'Early morning will boat to Komodo island – After breakfast on the boat trip, trekking at Komodo island to see the Komodo dragon and other wild life – boat to Pink Beach to snorkel and relax at spectacular pink color beach – Lunch on the boat while boating back to Labuan Bajo’s harbor, west Flores – transfer to the hotel for your accommodation.', '["Early morning will boat to Komodo island – After breakfast on the boat trip, trekking at Komodo island to see the Komodo dragon and other wild life – boat to Pink Beach to snorkel and relax at spectacular pink color beach – Lunch on the boat while boating back to Labuan Bajo’s harbor, west Flores – transfer to the hotel for your accommodation"]', '/images/explor-1.jpg', 5
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  105, 7, 'Day 7. Hotel – chcek out for your next destination (B).', 'Komodo', 
  'Today is the last day of Flores Adventure Tour. Breakfast at hotel – free at leisure until time to check out for your next destination.', '["Today is the last day of Flores Adventure Tour","Breakfast at hotel – free at leisure until time to check out for your next destination"]', '/images/explor-1.jpg', 6
);
