INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  106, 1, 'Labuan Bajo – Lembor village – Narang village – Denge village – Wae Rebo village (L,D).', 'Wae Rebo Village', 
  'Early morning picking up service at your hotel in Labuan Bajo, west Flores – drive to Lembor village to see the largest wet paddy-field in west Flores – drive to Narang village southern coast of west Flores – drive to Denge village – start trekking up for 2,5 hours to impressive and unique traditional village of Wae Rebo. Lunch on the way, Dinner and overnight at Wae Rebo village.', '["Early morning picking up service at your hotel in Labuan Bajo, west Flores – drive to Lembor village to see the largest wet paddy-field in west Flores – drive to Narang village southern coast of west Flores – drive to Denge village – start trekking up for 2,5 hours to impressive and unique traditional village of Wae Rebo","Lunch on the way, Dinner and overnight at Wae Rebo village"]', '/images/explor-1.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  106, 2, 'Wae Rebo Village – Denge village – Narang village – Lembor village – Labuan Bajo (B,L).', 'Wae Rebo Village', 
  'on the second we are having a Simple breakfast at Wae Rebo village – see and enjoy the Wae Rebo village, by interacting with the local community to learn about their way of life and their unique culture before leaving the village – trek down back to Denge village – drive back to to Labuan Bajo via Narang and Lembor village. Lunch will be served on the way. Drop you off at your hotel in Labuan Bajo. End of your Wae Rebo Village Tour with us.', '["on the second we are having a Simple breakfast at Wae Rebo village – see and enjoy the Wae Rebo village, by interacting with the local community to learn about their way of life and their unique culture before leaving the village – trek down back to Denge village – drive back to to Labuan Bajo via Narang and Lembor village","Lunch will be served on the way","Drop you off at your hotel in Labuan Bajo"]', '/images/explor-1.jpg', 1
);
