INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  109, 1, 'Day 1. On the first day of your trip', 'Jogyakarta', 
  'AirAsia will bring you to Yogyakarta International Airport, and your guide will pick you up. From there, you''ll head straight to a local restaurant for dinner before checking into your hotel.', '["AirAsia will bring you to Yogyakarta International Airport, and your guide will pick you up","From there, you''ll head straight to a local restaurant for dinner before checking into your hotel"]', '/images/explor-1.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  109, 2, 'Day 2. The second day', 'Jogyakarta', 
  'The second day starts at 3:00 am as you travel to Magelang for a breathtaking sunrise view from Setumbu Hills. From a height of about 400 meters, you''ll get an incredible panoramic view of the Borobudur temple. Afterward, you''ll head to Svargabhumi, an aesthetic rice field with many Instagram-worthy photo spots. You''ll have lunch at a local restaurant and visit Borobudur Temple, the largest Buddhist temple. The day ends with dinner at a local restaurant and some rest at your hotel in Yogyakarta.', '["The second day starts at 3:00 am as you travel to Magelang for a breathtaking sunrise view from Setumbu Hills","From a height of about 400 meters, you''ll get an incredible panoramic view of the Borobudur temple","Afterward, you''ll head to Svargabhumi, an aesthetic rice field with many Instagram-worthy photo spots"]', '/images/explor-1.jpg', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  109, 3, 'Day 3. On the third day', 'Jogyakarta', 
  'On the third day, you''ll have breakfast at your hotel before visiting the "KRATON" – Sultan Palace and Pines Forest. The palace is the home of the Yogyakarta king, while the forest is a great place to relax and take selfies. It''s perfect for both amateur and professional photographers. You''ll have lunch at a local restaurant and then head to Sky View, a new tourist attraction on a hill that''s great for taking pictures to use on social media. After that, you''ll check out Malioboro Street, famous for its markets selling crafts and other things. Dinner will be at a local restaurant before heading back to your hotel.', '["On the third day, you''ll have breakfast at your hotel before visiting the \\"KRATON\\" – Sultan Palace and Pines Forest","The palace is the home of the Yogyakarta king, while the forest is a great place to relax and take selfies","It''s perfect for both amateur and professional photographers"]', '/images/explor-1.jpg', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  109, 4, 'Day 4. On the fourth and final day', 'Jogyakarta', 
  'On the fourth and final day, you''ll have breakfast at your hotel before checking out. Your first stop will be Gamplong, where you can visit the famous Indonesian filmmaker Hanung Bramantyo''s studio. He filmed Sultan Agung: Throne, Struggle, Love, Earth of Mankind, and Ainun Habibie 3 there. You''ll have lunch at a local restaurant before transferring to Yogyakarta International Airport to end your tour.', '["On the fourth and final day, you''ll have breakfast at your hotel before checking out","Your first stop will be Gamplong, where you can visit the famous Indonesian filmmaker Hanung Bramantyo''s studio","He filmed Sultan Agung: Throne, Struggle, Love, Earth of Mankind, and Ainun Habibie 3 there"]', '/images/explor-1.jpg', 3
);
