  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  '5d-4n-fun-adventure-yogyakarta-city-tour', '5D/4N - Fun & Adventure Yogyakarta City Tour', 'Indonesia', 'Southeast Asia', 
  'Explore 5D/4N - Fun & Adventure Yogyakarta City Tour with daily itineraries, local guides, and highlights', '/images/indonesia/12-600x400.jpg', 'Experience the beauty of Indonesia with our special package: 5D/4N - Fun & Adventure Yogyakarta City Tour. Discover rich culture, stunning scenery, and unforgettable experiences on this day-by-day guided tour.', 
  110.37, -7.79, 'Historical', 'bg-amber-600', 
  'Custom package for 5D/4N - Fun & Adventure Yogyakarta City Tour including accommodation, tours, and transfers.', '/images/indonesia/12-600x400.jpg', 
  'published', '', '5 Days', 
  'Yogyakarta', 'Indonesian Rupiah (Rp)', 'Tropical with dry season (April–October) and wet season (November–March)', 'April–October (dry season)', 
  'Indonesian (Bahasa), English', 'WIB (UTC+7)', 'Left'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  111, 1, 'Day 1.', 'Yogyakarta', 
  'You will arrive at Yogyakarta International Airport via AirAsia, where your guide will be waiting to pick you up. You will then head directly to a local restaurant for dinner before checking into your hotel.', '["You will arrive at Yogyakarta International Airport via AirAsia, where your guide will be waiting to pick you up","You will then head directly to a local restaurant for dinner before checking into your hotel"]', '/images/explor-1.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  111, 2, 'Day 2.', 'Yogyakarta', 
  'Starts with breakfast at the hotel, followed by a lava tour in a 4WD jeep to explore Mount Merapi''s slopes. You will also visit Alien Rock, an underground bunker, and the SisaHartaku Museum. We will provide lunch for you at a local restaurant. Afterward, you will continue to Magelang and visit Borobudur Temple, the biggest Buddhist temple, before returning to Yogyakarta.', '["Starts with breakfast at the hotel, followed by a lava tour in a 4WD jeep to explore Mount Merapi''s slopes","You will also visit Alien Rock, an underground bunker, and the SisaHartaku Museum","We will provide lunch for you at a local restaurant"]', '/images/explor-1.jpg', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  111, 3, 'Day 3.', 'Yogyakarta', 
  'You will visit Pindul Cave for water activities, followed by an adrenaline rush on the gondola at TIMANG Beach (personal account of gondola ride included). You will then return to Yogyakarta for dinner at a local restaurant.', '["You will visit Pindul Cave for water activities, followed by an adrenaline rush on the gondola at TIMANG Beach (personal account of gondola ride included)","You will then return to Yogyakarta for dinner at a local restaurant"]', '/images/explor-1.jpg', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  111, 4, 'Day 4.', 'Yogyakarta', 
  'You will start with breakfast at the hotel and visit the Sultan''s Palace, known as "KRATON," home to the Yogyakarta King. Then, you will head to the Pines Forest, ideal for amateur and professional photographers. We will provide lunch for you at a local restaurant. In the afternoon, you will visit Heha Sky View, a new tourist spot on a hill that''s great for taking photos for your social media profile. Later, you will visit Malioboro Street, well-known for various goods and handicraft markets, and enjoy dinner at a local restaurant.', '["You will start with breakfast at the hotel and visit the Sultan''s Palace, known as \\"KRATON,\\" home to the Yogyakarta King","Then, you will head to the Pines Forest, ideal for amateur and professional photographers","We will provide lunch for you at a local restaurant"]', '/images/explor-1.jpg', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  111, 5, 'Day 5.', 'Yogyakarta', 
  'You will have breakfast at the hotel and check out before visiting Gamplong Studio Alam, where famous Indonesian filmmaker Hanung Bramantyo filmed several movies. After lunch at a local restaurant, you will continue to Yogyakarta International Airport to end your tour.', '["You will have breakfast at the hotel and check out before visiting Gamplong Studio Alam, where famous Indonesian filmmaker Hanung Bramantyo filmed several movies","After lunch at a local restaurant, you will continue to Yogyakarta International Airport to end your tour"]', '/images/explor-1.jpg', 4
);
