INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'jogyakarta', 'Jogyakarta', 'Indonesia', 'Southeast Asia', 
  'Cultural soul of Java — home of Borobudur and royal palaces', '/images/indonesia/9-600x400.webp', 'Jogyakarta (often called Jogja) is the cultural heart of Java, Indonesia. It is a city of historic palaces, vibrant street art, traditional batik, and shadow puppet theatre. Most importantly, it serves as the gateway to two of Southeast Asia''s greatest archaeological treasures: Borobudur, the world''s largest Buddhist temple, and Prambanan, a towering Hindu temple complex. Jogja remains a royal sultanate, blending royal heritage, ancient spirituality, and a bustling university atmosphere.', 
  110.37, -7.79, 'Historical', 'bg-amber-600', 
  'Ancient Borobudur temples, sultan palaces, and vibrant Javanese culture.', '/images/indonesia/9-600x400.webp', 
  'published', '', '3 Days', 
  'Jogyakarta', 'Indonesian Rupiah (Rp)', 'Tropical with dry season (April–October) and wet season (November–March)', 'April–October (dry season)', 
  'Javanese, Indonesian (Bahasa), English', 'WIB (UTC+7)', 'Left'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  112, 1, 'Jogyakarta Arrival & Sultan Palace', 'Jogyakarta', 
  'Arrive in Jogyakarta, transfer to hotel. In the afternoon, explore the Kraton Sultan Palace and Tamansari Water Castle.', '["Airport transfer to hotel","Explore Kraton Sultan Palace heritage","Visit Tamansari Water Castle ruins"]', '/images/indonesia/9-600x400.webp', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  112, 2, 'Borobudur Sunrise & Prambanan Temple', 'Jogyakarta', 
  'Wake up early for a spectacular sunrise over the ancient Borobudur Buddhist temple. In the afternoon, visit the towering Prambanan Hindu temple complex.', '["Spectacular sunrise at Borobudur","Explore the volcanic stone stupas","Visit Prambanan Hindu temples"]', '/images/indonesia/10-600x400.jpg', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  112, 3, 'Malioboro Shopping & Departure', 'Jogyakarta', 
  'Stroll along Jalan Malioboro for local batik shopping, then transfer to Jogyakarta International Airport for departure.', '["Batik shopping along Malioboro street","Transfer to Jogyakarta International Airport"]', '/images/indonesia/11-600x400.jpg', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  112, 'Temple Exploring', 'Walk through Borobudur and Prambanan temple compounds to admire ancient Javanese stone carvings.', 'Compass', 0
);
