INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'wae-rebo-village', 'Wae Rebo Village', 'Indonesia', 'Southeast Asia', 
  'The cloud village of Flores — traditional Mbaru Niang houses', '/images/indonesia/3-indo-600x400.jpg', 'Wae Rebo is an isolated, traditional village in the highlands of Manggarai on the island of Flores, Indonesia. Surrounded by dense rainforests and mountains, the village is famous for its unique conical houses called Mbaru Niang, built of wood and thatch. Reached only via a scenic 3-hour trek, Wae Rebo offers visitors a rare opportunity to experience traditional Manggarai lifestyle, warm hospitality, and pure starlight nights.', 
  120.28, -8.63, 'Adventure', 'bg-orange-500', 
  'Traditional mountain village with conical thatch houses in Flores.', '/images/indonesia/3-indo-600x400.jpg', 
  'published', '', '2 Days', 
  'Jakarta', 'Indonesian Rupiah (Rp)', 'Cool mountain climate, humid and wet during monsoons', 'April–October (dry season)', 
  'Manggarai, Indonesian (Bahasa), English', 'WITA (UTC+8)', 'Left'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  113, 1, 'Trek to Wae Rebo Village', 'Wae Rebo Village', 
  'Drive from Labuan Bajo or Denge, then embark on a scenic 3-hour jungle trek up to Wae Rebo Village. Welcome ceremony and overnight in Mbaru Niang.', '["Drive through Flores hills","Trek through lush mountain jungle","Stay in a traditional conical Mbaru Niang house"]', '/images/indonesia/3-indo-600x400.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  113, 2, 'Explore Wae Rebo & Return', 'Wae Rebo Village', 
  'Interact with the local community, learn about their daily coffee harvesting, and trek back down to Denge before transferring back.', '["Meet local Manggarai families","Learn about traditional mountain coffee making","Scenic trek down the mountain"]', '/images/indonesia/4-indo-600x400.jpg', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  113, 'Mbaru Niang Stay', 'Experience sleeping on traditional woven mats inside the towering conical thatch houses.', 'Home', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  113, 'Coffee Tasting', 'Enjoy freshly brewed organic Arabica coffee harvested directly from the surrounding mountain slopes.', 'Coffee', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  113, 'Dress warmly as temperature drops significantly at night in the mountains.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  113, 'Bring cash to purchase local mountain coffee and handwoven textiles.', 1
);
