INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  114, 1, 'Day 1', 'Jogyakarta', 
  'The itinerary involves arriving at Yogyakarta International Airport via AirAsia and being picked up by a guide. From there, you will be taken to a local restaurant for dinner before checking in at the hotel.', '["The itinerary involves arriving at Yogyakarta International Airport via AirAsia and being picked up by a guide","From there, you will be taken to a local restaurant for dinner before checking in at the hotel"]', '/images/explor-1.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  114, 2, 'Day 2', 'Jogyakarta', 
  'will begin with a breakfast at the hotel, followed by a Lava tour where you will explore the slopes of Mount Merapi using a 4 WD jeep. The first stop on this tour will be the Alien Rock, after which you will head to the underground bunker and SisaHartaku Museum. You will then have lunch at a local restaurant before continuing your journey to Magelang, where you will visit the Borobudur Temple, the biggest Buddhist temple. Once you return to Yogyakarta, you should not miss seeing Malioboro Street, which has many stores selling handmade items and souvenirs. Your day will end with dinner at a local restaurant before being taken back to the hotel.', '["will begin with a breakfast at the hotel, followed by a Lava tour where you will explore the slopes of Mount Merapi using a 4 WD jeep","The first stop on this tour will be the Alien Rock, after which you will head to the underground bunker and SisaHartaku Museum","You will then have lunch at a local restaurant before continuing your journey to Magelang, where you will visit the Borobudur Temple, the biggest Buddhist temple"]', '/images/explor-1.jpg', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  114, 3, 'Day 3', 'Jogyakarta', 
  'involves visiting Gamplong and Studio Alam during your stay at the hotel. The filmmakers used these places for filming Sultan Agung: Throne, Struggle, Love, Earth of Mankind, and Ainun Habibie 3. Finally, you will have lunch at a local restaurant before being transferred to Yogyakarta International Airport to end the tour.', '["involves visiting Gamplong and Studio Alam during your stay at the hotel","The filmmakers used these places for filming Sultan Agung: Throne, Struggle, Love, Earth of Mankind, and Ainun Habibie 3","Finally, you will have lunch at a local restaurant before being transferred to Yogyakarta International Airport to end the tour"]', '/images/explor-1.jpg', 2
);
