INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'vientiane', 'Vientiane', 'Laos', 'Southeast Asia', 
  'The quiet capital on the Mekong, known for golden stupas and French-Lao heritage', '/images/laos/laos-6.jpg', 'Vientiane, the capital of Laos, sits on a bend of the Mekong River bordering Thailand. It retains a peaceful, slow-paced charm unlike other regional capitals, featuring wide French-designed boulevards alongside gilded Buddhist temples. Key sights include the massive golden Pha That Luang stupa, the Patuxai victory monument resembling a Parisian Arc de Triomphe decorated with Lao motifs, and bustling night markets overlooking the Mekong.', 
  102.6, 17.97, 'Spiritual', 'bg-violet-500', 
  'Quiet riverside capital, golden stupas, and French colonial charm.', '/images/laos/laos-6.jpg', 
  'published', '', '3 Days', 
  'Vientiane', 'Laotian Kip (LAK)', 'Tropical monsoon — hot year-round, wet May–October', 'November–February (cool, dry season)', 
  'Lao, French, English', 'ICT (UTC+7)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  116, 1, 'Arrive Vientiane, Transfer to Hotel', 'Vientiane', 
  'Arrive at Wattay International Airport in Vientiane, meet and greet with your driver, and transfer to your hotel. Afternoon at leisure.', '["Airport pickup and hotel transfer","Check-in and rest at hotel","Explore Vientiane riverside walk at sunset"]', '/images/laos/laos-6.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  116, 2, 'Vientiane City Tour', 'Vientiane', 
  'Explore Vientiane''s landmarks, including the gold-covered Pha That Luang, Wat Si Saket with its thousands of Buddha statues, Haw Phra Kaew, and climb Patuxai Monument for panoramic views.', '["Marvel at golden Pha That Luang","Explore thousands of Buddha icons at Wat Si Saket","Visit the former royal temple Haw Phra Kaew","Climb Patuxai monument"]', '/images/laos/laos-4.jpg', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  116, 3, 'Morning Market & Departure', 'Vientiane', 
  'Visit the Talat Sao morning market for local handicrafts, textiles, and foods. Transfer to airport for departure.', '["Bargain for local textiles at Talat Sao market","Transfer to Vientiane Airport for departure"]', '/images/laos/laos-5.jpg', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  116, 'Golden Stupa Tour', 'Walk around the sacred gold-leafed Pha That Luang, the national symbol of Laos.', 'Compass', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  116, 'Mekong Sunset Walk', 'Join locals for an evening stroll, aerobics, and street food along the Mekong River park.', 'Sunset', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  116, 'Tap water is not drinkable; always consume bottled or filtered water.', 0
);
INSERT INTO `tour_package_travel_tips` (
