INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'luang-prabang', 'Luang Prabang', 'Laos', 'Southeast Asia', 
  'UNESCO ancient capital of royal temples, monk almsgiving, and Kuang Si waterfalls', '/images/laos/laos-1.jpg', 'Luang Prabang, the former royal capital of Laos, is a UNESCO World Heritage site nestled in a valley where the Mekong and Nam Khan rivers meet. Renowned for its outstandingly preserved architectural fusion of traditional Lao wooden houses and French provincial brick structures, the town is the spiritual heart of Laos. Witness the daily sunrise saffron-robed monk almsgiving (Tak Bat), climb Mount Phousi, visit the historic Wat Xieng Thong, and swim in the multi-tiered turquoise pools of Kuang Si Waterfall.', 
  102.13, 19.89, 'Historical', 'bg-amber-600', 
  'UNESCO town of old French villas, active temples, and turquoise jungle waterfalls.', '/images/laos/laos-1.jpg', 
  'published', '', '3 Days', 
  'Vientiane', 'Laotian Kip (LAK)', 'Tropical monsoon — hot year-round, wet May–October', 'November–February (cool, dry season)', 
  'Lao, English', 'ICT (UTC+7)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  117, 1, 'Luang Prabang Arrival & Sunset Mount Phousi', 'Luang Prabang', 
  'Arrive in Luang Prabang, meet your driver, and transfer to hotel. In the late afternoon, climb 328 steps up Mount Phousi for a panoramic sunset view over the town and Mekong River. Explore the Night Market.', '["Airport pickup and check-in","Climb Mount Phousi for golden sunset views","Browse traditional crafts at the Night Market"]', '/images/laos/laos-1.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  117, 2, 'Almsgiving & Wat Xieng Thong & Kuang Si Waterfall', 'Luang Prabang', 
  'Wake up early to witness Tak Bat (monk almsgiving). Visit the exquisite Wat Xieng Thong temple with its sweeping roofs. In the afternoon, drive to the breathtaking Kuang Si Waterfall to swim in the natural turquoise pools.', '["Observe early morning Buddhist almsgiving","Visit Wat Xieng Thong temple heritage","Swim in turquoise pools of Kuang Si Waterfall"]', '/images/laos/laos-7.jpg', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  117, 3, 'Pak Ou Caves & Departure', 'Luang Prabang', 
  'Take a scenic longtail boat cruise upstream along the Mekong to visit Pak Ou Caves, crammed with thousands of Buddha icons. Transfer to airport for departure.', '["Mekong River longtail boat cruise","Explore Pak Ou Caves filled with Buddha statues","Transfer to Luang Prabang Airport"]', '/images/laos/laos-2.jpg', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  117, 'Tak Bat Almsgiving', 'Participate or observe silently at dawn as hundreds of saffron-robed monks collect food donations.', 'Compass', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  117, 'Waterfall Swimming', 'Cool off in the multi-tiered cascades of Kuang Si, surrounded by dense jungle.', 'Droplets', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  117, 'Keep a respectful distance and avoid camera flashes during the morning almsgiving ceremony.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  117, 'Bring swimwear and a towel for the pools at Kuang Si Waterfall.', 1
);
