INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'vang-vieng', 'Vang Vieng', 'Laos', 'Southeast Asia', 
  'Stunning karst mountains, blue lagoons, and tubing down the Nam Song river', '/images/laos/laos-3.jpg', 'Vang Vieng is an adventure hub in central Laos, surrounded by dramatic limestone karst landscapes, natural caves, and deep blue springs. Originally known as a party destination, Vang Vieng has matured into a premium outdoor adventure sanctuary offering rock climbing, hot air ballooning, kayaking, and cave exploring, while retaining its laid-back riverside charm.', 
  102.45, 18.93, 'Adventure', 'bg-orange-500', 
  'Dramatic karst mountain landscape, clear blue lagoons, and tubing.', '/images/laos/laos-3.jpg', 
  'published', '', '2 Days', 
  'Vientiane', 'Laotian Kip (LAK)', 'Tropical monsoon — hot year-round, wet May–October', 'November–February (cool, dry season)', 
  'Lao, English', 'ICT (UTC+7)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  118, 1, 'Arrive Vang Vieng & Nam Song Sunset Cruise', 'Vang Vieng', 
  'Arrive in Vang Vieng from Vientiane or Luang Prabang. Check in to your hotel. Enjoy a relaxing longtail boat ride along the Nam Song River at sunset, flanked by towering karst mountains.', '["Scenic transfer to Vang Vieng"," Nam Song River longtail boat cruise","Sunset views of karst mountains"]', '/images/laos/laos-3.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  118, 2, 'Blue Lagoon & Tham Phu Kham Cave', 'Vang Vieng', 
  'Explore the famous Blue Lagoon, jump into the crystal waters, and hike up to the mystical Tham Phu Kham Cave to see the golden reclining Buddha inside.', '["Swim in the crystal blue lagoon","Hike to Tham Phu Kham golden Buddha cave","Cross the iconic orange bridge"]', '/images/laos/laos-8.jpg', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  118, 'Lagoon Jumping', 'Swing from rope swings into the cold blue waters of Vang Vieng''s natural springs.', 'Droplets', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  118, 'Cave Kayaking', 'Navigate tunnels and waters inside the water-filled Tham Nam cave on an inflatable tube.', 'Compass', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  118, 'Rent a bicycle or buggy to explore the countryside dirt tracks surrounding Vang Vieng.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  118, 'Wear life jackets when tubing or kayaking on the Nam Song River.', 1
);
