INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'xieng-khuang', 'Xieng Khuang', 'Laos', 'Southeast Asia', 
  'Gate to the mysterious Plain of Jars, an archaeological wonder of giant stone vessels', '/images/laos/laos-4.jpg', 'Xieng Khuang province, centered around Phonsavan town, is a highland region famous for the Plain of Jars — a UNESCO World Heritage site consisting of thousands of giant stone jars scattered across the valleys. Dating back to the Iron Age, these mysterious vessels are believed to have been used in ancient burial rituals. Xieng Khuang also holds deep historical significance as one of the most heavily bombed regions during the Secret War, today standing as a testament to resilience.', 
  103.22, 19.45, 'Historical', 'bg-amber-600', 
  'UNESCO Plain of Jars stone archaeological sites and Secret War history.', '/images/laos/laos-4.jpg', 
  'published', '', '2 Days', 
  'Vientiane', 'Laotian Kip (LAK)', 'Cooler highland climate, tropical monsoon', 'November–February (dry and cool)', 
  'Lao, English', 'ICT (UTC+7)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  119, 1, 'Arrive Phonsavan & Plain of Jars Site 1', 'Xieng Khuang', 
  'Arrive in Phonsavan, transfer to hotel. Visit Site 1 of the Plain of Jars, the largest and most famous site, containing over 300 giant stone vessels.', '["Arrive in highland Phonsavan","Explore Plain of Jars Site 1 archeology","See craters left by Secret War bombs"]', '/images/laos/laos-4.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  119, 2, 'Plain of Jars Site 2 & Site 3 & MAG Center', 'Xieng Khuang', 
  'Explore the scenic forest-enveloped Site 2 and Site 3 jars. In the afternoon, visit the Mines Advisory Group (MAG) visitor center to learn about UXO clearance work in Laos.', '["Trek to scenic forest Site 2 and Site 3","Visit MAG UXO center to support clearing operations","Discover local Hmong village crafts"]', '/images/laos/laos-5.jpg', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  119, 'Stone Jar Hiking', 'Walk through pine-forested hills to locate ancient stone jars of varying shapes and sizes.', 'Compass', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  119, 'MAG Center Visit', 'Learn about the tragicSecret War history and humanitarian demining efforts in Laos.', 'Info', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  119, 'Always stay on marked paths at Plain of Jars sites, as clearance of UXO is still ongoing in surrounding areas.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  119, 'Xieng Khuang is elevated, so it can get chilly; bring a light jacket or sweater.', 1
);
