) VALUES (
  'laos-1', '6N/7D - Amazing Laos for Honeymooners', 'Laos', 'Southeast Asia', 
  'Explore 6N/7D - Amazing Laos for Honeymooners with daily itineraries, local guides, and highlights', '/images/laos/laos-1.jpg', 'Experience the beauty of Laos with our special package: 6N/7D - Amazing Laos for Honeymooners. Discover rich culture, stunning scenery, and unforgettable experiences on this day-by-day guided tour.', 
  102.13, 19.89, 'Luxury', 'bg-indigo-500', 
  'Custom package for 6N/7D - Amazing Laos for Honeymooners including accommodation, tours, and transfers.', '/images/laos/laos-1.jpg', 
  'published', '', '7 Days', 
