INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  121, 1, 'LUANG PRABANG ARRIVAL - LUANG PRABANG CITY TOUR', 'Vientiane', 
  'Luang Prabang is one of the best preserved traditional cities in Southeast Asia. It is one of the most peaceful and charming places in Laos, with beautiful natural scenery and cultural attractions.
After a brief rest, we visit Wat Visoun stupa and Wat Aham shrine, Wat Mai. Then, we climb Mount Phousi to explore the sacred, golden stupa and enjoy the sunset view of the town and the Mekong river.
From Mount Phousi, we go to the Night Market where you can buy handmade textiles from the hill tribe and the local people around the town.
You can spend the night in Luang prabang. Standard check in is 14:00, early check in depends on availability of the hotel.', '["Luang Prabang is one of the best preserved traditional cities in Southeast Asia","It is one of the most peaceful and charming places in Laos, with beautiful natural scenery and cultural attractions.\\nAfter a brief rest, we visit Wat Visoun stupa and Wat Aham shrine, Wat Mai","Then, we climb Mount Phousi to explore the sacred, golden stupa and enjoy the sunset view of the town and the Mekong river.\\nFrom Mount Phousi, we go to the Night Market where you can buy handmade textiles from the hill tribe and the local people around the town.\\nYou can spend the night in Luang prabang"]', '/images/laos/laos-6.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  121, 2, 'LUANG PRABANG - CITY TOUR - PAK OU CAVE (B)', 'Vientiane', 
  'After breakfast, we visit The National Museum at the former Royal Palace, which displays a lovely collection of the artifacts reflecting the richness of Lao culture dating from the days of the early kings right through to the last sovereign. Continue to explore some of the major sights in this faboulous city, including the city’s oldest temple of Wat Sene, the magnificent Wat Xiengthong, its exterior architecture is remarkable with decorated guilded stuccoes and doorways, a “tree of life” mosaic pattern set in coloured glass on the back wall and its three tiered roofs sweeping low to the ground representing classical Laotian architecture.
Afternoon we then embark on a cruise upstream on the Mekong River, which also gives us a breathtaking view of the tranquil countryside as well as explore the mysterious Pak Ou Caves, two linked caves crammed with thousands of gold lacquered Buddha statues of various shapes and sizes left by pilgrims.  Along the way, we stop at the village of Ban Xanghai, where they make the local rice wine. On return, we take a short drive to Ban Xangkhong, a village well known for its silk weavings and for its Saa (jute) Papermaking and Ban Phanom, a small village known for its hand weaving. Overnight in Luang Prabang.', '["After breakfast, we visit The National Museum at the former Royal Palace, which displays a lovely collection of the artifacts reflecting the richness of Lao culture dating from the days of the early kings right through to the last sovereign","Continue to explore some of the major sights in this faboulous city, including the city’s oldest temple of Wat Sene, the magnificent Wat Xiengthong, its exterior architecture is remarkable with decorated guilded stuccoes and doorways, a “tree of life” mosaic pattern set in coloured glass on the back wall and its three tiered roofs sweeping low to the ground representing classical Laotian architecture.\\nAfternoon we then embark on a cruise upstream on the Mekong River, which also gives us a breathtaking view of the tranquil countryside as well as explore the mysterious Pak Ou Caves, two linked caves crammed with thousands of gold lacquered Buddha statues of various shapes and sizes left by pilgrims","Along the way, we stop at the village of Ban Xanghai, where they make the local rice wine"]', '/images/laos/laos-6.jpg', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  121, 3, 'LUANG PRABANG - KUANGSI WATERFALL - VIENTIANE BY FLIGHT (B)', 'Vientiane', 
  'With an optional early start, you have the amazing chance to take part in the morning rituals where saffron-dressed monks collect Alms (unlimited sticky rice) from local inhabitants. Laos is the only Buddhist nation in the world to still have this tradition.
After breakfast at your hotel, transfer to Khouangsi waterfall, where you can cool down with a refreshing pool or stroll through the forest trails.
From Khouangsi, head to the airport to catch your flight to the capital of Laos, Vientiane. Upon arrival, you will be greeted by our tour guide, and then transfer to your hotel for check in, where you will spend the night.', '["With an optional early start, you have the amazing chance to take part in the morning rituals where saffron-dressed monks collect Alms (unlimited sticky rice) from local inhabitants","Laos is the only Buddhist nation in the world to still have this tradition.\\nAfter breakfast at your hotel, transfer to Khouangsi waterfall, where you can cool down with a refreshing pool or stroll through the forest trails.\\nFrom Khouangsi, head to the airport to catch your flight to the capital of Laos, Vientiane","Upon arrival, you will be greeted by our tour guide, and then transfer to your hotel for check in, where you will spend the night"]', '/images/laos/laos-6.jpg', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  121, 4, 'VIENTIANE FULL DAY CITY TOUR (B)', 'Vientiane', 
  'After breakfast we ride 306km uphill on a mountain rim surrounded by stunning natural scenery to the historical site of Xieng khuang which was destroyed by U.S. bombing from 1964 to 1973. Once we arrive, we will be transferred to visit the plain of jars which is an archaeological site with hundreds of big stone jars scattered on the plains. If we have time, we will visit the old capital Muang khuang and nearby villages where Hmong hill tribesmen live with a colorful history and interesting local culture. We will spend an overnight in xiang khuang.', '["After breakfast we ride 306km uphill on a mountain rim surrounded by stunning natural scenery to the historical site of Xieng khuang which was destroyed by U.S","bombing from 1964 to 1973","Once we arrive, we will be transferred to visit the plain of jars which is an archaeological site with hundreds of big stone jars scattered on the plains"]', '/images/laos/laos-6.jpg', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  121, 5, 'DEPARTURE (B)', 'Vientiane', 
  'Breakfast at the hotel and check-out. Free time at your own pace until your transfer to the airport for your flight. End of service.', '["Breakfast at the hotel and check-out","Free time at your own pace until your transfer to the airport for your flight","End of service"]', '/images/laos/laos-6.jpg', 4
);
