) VALUES (
  122, 6, 'DEPARTURE (B)', 'Luang Prabang', 
  'After breakfast, free time until your next transfer to the airport for your onward flight.
End of service', '["After breakfast, free time until your next transfer to the airport for your onward flight.\\nEnd of service"]', '/images/laos/laos-2.jpg', 5
);
