) VALUES (
  'laos-8', '3N/4D - Exploration of Luang Prabang', 'Laos', 'Southeast Asia', 
  'Explore 3N/4D - Exploration of Luang Prabang with daily itineraries, local guides, and highlights', '/images/laos/laos-8.jpg', 'Experience the beauty of Laos with our special package: 3N/4D - Exploration of Luang Prabang. Discover rich culture, stunning scenery, and unforgettable experiences on this day-by-day guided tour.', 
