INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  125, 1, 'LUANG PRABANG ARRIVAL - CITY TOUR', 'Luang Prabang', 
  'Luang Prabang is one of the best preserved traditional cities in Southeast Asia. It is one of the most peaceful and charming places in Laos, with beautiful natural scenery and cultural attractions. After a short break, we visit Wat Visoun stupa and Wat Aham shrine, Wat Mai. Then, we climb Mount Phousi, where we can explore the sacred, gold-studded stupa and enjoy a stunning sunset view of our city and Mekong River. After that, we go to the Night Market where we can find a beautiful collection of handmade textiles handmade by the hill tribe and the local people in the area. We will spend the night in Luang prabang. Standard check in is 14:00, early check in depends on availability of the hotel.', '["Luang Prabang is one of the best preserved traditional cities in Southeast Asia","It is one of the most peaceful and charming places in Laos, with beautiful natural scenery and cultural attractions","After a short break, we visit Wat Visoun stupa and Wat Aham shrine, Wat Mai"]', '/images/laos/laos-8.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  125, 2, 'LUANG PRABANG - CITY TOUR - PAK OU CAVE (B)', 'Luang Prabang', 
  'After breakfast, we visit The National Museum at the former Royal Palace, which displays a lovely collection of the artifacts reflecting the richness of Lao culture dating from the days of the early kings right through to the last sovereign. Continue to explore some of the major sights in this faboulous city, including the city’s oldest temple of Wat Sene, the magnificent Wat Xiengthong, its exterior architecture is remarkable with decorated guilded stuccoes and doorways, a “tree of life” mosaic pattern set in coloured glass on the back wall and its three tiered roofs sweeping low to the ground representing classical Laotian architecture.
Afternoon we then embark on a cruise upstream on the Mekong River, which also gives us a breathtaking view of the tranquil countryside as well as explore the mysterious Pak Ou Caves, two linked caves crammed with thousands of gold lacquered Buddha statues of various shapes and sizes left by pilgrims.  Along the way, we stop at the village of Ban Xanghai, where they make the local rice wine. On return, we take a short drive to Ban Xangkhong, a village well known for its silk weavings and for its Saa (jute) Papermaking and Ban Phanom, a small village known for its hand weaving. Overnight in Luang Prabang.', '["After breakfast, we visit The National Museum at the former Royal Palace, which displays a lovely collection of the artifacts reflecting the richness of Lao culture dating from the days of the early kings right through to the last sovereign","Continue to explore some of the major sights in this faboulous city, including the city’s oldest temple of Wat Sene, the magnificent Wat Xiengthong, its exterior architecture is remarkable with decorated guilded stuccoes and doorways, a “tree of life” mosaic pattern set in coloured glass on the back wall and its three tiered roofs sweeping low to the ground representing classical Laotian architecture.\\nAfternoon we then embark on a cruise upstream on the Mekong River, which also gives us a breathtaking view of the tranquil countryside as well as explore the mysterious Pak Ou Caves, two linked caves crammed with thousands of gold lacquered Buddha statues of various shapes and sizes left by pilgrims","Along the way, we stop at the village of Ban Xanghai, where they make the local rice wine"]', '/images/laos/laos-8.jpg', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  125, 3, 'LUANG PRABANG - KUANGSI WATERFALL (B)', 'Luang Prabang', 
  'With an optional early start, you have the amazing chance to take part in the morning rituals of the saffron-dressed monks collecting Alms (rubbish rice) from the loyal inhabitants. Laos is the only Buddhist nation that still follows this tradition.
From the morning market, you will visit the Phosi Market where you will see all kinds of offerings such as dried buffalo skins, local tea, saltpeter from chickens, vegetables and handmade weavings.
Laos is also famous for its traditional handicrafts. Today you will visit the local villages of Laotian ethnic minorities at Ban Ouay village, Hmong village, Ban Ou village Laoloum village, Ban Thapene village Khmu Village, and then drive to Khouangsi waterfall where you can swim in the beautiful turquoise pools, or take a stroll through the forest trails.
By late afternoon, you will return to the city to watch the sunset at wat phabath.', '["With an optional early start, you have the amazing chance to take part in the morning rituals of the saffron-dressed monks collecting Alms (rubbish rice) from the loyal inhabitants","Laos is the only Buddhist nation that still follows this tradition.\\nFrom the morning market, you will visit the Phosi Market where you will see all kinds of offerings such as dried buffalo skins, local tea, saltpeter from chickens, vegetables and handmade weavings.\\nLaos is also famous for its traditional handicrafts","Today you will visit the local villages of Laotian ethnic minorities at Ban Ouay village, Hmong village, Ban Ou village Laoloum village, Ban Thapene village Khmu Village, and then drive to Khouangsi waterfall where you can swim in the beautiful turquoise pools, or take a stroll through the forest trails.\\nBy late afternoon, you will return to the city to watch the sunset at wat phabath"]', '/images/laos/laos-8.jpg', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  125, 4, 'DEPARTURE (B)', 'Luang Prabang', 
  'Breakfast at the hotel and check-out. Free time until your transfer to the airport for your flight departure. End of service.', '["Breakfast at the hotel and check-out","Free time until your transfer to the airport for your flight departure","End of service"]', '/images/laos/laos-8.jpg', 3
);
