INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  126, 1, 'VIENTIANE ARRIVAL – CITY TOUR', 'Vientiane', 
  'On arrival, you will be picked up by your local tour guide from Wattay airport, and transferred to check in to your hotel. Check in is at 14h00.
This afternoon, we will begin our city tour from the oldest temple in the city, Wat sisaket. Built in 1818, this temple is the most significant heritage temple in Laos today. It is home to thousands of Buddha pictures from all over the world, long lost architecture styles, sculptures, and paintings.
On the way to That Luang stupa, you will stop to take pictures of the impressive Patuxay monument, the Arc de Triumph of Vientiane, and then enjoy the sunset by boat trip on Mekong river.
After that, you will continue your tour by visiting Wat prakeo, the former royal temple in the Laotian monarchy, originally constructed in 1565 and the home of the emerald Buddha image. Along the perimeter wall of the temple, you will see Buddhist sculptures from the 6th-9th centuries, including a standing and sitting Buddha and several other Buddhas.
You will be able to spend the night in vientiane. Please note that the check in is at 14:00,', '["On arrival, you will be picked up by your local tour guide from Wattay airport, and transferred to check in to your hotel","Check in is at 14h00.\\nThis afternoon, we will begin our city tour from the oldest temple in the city, Wat sisaket","Built in 1818, this temple is the most significant heritage temple in Laos today"]', '/images/laos/laos-4.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  126, 2, 'VIENTIANE – BUDDHA PARK – FLY TO LUANG PRABANG (B)', 'Vientiane', 
  'After breakfast and check-in at your hotel, visit Buddha Park, where you can see hundreds of Buddha and Hindu statues imported from India. After visiting the Buddha Park, you will be transferred to the airport for your flight to Luang prabang.
Upon arrival, you will be picked up by your local tour guide from the airport and transferred to check in to your hotel.
You will spend the night in Luang pprabang.', '["After breakfast and check-in at your hotel, visit Buddha Park, where you can see hundreds of Buddha and Hindu statues imported from India","After visiting the Buddha Park, you will be transferred to the airport for your flight to Luang prabang.\\nUpon arrival, you will be picked up by your local tour guide from the airport and transferred to check in to your hotel.\\nYou will spend the night in Luang pprabang"]', '/images/laos/laos-4.jpg', 1
);
