INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'laos-5', '12N/13D - Laos at a Glance', 'Laos', 'Southeast Asia', 
  'Explore 12N/13D - Laos at a Glance with daily itineraries, local guides, and highlights', '/images/laos/laos-5.jpg', 'Experience the beauty of Laos with our special package: 12N/13D - Laos at a Glance. Discover rich culture, stunning scenery, and unforgettable experiences on this day-by-day guided tour.', 
  103.22, 19.45, 'Historical', 'bg-amber-600', 
  'Custom package for 12N/13D - Laos at a Glance including accommodation, tours, and transfers.', '/images/laos/laos-5.jpg', 
  'published', '', '13 Days', 
  'Vientiane', 'Laotian Kip (LAK)', 'Tropical monsoon — hot year-round, wet May–October', 'November–February (cool, dry season)', 
  'Lao, English', 'ICT (UTC+7)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  127, 1, 'ARRIVAL – LUANG PRABANG (B)', 'Xieng Khuang', 
  'Upon arrival, you will be greeted by our guide and then transferred to your hotel for check-in and leisurely time. You will spend the night in Luang prabang international airport.', '["Upon arrival, you will be greeted by our guide and then transferred to your hotel for check-in and leisurely time","You will spend the night in Luang prabang international airport"]', '/images/laos/laos-5.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  127, 2, 'LUANG PRABANG – CITY TOUR – KHOUANGSI WATER FALL (B)', 'Xieng Khuang', 
  'After breakfast, we enjoy a short-guided tour visit the National Museum at the former Royal Palace displays a lovely collection of the artifacts reflecting the richness of Lao culture dating from the days of the early kings right through the last sovereign; we will visit Wat Visoun, the holiest temple of the city, which was entirely rebuilt in 1887 after being destroyed by the invading Black Flags from Southern China. In the courtyard of Wat Visoun stands the Watermelon Stupa shaped like the fruit from which it takes its name. Continue past Wat Aham, which was first built in the 1500s and we then to Khouang Si waterfall. On the way, you can visit to the Lao ethnic minority groups-Ban Ouay Village, Ban Ou village and Ban Thapene Village. Once at the waterfalls, take a leisurely hike through the national park towards the Khouangsi waterfall and pass by the Asian bear rescue center. You will enjoy feeling the mist of the cool, turquoise waters of the different waterfalls. Swimming in the refreshing waters is possible. Transfer back to Luang Prabang for climb up 328 steps of Mount Phousi for an enjoyable exploration of the sacred, gilded stupa as well as a beautiful sunset view of the city and the Mekong River. We then will explore the Night Market, where you can find a lovely selection of handmade textiles made by the hill tribe and local people surrounding Luang Prabang. Overnight in Luang Prabang', '["After breakfast, we enjoy a short-guided tour visit the National Museum at the former Royal Palace displays a lovely collection of the artifacts reflecting the richness of Lao culture dating from the days of the early kings right through the last sovereign; we will visit Wat Visoun, the holiest temple of the city, which was entirely rebuilt in 1887 after being destroyed by the invading Black Flags from Southern China","In the courtyard of Wat Visoun stands the Watermelon Stupa shaped like the fruit from which it takes its name","Continue past Wat Aham, which was first built in the 1500s and we then to Khouang Si waterfall"]', '/images/laos/laos-5.jpg', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  127, 3, 'LUANG PRABANG – PAK OU CAVE (B)', 'Xieng Khuang', 
  'An optional early start gives you the fantastic opportunity to participate in the daily morning rituals of saffron-clad monks collecting offerings of Alms (ubiquitous sticky rice) from the faithful residents. This tradition is very unique in Laos, being the only Buddhist nation still preserving the procession. We then visit the Morning Market, where you will see such diverse offerings as dried buffalo skin, local tea and saltpeter among the chickens, vegetables and hill-tribe weavings. Then back to hotel for breakfast before visiting the magnificent Wat Xiengthong with its roofs sweeping low to the ground, which represents classical Laotian architecture. We then board a cruise upstream on the Mekong River, which also gives us a panoramic view of the tranquil countryside as well as an interesting visit to the mysterious of Pak Ou Caves, two linked caves crammed with thousands of gold lacquered Buddha statues of various shapes and sizes left by pilgrims. Along the way, we will make a stop at Ban Xang Hai village where rice wine is distilled. We will visit the caves of Tham Ting and Tham Phoum which house hundreds of Buddha statues. We return to Luang Prabang in the afternoon, continue to visit Ban Xang Khong, a village well known for silk hand-weaving and traditional Saa paper-making. Overnight in Luang Prabang', '["An optional early start gives you the fantastic opportunity to participate in the daily morning rituals of saffron-clad monks collecting offerings of Alms (ubiquitous sticky rice) from the faithful residents","This tradition is very unique in Laos, being the only Buddhist nation still preserving the procession. We then visit the Morning Market, where you will see such diverse offerings as dried buffalo skin, local tea and saltpeter among the chickens, vegetables and hill-tribe weavings","Then back to hotel for breakfast before visiting the magnificent Wat Xiengthong with its roofs sweeping low to the ground, which represents classical Laotian architecture"]', '/images/laos/laos-5.jpg', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  127, 4, 'LUANG PRABANG – XIENG KHUANG (B)', 'Xieng Khuang', 
  'After breakfast we ride 306km uphill on a mountain rim surrounded by stunning natural scenery to the historical site of Xieng khuang which was destroyed by U.S. bombing from 1964 to 1973. Once we arrive, we will be transferred to visit the plain of jars which is an archaeological site with hundreds of big stone jars scattered on the plains. If we have time, we will visit the old capital Muang khuang and nearby villages where Hmong hill tribesmen live with a colorful history and interesting local culture. We will spend an overnight in xiang khuang.', '["After breakfast we ride 306km uphill on a mountain rim surrounded by stunning natural scenery to the historical site of Xieng khuang which was destroyed by U.S","bombing from 1964 to 1973","Once we arrive, we will be transferred to visit the plain of jars which is an archaeological site with hundreds of big stone jars scattered on the plains"]', '/images/laos/laos-5.jpg', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  127, 5, 'XIENG KHUANG – VANG VIENG – CITY TOUR (B)', 'Xieng Khuang', 
  'After breakfast, we will drive to Vang Vieng on the way. Along the way, we will visit the Buddha images at the site of Thampra, which is over 200 years old. We will also visit several Hmong and hill tribe minority villages on the way. After several photo stops, we will continue on the road, taking in the beautiful natural scenery of mountains, forest and landscape. We will drive through mountainous regions until we reach Vang Vieng, where we will stay for a short rest before taking a long tail boat on the Nam Song river for sightseeing and visiting a mulberry farm to taste mulberry tea before returning to our hotel for an overnight stay.', '["After breakfast, we will drive to Vang Vieng on the way","Along the way, we will visit the Buddha images at the site of Thampra, which is over 200 years old","We will also visit several Hmong and hill tribe minority villages on the way"]', '/images/laos/laos-5.jpg', 4
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  127, 6, 'VANG VIENG – VIENTIANE – HALF DAY TOUR (B)', 'Xieng Khuang', 
  'After breakfast, we drove 3 hours to Vientiane, stopping at finishing villages at Ban Houimor and Hmong market at KM 52 before arriving at Vientiane, where we stayed at a hotel.
After that, we started to explore the town by visiting the oldest temple in Vientiane, Wat Sisaketo, which has amazing frescoes and amazing Buddha images.
Then, we visited Haw Prakeo which was once the royal temple of the Laos monarchy, which used to be the Emerald Buddha Statue.
Next, we visited the impressive Patuxay Monument which is known as Vientian’s own Arc de Triumph.
Finally, we visited the famous that Luang stupa.
We stayed in Vientiane overnight.', '["After breakfast, we drove 3 hours to Vientiane, stopping at finishing villages at Ban Houimor and Hmong market at KM 52 before arriving at Vientiane, where we stayed at a hotel.\\nAfter that, we started to explore the town by visiting the oldest temple in Vientiane, Wat Sisaketo, which has amazing frescoes and amazing Buddha images.\\nThen, we visited Haw Prakeo which was once the royal temple of the Laos monarchy, which used to be the Emerald Buddha Statue.\\nNext, we visited the impressive Patuxay Monument which is known as Vientian’s own Arc de Triumph.\\nFinally, we visited the famous that Luang stupa.\\nWe stayed in Vientiane overnight"]', '/images/laos/laos-5.jpg', 5
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  127, 7, 'VIENTIANE – THA KHAEK – BAN NA HIN (B)', 'Xieng Khuang', 
  'After breakfast, we will leave early in the morning on our way to Khom Moulan Province. We can make several stops along the way to stretch our legs and take beautiful photos of the beautiful scenery. Depending on the road and traffic conditions, we will reach Ban Na Hin, Khong Lor Cave''s entrance by late afternoon. Upon arrival, we will take a short stroll around this charming village to learn more about the locals'' culture and lifestyle. We will spend the night in Ban Na Hin.', '["After breakfast, we will leave early in the morning on our way to Khom Moulan Province","We can make several stops along the way to stretch our legs and take beautiful photos of the beautiful scenery","Depending on the road and traffic conditions, we will reach Ban Na Hin, Khong Lor Cave''s entrance by late afternoon"]', '/images/laos/laos-5.jpg', 6
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  127, 8, 'BAN NA HIN – KHONG LOR CAVE – BAN NA HIN (B)', 'Xieng Khuang', 
  'After breakfast this morning, we will take a short drive to Khong Lor cave. Khong Lor cave is the result of the 7.5kms of Hinboun river flowing through the mountains. We will go through the Khong Lor cave in a motorized canoe. This cave is full of limestone formations and a 100m high cave.
On the way back from Khong Lor, we will make a stop at that Mouang and that namsanam waterfalls.
We will spend the night at Ban Na Hin.', '["After breakfast this morning, we will take a short drive to Khong Lor cave","Khong Lor cave is the result of the 7.5kms of Hinboun river flowing through the mountains","We will go through the Khong Lor cave in a motorized canoe"]', '/images/laos/laos-5.jpg', 7
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  127, 9, 'BAN NA HIN – SAVANNAKET – PAKSE (B)', 'Xieng Khuang', 
  'Following breakfast, we depart from Ban Na Hin, and make our way further south to southern Laos and Pakse town. On the way, we make a pit stop for lunch in Pakse (Your own account), a fast-developing town that has become a major trade hub between the countries of Vietnam, Laos, and Thailand.
The centre of Pakse town is full of old French colonial structures, and it has an old-world atmosphere. We arrive at Pakse town in the late afternoon, and have plenty of time to walk around and see the town for the first time. We stay overnight in Pakse.', '["Following breakfast, we depart from Ban Na Hin, and make our way further south to southern Laos and Pakse town","On the way, we make a pit stop for lunch in Pakse (Your own account), a fast-developing town that has become a major trade hub between the countries of Vietnam, Laos, and Thailand.\\nThe centre of Pakse town is full of old French colonial structures, and it has an old-world atmosphere","We arrive at Pakse town in the late afternoon, and have plenty of time to walk around and see the town for the first time"]', '/images/laos/laos-5.jpg', 8
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  127, 10, 'PAKSE – WAT PHU – DON KHONG (B)', 'Xieng Khuang', 
  'Following breakfast, we drive to the pre-Angkorian ruins in Champassak, where we have a chance to visit Wat Phu. One of Southeast Asia’s most dramatic temple sites, we have plenty of time to visit these fascinating Khmer ruins which are located at the foothills of Mount phu kao.
Wat Phu is recognized by UNESCO as one of Lao’s World Heritage sites. This amazing archaeological site of the Khmer civilization, dating back to the tenth century, predates the well-known Angkor in Cambodia.
From Champassak, we drive by land to the small island of Ban hatxaikhoun, where we cross the mighty Mekong bridge. Don Khong is the largest island of the 4000 islands of the south Mekong river area known as the most beautiful area in Laos. We stay overnight at Don Khong.', '["Following breakfast, we drive to the pre-Angkorian ruins in Champassak, where we have a chance to visit Wat Phu","One of Southeast Asia’s most dramatic temple sites, we have plenty of time to visit these fascinating Khmer ruins which are located at the foothills of Mount phu kao.\\nWat Phu is recognized by UNESCO as one of Lao’s World Heritage sites","This amazing archaeological site of the Khmer civilization, dating back to the tenth century, predates the well-known Angkor in Cambodia.\\nFrom Champassak, we drive by land to the small island of Ban hatxaikhoun, where we cross the mighty Mekong bridge"]', '/images/laos/laos-5.jpg', 9
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  127, 11, 'DON KHONG – FULL DAY SURROUNDING (B)', 'Xieng Khuang', 
  'After breakfast, we visit local villages in Ban Khone where you will find a lot of old colonial buildings and traces of old colonial history, including the first Laotian railway with a locomotive.
We continue exploring 4000 islands area at our own pace by tuk tuk at our own pace to visit Liphi waterfall which is one of the best waterfalls in Laos at the border of Laos with Cambodia, also called Samphamith.
If we are lucky, we may see a rare freshwater Irrawaddy Mekong dolphins at Ban hang Khone.
We return to ban nakasang and take a drive to Khon Phapeng famous waterfalls which is the biggest waterfall in Southeast Asia, also called Niagara of the East.
We stay overnight at Don Khong', '["After breakfast, we visit local villages in Ban Khone where you will find a lot of old colonial buildings and traces of old colonial history, including the first Laotian railway with a locomotive.\\nWe continue exploring 4000 islands area at our own pace by tuk tuk at our own pace to visit Liphi waterfall which is one of the best waterfalls in Laos at the border of Laos with Cambodia, also called Samphamith.\\nIf we are lucky, we may see a rare freshwater Irrawaddy Mekong dolphins at Ban hang Khone.\\nWe return to ban nakasang and take a drive to Khon Phapeng famous waterfalls which is the biggest waterfall in Southeast Asia, also called Niagara of the East.\\nWe stay overnight at Don Khong"]', '/images/laos/laos-5.jpg', 10
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  127, 12, 'DON KHONG – TADLO BOLAVEN PLATEAU – PAKSE (B)', 'Xieng Khuang', 
  'After breakfast, we proceed to Tadlo via Boloven plateau. Boloven plateau is famous for its cooler temperatures due to its location above the Mekong valley. The high plateau runs off in all directions, and then plunges into lush forests with a series of cascading waterfalls. Taking a trip to the plateau is a great way to take a break from the heat, and you can see the cultivation of rich crops such as coffee, tea, and cardamom, as well as bananas and other crops along the way. This trip gives you the opportunity to explore some of the lesser known areas of Laos, discovering the wild beauty of the southern region.
On the way to Tad lo waterfall, we visit Alak village, Nge village, and Katu village, where ethnic minority groups live. We will return to Pakse late evening. We will spend an overnight in Pakse.', '["After breakfast, we proceed to Tadlo via Boloven plateau","Boloven plateau is famous for its cooler temperatures due to its location above the Mekong valley","The high plateau runs off in all directions, and then plunges into lush forests with a series of cascading waterfalls"]', '/images/laos/laos-5.jpg', 11
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  127, 13, 'DEPARTURE (B)', 'Xieng Khuang', 
  'After breakfast, you are free to roam around until you are picked up at the airport for your onward flight.
End of service', '["After breakfast, you are free to roam around until you are picked up at the airport for your onward flight.\\nEnd of service"]', '/images/laos/laos-5.jpg', 12
);
