) VALUES (
  128, 1, 'Arrive Manila, Welcome Dinner', 'Manila', 
  'Arrive at Ninoy Aquino International Airport, meet your driver and transfer to your hotel. Evening welcome dinner in the bayfront M.H. Del Pilar area.', '["Airport meet & greet","Hotel check-in","Sunset dinner along Manila Bay"]', '/images/philippines/MANILA.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  128, 2, 'Manila Historical Walled City Tour', 'Manila', 
  'Immerse in Spanish colonial history with a guided walking tour of Intramuros. Visit Fort Santiago, San Agustin Church, Casa Manila, and the massive Manila Cathedral. End the day shopping at SM Mall of Asia.', '["Explore Fort Santiago colonial dungeons","Visit UNESCO San Agustin Church","Shop at SM Mall of Asia"]', '/images/philippines/pack-9.jpg', 1
);
