INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'cebu', 'Cebu', 'Philippines', 'Southeast Asia', 
  'Gateway to pristine dive sites, whale shark swimming, and colonial history', '/images/philippines/pack-2.jpg', 'Cebu is a province in the Philippines consisting of a main island and 167 surrounding islands. Cebu City, its capital, is the oldest city in the Philippines and retains landmarks from its 16th-century Spanish colonial past, including the Basilica Minore del Santo Niño and Magellan''s Cross. It is globally famous for white sand beaches, diving at Malapascua and Moalboal, and swimming with whale sharks in Oslob.', 
  123.89, 10.31, 'Adventure', 'bg-orange-500', 
  'Marine wildlife, white sand islands, whale sharks, and old Spanish chapels.', '/images/philippines/pack-2.jpg', 
  'published', '', '2 Days', 
  'Manila', 'Philippine Peso (PHP)', 'Tropical savanna climate, warm year-round', 'December to May', 
  'Cebuano, Tagalog, English', 'PHT (UTC+8)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  129, 1, 'Arrive Cebu, Historical City Highlights', 'Cebu', 
  'Arrive at Mactan-Cebu International Airport, transfer to hotel. Tour Fort San Pedro, Magellan''s Cross, and Basilica del Santo Niño.', '["Airport transfer","Visit Basilica del Santo Niño","See historic Magellan''s Cross"]', '/images/philippines/pack-2.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  129, 2, 'Oslob Whale Shark Swimming & Tumalog Falls', 'Cebu', 
  'Wake up early for a scenic drive south to Oslob. Snorkel alongside massive, gentle whale sharks. Hike to the mist-veiled Tumalog Falls.', '["Snorkel with Oslob whale sharks","Trek to majestic Tumalog Falls","Cebuano buffet lunch"]', '/images/philippines/pack-3.jpg', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  129, 'Whale Shark Snorkel', 'Float in clear waters as massive whale sharks swim alongside local outriggers.', 'Droplets', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  129, 'Heritage Walk', 'Explore the oldest street in the Philippines (Colon Street) and ancient forts.', 'Compass', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  129, 'Apply mineral-safe sunscreen to protect marine life during snorkeling tours.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  129, 'Bring waterproof dry bags (dry bags are widely sold locally) for boat excursions.', 1
);
