INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'boracay', 'Boracay', 'Philippines', 'Southeast Asia', 
  'World-famous white sand beaches, active water sports, and sunset sailing', '/images/philippines/pack-7.jpg', 'Boracay is a small island in the central Philippines. It is famous for its beaches, which have won awards from numerous travel publications. The crown jewel is White Beach, a 4km stretch of powder-soft sand lined with palm trees, hotels, and restaurants. On the east coast, Bulabog Beach is a global hub for windsurfing and kitesurfing, while offshore reefs offer excellent scuba diving.', 
  121.92, 11.97, 'Beach', 'bg-blue-500', 
  'Powder-soft White Beach, coconut groves, vibrant beach clubs, and water sports.', '/images/philippines/pack-7.jpg', 
  'published', '', '2 Days', 
  'Manila', 'Philippine Peso (PHP)', 'Tropical wet and dry climate', 'November to May', 
  'Aklanon, Tagalog, English', 'PHT (UTC+8)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  130, 1, 'Transfer to Boracay Island', 'Boracay', 
  'Fly to Caticlan Airport, take a short outrigger boat ride to Boracay Island, and check into your beachfront resort. Relax on White Beach.', '["Boat transfer to Boracay","Check-in to beach resort","Sunset stroll on White Beach"]', '/images/philippines/pack-7.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  130, 2, 'Boracay Island Hopping & Snorkeling', 'Boracay', 
  'Board a shared outrigger boat to explore Puka Beach, Crystal Cove Island, and snorkel among vibrant coral reefs at Crocodile Island. Enjoy a beachfront BBQ lunch.', '["Lounge on quiet Puka Beach","Snorkel coral reefs near Crocodile Island","BBQ lunch on the boat"]', '/images/philippines/pack-8.jpg', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  130, 'Sunset Paraw Sailing', 'Sail along White Beach on a traditional double-outrigger sailboat during sunset.', 'Sunset', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  130, 'Helmet Diving', 'Walk on the ocean floor wearing an air-supplied glass helmet to feed colorful fish.', 'Droplets', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  130, 'Boracay has strict eco-tourism guidelines; do not bring plastics, food, or drinks onto White Beach.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  130, 'Bring cash as some smaller restaurants and boat operators do not accept cards.', 1
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  130, '/images/philippines/pack-7.jpg', 0
);
INSERT INTO `tour_package_images` (
  `tour_package_id`, `image_url`, `sort_order`
) VALUES (
  130, '/images/philippines/pack-8.jpg', 1
);

INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'palawan', 'Palawan', 'Philippines', 'Southeast Asia', 
  'Island paradise containing Puerto Princesa underground river, El Nido limestone cliffs, and Coron wrecks', '/images/philippines/PUERTO-PRINCESA.jpg', 'Palawan is an archipelagic province of the Philippines, known as the ''Last Frontier'' due to its untouched ecological beauty. It features Puerto Princesa, home to the UNESCO Subterranean River; El Nido, famous for towering limestone karsts rising out of turquoise lagoons; and Coron, celebrated for world-class scuba diving among sunken Japanese WWII shipwrecks.', 
  118.73, 9.74, 'Nature', 'bg-teal-500', 
  'UNESCO underground river, limestone karsts, secret lagoons, and WWII scuba diving sites.', '/images/philippines/PUERTO-PRINCESA.jpg', 
  'published', '', '2 Days', 
  'Manila', 'Philippine Peso (PHP)', 'Tropical wet and dry climate', 'December to May', 
  'Cuyonon, Tagalog, English', 'PHT (UTC+8)', 'Right'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  131, 1, 'Arrive Puerto Princesa, Underground River Tour', 'Palawan', 
  'Arrive in Puerto Princesa. Drive to Sabang and board a boat to the Underground River, a UNESCO World Heritage site and one of the New 7 Wonders of Nature.', '["Arrive in Palawan","Explore Puerto Princesa Underground River cave system","Buffet lunch in Sabang"]', '/images/philippines/PUERTO-PRINCESA.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  131, 2, 'Transfer to El Nido, Lagoon Kayaking', 'Palawan', 
  'Take a scenic drive north to El Nido. Check in to resort. Board an outrigger boat for a kayak tour of Big Lagoon and Secret Lagoon, enclosed by limestone karsts.', '["Scenic drive to El Nido","Kayak Big Lagoon''s emerald waters","Swim through Secret Lagoon tunnels"]', '/images/philippines/EL-NIDO.jpg', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  131, 'Underground Cave Tour', 'Paddle inside a 8.2km navigable cave river decorated with spectacular stalactites.', 'Compass', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  131, 'WWII Shipwreck Diving', 'Dive down to explore well-preserved Japanese warships from 1944 in Coron bay.', 'Droplets', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  131, 'Bring reef shoes/aquashoes as walking inside El Nido''s lagoons requires stepping on sharp corals/rocks.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  131, 'Electricity in El Nido can sometimes experience brief blackouts; carry a power bank.', 1
);
