INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  134, 1, 'ARRIVE MANILA + FLIGHT TO PUERTO PRINCESA (DOMESTIC FLIGHT NOT INCLUDED)', 'Cebu', 
  'Welcome to your Mesmerizing Philippines tour. On arrival you will be met by your Tour Manager who will welcome you and take you to your hotel. Over Night stay at Puerto Princesa', '["Welcome to your Mesmerizing Philippines tour","On arrival you will be met by your Tour Manager who will welcome you and take you to your hotel","Over Night stay at Puerto Princesa"]', '/images/philippines/pack-3.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  134, 2, 'UNDERGROUND RIVER TOUR', 'Cebu', 
  'After breakfast, Process for Underground River Tour Declared as a Natural World Heritage Site by the United Nations Educational and Scientific Organizations (UNESCO) on December 4, 1999, because of its unique geological features and globally significant biodiversity is also known as the Underground River Park. These forest ecosystems are home to 800 species of plants, 165 species of birds, 30 species of mammals, 19 species of reptiles and 10 species of amphitheaters. On board a paddle boat with outriggers and equipped with search light one enters a mystical environment exploring the pitch-dark inner recesses of the cavern. Every turn and bend in its navigable stalactite and stalagmites-pillared interiors appears different rock formations and doomed amphitheaters. Over Night stay at Puerto Princesa.', '["After breakfast, Process for Underground River Tour Declared as a Natural World Heritage Site by the United Nations Educational and Scientific Organizations (UNESCO) on December 4, 1999, because of its unique geological features and globally significant biodiversity is also known as the Underground River Park","These forest ecosystems are home to 800 species of plants, 165 species of birds, 30 species of mammals, 19 species of reptiles and 10 species of amphitheaters","On board a paddle boat with outriggers and equipped with search light one enters a mystical environment exploring the pitch-dark inner recesses of the cavern"]', '/images/philippines/pack-3.jpg', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  134, 3, 'HALF DAY PUERTO PRINCESA CITY TOUR', 'Cebu', 
  'Breakfast at the hotel. Proceed for Half Day Puerto Princesa City Tour. Over Night stay at Puerto Princesa.', '["Breakfast at the hotel","Proceed for Half Day Puerto Princesa City Tour","Over Night stay at Puerto Princesa"]', '/images/philippines/pack-3.jpg', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  134, 4, 'PUERTO PRINCESA TO EL NIDO (DOMESTIC FLIGHT NOT INCLUDED)', 'Cebu', 
  'After breakfast, your will be checkout from hotel and transfers to the airport to board your next flight for El Nido. On arrival in El Nido, you will be welcomed by your representative and transferred to your hotel. The rest of the day is at leisure to discover this charming island. Over Night stay at El Nido.', '["After breakfast, your will be checkout from hotel and transfers to the airport to board your next flight for El Nido","On arrival in El Nido, you will be welcomed by your representative and transferred to your hotel","The rest of the day is at leisure to discover this charming island"]', '/images/philippines/pack-3.jpg', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  134, 5, 'EL NIDO TOUR WITH LUNCH', 'Cebu', 
  'Breakfast at the hotel. Proceed for El Nido Tour. Visit Secret Beach, Hidden Beach, Matinloc Shrine, Helicopter Island, Tapiutan Island. Local Lunch Over Night stay at El Nido.', '["Breakfast at the hotel","Proceed for El Nido Tour","Visit Secret Beach, Hidden Beach, Matinloc Shrine, Helicopter Island, Tapiutan Island"]', '/images/philippines/pack-3.jpg', 4
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  134, 6, 'EL NIDO TOUR WITH LUNCH', 'Cebu', 
  'Breakfast at the hotel. Proceed for El Nido Tour. Visit Big Lagoon, Shimizu Island, Secret Lagoon, Seven Commando, Payong Payong Beach. Local Lunch Over Night stay at El Nido.', '["Breakfast at the hotel","Proceed for El Nido Tour","Visit Big Lagoon, Shimizu Island, Secret Lagoon, Seven Commando, Payong Payong Beach"]', '/images/philippines/pack-3.jpg', 5
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  134, 7, 'EL NIDO TO CORON BY FERRY', 'Cebu', 
  'After breakfast, your will be checkout from hotel and transfers to the Port to board your Ferry to Coron (Approximate 4 hours by ferry) Over Night stay at Coron.', '["After breakfast, your will be checkout from hotel and transfers to the Port to board your Ferry to Coron (Approximate 4 hours by ferry) Over Night stay at Coron"]', '/images/philippines/pack-3.jpg', 6
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  134, 8, 'REEFS AND WRECKS TOUR', 'Cebu', 
  'Breakfast at the hotel. Proceed for Reefs And Wrecks Tour. ? PASS ISLAND Activities: kayaking, siesta, swimming, and snorkeling at the islands best coral reefs and see the colorful fishes thriving on the reefs ? LUSONG CORAL GARDEN Activities: snorkeling at one of the excellent coral reefs of Coron ? LUSONG GUNBOAT Activities: snorkeling around East Tangat gunboat, a World War 2 Japanese shipwreck and photo shooting Over Night stay at Coron.', '["Breakfast at the hotel","Proceed for Reefs And Wrecks Tour","? PASS ISLAND Activities: kayaking, siesta, swimming, and snorkeling at the islands best coral reefs and see the colorful fishes thriving on the reefs ? LUSONG CORAL GARDEN Activities: snorkeling at one of the excellent coral reefs of Coron ? LUSONG GUNBOAT Activities: snorkeling around East Tangat gunboat, a World War 2 Japanese shipwreck and photo shooting Over Night stay at Coron"]', '/images/philippines/pack-3.jpg', 7
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  134, 9, 'CORON ISLAND SUPER ULTIMATE TOUR', 'Cebu', 
  'Breakfast at the hotel. Proceed for Coron Island Super Ultimate Tour. ? SIETE PECADOS Activities: kayaking, swimming & snorkeling to the marine park to view colorful and diverse corals and fishes underwater ? KAYANGAN LAKE Activities: easy trekking, photo-shooting, swimming, and snorkeling at the lake ? BEACH 91 Activities: swimming, kayaking, photo-shooting, relaxing, siesta ? SKELETON WRECK Activities: swimming and snorkeling and fish- feeding of fishes thriving at skeleton wreck ? MALWAWEY CORAL GARDEN Activities: snorkeling at one of the excellent coral reefs of Coron ? CYC BEACH Activities: swimming, photo-shooting, and snorkeling ? TWIN LAGOON Activities: snorkeling and swimming through a hole from one to another majestic and enchanting lagoon Over Night stay at Coron.', '["Breakfast at the hotel","Proceed for Coron Island Super Ultimate Tour","? SIETE PECADOS Activities: kayaking, swimming & snorkeling to the marine park to view colorful and diverse corals and fishes underwater ? KAYANGAN LAKE Activities: easy trekking, photo-shooting, swimming, and snorkeling at the lake ? BEACH 91 Activities: swimming, kayaking, photo-shooting, relaxing, siesta ? SKELETON WRECK Activities: swimming and snorkeling and fish- feeding of fishes thriving at skeleton wreck ? MALWAWEY CORAL GARDEN Activities: snorkeling at one of the excellent coral reefs of Coron ? CYC BEACH Activities: swimming, photo-shooting, and snorkeling ? TWIN LAGOON Activities: snorkeling and swimming through a hole from one to another majestic and enchanting lagoon Over Night stay at Coron"]', '/images/philippines/pack-3.jpg', 8
);
