INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  135, 1, 'ARRIVE MANILA', 'Palawan', 
  'Welcome to your MARVELLOUS PHILIPPINES tour. On arrival you will be met by our Tour Manager who will welcome you and take you to your hotel. known as the "Pearl of the Orient" which is the nation''s capital city. This bustling historic city is full of things to see and do – including museums, parks, theatres, shopping malls and a plethora of restaurants to choose from. Overnight stay at Manila', '["Welcome to your MARVELLOUS PHILIPPINES tour","On arrival you will be met by our Tour Manager who will welcome you and take you to your hotel","known as the \\"Pearl of the Orient\\" which is the nation''s capital city"]', '/images/philippines/pack-4.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  135, 2, 'MANILA CITY TOUR + DESTILERIA MUSEUM', 'Palawan', 
  'Breakfast at the hotel. Proceed Half Day Manila City Tour An introduction to Manila and its suburbs by driving through the financial district of Makati and Forbes Park, then a War Memorial stop over at the Global City. Next, proceed to the reclaimed area (Mall of Asia) and the Cultural Center along Roxas Boulevard. Lastly, a running tour of Rizal Park and the Walled City of Intramuros; Driving by San Agustin Church and Casa Manila then take a walk inside Fort Santiago. DESTILERIA LIMTUACO MUSEUM-Showcases the history of the oldest distillery in the Philippines, dating back to the Spanish colonial period. (Wine Tasting) Indian/Local Lunch at Restaurant After Lunch proceed for Shopping Tour. Over Night stay at Manila.', '["Breakfast at the hotel","Proceed Half Day Manila City Tour An introduction to Manila and its suburbs by driving through the financial district of Makati and Forbes Park, then a War Memorial stop over at the Global City","Next, proceed to the reclaimed area (Mall of Asia) and the Cultural Center along Roxas Boulevard"]', '/images/philippines/pack-4.jpg', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  135, 3, 'MANILA TO CEBU (DOMESTIC FLIGHT NOT INCLUDED)', 'Palawan', 
  'After breakfast, check out from the hotel and transfer to the airport to board your next flight for Cebu. On arrival in Cebu, you will be welcomed by your representative and transferred to your hotel. The rest of the day is at leisure to discover this charming island. Over Night stay at Cebu.', '["After breakfast, check out from the hotel and transfer to the airport to board your next flight for Cebu","On arrival in Cebu, you will be welcomed by your representative and transferred to your hotel","The rest of the day is at leisure to discover this charming island"]', '/images/philippines/pack-4.jpg', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  135, 4, 'CEBU TWIN CITY TOUR', 'Palawan', 
  'Breakfast at the hotel. Go for a City tour of Cebu famous for its historical and tourist attractions. Visit Lapu-Lapu Monument Magellan’s Shrine, Alegre Guitar Factory, Magellan’s Cross, Basilica Minore Del Sto. Nino, The Heritage of Cebu Monument Yap San Diego House, Taoist Temple, Running Tour: Colon Street, Fuente Osmena, Circle, Capitol Site Over Night stay at Cebu.', '["Breakfast at the hotel","Go for a City tour of Cebu famous for its historical and tourist attractions","Visit Lapu-Lapu Monument Magellan’s Shrine, Alegre Guitar Factory, Magellan’s Cross, Basilica Minore Del Sto"]', '/images/philippines/pack-4.jpg', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  135, 5, 'DEPARTURE TO HOMETOWN', 'Palawan', 
  'Today you will be transferred to Airport for your flight back home. We trust that you enjoyed your Vacation.', '["Today you will be transferred to Airport for your flight back home","We trust that you enjoyed your Vacation"]', '/images/philippines/pack-4.jpg', 4
);
