INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  137, 1, 'ARRIVE MANILA', 'Boracay', 
  'Welcome to your Explore Philippines tour. On arrival you will be met by your Tour Manager who will welcome you and take you to your hotel. known as the "Pearl of the Orient" which is the nation''s capital city. This bustling historic city is full of things to see and do – including museums, parks, theatres, shopping malls and a plethora of restaurants to choose from. Overnight stay at Manila', '["Welcome to your Explore Philippines tour","On arrival you will be met by your Tour Manager who will welcome you and take you to your hotel","known as the \\"Pearl of the Orient\\" which is the nation''s capital city"]', '/images/philippines/pack-6.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  137, 2, 'MANILA CITY TOUR + DESTILERIA MUSEUM', 'Boracay', 
  'Breakfast at the hotel. Proceed Half Day Manila City Tour An introduction to Manila and its suburbs by driving through the financial district of Makati and Forbes Park, then a War Memorial stop over at the Global City. Next, proceed to the reclaimed area (Mall of Asia) and the Cultural Center along Roxas Boulevard. Lastly, a running tour of Rizal Park and the Walled City of Intramuros; Driving by San Agustin Church and Casa Manila then take a walk inside Fort Santiago. DESTILERIA LIMTUACO MUSEUM – Showcases the history of the oldest distillery in the Philippines, dating back to the Spanish colonial period. (Wine Tasting) Indian/Local Lunch at Restaurant After Lunch proceed for Shopping Tour. Over Night stay at Manila.', '["Breakfast at the hotel","Proceed Half Day Manila City Tour An introduction to Manila and its suburbs by driving through the financial district of Makati and Forbes Park, then a War Memorial stop over at the Global City","Next, proceed to the reclaimed area (Mall of Asia) and the Cultural Center along Roxas Boulevard"]', '/images/philippines/pack-6.jpg', 1
);
INSERT INTO `tour_package_itinerary` (
