INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  140, 1, 'ARRIVE MANILA', 'Boracay', 
  'Welcome to your Discover Philippines tour. On arrival you will be met by your Tour Manager who will welcome you and take you to your hotel. known as the "Pearl of the Orient" which is the nation''s capital city. This bustling historic city is full of things to see and do – including museums, parks, theaters, shopping malls and a plethora of restaurants to choose from. Overnight stay at Manila', '["Welcome to your Discover Philippines tour","On arrival you will be met by your Tour Manager who will welcome you and take you to your hotel","known as the \\"Pearl of the Orient\\" which is the nation''s capital city"]', '/images/philippines/pack-9.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  140, 2, 'MANILA CITY TOUR + DESTILERIA MUSEUM', 'Boracay', 
  'Breakfast at the hotel. Proceed Half Day Manila City Tour An introduction to Manila and its suburbs by driving through the financial district of Makati and Forbes Park, then a War Memorial stop over at the Global City. Next, proceed to the reclaimed area (Mall of Asia) and the Cultural Center along Roxas Boulevard. Lastly, a running tour of Rizal Park and the Walled City of Intramuros; Driving by San Agustin Church and Casa Manila then take a walk inside Fort Santiago. DESTILERIA LIMTUACO MUSEUM-Showcases the history of the oldest distillery in the Philippines, dating back to the Spanish colonial period. (Wine Tasting). Indian/Local Lunch at Restaurant After Lunch proceed for Shopping Tour. Over Night stay at Manila.', '["Breakfast at the hotel","Proceed Half Day Manila City Tour An introduction to Manila and its suburbs by driving through the financial district of Makati and Forbes Park, then a War Memorial stop over at the Global City","Next, proceed to the reclaimed area (Mall of Asia) and the Cultural Center along Roxas Boulevard"]', '/images/philippines/pack-9.jpg', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  140, 3, 'PAGSANJAN FALLS TOUR', 'Boracay', 
  'Breakfast at the hotel. A two-hour drive or 110 kilometers south of Manila is the rustic town of Pagsanjan; stunningly beautiful with thrilling adventure. "Shoot the rapids" on dugout canoes and experience nature''s wonders. Be prepared to board a native banca (canoe) skilfully driven by two boatmen and maneuvered upstream through rocks and boulders amidst steep gorges and lush tropical vegetation. Your destination – the magnificent Pagsanjan Falls. Take a swim or board a bamboo raft through the falls into a cave right behind its veil of water. Highlight of the program is the upriver ride on board canoe boats to the main falls followed by downriver ride that passes through 14 rapids: the most breathtaking part of the tour.', '["Breakfast at the hotel","A two-hour drive or 110 kilometers south of Manila is the rustic town of Pagsanjan; stunningly beautiful with thrilling adventure","\\"Shoot the rapids\\" on dugout canoes and experience nature''s wonders"]', '/images/philippines/pack-9.jpg', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  140, 4, 'MANILA TO BORACAY (DOMESTIC FLIGHT NOT INCLUDED)', 'Boracay', 
  'After breakfast, your will be checkout from hotel and transfers to the airport to board your next flight for Boracay. On arrival in Boracay, you will be welcomed by your representative and transferred to your hotel. The rest of the day is at leisure to discover this charming island. Over Night stay at Boracay.', '["After breakfast, your will be checkout from hotel and transfers to the airport to board your next flight for Boracay","On arrival in Boracay, you will be welcomed by your representative and transferred to your hotel","The rest of the day is at leisure to discover this charming island"]', '/images/philippines/pack-9.jpg', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  140, 5, 'BORACAY ISLAND HOPPING TOUR WITH LUNCH', 'Boracay', 
  'Breakfast at the hotel. Proceed for Boracay island hopping is a good opportunity to explore the islands surrounding this famous tropical escape, many of which have secluded beaches and a fascinating underwater paradise. Local Lunch @ The Picnic Area Over Night stay at Boracay.', '["Breakfast at the hotel","Proceed for Boracay island hopping is a good opportunity to explore the islands surrounding this famous tropical escape, many of which have secluded beaches and a fascinating underwater paradise","Local Lunch @ The Picnic Area Over Night stay at Boracay"]', '/images/philippines/pack-9.jpg', 4
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  140, 6, 'BORACAY', 'Boracay', 
  'Breakfast at the hotel. Day Free at leisure. Over Night stay at Boracay.', '["Breakfast at the hotel","Day Free at leisure","Over Night stay at Boracay"]', '/images/philippines/pack-9.jpg', 5
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  140, 7, 'BORACAY TO CEBU (DOMESTIC FLIGHT NOT INCLUDED)', 'Boracay', 
  'After breakfast, your will be checkout from hotel and transfers to the airport to board your next flight for Cebu. On arrival in Cebu, you will be welcomed by your representative and transferred to your hotel. The rest of the day is at leisure to discover this charming island. Over Night stay at Cebu.', '["After breakfast, your will be checkout from hotel and transfers to the airport to board your next flight for Cebu","On arrival in Cebu, you will be welcomed by your representative and transferred to your hotel","The rest of the day is at leisure to discover this charming island"]', '/images/philippines/pack-9.jpg', 6
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  140, 8, 'CEBU TWIN CITY TOUR', 'Boracay', 
  'Breakfast at the hotel. Go for a City tour of Cebu famous for its historical and tourist attractions. Visit Lapu-Lapu Monument Magellan’s Shrine, Alegre Guitar Factory, Magellan’s Cross, Basilica Minore Del Sto. Nino, The Heritage of Cebu Monument Yap San Diego House, Taoist Temple, Running Tour: Colon Street, Fuente Osmena, Circle, Capitol Site Local Lunch. Over Night stay at Cebu.', '["Breakfast at the hotel","Go for a City tour of Cebu famous for its historical and tourist attractions","Visit Lapu-Lapu Monument Magellan’s Shrine, Alegre Guitar Factory, Magellan’s Cross, Basilica Minore Del Sto"]', '/images/philippines/pack-9.jpg', 7
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  140, 9, 'BOHOL COUNTRYSIDE TOUR', 'Boracay', 
  'Breakfast at the hotel. A whole day trip that showcases the province''s history, culture and its unspoiled nature, this tour starts in the city towards the east starting with the historic Blood Compact Commemorative Shrine. A few kilometers away is the centuries old Baclayon church with its impressive carved wooden altars built during the Spanish regime. En route to Chocolate Hills which are very uniform in shape and mostly between 30 and 50 meters high. They are covered with grass, which, at the end of the dry season, turns chocolate brown, one drives through the lush man-made forest of the towns of Loboc and Bilar planted with Mahogany and endemic trees. The highlight of the entire trip is a 50-minute Loboc river cruise on board a motorized catamaran boat. A sumptuous lunch of local cuisine is served while the guests are enjoying the beautiful scenery along the riverbanks verdant rolling hills, cliffs, trees, and coconuts that recline in the river. Over Night stay at Cebu.', '["Breakfast at the hotel","A whole day trip that showcases the province''s history, culture and its unspoiled nature, this tour starts in the city towards the east starting with the historic Blood Compact Commemorative Shrine","A few kilometers away is the centuries old Baclayon church with its impressive carved wooden altars built during the Spanish regime"]', '/images/philippines/pack-9.jpg', 8
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  140, 10, 'DEPARTURE TO HOMETOWN', 'Boracay', 
  'Today you will be transferred to Airport for your flight back home. We trust that you enjoyed your Vacation.', '["Today you will be transferred to Airport for your flight back home","We trust that you enjoyed your Vacation"]', '/images/philippines/pack-9.jpg', 9
);
