INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  141, 2, 'Manila Full day sight-seeing', 'Manila', 
  'After breakfast morning 9am Proceed to Manila City Tour SIGHTS OF INTERESTS – RIZAL PARK – Immerse you into Philippines history at the Rizal Park named after Dr. Jose Rizal, Philippine national hero. INTRAMUROS – also known as the Walled City” that was considered as Manila itself during the Spanish colonial period FORT SANTIAGO – The fort is one of the most important historical sites in Manila. Several lives were lost in its prisons during the Spanish Colonial Period and World War II. José Rizal, the Philippine national hero, was imprisoned here before his execution in 1896 MANILA CATHEDRAL – a Roman Catholic Basilica and one of the oldest churches in the Philippines CASA MANILA – The museum is the imposing stone-and-wood structure circa. SM MALL of ASIA SHOPPING & SEASIDE AREA Back to Hotel Overnight in Manila', '["After breakfast morning 9am Proceed to Manila City Tour SIGHTS OF INTERESTS – RIZAL PARK – Immerse you into Philippines history at the Rizal Park named after Dr","Jose Rizal, Philippine national hero","INTRAMUROS – also known as the Walled City” that was considered as Manila itself during the Spanish colonial period FORT SANTIAGO – The fort is one of the most important historical sites in Manila"]', '/images/philippines/pack-9.jpg', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  141, 3, 'Taal Volcano Island Tour - Tagaytay Tour', 'Manila', 
  'Breakfast at the Hotel Morning 8am Proceed to Taal Volcano Island Tour + Boat Ride(inclusive of entry tickets) See the stunning Taal Lake and Taal Volcano up close with this boat tour that comes with a DOT (Department of Tourism) – accredited guide, the use of a life vest, and all entrance and boat station fees. This one-hour Taal Lake tour is perfect for those who want to get a closer look at the Taal Volcano, as the boat will get as close as 10 meters away from the natural wonder. Proceed to Tagaytay viewpoint Tour Back to Manila Evening Transfer For Okada Fountain show & Casino Visit Overnight at Manila', '["Breakfast at the Hotel Morning 8am Proceed to Taal Volcano Island Tour + Boat Ride(inclusive of entry tickets) See the stunning Taal Lake and Taal Volcano up close with this boat tour that comes with a DOT (Department of Tourism) – accredited guide, the use of a life vest, and all entrance and boat station fees","This one-hour Taal Lake tour is perfect for those who want to get a closer look at the Taal Volcano, as the boat will get as close as 10 meters away from the natural wonder","Proceed to Tagaytay viewpoint Tour Back to Manila Evening Transfer For Okada Fountain show & Casino Visit Overnight at Manila"]', '/images/philippines/pack-9.jpg', 2
);
