INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  144, 2, 'MANILA CITY TOUR', 'Boracay', 
  'Breakfast at the Hotel Proceed to Manila City Tour SIGHTS OF INTERESTS – RIZAL PARK – Immerse yourself into Philippines history at the Rizal Park named after Dr. Jose Rizal, Philippine national hero. INTRAMUROS – also known as the Walled City” that was considered as Manila itself during the Spanish colonial period. FORT SANTIAGO – The fort is one of the most important historical sites in Manila. Several lives were lost in its prisons during the Spanish Colonial Period and World War II. José Rizal, the Philippine national hero, was imprisoned here before his execution in 1896. MANILA CATHEDRAL – a Roman Catholic Basilica and one of the oldest churches in the Philippines. Transfer for Shopping at SM Mall Back To Hotel Overnight stay at Manila', '["Breakfast at the Hotel Proceed to Manila City Tour SIGHTS OF INTERESTS – RIZAL PARK – Immerse yourself into Philippines history at the Rizal Park named after Dr","Jose Rizal, Philippine national hero","INTRAMUROS – also known as the Walled City” that was considered as Manila itself during the Spanish colonial period"]', '/images/philippines/pack-4.jpg', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  144, 3, 'FLIGHT TO BORACAY', 'Boracay', 
  'Breakfast at the Hotel Check out the Hotel/ Transfer to the Domestic Airport. Fly to Boracay. Check in the Hotel and enjoy the beach. Pick up from Hotel & proceed for Boracay Sunset Cruise – meet up time 03.30 PM Shared in Local Boat Live music (Acoustic Singer) Back massage on board Amazing sunset viewing Back to hotel at Boracay Overnight stay at Boracay', '["Breakfast at the Hotel Check out the Hotel/ Transfer to the Domestic Airport","Fly to Boracay","Check in the Hotel and enjoy the beach"]', '/images/philippines/pack-4.jpg', 2
);
