) VALUES (
  144, 4, 'BORACAY ISLAND HOPPING TOUR', 'Boracay', 
  'Pick from the Hotel (Proceed to Station 1) Start the tour Explore Ilig Iligan Beach. Proceed to Crocodile for Swimming Crocodile Island Tambisaan Beach Visit Crystal Cove Island Take picnic lunch during the Tour Back to Boat Station. Overnight stay at Boracay.', '["Pick from the Hotel (Proceed to Station 1) Start the tour Explore Ilig Iligan Beach","Proceed to Crocodile for Swimming Crocodile Island Tambisaan Beach Visit Crystal Cove Island Take picnic lunch during the Tour Back to Boat Station","Overnight stay at Boracay"]', '/images/philippines/pack-4.jpg', 3
);
