INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  145, 2, 'TAAL VOLCANO ISLAND TOUR TAGAYTAY SIGHTSEEING TOUR', 'Manila', 
  'Breakfast at the Hotel Proceed to Taal Volcano Island Tour + Boat ride See the stunning Taal Lake and Taal Volcano up close with this boat tour that comes with a DOT (Department of Tourism) – accredited guide, the use of a life vest, and all entrance and boat station fees. This one-hour Taal Lake tour is perfect for those who want to get a closer look at the Taal Volcano, as the boat will get as close as 10 meters away from the natural wonder. Proceed to Tagaytay Sightseeing Tour Transfer for Shopping at SM Mall Back to Manila Overnight in Manila', '["Breakfast at the Hotel Proceed to Taal Volcano Island Tour + Boat ride See the stunning Taal Lake and Taal Volcano up close with this boat tour that comes with a DOT (Department of Tourism) – accredited guide, the use of a life vest, and all entrance and boat station fees","This one-hour Taal Lake tour is perfect for those who want to get a closer look at the Taal Volcano, as the boat will get as close as 10 meters away from the natural wonder","Proceed to Tagaytay Sightseeing Tour Transfer for Shopping at SM Mall Back to Manila Overnight in Manila"]', '/images/philippines/pack-5.jpg', 1
);
