) VALUES (
  151, 'Darwin Sunset Sail', 'Sail Darwin Harbour on a luxury catamaran and watch a legendary Top End sunset with fresh seafood.', 'Waves', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
