) VALUES (
  163, 'Waiheke Vineyard Tour', 'Taste premium Syrah and oysters on Waiheke Island, just a short ferry ride from Auckland.', 'Wine', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  163, 'Carry your passport or ID when visiting wineries on Waiheke, as licensing laws are strictly enforced.', 0
