INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  '4-day-off-season-hokkaido', '4-Day Off-Season Hokkaido', 'Japan', 'East Asia', 
  'Discover Japan''s natural wonders, volcanic hot springs, and scenic trails over 4 days', 'https://images.unsplash.com/photo-1578271887552-5ac3a72752bc?auto=format&fit=crop&w=600&q=80', 'Embark on a magnificent 4-day tour of Japan, starting in Hokkaido. This package covers a curated route highlighting key cultural sights, bullet train experiences, local culinary delicacies, and historical landmarks. Perfect for families, first-time visitors, and seasoned travelers seeking a seamless, well-organized itinerary.', 
  141.3545, 43.0621, 'Nature', 'bg-green-600', 
  'Explore Hokkaido''s highlights from Sapporo''s beer history to Otaru''s historic canals.', 'https://images.unsplash.com/photo-1578271887552-5ac3a72752bc?auto=format&fit=crop&w=600&q=80', 
  'published', '', '4 Days', 
  NULL, 'Japanese Yen (¥)', 'Subtropical to temperate with distinct seasonal changes', 'March–May (Cherry Blossom) & October–November (Autumn Foliage)', 
  'Japanese', 'JST (UTC+9)', 'Left'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  170, 1, 'Sapporo Highlights', 'Sapporo, Hokkaido', 
  '9:00 AM – 10:00 AM: Odori Park and Sapporo TV TowerBegin at Odori Park, Sapporo’s central green space stretching across the city with seasonal flowerbeds and fountains. Ascend the Sapporo TV Tower for panoramic views over the city, offering a glimpse of the city''s unique skyline against the backdrop of Hokkaido’s mountains.
10:30 AM – 12:30 PM: Mount MoiwaTravel to Mount Moiwa, taking the ropeway to the summit for stunning vistas of Sapporo and Ishikari Bay. A popular viewpoint, Mount Moiwa is known for its spectacular outlooks, especially beautiful during fall and winter. The observatory offers a unique panoramic experience in Hokkaido.
1:00 PM – 2:30 PM: Lunch Break
3:00 PM – 5:00 PM: Sapporo Beer MuseumDiscover Hokkaido’s beer history at the Sapporo Beer Museum, housed in a historic red-brick building. Learn about the brewing process and Sapporo’s significance in Japanese beer culture. End with a tasting at the on-site beer hall, featuring popular and unique Sapporo brews.', '["Odori Park and Sapporo TV TowerBegin at Odori Park, Sapporo’s central green space stretching across the city with seasonal flowerbeds and fountains","Ascend the Sapporo TV Tower for panoramic views over the city, offering a glimpse of the city''s unique skyline against the backdrop of Hokkaido’s mountains","Mount MoiwaTravel to Mount Moiwa, taking the ropeway to the summit for stunning vistas of Sapporo and Ishikari Bay","A popular viewpoint, Mount Moiwa is known for its spectacular outlooks, especially beautiful during fall and winter"]', 'https://images.unsplash.com/photo-1578271887552-5ac3a72752bc?auto=format&fit=crop&w=600&q=80', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  170, 2, 'Day Trip to Otaru', 'Otaru, Hokkaido', 
  '9:00 AM – 10:00 AM: Sankaku Fish MarketStart with the lively Sankaku Fish Market, known for its fresh seafood offerings, including Hokkaido specialties such as crab and sea urchin. Enjoy the bustling market atmosphere and sample some sashimi or grilled fish from the vendor stalls.
10:30 AM – 12:00 PM: Hiyoriyama LighthouseVisit the Hiyoriyama Lighthouse overlooking the Sea of Japan, offering scenic coastal views. This spot is ideal for photographs, capturing Otaru’s seaside charm. The lighthouse area provides a tranquil atmosphere, perfect for a peaceful stroll.
12:30 PM – 2:00 PM: Sakaimachi Dori Shopping StreetExplore Sakaimachi Dori, a historic shopping street lined with preserved buildings, boutiques, and cafes. Famous for glassware and music boxes, this street is perfect for souvenir shopping and experiencing Otaru’s nostalgic atmosphere.
2:00 PM – 4:00 PM: Unique Accommodation Experience (Optional)Consider a stay in a traditional ryokan or unique Otaru accommodation for an authentic Japanese lodging experience. Many offer on-site hot springs and a taste of Hokkaido’s hospitality, making this a memorable part of your trip.', '["Sankaku Fish MarketStart with the lively Sankaku Fish Market, known for its fresh seafood offerings, including Hokkaido specialties such as crab and sea urchin","Enjoy the bustling market atmosphere and sample some sashimi or grilled fish from the vendor stalls","Hiyoriyama LighthouseVisit the Hiyoriyama Lighthouse overlooking the Sea of Japan, offering scenic coastal views","This spot is ideal for photographs, capturing Otaru’s seaside charm"]', 'https://images.unsplash.com/photo-1578271887552-5ac3a72752bc?auto=format&fit=crop&w=600&q=80', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  170, 3, 'Asahikawa and Optional Furano & Biei', 'Asahikawa, Hokkaido', 
  '9:00 AM – 10:30 AM: Asahikawa Ramen VillageDiscover the local favorite at Asahikawa Ramen Village, dedicated to Hokkaido’s iconic miso-based ramen. With eight ramen shops to choose from, savor the rich, flavorful broth and noodles that have put Asahikawa on the culinary map.
11:00 AM – 12:00 PM: Hokkaido Gokoku ShrineVisit Hokkaido Gokoku Shrine, a tranquil Shinto shrine dedicated to Hokkaido’s ancestors. The grounds are peaceful, with traditional architecture and seasonal foliage, making it an ideal spot for a calm respite.
12:30 PM – 2:00 PM: Heiwa Shopping StreetStroll along Heiwa Shopping Street, Asahikawa’s main shopping avenue. This pedestrian-friendly street features shops, cafes, and galleries offering a taste of local culture and Hokkaido’s artistic scene, perfect for souvenirs and exploring the area.
2:30 PM – 5:30 PM: Furano & Biei Day Trip (Optional)If time allows, take a day trip to Furano and Biei, famed for rolling flower fields in summer and scenic snow-covered landscapes in winter. The Blue Pond and rolling hills offer a refreshing change of pace and breathtaking photo opportunities.', '["Asahikawa Ramen VillageDiscover the local favorite at Asahikawa Ramen Village, dedicated to Hokkaido’s iconic miso-based ramen","With eight ramen shops to choose from, savor the rich, flavorful broth and noodles that have put Asahikawa on the culinary map","Hokkaido Gokoku ShrineVisit Hokkaido Gokoku Shrine, a tranquil Shinto shrine dedicated to Hokkaido’s ancestors","The grounds are peaceful, with traditional architecture and seasonal foliage, making it an ideal spot for a calm respite"]', 'https://images.unsplash.com/photo-1578271887552-5ac3a72752bc?auto=format&fit=crop&w=600&q=80', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  170, 4, 'Final Day in Sapporo and Departure', 'Sapporo, Hokkaido', 
  '9:00 AM – 11:00 AM: Moerenuma ParkDesigned by artist Isamu Noguchi, Moerenuma Park features artistic landscapes and sculptures, combining nature and modern art. Walk through its expansive grounds and appreciate the park’s minimalist beauty, with highlights like the glass pyramid and mountain observatory.
11:30 AM – 1:30 PM: Kuma Chen Onsen HotpotConclude your Hokkaido experience with a visit to Kuma Chen Onsen for a relaxing hotpot meal. This venue offers private hot spring baths paired with Hokkaido’s freshest ingredients in a delightful hotpot, providing a cozy finale to your journey.Afternoon: Departure from AirportComplete your 4-day itinerary by heading back to the airport in time for your departure, wrapping up an unforgettable off-season Hokkaido adventure.', '["Moerenuma ParkDesigned by artist Isamu Noguchi, Moerenuma Park features artistic landscapes and sculptures, combining nature and modern art","Walk through its expansive grounds and appreciate the park’s minimalist beauty, with highlights like the glass pyramid and mountain observatory","Kuma Chen Onsen HotpotConclude your Hokkaido experience with a visit to Kuma Chen Onsen for a relaxing hotpot meal","This venue offers private hot spring baths paired with Hokkaido’s freshest ingredients in a delightful hotpot, providing a cozy finale to your journey"]', 'https://images.unsplash.com/photo-1578271887552-5ac3a72752bc?auto=format&fit=crop&w=600&q=80', 3
);
