INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'winter-northern-japan-discovery-route', 'Winter Northern Japan Discovery Route', 'Japan', 'East Asia', 
  'Explore the best of Japan''s highlights on this immersive 6-day journey', '/images/japan/japan-2.jpg', 'Embark on a magnificent 6-day tour of Japan, starting in Tokyo. This package covers a curated route highlighting key cultural sights, bullet train experiences, local culinary delicacies, and historical landmarks. Perfect for families, first-time visitors, and seasoned travelers seeking a seamless, well-organized itinerary.', 
  140.74, 40.82, 'Culture', 'bg-emerald-500', 
  'Discover Japan''s highlights from traditional landmarks to modern marvels on this 6-day package.', '/images/japan/japan-2.jpg', 
  'published', '', '6 Days', 
  NULL, 'Japanese Yen (¥)', 'Subtropical to temperate with distinct seasonal changes', 'March–May (Cherry Blossom) & October–November (Autumn Foliage)', 
  'Japanese', 'JST (UTC+9)', 'Left'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  172, 1, 'Tokyo to Sendai', 'Tokyo, Kanto', 
  '08:00 AM: Depart from Tokyo via Shinkansen to Sendai, the largest city in the Tohoku region.10:30 AM: Arrive in Sendai, transfer to Miyagikyo Distillery for a tour of the famous Nikka Whisky distillery.12:00 PM: Lunch at a local restaurant. 01:30 PM: Visit Sendai Tansu Kumanodo to experience lacquering techniques. Participate in a chopstick lacquering workshop. 04:00 PM: Free time to explore downtown Sendai or rest. 06:00 PM: Dinner at a local restaurant', '["Depart from Tokyo via Shinkansen to Sendai, the largest city in the Tohoku region","Arrive in Sendai, transfer to Miyagikyo Distillery for a tour of the famous Nikka Whisky distillery","Visit Sendai Tansu Kumanodo to experience lacquering techniques","Participate in a chopstick lacquering workshop"]', 'https://images.unsplash.com/photo-1578271887552-5ac3a72752bc?auto=format&fit=crop&w=600&q=80', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  172, 2, 'Iwate – Historical and Cultural Immersion', 'Morioka, Iwate', 
  '09:00 AM: Depart for Iwate''s Sekino-ichi, a century-old brewery famous for sake and local beer. 11:00 AM: Visit Chūson-ji Temple, home to the Konjiki-do (Golden Hall), a UNESCO World Heritage site. 01:00 PM: Lunch at a traditional restaurant.02:30 PM: Tour the Nambu ironware foundry and observe craftsmen creating the region’s iconic metalwork. 05:00 PM: Return to the hotel and leisure time. 07:00 PM: Dinner at a local restaurant', '["Depart for Iwate''s Sekino-ichi, a century-old brewery famous for sake and local beer","Visit Chūson-ji Temple, home to the Konjiki-do (Golden Hall), a UNESCO World Heritage site","Tour the Nambu ironware foundry and observe craftsmen creating the region’s iconic metalwork","Return to the hotel and leisure time"]', 'https://images.unsplash.com/photo-1503899036084-c55cdd92da26?auto=format&fit=crop&w=600&q=80', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  172, 3, 'Kakunodate - "Little Kyoto of Michinoku"', 'Kyoto, Kansai', 
  '09:00 AM: Depart for Kakunodate, a historic samurai town.11:00 AM: Explore the samurai residences of Kakunodate, known for their preserved architecture from the Edo period.12:30 PM: Lunch at a local restaurant featuring regional cuisine.02:00 PM: Continue to Cherry Blossom Road or enjoy the winter atmosphere with snow-covered streets and houses.04:00 PM: Free time to stroll around and shop for local handicrafts.06:00 PM: Return to the hotel for dinner.', '["Depart for Kakunodate, a historic samurai town","Explore the samurai residences of Kakunodate, known for their preserved architecture from the Edo period","Continue to Cherry Blossom Road or enjoy the winter atmosphere with snow-covered streets and houses","Free time to stroll around and shop for local handicrafts"]', '/images/japan/japan-2.jpg', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  172, 4, 'Aomori – Nebuta Festival Experience', 'Aomori, Tohoku', 
  '09:00 AM: Visit Nebuta Museum WaRasse in Aomori to learn about the Nebuta Festival''s cultural significance. 11:30 AM: Participate in a hands-on workshop creating lanterns from neputa paintings. 01:00 PM: Lunch at a local seafood restaurant. 02:30 PM: Free time to explore Aomori City and its scenic waterfront. 05:00 PM: Return to the hotel for a relaxing evening and dinner.', '["Visit Nebuta Museum WaRasse in Aomori to learn about the Nebuta Festival''s cultural significance","Participate in a hands-on workshop creating lanterns from neputa paintings","Free time to explore Aomori City and its scenic waterfront","Return to the hotel for a relaxing evening and dinner"]', 'https://images.unsplash.com/photo-1578271887552-5ac3a72752bc?auto=format&fit=crop&w=600&q=80', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  172, 5, 'Aomori – Tsurunomai Bridge and Shirakami Sanchi', 'Aomori, Tohoku', 
  '09:00 AM: Head to Tsurunomai Bridge, Japan’s longest triple-arch wooden bridge. Enjoy the serene winter landscape (roads may be closed based on the season). 11:00 AM: Travel to Shirakami-Sanchi Visitor Center to learn about Japan’s natural heritage and its preserved beech forest ecosystem. 01:00 PM: Lunch break at a local restaurant. 02:30 PM: Explore Shirakami Sanchi with a short hike (if open to visitors based on season). 05:00 PM: Return to the hotel for dinner and rest.', '["Head to Tsurunomai Bridge, Japan’s longest triple-arch wooden bridge","Enjoy the serene winter landscape (roads may be closed based on the season)","Travel to Shirakami-Sanchi Visitor Center to learn about Japan’s natural heritage and its preserved beech forest ecosystem","Explore Shirakami Sanchi with a short hike (if open to visitors based on season)"]', '/images/japan/japan-2.jpg', 4
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  172, 6, 'Hirosaki Castle and Takayama Inari Shrine', 'Japan', 
  '09:00 AM: Visit Hirosaki Castle, a rare example of an Edo-period castle with the stunning winter landscape. 11:30 AM: Explore the Tachineputa Museum to see the massive floats used in summer festivals. 01:00 PM: Lunch at a local restaurant. 02:30 PM: Conclude the tour with a visit to Takayama Inari Shrine, known for its hundreds of red torii gates creating a mystical atmosphere. 04:00 PM: Depart for Shin-Aomori Station to take the Shinkansen back to Tokyo. 07:00 PM: Arrive at Tokyo Station and conclude the tour.', '["Visit Hirosaki Castle, a rare example of an Edo-period castle with the stunning winter landscape","Explore the Tachineputa Museum to see the massive floats used in summer festivals","Conclude the tour with a visit to Takayama Inari Shrine, known for its hundreds of red torii gates creating a mystical atmosphere","Depart for Shin-Aomori Station to take the Shinkansen back to Tokyo"]', 'https://images.unsplash.com/photo-1503899036084-c55cdd92da26?auto=format&fit=crop&w=600&q=80', 5
);
INSERT INTO `tour_package_things_to_do` (
