) VALUES (
  'golden-route-japan', 'Golden Route, Japan', 'Japan', 'East Asia', 
  'Explore the best of Japan''s highlights on this immersive 7-day journey', '/images/japan/japan-3.jpg', 'Embark on a magnificent 7-day tour of Japan, starting in Osaka. This package covers a curated route highlighting key cultural sights, bullet train experiences, local culinary delicacies, and historical landmarks. Perfect for families, first-time visitors, and seasoned travelers seeking a seamless, well-organized itinerary.', 
  135.5, 34.69, 'Culture', 'bg-emerald-500', 
