);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  173, 1, 'Osaka', 'Osaka, Kansai', 
  'Arrival Flight Details: TBAWelcome to JapanProceed for immigrations and Baggage Claim. Collect your bags, Meet local Representative at the AirportPrivate Transfer from KIX airport to City hotel – OsakaOn arrival Check-in at the Pre-Booked Hotel. Complete check in formalitiesEvening at leisure – before dinner some free timeDinner at Indian RestaurantOvernight stay in Osaka', '["Arrival Flight Details: TBAWelcome to JapanProceed for immigrations and Baggage Claim","Collect your bags, Meet local Representative at the AirportPrivate Transfer from KIX airport to City hotel – OsakaOn arrival Check-in at the Pre-Booked Hotel","Complete check in formalitiesEvening at leisure – before dinner some free timeDinner at Indian RestaurantOvernight stay in Osaka"]', 'https://images.unsplash.com/photo-1590250591827-024505f019f6?auto=format&fit=crop&w=600&q=80', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  173, 2, 'Osaka - Kyoto & Nara Tour ~ Arashiyama, Golden Pavillion, Imperial Palace, Tōdaiji Temple, Deer park', 'Kyoto, Kansai', 
  '01 bag per person not exceeding 23 kgs. will be couriered to Tokyo hotel. Prepare a bag for overnight stay and keep all necessary medicines, prescription etc. in itPick up from Hotel @0900 HrsArashiyama Bamboo Forest, Walk through this serene bamboo grove, a hallmark of Kyoto''s natural beautyKinkaku-ji (Golden Pavilion), admire this stunning Zen temple covered in gold leaf, surrounded by a beautiful gardenStop for LunchAfter lunch, we proceed towards NaraVisit Tōdai-ji Temple - the world''s largest wooden structure; home to the Great Buddha (*No Entrance)Nara Deer Park - Interact with friendly deer roaming freely in this historic parkAfter completing Nara tour, we shall return to OsakaDinner at Indian restaurantOvernight stay at Hotel in Osaka', '["01 bag per person not exceeding 23 kgs","will be couriered to Tokyo hotel","Prepare a bag for overnight stay and keep all necessary medicines, prescription etc","in itPick up from Hotel @0900 HrsArashiyama Bamboo Forest, Walk through this serene bamboo grove, a hallmark of Kyoto''s natural beautyKinkaku-ji (Golden Pavilion), admire this stunning Zen temple covered in gold leaf, surrounded by a beautiful gardenStop for LunchAfter lunch, we proceed towards NaraVisit Tōdai-ji Temple - the world''s largest wooden structure; home to the Great Buddha (*No Entrance)Nara Deer Park - Interact with friendly deer roaming freely in this historic parkAfter completing Nara tour, we shall return to OsakaDinner at Indian restaurantOvernight stay at Hotel in Osaka"]', 'https://images.unsplash.com/photo-1590250591827-024505f019f6?auto=format&fit=crop&w=600&q=80', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  173, 3, 'Osaka/ Hiroshima - Osaka tour ~Osaka Castle, Dotonbori & Shinsaibashi-Suji / Shinkansen Bullet train to Hiroshima', 'Osaka, Kansai', 
  'Pick up from Hotel @0900 HrsOsaka Castle - the most famous landmarks in JapanStop for LunchDotonbori District (Shinsaibashi-Suji Shopping Street) - hotspot for touristsClick a picture with the iconic Glico Man, shot from under Ebisubashi bridge, a famous Osaka picture spotAfter shopping, drop off to Shin Osaka stationShin Osaka station to Hiroshima station in Bullet Train - ShinkansenUpon reaching Hiroshima, pick up from station & transfer to Indian restaurantDinner at local Indian restaurantReach hotel & complete check in formalitiesOvernight stay at Hotel in Osaka', '["Explore local attractions and historical landmarks","Enjoy local dining and sightseeing options"]', 'https://images.unsplash.com/photo-1590250591827-024505f019f6?auto=format&fit=crop&w=600&q=80', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  173, 4, 'Hiroshima/ Tokyo - Hiroshima and Miyajima Day Tour ~Miyajima, Peace memorial, Bomb Dome / Shinkansen BT to Tokyo', 'Tokyo, Kanto', 
  'After breakfast, check out from HotelPick up from Hotel and transfer to Hiroshima ferry terminalFerry transfer to Itsukushima ShrineItsukushima Shrine - best known for its "floating" torii gateSee wild deer in MiyajimaReturn to Hiroshima main Island, ferry transferProceed to Hiroshima Peace Memorial MuseumAtomic Bomb Dome (Hiroshima Memorial Park), Children''s Peace Monument, Flame of PeaceAfter tour ends, Proceed to Hiroshima StationHiroshima station to Tokyo station Bullet trainPick up from Tokyo Station and transfer to restaurantDinner at local Indian restaurantDrop off to hotel, collect bags and complete check in formalitiesOvernight stay at hotel in Tokyo', '["Explore local attractions and historical landmarks","Enjoy local dining and sightseeing options"]', 'https://images.unsplash.com/photo-1542640244-7e672d6cef21?auto=format&fit=crop&w=600&q=80', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  173, 5, 'Tokyo - Mt Fuji and Hakone Tour by coach ~ Oshino Hakkai, Ōwakudani, Hakone Ropeway, Hakone Ship', 'Tokyo, Kanto', 
  'Pick up from hotel and Visit Oshino Hakkai Village @0730 HrsOshino Hakkai (Springs of Mt. Fuji), a must-visit tourist spotŌwakudani - an active volcanic valley, Famous for its black eggs (**weather permitting)Stop for Lunch at Indian RestaurantHakone Ropeway cable car and go sightseeing around the Ōwakudani Valley (*weather permitting)Hakone Pirate Ship on Ashinoko Lake (*weather permitting)Dinner at Indian restaurantReturn to Tokyo, Reach hotel, free time for own activitiesOvernight stay in Tokyo', '["Pick up from hotel and Visit Oshino Hakkai Village @0730 HrsOshino Hakkai (Springs of Mt","Fuji), a must-visit tourist spotŌwakudani - an active volcanic valley, Famous for its black eggs (**weather permitting)Stop for Lunch at Indian RestaurantHakone Ropeway cable car and go sightseeing around the Ōwakudani Valley (*weather permitting)Hakone Pirate Ship on Ashinoko Lake (*weather permitting)Dinner at Indian restaurantReturn to Tokyo, Reach hotel, free time for own activitiesOvernight stay in Tokyo"]', 'https://images.unsplash.com/photo-1493976040374-85c8e12f0c0e?auto=format&fit=crop&w=600&q=80', 4
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  173, 6, 'Tokyo - Tokyo City Tour ~Asakusa (Sensoji), Nakamise, Sumida River, Tokyo Skytree', 'Tokyo, Kanto', 
  'Pick up from Hotel @0900 HrsAsakusa Kannon Temple (Sensoji ) - Tokyo''s oldest and iconic templeStop at Kaminarimon "Thunder Gate". Capture photos of this iconic entrance to Sensō-ji TempleExplore Nakamise Shopping Street. Shop for traditional souvenirs and snacks along this bustling streetStop for LunchSumida River Cruise from AsakusaTokyo Skytree - Tembo deck 350 mReturn to Hotel and free time for own activitiesDinner at Indian restaurantOvernight stay at Hotel in Tokyo', '["Pick up from Hotel @0900 HrsAsakusa Kannon Temple (Sensoji ) - Tokyo''s oldest and iconic templeStop at Kaminarimon \\"Thunder Gate\\"","Capture photos of this iconic entrance to Sensō-ji TempleExplore Nakamise Shopping Street","Shop for traditional souvenirs and snacks along this bustling streetStop for LunchSumida River Cruise from AsakusaTokyo Skytree - Tembo deck 350 mReturn to Hotel and free time for own activitiesDinner at Indian restaurantOvernight stay at Hotel in Tokyo"]', 'https://images.unsplash.com/photo-1503899036084-c55cdd92da26?auto=format&fit=crop&w=600&q=80', 5
);
