INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  174, 1, 'Tokyo', 'Tokyo, Kanto', 
  'Arrival Flight Details: TBA After disembarking, please follow the signs to the Immigration Collect your bags and Meet our representative Private Transfer to City hotel - Tokyo Complete check in formalities Standard Check in time 14:00~15:00 hrs. (Early check in on request) Dinner - own arrangement (No Transfer/ Pay locally) Overnight stay in Tokyo', '["Arrival Flight Details: TBA After disembarking, please follow the signs to the Immigration Collect your bags and Meet our representative Private Transfer to City hotel - Tokyo Complete check in formalities Standard Check in time 14:00~15:00 hrs","(Early check in on request) Dinner - own arrangement (No Transfer/ Pay locally) Overnight stay in Tokyo"]', '/images/japan/japan-4.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  174, 2, 'Tokyo - Tokyo City Tour ~Asakusa (Sensoji), Nakamise, Sumida River, Imperial Palace, Tokyo Skytree', 'Tokyo, Kanto', 
  '01 bag per person not exceeding 23 kgs. will be couriered to Osaka hotel. Prepare a bag for overnight stay and keep all necessary medicines, prescription etc. in it Pick up from Hotel @0900 Hrs Asakusa Kannon Temple (Sensoji ) - Tokyo''s oldest and iconic temple Nakamise Dori Shopping street Sumida River Cruise Stop for Lunch (Pay locally) Imperial Palace East Garden(Nijubashi Bridge) (** No Stop/ Pass by) Tokyo Skytree - Climb up to the Tembo deck 350 m Dinner - own arrangement (No Transfer/ Pay locally) Overnight stay at Hotel in Tokyo', '["01 bag per person not exceeding 23 kgs","will be couriered to Osaka hotel","Prepare a bag for overnight stay and keep all necessary medicines, prescription etc","in it Pick up from Hotel @0900 Hrs Asakusa Kannon Temple (Sensoji ) - Tokyo''s oldest and iconic temple Nakamise Dori Shopping street Sumida River Cruise Stop for Lunch (Pay locally) Imperial Palace East Garden(Nijubashi Bridge) (** No Stop/ Pass by) Tokyo Skytree - Climb up to the Tembo deck 350 m Dinner - own arrangement (No Transfer/ Pay locally) Overnight stay at Hotel in Tokyo"]', 'https://images.unsplash.com/photo-1590250591827-024505f019f6?auto=format&fit=crop&w=600&q=80', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  174, 3, 'Tokyo/ Mt. Fuji/ Hiroshima - Mt Fuji & Hakone Tour ~ 5th Stn/Oshino Hakkai, Ōwakudani, Jigokudani, Ropeway, Hakone Ship/ BT to Hiroshima', 'Tokyo, Kanto', 
  'After breakfast, check out and assemble at the lobby Pick up from hotel and proceed to Mt Fuji 5th Station @0730 Hrs Mt. Fuji Fifth Station - Sky Palace (* Weather permitting) If 5th station is closed, we will be visiting Oshino Hakkai Oshino Hakkai (Springs of Mt. Fuji), a must-visit tourist spot (*weather permitting) Ōwakudani - an active volcanic valley (**weather permitting) Jigokudani - Famous for its black eggs, boiled in the sulphurous waters to give the egg shells a distinctive colour Stop for Lunch Hakone Ropeway cable car and go sightseeing around the Ōwakudani Valley (weather permitting) Hakone Pirate Ship - go cruising from Togendai Port to Moto Hakone Port along Ashinoko Lake (*weather permitting) After tour ends, proceed further to Odawara/ Mishima Station Odawara/ Mishima station to Hiroshima Station Shinkansen Bullet Train Upon arrival at Hiroshima station, pick up from station and transfer to restaurant Dinner at Indian restaurant (Pay locally) After dinner, Reach Hotel, Collect Your bags and complete check in formalities Check in and Overnight stay at hotel in Hiroshima', '["After breakfast, check out and assemble at the lobby Pick up from hotel and proceed to Mt Fuji 5th Station @0730 Hrs Mt","Fuji Fifth Station - Sky Palace (* Weather permitting) If 5th station is closed, we will be visiting Oshino Hakkai Oshino Hakkai (Springs of Mt","Fuji), a must-visit tourist spot (*weather permitting) Ōwakudani - an active volcanic valley (**weather permitting) Jigokudani - Famous for its black eggs, boiled in the sulphurous waters to give the egg shells a distinctive colour Stop for Lunch Hakone Ropeway cable car and go sightseeing around the Ōwakudani Valley (weather permitting) Hakone Pirate Ship - go cruising from Togendai Port to Moto Hakone Port along Ashinoko Lake (*weather permitting) After tour ends, proceed further to Odawara/ Mishima Station Odawara/ Mishima station to Hiroshima Station Shinkansen Bullet Train Upon arrival at Hiroshima station, pick up from station and transfer to restaurant Dinner at Indian restaurant (Pay locally) After dinner, Reach Hotel, Collect Your bags and complete check in formalities Check in and Overnight stay at hotel in Hiroshima"]', 'https://images.unsplash.com/photo-1493976040374-85c8e12f0c0e?auto=format&fit=crop&w=600&q=80', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  174, 4, 'Hiroshima/ Osaka - Hiroshima & Miyajima Tour ~Torii gate, Bomb Dome, Peace Memorial park/ Shinkansen Train to Osaka', 'Osaka, Kansai', 
  'After breakfast, check out from Hotel, proceed to Hiroshima & Miyajima Day tour Ferry transfer to Itsukushima Shrine Itsukushima Shrine - best known for its "floating" torii gate See wild deer in Miyajima Return to Hiroshima main Island, ferry transfer Stop for Lunch (Pay locally) Proceed to Hiroshima Peace Memorial Museum Atomic Bomb Dome (Hiroshima Memorial Park) Proceed to Hiroshima Station Hiroshima station to Shin Osaka station Bullet train This super fast bullet train journey takes less than 2 hours each way Pick up from Shin Osaka Station and transfer to Indian Restaurant Dinner - own arrangement (No Transfer/ Pay locally) Reach hotel, complete check in and free time for relaxation Overnight stay at hotel in Osaka', '["Explore local attractions and historical landmarks","Enjoy local dining and sightseeing options"]', 'https://images.unsplash.com/photo-1590250591827-024505f019f6?auto=format&fit=crop&w=600&q=80', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  174, 5, 'Osaka - Kyoto & Nara Tour ~ Arashiyama, Golden Pavillion, Imperial Palace, Tōdaiji, Deer park', 'Kyoto, Kansai', 
  'Pick up from Hotel @0900 Hrs Arashiyama Bamboo Forest -Japan''s most famous bamboo forest. Walk through the Bamboo grooves Kinkaku-ji - Rokuon-ji is a Zen Buddhist temple, the “the Golden Pavilion”, Mirror Pond Kyoto Imperial Palace - the former palace of the Emperor of Japan (Drive pass/ No stop**) Stop for Lunch (Pay locally) After lunch, we proceed towards Nara Visit Tōdai-ji Temple - the world''s largest wooden structure; home to the Great Buddha, the largest bronze statue in the world Nara Deer Park - renowned for its free-roaming deer and world famous temples Dinner - own arrangement (No Transfer/ Pay locally) Overnight stay at Hotel in Osaka', '["Pick up from Hotel @0900 Hrs Arashiyama Bamboo Forest -Japan''s most famous bamboo forest","Walk through the Bamboo grooves Kinkaku-ji - Rokuon-ji is a Zen Buddhist temple, the “the Golden Pavilion”, Mirror Pond Kyoto Imperial Palace - the former palace of the Emperor of Japan (Drive pass/ No stop**) Stop for Lunch (Pay locally) After lunch, we proceed towards Nara Visit Tōdai-ji Temple - the world''s largest wooden structure; home to the Great Buddha, the largest bronze statue in the world Nara Deer Park - renowned for its free-roaming deer and world famous temples Dinner - own arrangement (No Transfer/ Pay locally) Overnight stay at Hotel in Osaka"]', 'https://images.unsplash.com/photo-1590250591827-024505f019f6?auto=format&fit=crop&w=600&q=80', 4
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  174, 6, 'Osaka - Osaka tour ~Osaka Castle, Umeda Sky Building, Dotonbori/ Shinsaibashi', 'Osaka, Kansai', 
  'Pick up from Hotel @0930 Hrs Osaka Castle - the most famous landmarks in Japan Umeda Sky Building Floating Garden Observatory Stop for Lunch (Pay locally) Dotonbori District (Shinsaibashi-Suji Shopping Street) - hotspot for tourists. Filled with towering neon signs, clubs, bars & restaurants Click a picture with the iconic Glico Man, shot from under Ebisubashi bridge, a famous Osaka picture spot Dinner - own arrangement (No Transfer/ Pay locally) Overnight stay at Hotel in Osaka', '["Pick up from Hotel @0930 Hrs Osaka Castle - the most famous landmarks in Japan Umeda Sky Building Floating Garden Observatory Stop for Lunch (Pay locally) Dotonbori District (Shinsaibashi-Suji Shopping Street) - hotspot for tourists","Filled with towering neon signs, clubs, bars & restaurants Click a picture with the iconic Glico Man, shot from under Ebisubashi bridge, a famous Osaka picture spot Dinner - own arrangement (No Transfer/ Pay locally) Overnight stay at Hotel in Osaka"]', 'https://images.unsplash.com/photo-1590250591827-024505f019f6?auto=format&fit=crop&w=600&q=80', 5
);
