INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  178, 2, 'Tokyo - Tokyo City Tour ~Tokyo Skytree, UENO Park , teamlab Planets, Meguro River Cruise', 'Tokyo, Kanto', 
  'Pick up from Hotel @0900 HrsTokyo Skytree - Climb up to the Tembo deck 350 mVisit Ueno Park for best Cheery Blossom experienceStop for LunchAfter lunch, teamlab planets, a museum where you walk through water, and a garden where you become one with the flowersMeguro River Park - Home to a one kilometre promenade of cherry blossomsMeguro River cherry blossom cruise - Get a view of the Meguro River''s cherry blossoms from the water with this special cruise (** Cruise subject to availability; incase of cruise unavailability, we shall take the guests to visit Shinjuku Gyon Park for Cherry Blossom viewing)Dinner at local restaurantOvernight stay at Hotel in Tokyo', '["Explore local attractions and historical landmarks","Enjoy local dining and sightseeing options"]', '/images/tour-2.jpg', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  178, 3, 'Tokyo - Mt Fuji and Hakone Tour by coach ~ 5th Stn/Oshino Hakkai, Ōwakudani, Jigokudani, Hakone Ropeway, Hakone Ship', 'Tokyo, Kanto', 
  'After breakfast, check out and assemble at the lobbyPick up from hotel and proceed to Mt Fuji 5th Station @0730 HrsMt. Fuji Fifth Station - Sky Palace (* Weather permitting)If 5th station is closed, we will be visiting Oshino HakkaiOshino Hakkai (Springs of Mt. Fuji), a must-visit tourist spot (*weather permitting)Ōwakudani - an active volcanic valley (**weather permitting)Jigokudani - Famous for its black eggs, boiled in the sulphurous waters to give the egg shells a distinctive colourStop for LunchHakone Ropeway cable car and go sightseeing around the Ōwakudani Valley (weather permitting)Hakone Pirate Ship - go cruising from Togendai Port to Moto Hakone Port along Ashinoko Lake (*weather permitting)Dinner at local restaurantOvernight stay in Tokyo', '["After breakfast, check out and assemble at the lobbyPick up from hotel and proceed to Mt Fuji 5th Station @0730 HrsMt","Fuji Fifth Station - Sky Palace (* Weather permitting)If 5th station is closed, we will be visiting Oshino HakkaiOshino Hakkai (Springs of Mt","Fuji), a must-visit tourist spot (*weather permitting)Ōwakudani - an active volcanic valley (**weather permitting)Jigokudani - Famous for its black eggs, boiled in the sulphurous waters to give the egg shells a distinctive colourStop for LunchHakone Ropeway cable car and go sightseeing around the Ōwakudani Valley (weather permitting)Hakone Pirate Ship - go cruising from Togendai Port to Moto Hakone Port along Ashinoko Lake (*weather permitting)Dinner at local restaurantOvernight stay in Tokyo"]', 'https://images.unsplash.com/photo-1493976040374-85c8e12f0c0e?auto=format&fit=crop&w=600&q=80', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  178, 4, 'Tokyo - Tokyo Disney Land 1-Day Passport + Private Round Trip Transfers', 'Tokyo, Kanto', 
  '01 bag per person not exceeding 23 kgs. will be couriered to Kyoto hotel. Prepare a bag for overnight/ two nights stay and keep all necessary medicines, prescription etc. in itBreakfast at hotelPick up from Hotel @0900 HrsHotel Pick up and transfer to Disneyland @0900 HrsThe first Disney theme park outside of the United StatesDisneyland is made up of seven themed lands and features seasonal decorations & paradesLunch inside theme park (pay locally)Pick up from Disneyland Resort @1900 HrsProceed for Dinner at Indian RestaurantReturn to Hotel and free time for own activitiesOvernight stay in Tokyo', '["01 bag per person not exceeding 23 kgs","will be couriered to Kyoto hotel","Prepare a bag for overnight/ two nights stay and keep all necessary medicines, prescription etc","in itBreakfast at hotelPick up from Hotel @0900 HrsHotel Pick up and transfer to Disneyland @0900 HrsThe first Disney theme park outside of the United StatesDisneyland is made up of seven themed lands and features seasonal decorations & paradesLunch inside theme park (pay locally)Pick up from Disneyland Resort @1900 HrsProceed for Dinner at Indian RestaurantReturn to Hotel and free time for own activitiesOvernight stay in Tokyo"]', 'https://images.unsplash.com/photo-1503899036084-c55cdd92da26?auto=format&fit=crop&w=600&q=80', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  178, 5, 'Tokyo/ Kyoto - Tokyo to Kyoto Shinkansen Train/ Kyoto Tour ~Kyoto Station, Kyoto Railway Museum, Fushimi Inari Shrine', 'Tokyo, Kanto', 
  'Check out and proceed to Tokyo stationTokyo station to Kyoto station in Bullet Train - Shinkansen Nozomi/ Hikari/ SakuraReach Kyoto and Explore Kyoto StationKyoto Station, one of Japan''s largest buildingsStop for LunchKyoto Railway Museum, one of the best railway museums anywhere in the worldFushimi Inari Shrine - famous for its thousands of vermilion torii gates (Short stop**)Dinner at Indian restaurantReach Hotel, Collect Your bags and complete check in formalitiesOvernight stay at Hotel in Kyoto', '["Explore local attractions and historical landmarks","Enjoy local dining and sightseeing options"]', 'https://images.unsplash.com/photo-1503899036084-c55cdd92da26?auto=format&fit=crop&w=600&q=80', 4
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  178, 6, 'Kyoto - Kyoto Day Tour ~ Arashiyama, Sagano Rail, Sake Brewery, Kiyomizu Dera', 'Kyoto, Kansai', 
  'Pick up from Hotel @0900 HrsArashiyama Bamboo Forest -Japan''s most famous bamboo forest.Walk through the Bamboo groovesEnjoy The Sagano Romantic train/ Saga torokko station to Kameoka torokko Station (25 min)Enjoy the scenic beauty of the Hozukyo Ravine on its routePick up from Kameoka station, proceed to restaurantStop for lunchPost lunch, we shall visit the Sake breweryKiyomizu temple, Ninenzaka & SannenzakaDinner at local Indian restaurantOvernight stay at Hotel in Kyoto', '["Pick up from Hotel @0900 HrsArashiyama Bamboo Forest -Japan''s most famous bamboo forest","Walk through the Bamboo groovesEnjoy The Sagano Romantic train/ Saga torokko station to Kameoka torokko Station (25 min)Enjoy the scenic beauty of the Hozukyo Ravine on its routePick up from Kameoka station, proceed to restaurantStop for lunchPost lunch, we shall visit the Sake breweryKiyomizu temple, Ninenzaka & SannenzakaDinner at local Indian restaurantOvernight stay at Hotel in Kyoto"]', 'https://images.unsplash.com/photo-1503899036084-c55cdd92da26?auto=format&fit=crop&w=600&q=80', 5
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  178, 7, 'Kyoto - Kyoto to Osaka Private transfer/ Evening tour the Dotonbori & shainsaibashi shopping areas', 'Kyoto, Kansai', 
  'After breakfast, check out and meet our representativeProceed to Osaka by landStop for LunchReach Osaka hotel, complete check in formalitiesDotonbori District (Shinsaibashi-Suji Shopping Street) - hotspot for tourists. Filled with towering neon signs, clubs, bars & restaurantsClick a picture with the iconic Glico Man, shot from under Ebisubashi bridge, a famous Osaka picture spotDinner at local restaurantOvernight stay at Hotel in Osaka', '["After breakfast, check out and meet our representativeProceed to Osaka by landStop for LunchReach Osaka hotel, complete check in formalitiesDotonbori District (Shinsaibashi-Suji Shopping Street) - hotspot for tourists","Filled with towering neon signs, clubs, bars & restaurantsClick a picture with the iconic Glico Man, shot from under Ebisubashi bridge, a famous Osaka picture spotDinner at local restaurantOvernight stay at Hotel in Osaka"]', 'https://images.unsplash.com/photo-1590250591827-024505f019f6?auto=format&fit=crop&w=600&q=80', 6
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  178, 8, 'Osaka - Nara & Osaka tour ~Tōdai-ji Temple , Nara Deer Park, Osaka Castle, Umeda Sky Building', 'Osaka, Kansai', 
  'Pick up from Hotel @0900 HrsProceed to Nara Tour (takes approx. 80 minutes to cover about 35 kms)Visit Tōdai-ji Temple - the world''s largest wooden structure; home to the Great Buddha, the largest bronze statue in the worldNara Deer Park - renowned for its free-roaming deer and world famous templesStop for LunchAfter lunch, return to OsakaOsaka Castle - the most famous landmarks in JapanUmeda Sky Building - Floating Garden ObservatoryDinner at local restaurantOvernight stay at Hotel in Osaka', '["Pick up from Hotel @0900 HrsProceed to Nara Tour (takes approx","80 minutes to cover about 35 kms)Visit Tōdai-ji Temple - the world''s largest wooden structure; home to the Great Buddha, the largest bronze statue in the worldNara Deer Park - renowned for its free-roaming deer and world famous templesStop for LunchAfter lunch, return to OsakaOsaka Castle - the most famous landmarks in JapanUmeda Sky Building - Floating Garden ObservatoryDinner at local restaurantOvernight stay at Hotel in Osaka"]', 'https://images.unsplash.com/photo-1590250591827-024505f019f6?auto=format&fit=crop&w=600&q=80', 7
);
