) VALUES (
  'japan-golden-route', 'Japan Golden Route', 'Japan', 'East Asia', 
  'Explore the best of Japan''s highlights on this immersive 10-day journey', '/images/tour-1.jpg', 'Embark on a magnificent 10-day tour of Japan, starting in Tokyo. This package covers a curated route highlighting key cultural sights, bullet train experiences, local culinary delicacies, and historical landmarks. Perfect for families, first-time visitors, and seasoned travelers seeking a seamless, well-organized itinerary.', 
  138.38, 34.97, 'Culture', 'bg-emerald-500', 
  'Discover Japan''s highlights from traditional landmarks to modern marvels on this 10-day package.', '/images/tour-1.jpg', 
  'published', '', '10 Days', 
  NULL, 'Japanese Yen (¥)', 'Subtropical to temperate with distinct seasonal changes', 'March–May (Cherry Blossom) & October–November (Autumn Foliage)', 
  'Japanese', 'JST (UTC+9)', 'Left'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  179, 1, 'Tokyo', 'Tokyo, Kanto', 
  'Arrival Flight Details: TBAAfter disembarking, please follow the signs to the ImmigrationCollect your bags and Meet our representativePrivate Transfer Tokyo Airport to City hotel - TokyoStandard Check in time 14:00~15:00 hrs. (Early check in on request)Complete check in formalitiesOvernight stay in Tokyo', '["Arrival Flight Details: TBAAfter disembarking, please follow the signs to the ImmigrationCollect your bags and Meet our representativePrivate Transfer Tokyo Airport to City hotel - TokyoStandard Check in time 14:00~15:00 hrs","(Early check in on request)Complete check in formalitiesOvernight stay in Tokyo"]', '/images/tour-1.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  179, 2, 'Tokyo - Tokyo City Tour ~ Imperial Palace, Asakusa (Sensoji), Nakamise, Tokyo Skytree, Sumida River, Odaiba', 'Tokyo, Kanto', 
  'Pick up from Hotel @0900 HrsImperial Palace East Garden (Nijubashi Bridge) (** No Stop/ Pass by)Asakusa Kannon Temple (Sensoji ) - Tokyo''s oldest and iconic templeStop at Kaminarimon "Thunder Gate". Capture photos of this iconic entrance to Sensō-ji TempleExplore Nakamise Shopping Street. Shop for traditional souvenirs and snacks along this bustling streetStop for Lunch (Pay locally)Tokyo Skytree - Tembo deck 350 m (Entrance ticket included)Sumida River Cruise from Asakusa to Odaiba Seaside ParkRainbow Bridge (** View from the pier)Proceed to Statue of LibertyOvernight stay at Hotel in Tokyo', '["Pick up from Hotel @0900 HrsImperial Palace East Garden (Nijubashi Bridge) (** No Stop/ Pass by)Asakusa Kannon Temple (Sensoji ) - Tokyo''s oldest and iconic templeStop at Kaminarimon \\"Thunder Gate\\"","Capture photos of this iconic entrance to Sensō-ji TempleExplore Nakamise Shopping Street","Shop for traditional souvenirs and snacks along this bustling streetStop for Lunch (Pay locally)Tokyo Skytree - Tembo deck 350 m (Entrance ticket included)Sumida River Cruise from Asakusa to Odaiba Seaside ParkRainbow Bridge (** View from the pier)Proceed to Statue of LibertyOvernight stay at Hotel in Tokyo"]', 'https://images.unsplash.com/photo-1503899036084-c55cdd92da26?auto=format&fit=crop&w=600&q=80', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  179, 3, 'Tokyo - Tokyo shopping & Entertainment tour ~ Teamlab, Hie Shrine, Akihabara, Ginza Six', 'Tokyo, Kanto', 
  'Pick up from Hotel @0900 Hrsteamlab Planets, a museum where you walk through water, and a garden where you become one with the flowersVisit Hie Shrine, a traditional Japanese Shinto shrine famous for its striking row of red torii gatesStop for Lunch (Pay locally)Akihabara Electric Town (Electronic Shopping Market)Later, proceed to Ginza Six Mall. Ginza Japan’s premier shopping districtOvernight stay in Tokyo', '["Pick up from Hotel @0900 Hrsteamlab Planets, a museum where you walk through water, and a garden where you become one with the flowersVisit Hie Shrine, a traditional Japanese Shinto shrine famous for its striking row of red torii gatesStop for Lunch (Pay locally)Akihabara Electric Town (Electronic Shopping Market)Later, proceed to Ginza Six Mall","Ginza Japan’s premier shopping districtOvernight stay in Tokyo"]', '/images/tour-1.jpg', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  179, 4, 'Tokyo - Nikko World Heritage Tour ~Nikko Toshogu Shrine, Lake Chuzenji, Kegon Falls', 'Tokyo, Kanto', 
  '01 bag per person not exceeding 23 kgs. will be couriered to Nagoya hotel. Prepare a bag for overnight stay and keep all necessary medicines, prescription etc. in itPick up from Hotel @0900 Hrs and proceed to Nikko world heritage sightNikko Toshogu Shrine - A registered UNESCO World Heritage SiteToshogu Shrine in Nikko, you’ll find the original Three Wise Monkeys statue that has gained international fameLake Chuzenji - a symbol of NikkoStop for Lunch (Pay locally)Kegon Falls (elevator to lower observation deck)Return to Hotel and free time for own activitiesOvernight stay at Hotel in Tokyo', '["01 bag per person not exceeding 23 kgs","will be couriered to Nagoya hotel","Prepare a bag for overnight stay and keep all necessary medicines, prescription etc","in itPick up from Hotel @0900 Hrs and proceed to Nikko world heritage sightNikko Toshogu Shrine - A registered UNESCO World Heritage SiteToshogu Shrine in Nikko, you’ll find the original Three Wise Monkeys statue that has gained international fameLake Chuzenji - a symbol of NikkoStop for Lunch (Pay locally)Kegon Falls (elevator to lower observation deck)Return to Hotel and free time for own activitiesOvernight stay at Hotel in Tokyo"]', 'https://images.unsplash.com/photo-1571479539343-4cc06579a099?auto=format&fit=crop&w=600&q=80', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  179, 5, 'Tokyo/ Mt. Fuji/ Shizuoka - Mt Fuji and Hakone Tour ~ 5th Stn/Oshino Hakkai, Ōwakudani, Hakone Ropeway, Hakone Ship', 'Tokyo, Kanto', 
  'Pick up from hotel and proceed to Mt Fuji 5th Station @0730 HrsMt. Fuji Fifth Station - Sky Palace (* Weather permitting)If 5th station is closed, we will be visiting Oshino HakkaiOshino Hakkai (Springs of Mt. Fuji), a must-visit tourist spot (*weather permitting)Ōwakudani - an active volcanic valley, Famous for its black eggs (**weather permitting)Stop for Lunch (Pay locally)Hakone Ropeway cable car and go sightseeing around the Ōwakudani Valley (weather permitting)Hakone Pirate Ship, sail across Lake Ashi for picturesque views of the surrounding mountains.(*weather permitting)Reach hotel, Complete check in formalities, free time for own activitiesOvernight stay in Shizuoka', '["Pick up from hotel and proceed to Mt Fuji 5th Station @0730 HrsMt","Fuji Fifth Station - Sky Palace (* Weather permitting)If 5th station is closed, we will be visiting Oshino HakkaiOshino Hakkai (Springs of Mt","Fuji), a must-visit tourist spot (*weather permitting)Ōwakudani - an active volcanic valley, Famous for its black eggs (**weather permitting)Stop for Lunch (Pay locally)Hakone Ropeway cable car and go sightseeing around the Ōwakudani Valley (weather permitting)Hakone Pirate Ship, sail across Lake Ashi for picturesque views of the surrounding mountains","(*weather permitting)Reach hotel, Complete check in formalities, free time for own activitiesOvernight stay in Shizuoka"]', 'https://images.unsplash.com/photo-1493976040374-85c8e12f0c0e?auto=format&fit=crop&w=600&q=80', 4
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  179, 6, 'Shizuoka/ Nagoya - Shizuoka/ Nagoya Tokaido shinkansen/ Nagoya Tour ~ Toyota Museum or Railway Park, Nagoya Castle', 'Nagoya, Chubu', 
  'After breakfast, check out and proceed to Shizuoka stationWalk to Shizuoka station North (550 meters)Tokaido High Speed Bullet Train from Shizuoka to Nagoya stationThis journey takes about 01 hour 15 min to cover 177 kmsReach Nagoya, Toyota Automobile Museum [** Advance reservation required/ subject to availability]SC Maglev and Railway Park [** Admission fee included/ simulators cost excluded]Stop for Lunch (Pay locally)Nagoya Castle - one of the largest castles in the world!Reach hotel, collect your bags and complete check in formalitiesOvernight stay in Nagoya', '["After breakfast, check out and proceed to Shizuoka stationWalk to Shizuoka station North (550 meters)Tokaido High Speed Bullet Train from Shizuoka to Nagoya stationThis journey takes about 01 hour 15 min to cover 177 kmsReach Nagoya, Toyota Automobile Museum [** Advance reservation required/ subject to availability]SC Maglev and Railway Park [** Admission fee included/ simulators cost excluded]Stop for Lunch (Pay locally)Nagoya Castle - one of the largest castles in the world","Reach hotel, collect your bags and complete check in formalitiesOvernight stay in Nagoya"]', 'https://images.unsplash.com/photo-1571479539343-4cc06579a099?auto=format&fit=crop&w=600&q=80', 5
);
