INSERT INTO `tour_packages` (
  `slug`, `name`, `country`, `region`, `tagline`, `hero_image`, `overview`, 
  `coords_lon`, `coords_lat`, `tag`, `tag_color`, `short_description`, `thumbnail_image`, 
  `status`, `price`, `duration`, 
  `quick_fact_capital`, `quick_fact_currency`, `quick_fact_climate`, `quick_fact_best_season`, 
  `quick_fact_languages`, `quick_fact_time_zone`, `quick_fact_driving_side`
) VALUES (
  'exotic-japan-package-japan-with-alpine-route', 'Exotic Japan Package (Japan With Alpine Route)', 'Japan', 'East Asia', 
  'Discover Japan''s natural wonders, volcanic hot springs, and scenic trails over 11 days', '/images/dest-2.jpg', 'Embark on a magnificent 11-day tour of Japan, starting in Tokyo. This package covers a curated route highlighting key cultural sights, bullet train experiences, local culinary delicacies, and historical landmarks. Perfect for families, first-time visitors, and seasoned travelers seeking a seamless, well-organized itinerary.', 
  137.97, 36.23, 'Nature', 'bg-amber-500', 
  'Discover Japan''s highlights from traditional landmarks to modern marvels on this 11-day package.', '/images/dest-2.jpg', 
  'published', '', '11 Days', 
  NULL, 'Japanese Yen (¥)', 'Subtropical to temperate with distinct seasonal changes', 'March–May (Cherry Blossom) & October–November (Autumn Foliage)', 
  'Japanese', 'JST (UTC+9)', 'Left'
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  180, 1, 'Tokyo', 'Tokyo, Kanto', 
  'Arrival Flight Details: TBAAfter disembarking, please follow the signs to the ImmigrationCollect your bags and Meet our representativePrivate Transfer to City hotel - TokyoComplete check in formalitiesStandard Check in time 14:00~15:00 hrs. (Early check in on request)Free time for leisure/ relaxation; later proceed for the Tokyo evening sightseeing TourTokyo orientation/ sightseeing tour ~Odaiba, Statue of liberty, Rainbow bridgeOdaiba seaside park - Coastal green space with views of the Rainbow Bridge & cityStatue of Liberty (** Drive over/ No Stop)Rainbow Bridge (** View from window/ No Stop)Transfer to City hotel - Tokyo/ Complete check in formalitiesDinner at local Indian restaurantOvernight stay in Tokyo', '["Arrival Flight Details: TBAAfter disembarking, please follow the signs to the ImmigrationCollect your bags and Meet our representativePrivate Transfer to City hotel - TokyoComplete check in formalitiesStandard Check in time 14:00~15:00 hrs","(Early check in on request)Free time for leisure/ relaxation; later proceed for the Tokyo evening sightseeing TourTokyo orientation/ sightseeing tour ~Odaiba, Statue of liberty, Rainbow bridgeOdaiba seaside park - Coastal green space with views of the Rainbow Bridge & cityStatue of Liberty (** Drive over/ No Stop)Rainbow Bridge (** View from window/ No Stop)Transfer to City hotel - Tokyo/ Complete check in formalitiesDinner at local Indian restaurantOvernight stay in Tokyo"]', '/images/dest-2.jpg', 0
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  180, 2, 'Tokyo - Tokyo City Tour ~Imperial Palace, Asakusa (Sensoji), Nakamise, Sumida River, Tokyo Skytree', 'Tokyo, Kanto', 
  'Pick up from Hotel @0900 HrsImperial Palace East Garden (Nijubashi Bridge) (** No Stop/ Pass by)Asakusa Kannon Temple (Sensoji ) - Tokyo''s oldest and iconic templeNakamise Dori - Shopping Arcade where you can walk around the local stores or try famous street food of JapanSumida River Cruise, give best view of Tokyo Skytree and Sakura from the river banksStop for Lunch at Indian RestaurantTokyo Skytree - Climb up to the Tembo deck 350 metersDinner at local Indian restaurantReturn to Hotel and free time for own activitiesOvernight stay at Hotel in Tokyo', '["Explore local attractions and historical landmarks","Enjoy local dining and sightseeing options"]', 'https://images.unsplash.com/photo-1503899036084-c55cdd92da26?auto=format&fit=crop&w=600&q=80', 1
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  180, 3, 'Tokyo - Tokyo shopping & Sakura (Cherry blossom) tour ~Ueno park, Akihabara, Shinjuku Garden, Ginza Six', 'Tokyo, Kanto', 
  'Pick up from Hotel @1000 HrsVisit Ueno Park for best Cheery Blossom experienceAkihabara Harajuku Street Electronic Shopping Market (1 ½ Hours)Stop for Lunch at Indian RestaurantShinjuku Gyoen National garden for best Cherry Blossom viewing & Japanese Garden ExperienceLater, proceed to Ginza Six Mall. Ginza Japan’s premier shopping districtDinner at local Indian restaurantReach hotelOvernight stay in Tokyo', '["Pick up from Hotel @1000 HrsVisit Ueno Park for best Cheery Blossom experienceAkihabara Harajuku Street Electronic Shopping Market (1 ½ Hours)Stop for Lunch at Indian RestaurantShinjuku Gyoen National garden for best Cherry Blossom viewing & Japanese Garden ExperienceLater, proceed to Ginza Six Mall","Ginza Japan’s premier shopping districtDinner at local Indian restaurantReach hotelOvernight stay in Tokyo"]', '/images/dest-2.jpg', 2
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  180, 4, 'Tokyo/ Mt. Fuji/ Matsumoto - Mt Fuji and Hakone Tour by coach ~ Oshino Hakkai, Ōwakudani, Jigokudani, Hakone Ropeway, Hakone Ship', 'Tokyo, Kanto', 
  'After breakfast, check out and assemble at the lobbyMt Fuji and Hakone Tour by coach ~ Oshino Hakkai, Ōwakudani, Jigokudani, Hakone Ropeway, Hakone ShipPick up from hotel and Visit Oshino Hakkai Village @0900 HrsOshino Hakkai (Springs of Mt. Fuji), a must-visit tourist spot (*weather permitting)Ōwakudani - an active volcanic valley (**weather permitting)Jigokudani - Famous for its black eggs, boiled in the sulphurous waters to give the egg shells a distinctive colourStop for Lunch at Indian RestaurantHakone Ropeway cable car and go sightseeing around the Ōwakudani Valley (weather permitting)Hakone Pirate Ship, go cruising from Togendai Port to Moto Hakone Port along Ashinoko Lake (*weather permitting)Dinner At Local Indian RestaurantTransfer to hotel, complete check in formalitiesOvernight stay in Matsumoto', '["After breakfast, check out and assemble at the lobbyMt Fuji and Hakone Tour by coach ~ Oshino Hakkai, Ōwakudani, Jigokudani, Hakone Ropeway, Hakone ShipPick up from hotel and Visit Oshino Hakkai Village @0900 HrsOshino Hakkai (Springs of Mt","Fuji), a must-visit tourist spot (*weather permitting)Ōwakudani - an active volcanic valley (**weather permitting)Jigokudani - Famous for its black eggs, boiled in the sulphurous waters to give the egg shells a distinctive colourStop for Lunch at Indian RestaurantHakone Ropeway cable car and go sightseeing around the Ōwakudani Valley (weather permitting)Hakone Pirate Ship, go cruising from Togendai Port to Moto Hakone Port along Ashinoko Lake (*weather permitting)Dinner At Local Indian RestaurantTransfer to hotel, complete check in formalitiesOvernight stay in Matsumoto"]', 'https://images.unsplash.com/photo-1493976040374-85c8e12f0c0e?auto=format&fit=crop&w=600&q=80', 3
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  180, 5, 'Matsumoto/Toyama - Matsumoto - Ogizawa Tateyama - Toyama (Alpine Route)', 'Matsumoto, Nagano', 
  '01 bag per person not exceeding 23 kgs. will be couriered to Osaka hotel. Prepare a bag for overnight/ 02 nights stay and keep all necessary medicines, prescription etc. in itAfter breakfast, Check Out And Proceed to Matsumoto StationHead to the Tateyama Kurobe Alpine Route via busTateyama Station to Bijodaira Station Cable car -> Bijodaira Station to Murodo Station Highland bus -> Sightseeing in MurodoLunch At Local Indian RestaurantMurodo Station to Daikanbo Station Trolley bus -> Daikanbo Station to Kurobedaira Station RopewayKurobedaira Station to Kurobeko Station Cable car -> Kurobe Dam SightseeingKurobe Dam Station to Ogizawa Station Trolley busPick up from Ogizawa StationDinner At Local Indian RestaurantReach hotel, complete check in and free time for relaxationOvernight stay at hotel in Toyama', '["01 bag per person not exceeding 23 kgs","will be couriered to Osaka hotel","Prepare a bag for overnight/ 02 nights stay and keep all necessary medicines, prescription etc","in itAfter breakfast, Check Out And Proceed to Matsumoto StationHead to the Tateyama Kurobe Alpine Route via busTateyama Station to Bijodaira Station Cable car -> Bijodaira Station to Murodo Station Highland bus -> Sightseeing in MurodoLunch At Local Indian RestaurantMurodo Station to Daikanbo Station Trolley bus -> Daikanbo Station to Kurobedaira Station RopewayKurobedaira Station to Kurobeko Station Cable car -> Kurobe Dam SightseeingKurobe Dam Station to Ogizawa Station Trolley busPick up from Ogizawa StationDinner At Local Indian RestaurantReach hotel, complete check in and free time for relaxationOvernight stay at hotel in Toyama"]', 'https://images.unsplash.com/photo-1590250591827-024505f019f6?auto=format&fit=crop&w=600&q=80', 4
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  180, 6, 'Toyama/ Kanazawa/ Hiroshima - Toyama to Kanazawa Enroute visiting Shirakawa go/ Shinkansen Bullet Train to Hiroshima', 'Hiroshima, Chugoku', 
  'Breakfast at hotelCheck out and proceed to Shirakawa goVisit Ogimachi is the largest and most well-known village in Shirakawa-goLunch At Local Indian RestaurantProceed To Kanazawa StationKanazawa Station To Hiroshima Station By Bullet TrainPick up from Hiroshima station and Proceed To Local Indian RestaurantDinner at Indian restaurantReach hotel and complete check in formalitiesOvernight stay at Hotel in Osaka', '["Explore local attractions and historical landmarks","Enjoy local dining and sightseeing options"]', 'https://images.unsplash.com/photo-1590250591827-024505f019f6?auto=format&fit=crop&w=600&q=80', 5
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  180, 7, 'Hiroshima/ Osaka - Hiroshima & Miyajima Tour ~Torii gate, Bomb Dome, Peace Memorial park/ Shinkansen Train to Osaka', 'Osaka, Kansai', 
  'After breakfast, check out from Hotel, proceed to Hiroshima & Miyajima Day tourFerry transfer to Itsukushima ShrineItsukushima Shrine - best known for its "floating" torii gateSee wild deer in MiyajimaReturn to Hiroshima main Island, ferry transferLunch At Local Indian RestaurantProceed to Hiroshima Peace Memorial MuseumAtomic Bomb Dome (Hiroshima Memorial Park)Proceed to Hiroshima StationHiroshima station to Shin Osaka station Bullet trainThis super fast bullet train journey takes less than 2 hours each wayPick up from Shin Osaka Station and transfer to Indian RestaurantDinner at Indian restaurantReach hotel, collect your bags and complete check in formalitiesOvernight stay at hotel in Osaka', '["Explore local attractions and historical landmarks","Enjoy local dining and sightseeing options"]', 'https://images.unsplash.com/photo-1590250591827-024505f019f6?auto=format&fit=crop&w=600&q=80', 6
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  180, 8, 'Osaka - Kyoto Day Tour ~ Arashiyama, Kinkaku ji, Imperial Palace, Traditional Tea Ceremony, Fushimi Inari', 'Kyoto, Kansai', 
  'Pick up from HotelArashiyama Bamboo Forest -Japan''s most famous bamboo forest.Walk through the Bamboo groovesKinkaku-ji - Rokuon-ji is a Zen Buddhist temple, the “the Golden Pavilion”, Mirror PondKyoto Imperial Palace - the former palace of the Emperor of Japan (Drive pass/ No stop**)Lunch At Local Indian RestaurantTraditional Tea CeremonyFushimi Inari Shrine - famous for its thousands of vermilion torii gates (Short stop**)Return to OsakaDinner at local Indian restaurantOvernight stay at Hotel in Osaka', '["Pick up from HotelArashiyama Bamboo Forest -Japan''s most famous bamboo forest","Walk through the Bamboo groovesKinkaku-ji - Rokuon-ji is a Zen Buddhist temple, the “the Golden Pavilion”, Mirror PondKyoto Imperial Palace - the former palace of the Emperor of Japan (Drive pass/ No stop**)Lunch At Local Indian RestaurantTraditional Tea CeremonyFushimi Inari Shrine - famous for its thousands of vermilion torii gates (Short stop**)Return to OsakaDinner at local Indian restaurantOvernight stay at Hotel in Osaka"]', 'https://images.unsplash.com/photo-1590250591827-024505f019f6?auto=format&fit=crop&w=600&q=80', 7
);
INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  180, 9, 'Osaka - Nara Day Tour ~Tōdaiji Temple, Nara Deer Park, Kasuga Taisha shrine', 'Osaka, Kansai', 
  'Breakfast at HotelPick up from Hotel @0930 HrsVisit Tōdai-ji Temple - the world''s largest wooden structure; home to the Great Buddha, the largest bronze statue in the worldNara Deer Park - renowned for its free-roaming deer and world famous templesStop for Lunch at Indian RestaurantKasuga Taisha shrine, famous for Japan''s largest number of lanterns, with 2,000 stone lanterns and 1,000 hanging lanterns within the shrine premisesReturn to OsakaDinner at local Indian restaurantOvernight stay at Hotel in Osaka', '["Explore local attractions and historical landmarks","Enjoy local dining and sightseeing options"]', 'https://images.unsplash.com/photo-1590250591827-024505f019f6?auto=format&fit=crop&w=600&q=80', 8
);
INSERT INTO `tour_package_itinerary` (
