) VALUES (
  181, 1, 'Tokyo', 'Tokyo, Kanto', 
  'Arrival Flight Details: TBAAfter disembarking, please follow the signs to the ImmigrationAfter clearing immigration, collect your baggageMeet our representative. Pick up from Airport & transfer to city hotelTransfer to City hotel - Tokyo/ Complete check in formalitiesOvernight stay in Tokyo', '["Arrival Flight Details: TBAAfter disembarking, please follow the signs to the ImmigrationAfter clearing immigration, collect your baggageMeet our representative","Pick up from Airport & transfer to city hotelTransfer to City hotel - Tokyo/ Complete check in formalitiesOvernight stay in Tokyo"]', 'https://images.unsplash.com/photo-1493976040374-85c8e12f0c0e?auto=format&fit=crop&w=600&q=80', 0
);
