) VALUES (
  'best-of-japan-the-golden-route', 'Best Of Japan, The Golden Route', 'Japan', 'East Asia', 
  'Explore the best of Japan''s highlights on this immersive 12-day journey', 'https://images.unsplash.com/photo-1524413840807-0c3cb6fa808d?auto=format&fit=crop&w=600&q=80', 'Embark on a magnificent 12-day tour of Japan, starting in Osaka. This package covers a curated route highlighting key cultural sights, bullet train experiences, local culinary delicacies, and historical landmarks. Perfect for families, first-time visitors, and seasoned travelers seeking a seamless, well-organized itinerary.', 
  135.73, 34.98, 'Culture', 'bg-emerald-500', 
  'Discover Japan''s highlights from traditional landmarks to modern marvels on this 12-day package.', 'https://images.unsplash.com/photo-1524413840807-0c3cb6fa808d?auto=format&fit=crop&w=600&q=80', 
  'published', '', '12 Days', 
  NULL, 'Japanese Yen (¥)', 'Subtropical to temperate with distinct seasonal changes', 'March–May (Cherry Blossom) & October–November (Autumn Foliage)', 
  'Japanese', 'JST (UTC+9)', 'Left'
);
