) VALUES (
  183, 6, 'Kyoto /Hiroshima - Kyoto to Hiroshima - Bullet Train/ Free time for own activities', 'Kyoto, Kansai', 
  'After breakfast, check out from HotelPick up from Hotel and transfer to Kyoto StationKyoto station to Hiroshima station in Bullet Train - Shinkansen Nozomi/ Hikari/ SakuraUpon reaching Hiroshima, Pick up from the station and transfer to hotelReach hotel, complete check in formalities; rest of the day free for relaxationOvernight stay at hotel in Hiroshima', '["Explore local attractions and historical landmarks","Enjoy local dining and sightseeing options"]', 'https://images.unsplash.com/photo-1503899036084-c55cdd92da26?auto=format&fit=crop&w=600&q=80', 5
);
INSERT INTO `tour_package_itinerary` (
