) VALUES (
  183, 7, 'Hiroshima - Hiroshima & Miyajima tour ~ Itsukushima shrine (Miyajima), Peace Museum & Memorial Park, Atomic Bomb Dome', 'Hiroshima, Chugoku', 
  'Breakfast at hotelPick up from Hotel @0900 HrsTransfer to ferry terminal, ferry transfer to Itsukushima ShrineItsukushima Shrine - best known for its "floating" torii gateSee wild deer in MiyajimaReturn to Hiroshima main Island, ferry transferStop for lunchProceed to Hiroshima Peace Memorial MuseumAtomic Bomb Dome (Hiroshima Memorial Park)Hiroshima Castle (Drive by)Reach hotel and free time for own activitiesOvernight stay at hotel in Hiroshima', '["Explore local attractions and historical landmarks","Enjoy local dining and sightseeing options"]', 'https://images.unsplash.com/photo-1542640244-7e672d6cef21?auto=format&fit=crop&w=600&q=80', 6
