INSERT INTO `tour_package_itinerary` (
  `tour_package_id`, `day_number`, `title`, `location`, `description`, `highlights`, `image_url`, `sort_order`
) VALUES (
  183, 9, 'Tokyo - Tokyo City Tour ~Asakusa (Sensoji), Nakamise, Tokyo Skytree, Sumida River Cruise', 'Tokyo, Kanto', 
  'Imperial Palace East Garden (Nijubashi Bridge) (** No Stop/ Pass by)Asakusa Kannon Temple (Sensoji ) - Tokyo''s oldest and iconic templeStop at Kaminarimon "Thunder Gate". Capture photos of this iconic entrance to Sensō-ji TempleExplore Nakamise Shopping Street. Shop for traditional souvenirs and snacks along this bustling streetStop for Lunch (Pay locally)Tokyo Skytree - Tembo deck 350 m (Entrance ticket included)Sumida River CruiseOvernight stay at Hotel in Tokyo', '["Imperial Palace East Garden (Nijubashi Bridge) (** No Stop/ Pass by)Asakusa Kannon Temple (Sensoji ) - Tokyo''s oldest and iconic templeStop at Kaminarimon \\"Thunder Gate\\"","Capture photos of this iconic entrance to Sensō-ji TempleExplore Nakamise Shopping Street","Shop for traditional souvenirs and snacks along this bustling streetStop for Lunch (Pay locally)Tokyo Skytree - Tembo deck 350 m (Entrance ticket included)Sumida River CruiseOvernight stay at Hotel in Tokyo"]', 'https://images.unsplash.com/photo-1503899036084-c55cdd92da26?auto=format&fit=crop&w=600&q=80', 8
);
