INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  184, 'Shinkansen Bullet Train', 'Experience Japan''s high-speed train, linking key cities with incredible punctuality and comfort.', 'Train', 0
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
) VALUES (
  184, 'Traditional Tea Ceremony', 'Immerse yourself in the Zen practice of preparing and sipping ceremonial matcha in a tatami room.', 'BookOpen', 1
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
