  184, 'Sushi & Kaiseki Cuisine', 'Indulge in seasonal culinary masterpieces, from street food stalls to multi-course kaiseki banquets.', 'Utensils', 2
);
INSERT INTO `tour_package_things_to_do` (
  `tour_package_id`, `title`, `description`, `icon_name`, `sort_order`
