INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  184, 'Regional JR Rail Pass: Consider a regional pass to save significantly on Shinkansen bullet train routes.', 0
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  184, 'IC Card Setup: Download a mobile IC card (Suica/Pasmo) for seamless local bus and subway tap-ins.', 1
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  184, 'Carry Cash: Many small shrines, temple entrance counters, and local street stalls do not accept credit cards.', 2
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  184, 'Etiquette & Tipping: Good service is standard; tipping is not practiced and may cause confusion.', 3
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  184, 'Footwear Manners: Wear slip-on shoes since you''ll take them off frequently at temples and traditional ryokans.', 4
);
INSERT INTO `tour_package_travel_tips` (
  `tour_package_id`, `tip`, `sort_order`
) VALUES (
  184, 'Pocket Wi-Fi / eSIM: Pre-order a pocket Wi-Fi or eSIM to stay connected with navigation maps during your trip.', 5
);
